[24993] = { ["id"] = 24993, ["name"] = "Annihilate the Worgen", ["level"] = 8, ["requiredLevel"] = 5, ["faction"] = "horde", ["requiredRaces"] = { 5, 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 85, ["mapID"] = 18, ["storyline"] = { 24993 }, ["series"] = { 24992 }, ["description"] = "These worgen must be dealt with, and quickly. Our first priority is to eliminate any which may have infiltrated Brill. I want you to be on the lookout for any suspicious activity here in Brill, <name>. We know that these worgen can hide in the shadows, so look for any signs you can find... footsteps, kicked-up rocks... anything.", ["objectivesText"] = "Find and kill 5 Worgen Infiltrators within Brill. Progress: By Sylvanas, these wolf-men will NOT undo the progress we've made!", ["rewardGold"] = 225, ["rewardXP"] = 530, ["rewardItems"] = { 57154, 57155 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 85 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 18, ["questLines"] = { { ["id"] = 565, ["name"] = "Tirisfal Glades", ["orderIndex"] = 16, ["flags"] = 0 } } },
[25039] = { ["id"] = 25039, ["name"] = "Have You Seen Anything Weird Out There?", ["level"] = 7, ["requiredLevel"] = 5, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["storyline"] = { 25039 }, ["description"] = "<race>! Listen up, I got somethin'... odd to discuss. I was out fishin' by Brightwater Lake when I saw the darnedest thing... some sorta wolf-man, running around Tirisfal. Ya don't suppose that could be a... worgen, do ya? Anyway, I keep tellin' myself I should tell Executor Zygand about it, but I just get so scared when I talk to that guy. Maybe you could talk with him?", ["objectivesText"] = "Speak with Executor Zygand about your encounter with the worgen.", ["rewardGold"] = 85, ["rewardXP"] = 315, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[29393] = { ["id"] = 29393, ["name"] = "Brew For Brewfest", ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 14, ["storyline"] = { 29393 }, ["description"] = "So you want to check out the racing rams? The dwarves think they have got a handle on it, but let's be honest, they are drunk most of the time, so how hard can it really be? Now before I let you strut your stuff, you'll need to show me that you can handle these fine, legally obtained creatures. So here's the deal: I'll lend you some racing reins and the use of a ram. You need to prove to me that you can handle using these rams. Keep the ram at a trot, canter and gallop for 8 seconds each.", ["objectivesText"] = "You have 4 minutes to ride the ram and maintain 3 different levels of speed for 8 seconds.", ["rewardGold"] = 1500, ["rewardXP"] = 80, ["rewardItems"] = { 33030, 33031, 33034, 34017, 34020, 37829 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2751 } },
[29404] = { ["id"] = 29404, ["name"] = "Much to Learn", ["level"] = 1, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["storyline"] = { 29404 }, ["series"] = { 29405, 29406, 29408, 29409, 29410, 29524, 30027, 30033, 30034, 30035, 30036, 30037, 30038, 30039, 30040, 30041, 30042, 30043, 30044, 30045 }, ["description"] = "Fresh to your training, your first task is simple: Speak to Master Shang Xi.", ["objectivesText"] = "Speak to Master Shang Xi.", ["rewardGold"] = 2, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[29405] = { ["id"] = 29405, ["name"] = "The Lesson of the Iron Staff", ["level"] = 1, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["storyline"] = { 29405 }, ["series"] = { 29404, 29406, 29408, 29409, 29410, 29524, 30027, 30033, 30034, 30035, 30036, 30037, 30038, 30039, 30040, 30041, 30042, 30043, 30044, 30045 }, ["description"] = "To train, first you must be properly equipped. Retrieve a weapon from one of the weapon racks below, bring it to me, and show me that you know how to hold it properly.", ["objectivesText"] = "Loot a training weapon from a weapon rack and then equip it.", ["rewardGold"] = 15, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[29406] = { ["id"] = 29406, ["name"] = "The Lesson of the Sandy Fist", ["level"] = 2, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "class" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5736, ["mapID"] = 378, ["storyline"] = { 29406 }, ["series"] = { 29404, 29405, 29408, 29409, 29410, 29524, 30027, 30033, 30034, 30035, 30036, 30037, 30038, 30039, 30040, 30041, 30042, 30043, 30044, 30045 }, ["description"] = "I'd like to observe you putting your new weapon to use, my young student. This will aid me in determining what degree of training will be best suited to your talents. We have many training targets in the training grounds below. Practice your attacks upon them, and return to me once you're feeling comfortable with your new weapon.", ["objectivesText"] = "Destroy 5 Training Targets .", ["rewardGold"] = 100, ["rewardXP"] = 255, ["rewardItems"] = { 73214, 73215, 73216 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5736 } }, ["questType"] = "standard", ["db2PoiMapID"] = 860, ["db2PoiUiMapID"] = 378, ["questLines"] = { { ["id"] = 573, ["name"] = "The Wandering Isle", ["orderIndex"] = 7, ["flags"] = 0 } } },
[29407] = { ["id"] = 29407, ["name"] = "The First Sign of Winter", ["level"] = 2, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["storyline"] = { 29407 }, ["description"] = "At the stream below rests a single lotus flower. Within this lotus lies a sign of things to come. Bring it to me that I might show you.", ["objectivesText"] = "Recover the Shimmering Lotus .", ["rewardGold"] = 35, ["rewardXP"] = 170, ["rewardItems"] = { 71079 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[29408] = { ["id"] = 29408, ["name"] = "The Lesson of the Burning Scroll", ["level"] = 2, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "class" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5736, ["mapID"] = 378, ["storyline"] = { 29408 }, ["series"] = { 29404, 29405, 29406, 29409, 29410, 29524, 30027, 30033, 30034, 30035, 30036, 30037, 30038, 30039, 30040, 30041, 30042, 30043, 30044, 30045 }, ["description"] = "Every wisdom has a time and place, and times are changing for those of us living here on Shen-zin Su. For this lesson, I would ask two things of you. For the first, I hold a flame in my hand. Gather your wits, and when you think you are ready, attempt to snatch the flame. Should you succeed, I want you to then climb to the top of this temple and burn the Edict of Temperance that you find there.", ["objectivesText"] = "Snatch the flame from Master Shang Xi 's palm, then burn the Edict of Temperance.", ["rewardGold"] = 35, ["rewardXP"] = 170, ["rewardItems"] = { 80212 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5736 } }, ["questType"] = "standard", ["db2PoiMapID"] = 860, ["db2PoiUiMapID"] = 378, ["questLines"] = { { ["id"] = 573, ["name"] = "The Wandering Isle", ["orderIndex"] = 9, ["flags"] = 0 } } },
[29409] = { ["id"] = 29409, ["name"] = "The Disciple's Challenge", ["level"] = 2, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "class" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5736, ["mapID"] = 378, ["storyline"] = { 29409 }, ["series"] = { 29404, 29405, 29406, 29408, 29410, 29524, 30027, 30033, 30034, 30035, 30036, 30037, 30038, 30039, 30040, 30041, 30042, 30043, 30044, 30045 }, ["description"] = "<name>, I see great strength and great courage in you, and an unsurpassed purity of soul. The hour is young, but I think you may be ready to face a greater challenge. Go to the bottom of the stairs, and cross the bridge. There, you will find Jaomin Ro , one of our eldest students. Challenge and defeat him in honorable combat, and this first phase of your training will be complete.", ["objectivesText"] = "Defeat Jaomin Ro .", ["rewardGold"] = 100, ["rewardXP"] = 255, ["rewardItems"] = { 73220, 73221, 73222 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5736 } }, ["questType"] = "standard", ["db2PoiMapID"] = 860, ["db2PoiUiMapID"] = 378, ["questLines"] = { { ["id"] = 573, ["name"] = "The Wandering Isle", ["orderIndex"] = 10, ["flags"] = 0 } } },
[29410] = { ["id"] = 29410, ["name"] = "Aysa of the Tushui", ["level"] = 2, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5736, ["mapID"] = 378, ["storyline"] = { 29410 }, ["series"] = { 29404, 29405, 29406, 29408, 29409, 29524, 30027, 30033, 30034, 30035, 30036, 30037, 30038, 30039, 30040, 30041, 30042, 30043, 30044, 30045 }, ["description"] = "In such a short time, you've shown me that you have the potential to be a great <class>. The training grounds are behind you, but now you must prove yourself by facing a far greater challenge, one that none of my students have accomplished. I want you to return Huo, the spirit of fire, to the Temple of Five Dawns. My two other most gifted students will help you in this task. The first is Aysa Cloudsinger. Seek her out at the pool to the west.", ["objectivesText"] = "Speak to Merchant Lorvo by Fu's Pond.", ["rewardGold"] = 8, ["rewardXP"] = 45, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5736 } }, ["questType"] = "standard", ["db2PoiMapID"] = 860, ["db2PoiUiMapID"] = 378, ["questLines"] = { { ["id"] = 573, ["name"] = "The Wandering Isle", ["orderIndex"] = 11, ["flags"] = 0 } } },
[29414] = { ["id"] = 29414, ["name"] = "The Way of the Tushui", ["level"] = 3, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5736, ["mapID"] = 378, ["storyline"] = { 29414 }, ["series"] = { 29417, 29522 }, ["description"] = "It's a pleasure to meet you, <class>. I am Aysa, of the Tushui. I've spent much time in thought since Master Shang told me we would be searching for Huo, the spirit of fire. I know where he resides, but not how to reach him. The answers are close, however. Come with me to the Cave of Meditation nearby. It is a place of great wisdom. I will meditate there, open my mind, and the path shall find us.", ["objectivesText"] = "Protect Aysa while she meditates.", ["rewardGold"] = 50, ["rewardXP"] = 250, ["rewardItems"] = { 73224, 73225, 73226 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5736 } }, ["questType"] = "standard", ["db2PoiMapID"] = 860, ["db2PoiUiMapID"] = 378, ["questLines"] = { { ["id"] = 573, ["name"] = "The Wandering Isle", ["orderIndex"] = 14, ["flags"] = 0 } } },
[29417] = { ["id"] = 29417, ["name"] = "The Way of the Huojin", ["level"] = 4, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5736, ["mapID"] = 378, ["storyline"] = { 29417 }, ["series"] = { 29414, 29522 }, ["description"] = "We call those vicious monkeys swinging into town hozen. They keep to themselves normally, but they know something bad is coming, so they're here to steal our supplies. In situations like this, the clear answer is the only answer. These monkeys will leave when we force them to leave! To not defend our town and those we love would be the only true crime. Thus is the way of the Huojin.", ["objectivesText"] = "Kill 8 Fe-Feng attackers.", ["rewardGold"] = 75, ["rewardXP"] = 355, ["rewardItems"] = { 73227, 73228, 73229 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5736 } }, ["questType"] = "standard", ["db2PoiMapID"] = 860, ["db2PoiUiMapID"] = 378, ["questLines"] = { { ["id"] = 573, ["name"] = "The Wandering Isle", ["orderIndex"] = 16, ["flags"] = 0 } } },
[29418] = { ["id"] = 29418, ["name"] = "Kindling the Fire", ["level"] = 4, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5736, ["mapID"] = 378, ["storyline"] = { 29418 }, ["description"] = "Now that that's done with, let's get to it then! Huo, the spirit of fire, hungers for dry dogwood root kindling. It grows among the trees south of the village. It should be easy enough for you to gather some.", ["objectivesText"] = "Gather 5 Dry Dogwood Roots . Progress: I hope you're not shy about getting your hands dirty.", ["rewardGold"] = 75, ["rewardXP"] = 355, ["rewardItems"] = { 72111 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5736 } }, ["questType"] = "standard", ["db2PoiMapID"] = 860, ["db2PoiUiMapID"] = 378, ["questLines"] = { { ["id"] = 573, ["name"] = "The Wandering Isle", ["orderIndex"] = 17, ["flags"] = 0 } } },
[29419] = { ["id"] = 29419, ["name"] = "The Missing Driver", ["level"] = 3, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5736, ["mapID"] = 378, ["storyline"] = { 29419 }, ["description"] = "My driver went running off after the sprites just after they attacked. I don't think they'll really do him any harm, but I need him back to help me clean up the mess by the cart. He chased them off towards the cliffs to the north. If you head that direction, you should find him quickly.", ["objectivesText"] = "Rescue the Cart Driver.", ["rewardGold"] = 50, ["rewardXP"] = 250, ["rewardItems"] = { 73223, 73241 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5736 } }, ["questType"] = "standard", ["db2PoiMapID"] = 860, ["db2PoiUiMapID"] = 378, ["questLines"] = { { ["id"] = 573, ["name"] = "The Wandering Isle", ["orderIndex"] = 13, ["flags"] = 0 } } },
[29420] = { ["id"] = 29420, ["name"] = "The Spirit's Guardian", ["level"] = 4, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5736, ["mapID"] = 378, ["storyline"] = { 29420 }, ["series"] = { 29421, 29422, 29423, 29664 }, ["description"] = "You've done very well this far, my student. You have the materials you need to rekindle Huo, the spirit of fire. In the cave to the southwest he awaits, but he is guarded by Master Li Fei , the pandaren elder you met in the Cave of Meditation. Go to Master Li Fei with the offerings. Prove yourself, then meet with Huo.", ["objectivesText"] = "Speak to Master Li Fei in the Shrine of Inner-Light.", ["rewardGold"] = 20, ["rewardXP"] = 90, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5736 } }, ["questType"] = "standard", ["db2PoiMapID"] = 860, ["db2PoiUiMapID"] = 378, ["questLines"] = { { ["id"] = 573, ["name"] = "The Wandering Isle", ["orderIndex"] = 19, ["flags"] = 0 } } },
[29421] = { ["id"] = 29421, ["name"] = "Only the Worthy Shall Pass", ["level"] = 4, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5736, ["mapID"] = 378, ["storyline"] = { 29421 }, ["series"] = { 29420, 29422, 29423, 29664 }, ["description"] = "It is time for you to face me. With these three fires illuminating your potential, we will see with certainty whether your resolved soul is truly worthy of passing.", ["objectivesText"] = "Defeat Master Li Fei in combat.", ["rewardGold"] = 75, ["rewardXP"] = 355, ["rewardItems"] = { 73237, 73238, 73239, 73242 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5736 } }, ["questType"] = "standard", ["db2PoiMapID"] = 860, ["db2PoiUiMapID"] = 378, ["questLines"] = { { ["id"] = 573, ["name"] = "The Wandering Isle", ["orderIndex"] = 21, ["flags"] = 0 } } },
[29422] = { ["id"] = 29422, ["name"] = "Huo, the Spirit of Fire", ["level"] = 4, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5736, ["mapID"] = 378, ["storyline"] = { 29422 }, ["series"] = { 29420, 29421, 29423, 29664 }, ["description"] = "You are worthy of passing, <class>. Huo , the spirit of fire rests in the chamber beyond. Let him feast upon the kindling you've gathered, and use the wind to fan his flames. Doing so should endear you to him. Once he is ignited, if he is willing, lead him to the Temple of Five Dawns, the building standing high in the center of the island.", ["objectivesText"] = "Reignite Huo , the spirit of fire. Progress: < Huo rests quietly within the pool.>", ["rewardGold"] = 75, ["rewardXP"] = 355, ["rewardItems"] = { 72583 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5736 } }, ["questType"] = "standard", ["db2PoiMapID"] = 860, ["db2PoiUiMapID"] = 378, ["questLines"] = { { ["id"] = 573, ["name"] = "The Wandering Isle", ["orderIndex"] = 22, ["flags"] = 0 } } },
[29423] = { ["id"] = 29423, ["name"] = "The Passion of Shen-zin Su", ["level"] = 5, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5736, ["mapID"] = 378, ["storyline"] = { 29423 }, ["series"] = { 29420, 29421, 29422, 29664 }, ["description"] = "< Huo bounces around excitedly, ready to follow you.> < Master Shang Xi told you to bring Huo to meet him at the Temple of Five Dawns in the center of the island. Your next destination lies before you.>", ["objectivesText"] = "Bring the Spirit of Fire to the Temple of Five Dawns.", ["rewardGold"] = 50, ["rewardXP"] = 225, ["rewardItems"] = { 73233, 73234, 73235, 73236 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5736 } }, ["questType"] = "standard", ["db2PoiMapID"] = 860, ["db2PoiUiMapID"] = 378, ["questLines"] = { { ["id"] = 573, ["name"] = "The Wandering Isle", ["orderIndex"] = 23, ["flags"] = 0 } } },
[29424] = { ["id"] = 29424, ["name"] = "Items of Utmost Importance", ["level"] = 3, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5736, ["mapID"] = 378, ["storyline"] = { 29424 }, ["description"] = "Amberleaf scamps swarmed my cart and stole most of the training supplies I was bringing up to the training grounds. They've always been troublemakers, but they've never been this aggressive before. I don't know what happened. Please, help me recover my supplies.", ["objectivesText"] = "Recover 6 Training Supplies from Amberleaf Scamps. Progress: You needn't worry about hurting the sprites. They're really just living plants when it comes down to it - they'll resprout later.", ["rewardGold"] = 50, ["rewardXP"] = 250, ["rewardItems"] = { 72071 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5736 } }, ["questType"] = "standard", ["db2PoiMapID"] = 860, ["db2PoiUiMapID"] = 378, ["questLines"] = { { ["id"] = 573, ["name"] = "The Wandering Isle", ["orderIndex"] = 12, ["flags"] = 0 } } },
[29521] = { ["id"] = 29521, ["name"] = "The Singing Pools", ["level"] = 5, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5736, ["mapID"] = 378, ["storyline"] = { 29521 }, ["series"] = { 29661, 29663, 29676 }, ["description"] = "It is crucial that we bring all of the three remaining spirits back safely. I am too old to do this myself, and for all their strengths, both Aysa and Ji are single-minded in their ideals. You possess all the qualities of a hero, and a balance that they do not. It is you that must do this. Shu, the spirit of water is somewhere in the singing pools to the east. Find Aysa there and work with her to locate him. We are all depending on you.", ["objectivesText"] = "Speak to Aysa Cloudsinger in the Singing Pools.", ["rewardGold"] = 25, ["rewardXP"] = 110, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5736 } }, ["questType"] = "standard", ["db2PoiMapID"] = 860, ["db2PoiUiMapID"] = 378, ["questLines"] = { { ["id"] = 573, ["name"] = "The Wandering Isle", ["orderIndex"] = 24, ["flags"] = 0 } } },
[29522] = { ["id"] = 29522, ["name"] = "Ji of the Huojin", ["level"] = 3, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5736, ["mapID"] = 378, ["storyline"] = { 29522 }, ["series"] = { 29414, 29417 }, ["description"] = "Another of my most talented students is awaiting you in Wu-Song Village to the northwest. He is of a different mind than Aysa, but in their differences, they bring balance to each other. Ji Firepaw will instruct you on gathering the offerings for the spirit of fire. Trust in his wisdom.", ["objectivesText"] = "Speak to Ji Firepaw in Wu-Song Village.", ["rewardGold"] = 13, ["rewardXP"] = 65, ["rewardItems"] = { 73227, 73228, 73229 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5736 } }, ["questType"] = "standard", ["db2PoiMapID"] = 860, ["db2PoiUiMapID"] = 378, ["questLines"] = { { ["id"] = 573, ["name"] = "The Wandering Isle", ["orderIndex"] = 15, ["flags"] = 0 } } },
[29523] = { ["id"] = 29523, ["name"] = "Fanning the Flames", ["level"] = 4, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5736, ["mapID"] = 378, ["storyline"] = { 29523 }, ["description"] = "Strange thing about wind, it can be hard to wrap your hands around it. Best practice for me has been finding some sort of living wind. If it can punch you, you can punch it back, and it won't slip through your grasp. Head over to the Shrine of the Summer Breeze to the south and summon just such a living wind using this wind stone . Best it, gather a Fluttering Breeze from it, and come back over this way so that we can figure out what's next.", ["objectivesText"] = "Retrieve a Fluttering Breeze . Progress: When opportunity rises, it is our responsibility to reach out and grab it. Second guessing is as good as giving up.", ["rewardGold"] = 75, ["rewardXP"] = 355, ["rewardItems"] = { 72109, 72112, 73230, 73231, 73232 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5736 } }, ["questType"] = "standard", ["db2PoiMapID"] = 860, ["db2PoiUiMapID"] = 378, ["questLines"] = { { ["id"] = 573, ["name"] = "The Wandering Isle", ["orderIndex"] = 18, ["flags"] = 0 } } },
[29524] = { ["id"] = 29524, ["name"] = "The Lesson of Stifled Pride", ["level"] = 2, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "class" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5736, ["mapID"] = 378, ["storyline"] = { 29524 }, ["series"] = { 29404, 29405, 29406, 29408, 29409, 29410, 30027, 30033, 30034, 30035, 30036, 30037, 30038, 30039, 30040, 30041, 30042, 30043, 30044, 30045 }, ["description"] = "Facing a living opponent is a very different thing from the stationary targets in the yard. Living opponents strike back. There is the very real fear of failure, and sometimes, even death. You must have the courage to overcome those fears. Challenge the other trainees within the temple or down the steps below, and defeat them.", ["objectivesText"] = "Defeat 6 Huojin Trainees or Tushui Trainees.", ["rewardGold"] = 100, ["rewardXP"] = 255, ["rewardItems"] = { 73217, 73218, 73219 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5736 } }, ["questType"] = "standard", ["db2PoiMapID"] = 860, ["db2PoiUiMapID"] = 378, ["questLines"] = { { ["id"] = 573, ["name"] = "The Wandering Isle", ["orderIndex"] = 8, ["flags"] = 0 } } },
