[29541] = { ["id"] = 29541, ["name"] = "Take Care of It", ["level"] = 85, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["storyline"] = { 29541 }, ["description"] = "This looks bad... you'd better do something.", ["objectivesText"] = "Resolve the dispute any way you see fit.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[29576] = { ["id"] = 29576, ["name"] = "An Air of Worry", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["storyline"] = { 29576 }, ["series"] = { 29578 }, ["description"] = "My sight has long since faded, but when the wind is right I can still smell the blossoms of Nectarbreeze Orchard as if they were in my own palm. Today, though, their fragrance is muddled with smoke. Please, if you are able, check in on the orchard and see that things are okay. Perhaps my old nose is playing tricks on me. You'll find the orchard to the southwest, beyond the statue of the Jade Serpent.", ["objectivesText"] = "Speak with Shao the Defiant at Nectarbreeze Orchard.", ["rewardGold"] = 49000, ["rewardXP"] = 55000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard" },
[29577] = { ["id"] = 29577, ["name"] = "Ashyo's Vision", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 29577 }, ["series"] = { 29581, 29871 }, ["description"] = "Have a look at that! <Ashyo motions at the massive waterfall to the north.> This must be the water supply for the whole valley! Think about it, <name>: the pandaren use this water to grow vegetables the size of a house. Where could it come from? What is so special about it? The elders among my people know a technique for speaking with the water and divining the future. Perhaps this same technique can provide insight into the water's source... It's worth a shot at least!", ["objectivesText"] = "Speak with Ashyo at the Pools of Purity and observe his ritual. Progress: What is that jinyu up to over there?", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[29581] = { ["id"] = 29581, ["name"] = "The Golden Dream", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 29581 }, ["series"] = { 29577, 29871 }, ["description"] = "Ashyo must have experienced what we call the golden dream. Many of us working here have seen it, too - often after a long day of toiling in the pools. It is said this vision--and the feeling of elation it brings--is a reward to the mind for working the body. There IS an easier way, though we rarely resort to it anymore: a tea can be brewed using lotus root and dreamleaf, which grows around the shrine on the upper tier. Bring the dreamleaf to Yan back in town and he can brew the tea for you.", ["objectivesText"] = "Bring a Sprig of Dreamleaf to Yan in New Cifera. Progress: Yes, did you need something?", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["rewardItems"] = { 76973 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[29600] = { ["id"] = 29600, ["name"] = "Snap Judgment", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 29600 }, ["description"] = "These pools are very special: they nurture life like nothing else in Pandaria. Unfortunately this means they draw all kinds of attention from local fauna. Recently, dragon turtles have discovered that toadspawn pools are common on the tier just above us. They're running wild up there, trampling the lotuses and snapping at my workers. They aren't much of a threat on their own, but in groups they can be pretty nasty. Please, if you can spare your strength, help clear them out.", ["objectivesText"] = "Kill 16 Razorback Snappers at the Pools of Purity. Progress: <Yue sighs.> If only we'd kept up with our maintenance, the situation would not have come to this.", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["rewardItems"] = { 73058, 81805, 81806, 81807, 81808, 81809, 81810, 81811, 81812, 81813 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard", ["startItems"] = { 73058 } },
[29617] = { ["id"] = 29617, ["name"] = "Tian Monastery", ["level"] = 85, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["storyline"] = { 29617 }, ["series"] = { 29618 }, ["description"] = "People come from all over Pandaria to train at the Tian Monastery, just to the north of here. Probably because they never turn anybody down. They'll accept jinyu, hozen... or even a foreign <race> like you! My childhood friend, Lin, just joined the monastery's order a few weeks ago. If you're interested in learning how our monks train, maybe you should go talk with her!", ["objectivesText"] = "Speak with Lin Tenderpaw at the Tian Monastery in the Jade Forest .", ["rewardGold"] = 9400, ["rewardXP"] = 6940, ["rewardItems"] = { 79731 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard" },
[29661] = { ["id"] = 29661, ["name"] = "The Lesson of Dry Fur", ["level"] = 5, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5736, ["mapID"] = 378, ["storyline"] = { 29661 }, ["series"] = { 29521, 29663, 29676 }, ["description"] = "Through meditation, I intend to find a route to locating Shu. In the meantime, you would benefit from practice and discipline. Your first task is the task of all trainees entering the pools: cross the balance poles to the west and ring the bell without falling into the pool. Should you fall, the pool's curse will make it difficult to get on a pole again, so you will need to return to the edge of the pool to start over. Oh, and beware the cranes.", ["objectivesText"] = "Cross the balance poles and ring the training bell.", ["rewardGold"] = 100, ["rewardXP"] = 450, ["rewardItems"] = { 74568, 74569, 74570 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5736 } }, ["questType"] = "standard", ["db2PoiMapID"] = 860, ["db2PoiUiMapID"] = 378, ["questLines"] = { { ["id"] = 573, ["name"] = "The Wandering Isle", ["orderIndex"] = 25, ["flags"] = 0 } } },
[29662] = { ["id"] = 29662, ["name"] = "Stronger Than Reeds", ["level"] = 5, ["requiredLevel"] = 4, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5736, ["mapID"] = 378, ["storyline"] = { 29662 }, ["description"] = "Gather me reeds from the nearby pools. Do not question why. Do, and then observe the results.", ["objectivesText"] = "Gather 8 Hard Tearwood Reeds . Progress: Telling you of my strength means nothing. I must show you.", ["rewardGold"] = 100, ["rewardXP"] = 450, ["rewardItems"] = { 73178 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5736 } }, ["questType"] = "standard", ["db2PoiMapID"] = 860, ["db2PoiUiMapID"] = 378, ["questLines"] = { { ["id"] = 573, ["name"] = "The Wandering Isle", ["orderIndex"] = 27, ["flags"] = 0 } } },
[29663] = { ["id"] = 29663, ["name"] = "The Lesson of the Balanced Rock", ["level"] = 5, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5736, ["mapID"] = 378, ["storyline"] = { 29663 }, ["series"] = { 29521, 29661, 29676 }, ["description"] = "I require peace to perform my meditation. Practice your arts while I meditate on Shu's location. Other monks practice balance and combat upon the balance poles in the surrounding pools. Engage them and defeat them.", ["objectivesText"] = "Defeat 6 Tushui Monks atop the balance poles.", ["rewardGold"] = 100, ["rewardXP"] = 450, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5736 } }, ["questType"] = "standard", ["db2PoiMapID"] = 860, ["db2PoiUiMapID"] = 378, ["questLines"] = { { ["id"] = 573, ["name"] = "The Wandering Isle", ["orderIndex"] = 26, ["flags"] = 0 } } },
[29664] = { ["id"] = 29664, ["name"] = "The Challenger's Fires", ["level"] = 4, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5736, ["mapID"] = 378, ["storyline"] = { 29664 }, ["series"] = { 29420, 29421, 29422, 29423 }, ["description"] = "You're strong of mind and strong of will, but you lack the skills to face me in combat. You must fight with your body, but in truth, it is your character that is being tested. Let us even the playing field. Take this torch, light it in the brazier next to me, and then use it to light the three unlit braziers around the pool.", ["objectivesText"] = "Light your Unlit Challenger's Torch at the Brazier of Flickering Flame, then use it to light the 3 braziers near Master Li Fei . Progress: You are not yet ready to face me. First, you must light the braziers.", ["rewardGold"] = 75, ["rewardXP"] = 355, ["rewardItems"] = { 75000, 75008 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5736 } }, ["questType"] = "standard", ["db2PoiMapID"] = 860, ["db2PoiUiMapID"] = 378, ["questLines"] = { { ["id"] = 573, ["name"] = "The Wandering Isle", ["orderIndex"] = 20, ["flags"] = 0 } } },
[29665] = { ["id"] = 29665, ["name"] = "From Bad to Worse", ["level"] = 9, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5736, ["mapID"] = 378, ["storyline"] = { 29665 }, ["series"] = { 29798, 29799, 30767 }, ["description"] = "After their ship crashed, evil creatures swept up from the sea to pick through the wreckage. Our aid may seem but a drop in the pond at the thought of the misfortune they've faced today. Defeat their tormentors. These people desperately need our help.", ["objectivesText"] = "Defeat 8 Deepscale Tormentors .", ["rewardGold"] = 300, ["rewardXP"] = 780, ["rewardItems"] = { 53375, 53383, 53392 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5736 } }, ["questType"] = "standard", ["db2PoiMapID"] = 860, ["db2PoiUiMapID"] = 378, ["questLines"] = { { ["id"] = 573, ["name"] = "The Wandering Isle", ["orderIndex"] = 66, ["flags"] = 0 } } },
[29666] = { ["id"] = 29666, ["name"] = "The Sting of Learning", ["level"] = 5, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5736, ["mapID"] = 378, ["storyline"] = { 29666 }, ["series"] = { 29677, 29678, 29679, 29680, 29768, 29769, 29772, 29774, 29775 }, ["description"] = "There are dangers in the pools. The latest and most vicious are the water pincers . A time has come for their numbers to be diminished, and I am no longer up to the task. If you could clear out some of the water pincers , I would be very appreciative. Beware their numbers... sometimes it's best to lure them from the pool-side rather than wading all the way in.", ["objectivesText"] = "Kill 6 Water Pincers .", ["rewardGold"] = 100, ["rewardXP"] = 450, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5736 } }, ["questType"] = "standard", ["db2PoiMapID"] = 860, ["db2PoiUiMapID"] = 378, ["questLines"] = { { ["id"] = 573, ["name"] = "The Wandering Isle", ["orderIndex"] = 30, ["flags"] = 0 } } },
[29676] = { ["id"] = 29676, ["name"] = "Finding an Old Friend", ["level"] = 5, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5736, ["mapID"] = 378, ["storyline"] = { 29676 }, ["series"] = { 29521, 29661, 29663 }, ["description"] = "It seems Shu, the spirit of water, had a play companion when he came to the pools throughout the years. An old pandaren we know as Old Man Liang . Liang moved away from the main town and stopped practicing in the pools some time ago. I am told he lives in a small house northeast of here, up the hill. Liang may know what has driven Shu away, and where the spirit might be found. Go to Liang. Ask of Shu.", ["objectivesText"] = "Speak to Old Man Liang at Liang's Retreat in the Singing Pools.", ["rewardGold"] = 25, ["rewardXP"] = 110, ["rewardItems"] = { 73183 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5736 } }, ["questType"] = "standard", ["db2PoiMapID"] = 860, ["db2PoiUiMapID"] = 378, ["questLines"] = { { ["id"] = 573, ["name"] = "The Wandering Isle", ["orderIndex"] = 28, ["flags"] = 0 } } },
[29677] = { ["id"] = 29677, ["name"] = "The Sun Pearl", ["level"] = 5, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5736, ["mapID"] = 378, ["storyline"] = { 29677 }, ["series"] = { 29666, 29678, 29679, 29680, 29768, 29769, 29772, 29774, 29775 }, ["description"] = "Shu, the spirit of water, is eternally young, as are all the spirits of Shen-zin Su. I have been friends with Shu all of my life, but I no longer have it within me to play with him. I am old, and lack the energy. For all his complexities, Shu is simple to please: he desires friendship. When I returned to play with Shu each season, I would always bring a Sun Pearl as a gift, and then we would play together. You can find a Sun Pearl in the pools to the southeast. Perhaps you can be his new friend.", ["objectivesText"] = "Retrieve the Sun Pearl . Progress: The decision to not return to the pools was a hard one. I don't think Shu ever truly understood. He does not know what it is to get older and weaker.", ["rewardGold"] = 100, ["rewardXP"] = 450, ["rewardItems"] = { 73184, 74574, 74575, 74576 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5736 } }, ["questType"] = "standard", ["db2PoiMapID"] = 860, ["db2PoiUiMapID"] = 378, ["questLines"] = { { ["id"] = 573, ["name"] = "The Wandering Isle", ["orderIndex"] = 29, ["flags"] = 0 } } },
[29678] = { ["id"] = 29678, ["name"] = "Shu, the Spirit of Water", ["level"] = 5, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5736, ["mapID"] = 378, ["storyline"] = { 29678 }, ["series"] = { 29666, 29677, 29679, 29680, 29768, 29769, 29772, 29774, 29775 }, ["description"] = "Shu, the spirit of water, is sulking in the deep pool to the north. Cross the rocks and then drop the sun pearl in the center of the pool. He will know what this means.", ["objectivesText"] = "Coax Shu, the spirit of water, into a game.", ["rewardGold"] = 25, ["rewardXP"] = 110, ["rewardItems"] = { 73791 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5736 } }, ["questType"] = "standard", ["db2PoiMapID"] = 860, ["db2PoiUiMapID"] = 378, ["questLines"] = { { ["id"] = 573, ["name"] = "The Wandering Isle", ["orderIndex"] = 31, ["flags"] = 0 } } },
[29679] = { ["id"] = 29679, ["name"] = "A New Friend", ["level"] = 5, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5736, ["mapID"] = 378, ["storyline"] = { 29679 }, ["series"] = { 29666, 29677, 29678, 29680, 29768, 29769, 29772, 29774, 29775 }, ["description"] = "He wants you to play with him. Go for it!", ["objectivesText"] = "Water walk into 5 of Shu 's Water Spouts.", ["rewardGold"] = 100, ["rewardXP"] = 450, ["rewardItems"] = { 74571, 74572, 74573 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5736 } }, ["questType"] = "standard", ["db2PoiMapID"] = 860, ["db2PoiUiMapID"] = 378, ["questLines"] = { { ["id"] = 573, ["name"] = "The Wandering Isle", ["orderIndex"] = 32, ["flags"] = 0 } } },
[29680] = { ["id"] = 29680, ["name"] = "The Source of Our Livelihood", ["level"] = 5, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5736, ["mapID"] = 378, ["storyline"] = { 29680 }, ["series"] = { 29666, 29677, 29678, 29679, 29768, 29769, 29772, 29774, 29775 }, ["description"] = "We have done as Master Shang asked of us. I will return to the temple to inform the master of our progress. You should continue south on the road to the farmlands to seek out Wugou, the spirit of earth. Ji awaits you at the Dai-Lo Farmstead, and he'll surely need your help. I must warn you, Ji can be reckless in his directness. Remember well the things I have taught you: discipline and patience.", ["objectivesText"] = "Speak to Ji at the Dai-Lo Farmstead. A cart is waiting near the road to take you there.", ["rewardGold"] = 25, ["rewardXP"] = 110, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5736 } }, ["questType"] = "standard", ["db2PoiMapID"] = 860, ["db2PoiUiMapID"] = 378, ["questLines"] = { { ["id"] = 573, ["name"] = "The Wandering Isle", ["orderIndex"] = 33, ["flags"] = 0 } } },
[29693] = { ["id"] = 29693, ["name"] = "The General's Edge", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["storyline"] = { 29693 }, ["description"] = "As you gradually gather your senses and begin to take in your surroundings, this object stands out amongst the strewn wreckage. It occurs to you that this is the first time you've seen Nazgrim's axe outside of his tight grasp. Somehow, this fact makes your predicament even more unsettling... You know that dead or alive, the General would want his weapon back in his possession.", ["objectivesText"] = "Bring Nazgrim's axe to General Nazgrim. Provided item:", ["rewardGold"] = 74000, ["rewardXP"] = 83000, ["rewardItems"] = { 73265, 80970 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[29696] = { ["id"] = 29696, ["name"] = "My Stars!", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["storyline"] = { 29696 }, ["series"] = { 29815, 29827 }, ["description"] = "A number of Kiryn's articles have been scattered around the area by wood sprites, but this one stands out as important to you. The bag once hung from her waist, loaded with throwing stars. Without them, her arsenal will be considerably diminished. If you were to retrieve the weapons from the pests that inhabit this region, it could only help your cause.", ["objectivesText"] = "Collect 100 of Kiryn's Throwing Stars from Devious Wood Sprites.", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 21100, 21746, 73367, 80765 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[29703] = { ["id"] = 29703, ["name"] = "Barrel of Monkies", ["level"] = 4, ["requiredLevel"] = 4, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["storyline"] = { 29703 }, ["description"] = "These monkeymen are driving me insane! I was just trying to get some insight into panderan brewing tactics and these hozu things keep drinking the brews before I can properly chemical test them. Can you please go take a few of them out as a lesson to the others? I'll make it worth your while.", ["objectivesText"] = "Sally Fizzlefury wants you to kill 5 drunken monkies.", ["rewardGold"] = 75, ["rewardXP"] = 355, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[29715] = { ["id"] = 29715, ["name"] = "The Witch in the Woods", ["level"] = 85, ["requiredLevel"] = 85, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["storyline"] = { 29715 }, ["series"] = { 29716, 29723 }, ["description"] = "Oh please <race>! Can you help me? Some of the village children were playing in the woods and haven't come back. Could you please keep an eye out for them if you are going out there? I told those village rascals to leave that old widow up in the woods alone. My guess is they are probably harassing her. They think she is a witch.", ["objectivesText"] = "Find An Windfur on the road north of the Jade Witch Hut.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[29722] = { ["id"] = 29722, ["name"] = "A Lesson in Bravery", ["level"] = 85, ["requiredLevel"] = 85, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["storyline"] = { 29722 }, ["description"] = "Can you help teach me to be brave like you? When we played our prank on the witch we made a bunch of Leafy Tricksters angry. I think the witch did something to them. Can you show me how you stand up to them?", ["objectivesText"] = "Defeat 8 Leafy Tricksters south of the Jade Witch Hut.", ["rewardGold"] = 204000, ["rewardXP"] = 161000, ["rewardItems"] = { 81824, 81825, 81826, 81827, 81828 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[29728] = { ["id"] = 29728, ["name"] = "Explosive Evidence", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["storyline"] = { 29728 }, ["description"] = "I must ask you to do one more thing for me, <name>. The personal effects on this ship cannot be left for others to find. We'll have to destroy it. I cobbled together some Makeshift Dynamite from the scraps you brought me. Place the dynamite anywhere on the ship, but take care not to put them too close together. They might be...uh...a little unwieldy, so you should spread them out in case of premature detonation.", ["objectivesText"] = "Plant 4 Makeshift Dynamite near the sunken ship at Sapphire's End. Makeshift Dynamite must be placed at least 10 yards apart.", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 73837 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[29732] = { ["id"] = 29732, ["name"] = "What Goes Down, Must Come Up!", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["storyline"] = { 29732 }, ["description"] = "Rivett left behind what looks to be an important piece of equipment. Along its shaft you are able to make out the words: Goblin Drone Dispenser . With a simple calibration, the device is set to deliver drones to Nazgrim's basecamp. Easy enough.... There's just one problem. The only supply crates worth transporting have fallen to the cliff ledge below the crash impact. As you ponder the issue, you see the long, coiled tail of a Cliff Glider fly by the corner of your eye...", ["objectivesText"] = "Use the Goblin Drone Dispenser near the Exposed Root to recover supplies. NOTE: Each use will require one Cliff Glider Tail.", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 73861, 73901 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[29744] = { ["id"] = 29744, ["name"] = "Some \"Pupil of Nature\"", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["storyline"] = { 29744 }, ["series"] = { 29745, 29747, 29748, 29749, 29751, 31482 }, ["description"] = "Wood sprites are not prone to wandering, so I'm surprised they ventured down as far as the mason's quarter. Something must be forcing them out of their natural habitat. These particular sprites are native to the Woods of the Lost, just north of here. I'd go myself, but I've heard those woods are haunted. So yeah, that's out. I guess we'll never know. <Weng coughs.> Orrrr... A big brave adventurer like YOU could go check it out! What do you say?", ["objectivesText"] = "Investigate the Woods of the Lost, northeast of the Greenstone Quarry.", ["rewardGold"] = 49000, ["rewardXP"] = 55000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[29757] = { ["id"] = 29757, ["name"] = "Bottletoads", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 29757 }, ["description"] = "Have you heard about the crisis we're having at the pools? Toads have moved in and are spawning like crazy! It's become a real problem for the lotus farmers. Coincidentally, I make a jam out of gelatinous toadspawn. I call it \"Bottletoads\" and it's a big hit with the kids around here. Can't keep any in stock. If you're heading to the pools, you'd be doing everyone a favor by uh... liberating some of those toad eggs. Into this bottle. For me. Just look for bubbles and scoop right in!", ["objectivesText"] = "Scoop toad eggs from 8 Gurgling Toadspawn on the top level of the Pools of Purity. Progress: \"It just ain't a party without Bottletoads!\" Hmm... no, that doesn't work. \"Bottletoads: not as gross as they sound!\"", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["rewardItems"] = { 76727 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[29758] = { ["id"] = 29758, ["name"] = "Guess Whose Back", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 29758 }, ["description"] = "<This dragon turtle's massive shell is rock-hard and covered in sharp ridges. One of the locals could almost certainly make use of it.>", ["objectivesText"] = "Bring Krosh's Back to Yan in New Cifera. Provided item:", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["rewardItems"] = { 13245, 83767 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard", ["startItems"] = { 83767 } },
[29766] = { ["id"] = 29766, ["name"] = "A Good Start", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["storyline"] = { 29766 }, ["description"] = "Regardless of our predicament, our orders stand. We are to learn the lay of this land and prepare it for Hellscream's fleet. But first, we must deal with these savages! You see these corpses I've stacked up around the camp? I want mountains of them! We are the Horde! These vermin have not learned to fear us yet, but we will fix that soon enough...", ["objectivesText"] = "Kill 4 Hozen Mudflingers , 4 Hozen Skullthumpers , and 3 Hozen Fishcatchers", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard" },
[29767] = { ["id"] = 29767, ["name"] = "Fish Fry", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["storyline"] = { 29767 }, ["description"] = "Fortune favors the bold!", ["objectivesText"] = "Collect 12 Mature Carp from Hozu Fishcatchers", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 74609, 74614 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[29768] = { ["id"] = 29768, ["name"] = "Missing Mallet", ["level"] = 6, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5736, ["mapID"] = 378, ["storyline"] = { 29768 }, ["series"] = { 29666, 29677, 29678, 29679, 29680, 29769, 29772, 29774, 29775 }, ["description"] = "<name>, I've got it! It's simple really. Let's make a ruckus so loud that there's no way he can sleep through it. Why look at that, a conveniently placed gong! Makes me think this may just be how they've awoken him in the past. We just need the matching mallet to get it ringing as loud as possible. The village leader tells me the mallet is over at the Ki-Han Brewery on the river, to the southwest. It's not far. Mind picking it up for me while I give the village some fair warning?", ["objectivesText"] = "Recover the Dai-Lo Recess Mallet at the Ki-Han Brewery. Progress: Well, they're as warned as they're going to get. Do you have the mallet?", ["rewardGold"] = 125, ["rewardXP"] = 540, ["rewardItems"] = { 74298, 74583, 74584, 74585 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5736 } }, ["questType"] = "standard", ["db2PoiMapID"] = 860, ["db2PoiUiMapID"] = 378, ["questLines"] = { { ["id"] = 573, ["name"] = "The Wandering Isle", ["orderIndex"] = 36, ["flags"] = 0 } } },
[29769] = { ["id"] = 29769, ["name"] = "Rascals", ["level"] = 6, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5736, ["mapID"] = 378, ["storyline"] = { 29769 }, ["series"] = { 29666, 29677, 29678, 29679, 29680, 29768, 29772, 29774, 29775 }, ["description"] = "I'll keep trying to find ways to wake this stubborn little guy up, but there is no shortage of trouble on the island it seems. The crops to the south are infested with virmen, rabbit-like thieves and pillagers. Rascals! They breed faster than we can kill them! I have the perfect solution for such a situation: kill them faster! With you here, <name>, that shouldn't be a problem.", ["objectivesText"] = "Kill 10 Virmen.", ["rewardGold"] = 125, ["rewardXP"] = 540, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5736 } }, ["questType"] = "standard", ["db2PoiMapID"] = 860, ["db2PoiUiMapID"] = 378, ["questLines"] = { { ["id"] = 573, ["name"] = "The Wandering Isle", ["orderIndex"] = 34, ["flags"] = 0 } } },
[29770] = { ["id"] = 29770, ["name"] = "Still Good!", ["level"] = 6, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5736, ["mapID"] = 378, ["storyline"] = { 29770 }, ["description"] = "The virmen to the south have been running off with all of our crops, but they're taking more than they can eat. They must be stockpiling them somewhere - the ones they like anyway. Will you go out and recover any of the uprooted crops you can find? I've got an island's worth of people to feed, and every single vegetable makes a difference.", ["objectivesText"] = "Recover 3 Uprooted Turnips , 3 Stolen Carrots , and 3 Pilfered Pumpkins . Progress: Ever since Wugou. the spirit of earth, fell asleep, the dirt is drying out and it's getting harder and harder to get new seeds to sprout. We need to hold on to any food we can, or the island will have hard times ahead.", ["rewardGold"] = 125, ["rewardXP"] = 540, ["rewardItems"] = { 74295, 74296, 74297, 74580, 74581, 74582 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5736 } }, ["questType"] = "standard", ["db2PoiMapID"] = 860, ["db2PoiUiMapID"] = 378, ["questLines"] = { { ["id"] = 573, ["name"] = "The Wandering Isle", ["orderIndex"] = 35, ["flags"] = 0 } } },
[29771] = { ["id"] = 29771, ["name"] = "Stronger Than Wood", ["level"] = 6, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5736, ["mapID"] = 378, ["storyline"] = { 29771 }, ["description"] = "Gather me wood planks from construction near the Ki-Han Brewery. You do not yet know the extent of my strength, so I shall display it to you.", ["objectivesText"] = "Gather 12 Discarded Wood Planks . Progress: Have you done as I've asked?", ["rewardGold"] = 125, ["rewardXP"] = 540, ["rewardItems"] = { 74301 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5736 } }, ["questType"] = "standard", ["db2PoiMapID"] = 860, ["db2PoiUiMapID"] = 378, ["questLines"] = { { ["id"] = 573, ["name"] = "The Wandering Isle", ["orderIndex"] = 37, ["flags"] = 0 } } },
[29772] = { ["id"] = 29772, ["name"] = "Raucous Rousing", ["level"] = 6, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5736, ["mapID"] = 378, ["storyline"] = { 29772 }, ["series"] = { 29666, 29677, 29678, 29679, 29680, 29768, 29769, 29774, 29775 }, ["description"] = "You ready for this, <name>? I'm thinking maybe we should have looked for something to cover our ears, but it's a bit late for that now. Just remember that the intense ringing you'll be hearing for the next few hours is the ringing sound of victory! The honor's all yours, <name>. Ring the gong whenever you're ready!", ["objectivesText"] = "Ring the gong.", ["rewardGold"] = 125, ["rewardXP"] = 540, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5736 } }, ["questType"] = "standard", ["db2PoiMapID"] = 860, ["db2PoiUiMapID"] = 378, ["questLines"] = { { ["id"] = 573, ["name"] = "The Wandering Isle", ["orderIndex"] = 38, ["flags"] = 0 } } },
[29774] = { ["id"] = 29774, ["name"] = "Not In the Face!", ["level"] = 6, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5736, ["mapID"] = 378, ["storyline"] = { 29774 }, ["series"] = { 29666, 29677, 29678, 29679, 29680, 29768, 29769, 29772, 29775 }, ["description"] = "Alright <name>, I was thinking about what we'd try next if the whole gong thing didn't work, and it came to me just like that! Water in the face always worked on me. It's got to be twice as effective for someone so dry and earthy! Mind going over and asking Shu, the spirit of water, if he'll help us out? He should be playing in the pool next to the waterfall, just on the other side of that tree.", ["objectivesText"] = "Request Shu's help in waking Wugou, the spirit of earth.", ["rewardGold"] = 125, ["rewardXP"] = 540, ["rewardItems"] = { 38713, 39017, 39046, 39078, 39332, 39376, 39430, 39452, 44350, 44351, 44352, 44353, 59249, 59250, 59251, 59288, 59289, 59290, 199210 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5736 } }, ["questType"] = "standard", ["db2PoiMapID"] = 860, ["db2PoiUiMapID"] = 378, ["questLines"] = { { ["id"] = 573, ["name"] = "The Wandering Isle", ["orderIndex"] = 39, ["flags"] = 0 } } },
[29775] = { ["id"] = 29775, ["name"] = "The Spirit and Body of Shen-zin Su", ["level"] = 6, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5736, ["mapID"] = 378, ["storyline"] = { 29775 }, ["series"] = { 29666, 29677, 29678, 29679, 29680, 29768, 29769, 29772, 29774 }, ["description"] = "Well, that wraps it up here, doesn't it <name>? Now that we've got these two roused and all friendly towards you, we just need to get them back to the Temple of Five Dawns. You go ahead. I'm going to say my goodbyes, then I'll follow you up shortly.", ["objectivesText"] = "Bring Shu and Wugou, the spirits of water and earth, to the Temple of Five Dawns. A cart is waiting near the road to take you there.", ["rewardGold"] = 125, ["rewardXP"] = 540, ["rewardItems"] = { 74577, 74578, 74579 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5736 } }, ["questType"] = "standard", ["db2PoiMapID"] = 860, ["db2PoiUiMapID"] = 378, ["questLines"] = { { ["id"] = 573, ["name"] = "The Wandering Isle", ["orderIndex"] = 40, ["flags"] = 0 } } },
[29776] = { ["id"] = 29776, ["name"] = "Morning Breeze Village", ["level"] = 6, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5736, ["mapID"] = 378, ["storyline"] = { 29776 }, ["series"] = { 29778 }, ["description"] = "The fourth and final spirit is Dafeng, the spirit of air. When he is not in the skies, he can be found on the Ridge of Laughing Winds to the west. I've sent both Aysa and Ji to help you find him. When you are ready, I will summon winds to carry you to the top of the temple. From there, cross the bridges to the west and find Ji in Morning Breeze Village.", ["objectivesText"] = "Meet with Ji Firepaw in Morning Breeze Village.", ["rewardGold"] = 125, ["rewardXP"] = 540, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5736 } }, ["questType"] = "standard", ["db2PoiMapID"] = 860, ["db2PoiUiMapID"] = 378, ["questLines"] = { { ["id"] = 573, ["name"] = "The Wandering Isle", ["orderIndex"] = 41, ["flags"] = 0 } } },
[29777] = { ["id"] = 29777, ["name"] = "Tools of the Enemy", ["level"] = 7, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5736, ["mapID"] = 378, ["storyline"] = { 29777 }, ["description"] = "The hozen have stolen our brushes and are painting over our scrolls of wisdom with their own wisdoms, if you can call them that. If you're here to help, stop them and bring our brushes back before they can do more harm.", ["objectivesText"] = "Retrieve 8 Paint Soaked Brushes . Progress: I do not wish to disparage the hozen for their aspirations - each race must walk its own path. In this moment, however, they are bringing harm to our bodies and our culture. That is a line that cannot be crossed.", ["rewardGold"] = 175, ["rewardXP"] = 630, ["rewardItems"] = { 74615 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5736 } }, ["questType"] = "standard", ["db2PoiMapID"] = 860, ["db2PoiUiMapID"] = 378, ["questLines"] = { { ["id"] = 573, ["name"] = "The Wandering Isle", ["orderIndex"] = 42, ["flags"] = 0 } } },
[29778] = { ["id"] = 29778, ["name"] = "Rewritten Wisdoms", ["level"] = 7, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5736, ["mapID"] = 378, ["storyline"] = { 29778 }, ["series"] = { 29776 }, ["description"] = "<name>, we must help Elder Shaopai. There are few more deserving of our kindness. On the way here, you surely noticed the scrolls of wisdom hanging in the grotto to the south. The hozen have defiled many of them, and sadly, they are not recoverable. We will deal with the problem directly - burn the defiled scrolls. Wipe the hozen writings away entirely. Do not worry for Elder Shaopai. The people shall come together and help him rewrite the wisdoms in time. I shall see to that.", ["objectivesText"] = "Burn 5 Defaced Scroll of Wisdom.", ["rewardGold"] = 175, ["rewardXP"] = 630, ["rewardItems"] = { 74594, 74595, 74596 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5736 } }, ["questType"] = "standard", ["db2PoiMapID"] = 860, ["db2PoiUiMapID"] = 378, ["questLines"] = { { ["id"] = 573, ["name"] = "The Wandering Isle", ["orderIndex"] = 43, ["flags"] = 0 } } },
[29779] = { ["id"] = 29779, ["name"] = "The Direct Solution", ["level"] = 7, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5736, ["mapID"] = 378, ["storyline"] = { 29779 }, ["series"] = { 29780, 29781, 29784, 29785 }, ["description"] = "Alright <name>, this is the second time we've had to deal with ravaging hozen. I think it's time we take care of this problem the Huojin way. No more patience. No more mediation. We go to the source. We're going into the hozen village to the north and we're punishing those smelly troublemakers. I've been looking forward to a chance to fight by your side again, <name>.", ["objectivesText"] = "Kill 20 hozen in Fe-Feng Village. Progress: The time for kindness is done. We have monkeys to kill.", ["rewardGold"] = 175, ["rewardXP"] = 630, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5736 } }, ["questType"] = "standard", ["db2PoiMapID"] = 860, ["db2PoiUiMapID"] = 378, ["questLines"] = { { ["id"] = 573, ["name"] = "The Wandering Isle", ["orderIndex"] = 45, ["flags"] = 0 } } },
[29780] = { ["id"] = 29780, ["name"] = "Do No Evil", ["level"] = 7, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5736, ["mapID"] = 378, ["storyline"] = { 29780 }, ["series"] = { 29779, 29781, 29784, 29785 }, ["description"] = "<name>, I need you to understand that the way of the Huojin is not the way of violence. When fighting is needed, we will not hesitate, but when fighting is not needed, neither do we instigate. However, the direct solution is often cutting the head off the snake, as they say. The hozen have a leader instigating these attacks. If we remove Ruk-Ruk , we won't have to wipe the hozen out entirely. I know you are not of the Huojin, but are you with me in what must be done, <name>?", ["objectivesText"] = "Kill Ruk-ruk , the Fe-Feng Chief.", ["rewardGold"] = 175, ["rewardXP"] = 630, ["rewardItems"] = { 19182, 21326, 31761, 31762, 31816, 31817, 31818, 39773, 39792, 39795, 39837, 57256, 57257, 57258, 59249, 59250, 59251, 59288, 59289, 59290, 74591, 74592, 74593, 74606, 74607, 74608, 199210 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5736 } }, ["questType"] = "standard", ["db2PoiMapID"] = 860, ["db2PoiUiMapID"] = 378, ["questLines"] = { { ["id"] = 573, ["name"] = "The Wandering Isle", ["orderIndex"] = 46, ["flags"] = 0 } } },
[29781] = { ["id"] = 29781, ["name"] = "Monkey Advisory Warning", ["level"] = 7, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5736, ["mapID"] = 378, ["storyline"] = { 29781 }, ["series"] = { 29779, 29780, 29784, 29785 }, ["description"] = "The monkeys have been stealing from the village during their attacks. We should be fine without some of the extra food stores, but the idea of monkeys with fireworks... I'm a little bit concerned. Not to mention, who knows when some fireworks will come in handy? Help me recover the stolen fireworks from their village, <name>?", ["objectivesText"] = "Recover 8 Stolen Firework Bundles . Progress: I'm somewhat impressed they hadn't set their village on fire with these things.", ["rewardGold"] = 175, ["rewardXP"] = 630, ["rewardItems"] = { 74631 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5736 } }, ["questType"] = "standard", ["db2PoiMapID"] = 860, ["db2PoiUiMapID"] = 378, ["questLines"] = { { ["id"] = 573, ["name"] = "The Wandering Isle", ["orderIndex"] = 47, ["flags"] = 0 } } },
[29782] = { ["id"] = 29782, ["name"] = "Stronger Than Bone", ["level"] = 7, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5736, ["mapID"] = 378, ["storyline"] = { 29782 }, ["description"] = "This giant jade tiger pillar doesn't seem to fit in amidst the hozen buildings. What it does seem is very hard. Very solid. You know just the person to bring this to.", ["objectivesText"] = "Bring the Jade Tiger Pillar to Jojo Ironbrow in Morning Breeze Village. Provided item:", ["rewardGold"] = 175, ["rewardXP"] = 630, ["rewardItems"] = { 74587, 74588, 74589, 74590, 76174 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5736 } }, ["questType"] = "standard", ["db2PoiMapID"] = 860, ["db2PoiUiMapID"] = 378, ["questLines"] = { { ["id"] = 573, ["name"] = "The Wandering Isle", ["orderIndex"] = 48, ["flags"] = 0 } } },
[29783] = { ["id"] = 29783, ["name"] = "Stronger Than Stone", ["level"] = 7, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5736, ["mapID"] = 378, ["storyline"] = { 29783 }, ["description"] = "Gather me stone blocks from the Ridge of Laughing Winds to the south. You have seen my strength twice, yet I still spy doubt within your eyes. It will not last.", ["objectivesText"] = "Gather 12 Abandoned Stone Blocks . Progress: The strength of the body cannot exist without the strength of the mind.", ["rewardGold"] = 175, ["rewardXP"] = 630, ["rewardItems"] = { 74624 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5736 } }, ["questType"] = "standard", ["db2PoiMapID"] = 860, ["db2PoiUiMapID"] = 378, ["questLines"] = { { ["id"] = 573, ["name"] = "The Wandering Isle", ["orderIndex"] = 44, ["flags"] = 0 } } },
[29784] = { ["id"] = 29784, ["name"] = "Balanced Perspective", ["level"] = 7, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5736, ["mapID"] = 378, ["storyline"] = { 29784 }, ["series"] = { 29779, 29780, 29781, 29785 }, ["description"] = "Aysa has been meditating on the lake since we've arrived, all her thoughts focused on Dafeng. I don't know what she hopes to discover out there, but she's no fool, and Master Shang Xi has entrusted this task with her. You will need to cross the ropes leading from the end of the dock to reach her. It shall test your balance, but I think you're up to the task, <name>.", ["objectivesText"] = "Cross the ropes and speak to Aysa Cloudsinger on Morning Breeze Lake.", ["rewardGold"] = 175, ["rewardXP"] = 630, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5736 } }, ["questType"] = "standard", ["db2PoiMapID"] = 860, ["db2PoiUiMapID"] = 378, ["questLines"] = { { ["id"] = 573, ["name"] = "The Wandering Isle", ["orderIndex"] = 49, ["flags"] = 0 } } },
[29785] = { ["id"] = 29785, ["name"] = "Dafeng, the Spirit of Air", ["level"] = 7, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5736, ["mapID"] = 378, ["storyline"] = { 29785 }, ["series"] = { 29779, 29780, 29781, 29784 }, ["description"] = "If you listen long enough, the wind will carry the answer to you. Dafeng , the spirit of air, has been scared from the skies by Zhao-Ren, the Onyx Serpent. He hides within the Chamber of Whispers, at the south side of the plateau. Go to him. Ji and I will join you there.", ["objectivesText"] = "Speak to Dafeng , the spirit of air, in the Chamber of Whispers.", ["rewardGold"] = 175, ["rewardXP"] = 630, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5736 } }, ["questType"] = "standard", ["db2PoiMapID"] = 860, ["db2PoiUiMapID"] = 378, ["questLines"] = { { ["id"] = 573, ["name"] = "The Wandering Isle", ["orderIndex"] = 50, ["flags"] = 0 } } },
[29786] = { ["id"] = 29786, ["name"] = "Battle for the Skies", ["level"] = 7, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5736, ["mapID"] = 378, ["storyline"] = { 29786 }, ["series"] = { 29787 }, ["description"] = "Dafeng, the spirit of air, is terrified by Zhao-Ren , the Onyx Serpent. We must help him face that fear, or face it for him ourselves. When I told Ji of the serpent, he said he had an idea and would begin preparations outside of the chamber. Despite his rash nature, I must admit, I envy his passion and conviction. Let us go outside and confront the Onyx Serpent.", ["objectivesText"] = "Defeat Zhao-Ren , the Onyx Serpent with the aid of Ji's fireworks.", ["rewardGold"] = 175, ["rewardXP"] = 630, ["rewardItems"] = { 74586 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5736 } }, ["questType"] = "standard", ["db2PoiMapID"] = 860, ["db2PoiUiMapID"] = 378, ["questLines"] = { { ["id"] = 573, ["name"] = "The Wandering Isle", ["orderIndex"] = 51, ["flags"] = 0 } } },
[29787] = { ["id"] = 29787, ["name"] = "Worthy of Passing", ["level"] = 8, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5736, ["mapID"] = 378, ["storyline"] = { 29787 }, ["series"] = { 29786 }, ["description"] = "The four elemental spirits will help you speak with the land and uncover its plight, but first, I have one small task to ask of you. Join me, my pupil. Accompany this old pandaren to the western grove.", ["objectivesText"] = "Defeat the Guardian of the Elders .", ["rewardGold"] = 225, ["rewardXP"] = 700, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5736 } }, ["questType"] = "standard", ["db2PoiMapID"] = 860, ["db2PoiUiMapID"] = 378, ["questLines"] = { { ["id"] = 573, ["name"] = "The Wandering Isle", ["orderIndex"] = 52, ["flags"] = 0 } } },
[29788] = { ["id"] = 29788, ["name"] = "Unwelcome Nature", ["level"] = 8, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5736, ["mapID"] = 378, ["storyline"] = { 29788 }, ["series"] = { 29789, 29790, 29791, 29792, 30591 }, ["description"] = "You faced forest sprites in the Dawning Valley, but the forest sprites in this grove are a different breed. Crueler and more dangerous. If you would clear some of these sprites out, the spirits would thank you.", ["objectivesText"] = "Kill 8 Thornbranch Scamps .", ["rewardGold"] = 225, ["rewardXP"] = 700, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5736 } }, ["questType"] = "standard", ["db2PoiMapID"] = 860, ["db2PoiUiMapID"] = 378, ["questLines"] = { { ["id"] = 573, ["name"] = "The Wandering Isle", ["orderIndex"] = 54, ["flags"] = 0 } } },
[29789] = { ["id"] = 29789, ["name"] = "Small, But Significant", ["level"] = 8, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5736, ["mapID"] = 378, ["storyline"] = { 29789 }, ["series"] = { 29788, 29790, 29791, 29792, 30591 }, ["description"] = "I am tired, <name>. I must rest. We have a ritual to perform, but we require some of the charms from this grove. If you wander the grove, you should see them all over hanging from the trees. If it does not offend one as young as you, will you permit me to sit and recover my strength while you gather these charms?", ["objectivesText"] = "Retrieve 8 Kun-Pai Ritual Charms . Progress: Rest feels good. The burdens of life have become a great weight after so many years.", ["rewardGold"] = 225, ["rewardXP"] = 700, ["rewardItems"] = { 74634 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5736 } }, ["questType"] = "standard", ["db2PoiMapID"] = 860, ["db2PoiUiMapID"] = 378, ["questLines"] = { { ["id"] = 573, ["name"] = "The Wandering Isle", ["orderIndex"] = 53, ["flags"] = 0 } } },
[29790] = { ["id"] = 29790, ["name"] = "Passing Wisdom", ["level"] = 8, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5736, ["mapID"] = 378, ["storyline"] = { 29790 }, ["series"] = { 29788, 29789, 29791, 29792, 30591 }, ["description"] = "This journey shall soon be yours to undertake without me. Stay for a few moments and listen to an old man's words. Let my knowledge serve as a foundation for yours, that you might be greater than I ever was.", ["objectivesText"] = "Listen to Master Shang Xi .", ["rewardGold"] = 225, ["rewardXP"] = 700, ["rewardItems"] = { 74597, 74598, 74599 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5736 } }, ["questType"] = "standard", ["db2PoiMapID"] = 860, ["db2PoiUiMapID"] = 378, ["questLines"] = { { ["id"] = 573, ["name"] = "The Wandering Isle", ["orderIndex"] = 55, ["flags"] = 0 } } },
[29791] = { ["id"] = 29791, ["name"] = "The Suffering of Shen-zin Su", ["level"] = 8, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5736, ["mapID"] = 378, ["storyline"] = { 29791 }, ["series"] = { 29788, 29789, 29790, 29792, 30591 }, ["description"] = "Now is not the time to grieve. The balloon is ready, and Shen-zin Su awaits. We shall be the first pandaren to speak to Shen-zin Su in hundreds of years. It is a great honor.", ["objectivesText"] = "Board the Hot Air Balloon and Speak to Shen-zin Su.", ["rewardGold"] = 225, ["rewardXP"] = 700, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5736 } }, ["questType"] = "standard", ["db2PoiMapID"] = 860, ["db2PoiUiMapID"] = 378, ["questLines"] = { { ["id"] = 573, ["name"] = "The Wandering Isle", ["orderIndex"] = 56, ["flags"] = 0 } } },
[29792] = { ["id"] = 29792, ["name"] = "Bidden to Greatness", ["level"] = 9, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5736, ["mapID"] = 378, ["storyline"] = { 29792 }, ["series"] = { 29788, 29789, 29790, 29791, 30591 }, ["description"] = "It is up to all of you to remove the thorn from the side of Shen-zin Su. Do not let your differences come between you. Trust in each other. Within the Pei-Wu Forest is a lone hermit. Head directly to his hut. He knows intimately of the dark things that now lurk in the trees.", ["objectivesText"] = "Open the gates to Pei-Wu Forest.", ["rewardGold"] = 300, ["rewardXP"] = 780, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5736 } }, ["questType"] = "standard", ["db2PoiMapID"] = 860, ["db2PoiUiMapID"] = 378, ["questLines"] = { { ["id"] = 573, ["name"] = "The Wandering Isle", ["orderIndex"] = 57, ["flags"] = 0 } } },
[29793] = { ["id"] = 29793, ["name"] = "Evil from the Seas", ["level"] = 9, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5736, ["mapID"] = 378, ["storyline"] = { 29793 }, ["series"] = { 29796 }, ["description"] = "I do not know what this evil is that is infesting the forest, <name>, but I know exactly how to deal with it. So do you, I think.", ["objectivesText"] = "Kill 8 Darkened Horrors or Darkened Terrors.", ["rewardGold"] = 300, ["rewardXP"] = 780, ["rewardItems"] = { 74606, 74607, 74608 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5736 } }, ["questType"] = "standard", ["db2PoiMapID"] = 860, ["db2PoiUiMapID"] = 378, ["questLines"] = { { ["id"] = 573, ["name"] = "The Wandering Isle", ["orderIndex"] = 61, ["flags"] = 0 } } },
[29794] = { ["id"] = 29794, ["name"] = "None Left Behind", ["level"] = 9, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5736, ["mapID"] = 378, ["storyline"] = { 29794 }, ["description"] = "Your friend has been doing everything she can to save my crew. I'm deeply appreciative. We're still dealing with more than we can handle here: quenching the fires on the wreckage, getting my people out, fighting off these evil sea creatures, and trying to prevent the prisoners from escaping. We're simply in over our heads. I still have men on the ship that we need to get clear before the wreckage collapses on them. I know this is asking a lot, but can you help?", ["objectivesText"] = "Rescue 3 Injured Sailors .", ["rewardGold"] = 300, ["rewardXP"] = 780, ["rewardItems"] = { 74603, 74604, 74605 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5736 } }, ["questType"] = "standard", ["db2PoiMapID"] = 860, ["db2PoiUiMapID"] = 378, ["questLines"] = { { ["id"] = 573, ["name"] = "The Wandering Isle", ["orderIndex"] = 64, ["flags"] = 0 } } },
[29795] = { ["id"] = 29795, ["name"] = "Stocking Stalks", ["level"] = 9, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5736, ["mapID"] = 378, ["storyline"] = { 29795 }, ["series"] = { 30589, 30590 }, ["description"] = "My men are malnourished, injured, and exhausted, but they are Horde. Every one will fight to their dying breath. As our new ally, we will stand by you when the time comes, but we would stand stronger with weapons. I have my men out gathering bamboo stalks to fashion into spears. If you can spare the effort, we could use the extra pair of capable hands.", ["objectivesText"] = "Gather 10 Broken Bamboo Stalks . Progress: The Horde does not back down from a fight.", ["rewardGold"] = 300, ["rewardXP"] = 780, ["rewardItems"] = { 80806 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5736 } }, ["questType"] = "standard", ["db2PoiMapID"] = 860, ["db2PoiUiMapID"] = 378, ["questLines"] = { { ["id"] = 573, ["name"] = "The Wandering Isle", ["orderIndex"] = 59, ["flags"] = 0 } } },
[29796] = { ["id"] = 29796, ["name"] = "Urgent News", ["level"] = 9, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5736, ["mapID"] = 378, ["storyline"] = { 29796 }, ["series"] = { 29793 }, ["description"] = "I'm sure Aysa won't love this plan, but it's the only plan we've got. Would you mind being the bearer of bad news for me, <name>? She needs to know what we're doing so she can get everyone to safety.", ["objectivesText"] = "Speak to Delora Lionheart at the Wreck of the Skyseeker.", ["rewardGold"] = 300, ["rewardXP"] = 780, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5736 } }, ["questType"] = "standard", ["db2PoiMapID"] = 860, ["db2PoiUiMapID"] = 378, ["questLines"] = { { ["id"] = 573, ["name"] = "The Wandering Isle", ["orderIndex"] = 63, ["flags"] = 0 } } },
[29797] = { ["id"] = 29797, ["name"] = "Medical Supplies", ["level"] = 9, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5736, ["mapID"] = 378, ["storyline"] = { 29797 }, ["description"] = "We need supplies to tend to our wounded, but the supply crates containing them were scattered in the crash. If you can bring back any crates you find, I would be very grateful.", ["objectivesText"] = "Recover 8 Crates of Medical Supplies. Progress: Did you find the boxes I spoke of?", ["rewardGold"] = 300, ["rewardXP"] = 780, ["rewardItems"] = { 74958 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5736 } }, ["questType"] = "standard", ["db2PoiMapID"] = 860, ["db2PoiUiMapID"] = 378, ["questLines"] = { { ["id"] = 573, ["name"] = "The Wandering Isle", ["orderIndex"] = 65, ["flags"] = 0 } } },
[29798] = { ["id"] = 29798, ["name"] = "An Ancient Evil", ["level"] = 9, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5736, ["mapID"] = 378, ["storyline"] = { 29798 }, ["series"] = { 29665, 29799, 30767 }, ["description"] = "<name>, I was looking for you! One of the escaping sailors just spotted Aysa in the wreckage of the ship, facing some enormous beast. She might need your help - you should go to her, quickly!", ["objectivesText"] = "Defeat the Vordraka, the Deep Sea Nightmare .", ["rewardGold"] = 300, ["rewardXP"] = 780, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5736 } }, ["questType"] = "standard", ["db2PoiMapID"] = 860, ["db2PoiUiMapID"] = 378, ["questLines"] = { { ["id"] = 573, ["name"] = "The Wandering Isle", ["orderIndex"] = 67, ["flags"] = 0 } } },
[29799] = { ["id"] = 29799, ["name"] = "The Healing of Shen-zin Su", ["level"] = 9, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5736, ["mapID"] = 378, ["storyline"] = { 29799 }, ["series"] = { 29665, 29798, 30767 }, ["description"] = "This is more horrific than I imagined, but we can handle this. We need to gather the healers and close the wound. We need to save Shen-zin Su. Find any healers you can! Rescue them, relieve them - whatever you need to do to get them over here healing the wound. Keep the healers safe at all costs!", ["objectivesText"] = "Rescue and defend healers until Shen-zin Su's wound is healed.", ["rewardGold"] = 300, ["rewardXP"] = 780, ["rewardItems"] = { 74600, 74601, 74602 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5736 } }, ["questType"] = "standard", ["db2PoiMapID"] = 860, ["db2PoiUiMapID"] = 378, ["questLines"] = { { ["id"] = 573, ["name"] = "The Wandering Isle", ["orderIndex"] = 69, ["flags"] = 0 } } },
[29800] = { ["id"] = 29800, ["name"] = "New Allies", ["level"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5736, ["mapID"] = 378, ["storyline"] = { 29800 }, ["series"] = { 31450 }, ["description"] = "<name>, I did what had to be done. And the plan worked. Things could have been much worse had we not acted. I only wish Aysa could understand that. There will be plenty of time for reflection, but for now, we need to return to the Temple of Five Dawns. We need to let them know that Shen-zin Su has been saved, and we need to sort out the fates of these new allies.", ["objectivesText"] = "Return to the Temple of Five Dawns. A cart is waiting near the Wreck of the Skyseeker to take you there.", ["rewardGold"] = 350, ["rewardXP"] = 840, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5736 } }, ["questType"] = "standard", ["db2PoiMapID"] = 860, ["db2PoiUiMapID"] = 378, ["questLines"] = { { ["id"] = 573, ["name"] = "The Wandering Isle", ["orderIndex"] = 70, ["flags"] = 0 } } },
[29809] = { ["id"] = 29809, ["name"] = "Efficient Excavations", ["level"] = 83, ["requiredLevel"] = 83, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["storyline"] = { 29809 }, ["series"] = { 27925, 27926, 27928, 27941, 28132 }, ["description"] = "This manual describes outlandish theories on how to most efficiently manage large groups of workers as they engage in massive excavation projects. After a quick skim of the material, it becomes clear to you that the author of the book is the figure in charge of the over-aggressive pillagers here. A map on the back cover indicates that the author has a bunker in the southwest region of Uldum . Perhaps an introduction is in order.", ["objectivesText"] = "Bring ' Efficient Excavations ' to Belloc Brightblade in Schnottz's Landing. Provided item:", ["rewardGold"] = 8600, ["rewardXP"] = 11000, ["rewardItems"] = { 62768 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[29831] = { ["id"] = 29831, ["name"] = "DEPRECATED: Terror on the High Seas", ["level"] = 85, ["requiredLevel"] = 85, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["storyline"] = { 29831 }, ["description"] = "Word has reached Stormwind of terrible crimes committed against ships carrying Alliance citizens. The Horde stands accused of stopping Alliance ships, boarding them, mistreating passengers, and stealing cargo. Heroes of the Alliance, your help is needed to determine the truth of these allegations! Seek out Grand Admiral Jes-Tereth at Stormwind Keep if you would answer the call.", ["objectivesText"] = "Speak to Grand Admiral Jes-Tereth in the throne room of Stormwind Keep.", ["rewardXP"] = 6940, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[29832] = { ["id"] = 29832, ["name"] = "DEPRECATED: Gathering Evidence", ["level"] = 85, ["requiredLevel"] = 85, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["storyline"] = { 29832 }, ["description"] = "A ship called the Bravery routinely ferries passengers and cargo from Stormwind port to Rut'theran Village, right outside Darnassus. Well, the ship has just returned with distressing news. Both passengers and crew say that Horde vessels stopped and boarded the Bravery in the waters off Teldrassil, mistreated those on board, and stole some of the cargo before turning the ship around. We have to find out what happened, <name>. Would you go to Stormwind Harbor and listen to the stories of the passengers?", ["objectivesText"] = "Visit Stormwind Harbor and speak with Sentinel Eloria , Lumian Starwhisper , Nayeth Frostmoon , and Finelar Mistwalker .", ["rewardXP"] = 69400, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[29837] = { ["id"] = 29837, ["name"] = "Sacred Scroll", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["storyline"] = { 29837 }, ["series"] = { 29841, 29842 }, ["description"] = "The unfamiliar markings on this parchment have an elegance about them that Yoggtord and his gang don't seem capable of. You suspect that, like everything else these Hozu possess, this is stolen merchandise. Perhaps the original owner of the scroll is still nearby...", ["objectivesText"] = "Bring the Illegible Scroll to Lorewalker Cho. Provided item:", ["rewardGold"] = 24500, ["rewardXP"] = 28000, ["rewardItems"] = { 74768 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[29842] = { ["id"] = 29842, ["name"] = "Seeking Answers", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["storyline"] = { 29842 }, ["series"] = { 29837, 29841 }, ["description"] = "<Cho endures your stream of questions before speaking.> So much to ponder, traveler... You first must learn how to ask before your mind can discern the truth. I have completed my meditations for today, but my candles remain at the Cairn of Blood. Go there. Clear your mind. We will speak again when you are prepared to hear my words.", ["objectivesText"] = "Use the candles to meditate at the Cairn of Blood.", ["rewardGold"] = 74000, ["rewardXP"] = 83000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[29854] = { ["id"] = 29854, ["name"] = "DEPRECATED: Claiming Kalimdor", ["level"] = 85, ["requiredLevel"] = 85, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["storyline"] = { 29854 }, ["description"] = "Victory shall soon be ours! Our forces have engaged the enemy all over Kalimdor. Warchief Garrosh Hellscream has commanded all able-bodied <race>s to report for duty in support of our latest offensive. Make your way to Grommash Hold in Orgrimmar and present yourself to General Nazgrim for immediate assignment! For the Horde!", ["objectivesText"] = "Report to General Nazgrim at Grommash Hold in Orgrimmar .", ["rewardXP"] = 69400, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[29857] = { ["id"] = 29857, ["name"] = "DEPRECATED: Where Are Those Ships?", ["level"] = 85, ["requiredLevel"] = 85, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["storyline"] = { 29857 }, ["description"] = "With most of our fleet leading the attack on Theramore and engaging the enemy elsewhere, we're going to need more ships to complete our blockade of Kalimdor. The warchief ordered the shipwrights at Zoram'gar Outpost in Ashenvale to work overtime to meet the demand, but none of the new craft have arrived yet. Travel there and put the question to their overseer. Tell them the warchief wants his ships!", ["objectivesText"] = "Speak to Overseer Moxx at Zoram'gar Outpost in Ashenvale and kill 6 Night Elf Raiders on the ships outside the town.", ["rewardXP"] = 69400, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[29867] = { ["id"] = 29867, ["name"] = "DEPRECATED: Shadow Hunter Urko'jin", ["level"] = 5, ["requiredLevel"] = 5, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["storyline"] = { 29867 }, ["description"] = "We need to fill the remaining slots in the new blockade fleet before the night elves can reestablish their spy network in the city. The Darkspears have yet to contribute much to the war effort, but if we can convince Shadow Hunter Urko'jin to add his forces to the fleet, that will change. Problem is, Urko'jin won't go to war without the blessing of the spirits. Pay a visit to Darkspear Hold in the Echo Isles, retrieve the totem of seafaring, and deliver it to Urko'jin in the Valley of Spirits.", ["objectivesText"] = "Retrieve the Totem of Seafaring from Darkspear Hold in the Echo Isles and bring it to Shadow Hunter Urko'jin in Orgrimmar's Valley of Spirits.", ["rewardItems"] = { 75047 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[29871] = { ["id"] = 29871, ["name"] = "Clever Ashyo", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 29871 }, ["series"] = { 29577, 29581 }, ["description"] = "I'm not sure where Clever Ashyo got his \"Clever\" title from. All jinyu are clever, and I wouldn't say that he's any more clever than most of them. Quite the opposite, actually. At least he's a capable fighter. He did well enough at Tian Monastery to be selected for our training mission. If you want to help him look for the Hidden Master, you can find him along the Valley's northern border.", ["objectivesText"] = "Find Clever Ashyo .", ["rewardGold"] = 10200, ["rewardXP"] = 12900, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[29873] = { ["id"] = 29873, ["name"] = "Ken-Ken", ["level"] = 85, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 29873 }, ["series"] = { 30079, 30081 }, ["description"] = "So... Ken-Ken . The hozen. Personally, I'm impressed he's progressed so far in his training. He's got a brain between his ears, which is more than can be said for most of his kind. He said he was headed east, but, seeing as we're already on the far east side of the valley, I can't imagine he went too far from here. Look for him at Zhu's Watch, in Krasarang Wilds , down the path to the south. See what he's found.", ["objectivesText"] = "Find Ken-Ken .", ["rewardGold"] = 9400, ["rewardXP"] = 6940, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[29874] = { ["id"] = 29874, ["name"] = "Kang Bramblestaff", ["level"] = 85, ["requiredLevel"] = 86, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 29874 }, ["description"] = "Kang's pride regularly becomes overconfidence, which often leads him down dangerous paths. His current path is as dangerous as any - he is headed deep into the Krasarang Wilds . I wouldn't normally ask a favor of a stranger, but... would you make sure that he is well? It would give me relief to know that a brave <race> was looking out for him.", ["objectivesText"] = "Find Kang Bramblestaff .", ["rewardGold"] = 9400, ["rewardXP"] = 6940, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[29875] = { ["id"] = 29875, ["name"] = "Kang Bramblestaff", ["level"] = 85, ["requiredLevel"] = 86, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 29875 }, ["description"] = "Kang's pride regularly becomes overconfidence, which often leads him down dangerous paths. His current path is as dangerous as any - he is headed deep into the Krasarang Wilds . I wouldn't normally ask a favor of a stranger, but... would you make sure that he is well? It would give me relief to know that a brave <race> was looking out for him.", ["objectivesText"] = "Find Kang Bramblestaff .", ["rewardGold"] = 9400, ["rewardXP"] = 6940, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[29886] = { ["id"] = 29886, ["name"] = "Zen Healing", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["storyline"] = { 29886 }, ["description"] = "Your friend Taylor is in critical shape. Unfortunately, his wounds are tainted by hozen poison, which is very difficult to cure. Luckily, through many generations of fighting the hozen, my people have developed medicines to treat such injuries. The flowers growing on the surface of Glass Lake are needed to make the antidote. <name>, go quickly and bring back some blooms. Your Admiral's life depends on it.", ["objectivesText"] = "Collect 6 Zen Lotus .", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 75217 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[29895] = { ["id"] = 29895, ["name"] = "Trail of the White Pawn", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["storyline"] = { 29895 }, ["description"] = "Although the cloak is ragged and torn, there is no mistaking the fine tailoring and the King's royal crest. You should show it to your Alliance commander.", ["objectivesText"] = "Show the cloak to Admiral Taylor at Pearlfin Village in the Jade Forest . Provided item:", ["rewardGold"] = 49000, ["rewardXP"] = 55000, ["rewardItems"] = { 79812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["startItems"] = { 79812 } },
[29924] = { ["id"] = 29924, ["name"] = "Kill Kher Shan", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["storyline"] = { 29924 }, ["description"] = "Kher Shan is one big dooker. Grooked all my sons! Ick Ick, Nab Nab, Eet Eet, Bitty Bitty, and the others I can't remember. Wikket wanna help hozen? Go grook Kher Shan ! The dooker's over there. < Nibi Nibi points to the east.>", ["objectivesText"] = "Kill Kher Shan in Tigers' Wood.", ["rewardXP"] = 111000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard" },
[29933] = { ["id"] = 29933, ["name"] = "The Bees' Knees", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["storyline"] = { 29933 }, ["description"] = "You really hozen friend, wikket? Let's see, hmm? Hozen at Grookin' Hill all outta slicky bait. Tigerflies' legs stay twitchy in water - make best bait! Bo Bo sick from stings. Wikket get bait and take to Grookin.", ["objectivesText"] = "Collect 30 Bug Legs from Tigerflies in Tigers' Wood. Progress: Slicky food!", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 76173 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard" },
[29938] = { ["id"] = 29938, ["name"] = "Friends and Foes", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["storyline"] = { 29938 }, ["description"] = "These ookin' Jinyu grookin Kah Kah's nephews! Wikket once kill many hozen. Now wikket kill many jinyu.", ["objectivesText"] = "Kill 7 Riverstride Jinyu at the Slicky Stream.", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 84105 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard" },
[29971] = { ["id"] = 29971, ["name"] = "The Scouts Return", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["storyline"] = { 29971 }, ["description"] = "Hey, while you were out our scouts came back. And get this, they found some Alliance kid. You should probably go debrief them.", ["objectivesText"] = "Speak with Shokia in Grookin Hill.", ["rewardGold"] = 9800, ["rewardXP"] = 11100, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard" },
