[30006] = { ["id"] = 30006, ["name"] = "The Darkness Around Us", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["storyline"] = { 30006 }, ["description"] = "Despite our best efforts, the sha broke the seals around the main temple. If we cannot hold them back here, their darkness will spread to the rest of the Jade Forest. We need your help immediately. Kill any sha creatures that you see. They should not be difficult to find.", ["objectivesText"] = "Kill 15 sha invaders. Progress: We are holding ground, but just barely.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3281 } },
[30027] = { ["id"] = 30027, ["name"] = "The Lesson of the Iron Bough", ["level"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "class" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5736, ["mapID"] = 378, ["storyline"] = { 30027 }, ["series"] = { 29404, 29405, 29406, 29408, 29409, 29410, 29524, 30033, 30034, 30035, 30036, 30037, 30038, 30039, 30040, 30041, 30042, 30043, 30044, 30045 }, ["description"] = "First, you will need a weapon suited to your talents. Retrieve a staff from one of the weapon racks below, bring it to me, and show me that you know how to equip it properly.", ["objectivesText"] = "Retrieve and equip a Trainee's Staff .", ["rewardGold"] = 15, ["rewardItems"] = { 73209, 77278, 77279 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5736 } }, ["questType"] = "standard", ["db2PoiMapID"] = 860, ["db2PoiUiMapID"] = 378, ["questLines"] = { { ["id"] = 573, ["name"] = "The Wandering Isle", ["orderIndex"] = 0, ["flags"] = 0 } } },
[30033] = { ["id"] = 30033, ["name"] = "The Lesson of the Iron Bough", ["level"] = 1, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "class" }, ["sharable"] = false, ["expansion"] = 4, ["mapID"] = 378, ["storyline"] = { 30033 }, ["series"] = { 29404, 29405, 29406, 29408, 29409, 29410, 29524, 30027, 30034, 30035, 30036, 30037, 30038, 30039, 30040, 30041, 30042, 30043, 30044, 30045 }, ["description"] = "First, you will need weapons suited to your talents. Retrieve a spellblade and a hand fan from one of the weapon racks below, bring it to me, and show me that you know how to hold it properly.", ["objectivesText"] = "Retrieve and equip a Trainee's Spellblade and a Trainee's Hand Fan .", ["rewardGold"] = 15, ["rewardItems"] = { 76390, 76392 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2PoiMapID"] = 860, ["db2PoiUiMapID"] = 378, ["questLines"] = { { ["id"] = 573, ["name"] = "The Wandering Isle", ["orderIndex"] = 1, ["flags"] = 0 } } },
