[30058] = { ["id"] = 30058, ["name"] = "Mothallus!", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 30058 }, ["description"] = "The esteemed Journeyman Chu would appear to have created a monster. It is silken death with wings. Mothallus . You have already faced its brood. Now we ask that you help us face the creature itself. Please, <class>, venture into the pit and rifle the bait. This will bring the beast to you. Our mothfighters will assist you as you need, though silk tends to stick to them more than most so you may need to help them, should they become overwhelmed.", ["objectivesText"] = "Bait and defeat Mothallus . Progress: Have you vanquished the beast?", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["rewardItems"] = { 88028, 88029, 88030, 88031, 88032, 88033, 88034, 90622 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[30059] = { ["id"] = 30059, ["name"] = "The Moth Rebellion", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 30059 }, ["description"] = "Oh... oh good! A <class>! Could you help me? I created a strain of vile monsters during my experiments to improve silk output. The result was a full-scale moth rebellion. Can you use your <class>iness and destroy some of these mutants?", ["objectivesText"] = "Kill 6 Mutated Silkmoths and 8 Tiny Mutated Silkmoths . Progress: Master Goh keeps telling me I need to relax and that failure is part of learning. But this is a dangerous failure. The kind that might get people killed.", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[30063] = { ["id"] = 30063, ["name"] = "Behind the Masks", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["storyline"] = { 30063 }, ["description"] = "The sha may seem unstoppable, but this is not true. Their masks seem to be the source of their power. When a sha and its mask are separated, the creature's essence is banished back to its own realm. Bring me intact masks, for I wish to study them further. Do be careful. I'm sure the sha will not part with them easily.", ["objectivesText"] = "Collect 8 Masks of Doubt . Progress: Please handle the masks carefully. If you are not careful, they will attempt to consume you.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 77419 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3281 } },
[30064] = { ["id"] = 30064, ["name"] = "Saving the Sutras", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["storyline"] = { 30064 }, ["description"] = "My adepts had to abandon their studies when the sha invasion began. Unfortunately, they left their books scattered around the temple grounds. These priceless works of knowledge must be saved! The sutras can be found near the Training Pit and the Adept's Ring to the northeast.", ["objectivesText"] = "Collect 6 Ancient Sutras . Progress: How are the sutras? Are they damaged?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 77432 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3281 } },
[30065] = { ["id"] = 30065, ["name"] = "Arrows of Fortune", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["storyline"] = { 30065 }, ["description"] = "Our war supplies grow low, but especially needed are additional arrows. Our serpent riders are skilled marksmen, but they can do little without ammunition. We need someone to brave the battlefields and retrieve any undamaged arrows to refill our stores. Every arrow you retrieve will be used wisely.", ["objectivesText"] = "Collect 8 Defender's Arrows . Progress: Were you able to find any arrows?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 77452 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3281 } },
[30066] = { ["id"] = 30066, ["name"] = "Hidden Power", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["storyline"] = { 30066 }, ["description"] = "Our temple defenders have battled relentlessly for hours. No doubt they grow tired. I will give you mantras to deliver to our fighters. Do not be fooled by these pieces of paper. These ancient scriptures hold words of untold power.", ["objectivesText"] = "Deliver Ancient Mantras to 6 Yu'lon Guardians or Yu'lon Adepts. Progress: Words hold great power. Use them wisely.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 77475 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3281 } },
[30067] = { ["id"] = 30067, ["name"] = "The Shadow of Doubt", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["storyline"] = { 30067 }, ["description"] = "A terrible manifestation of the sha has appeared to the south. It is trying to destroy an ancient relic, the Bell of a Thousand Whispers. This bell has never been rung in the temple's history, for it is rumored to be an ancient instrument of power. Please go and defeat this demon where it stands! We must save this relic!", ["objectivesText"] = "Defeat the Shadow of Doubt . Progress: The bell is said to contain the voices of a thousand fallen temple priests.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3281 } },
[30068] = { ["id"] = 30068, ["name"] = "Flames of the Void", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["storyline"] = { 30068 }, ["description"] = "Do you see the violent black and white flames erupting all around the temple? The greater our doubt, the stronger they rage. Unchecked, they will devour the entire temple. We have but one hope. Take flight on one of our war serpents. Fly it near the pure springs of water, and then douse the fires with water from the pools.", ["objectivesText"] = "Fly your War Serpent near Pure Water Springs, then douse 6 Void Flames with the water carried in its mouth. Progress: These fires burn unlike anything in our world.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3281 } },
[30072] = { ["id"] = 30072, ["name"] = "Where Silk Comes From", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 30072 }, ["series"] = { 32035 }, ["description"] = "Would you like to be a Silkmaster for a day? The first thing you'll need are fresh mulberry leaves . You can find them in our grove of mulberry bushes to the northwest. Next you will need to feed them to a hungry silkworm in our feeding pit to the west. And finally you should get some raw silk from our processing hut on the south side of our farm. Have fun!", ["objectivesText"] = "Obtain Mulberry Leaves , feed 5 Hungry Silkworms , and get Raw Silk . Progress: Have you found all of the items? Did you pay close attention to our process?", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["rewardItems"] = { 77455, 77456, 84339, 84340, 84341, 84342, 84343 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[30085] = { ["id"] = 30085, ["name"] = "Into the Brewery", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 30085 }, ["series"] = { 30075, 30078, 31327 }, ["description"] = "We need to find out what's going on inside that brewery, <name>! We may have cleared out some of the bigger pests, but I'm certain there's plenty more where they came from. Gather up a few of your friends, and meet me inside!", ["objectivesText"] = "Speak to Chen Stormstout inside the Stormstout Brewery .", ["rewardGold"] = 10200, ["rewardXP"] = 12900, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "dungeon" },
[30086] = { ["id"] = 30086, ["name"] = "The Search for the Hidden Master", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 30086 }, ["description"] = "Oh, hello. Are you looking for the owner of this place? Then look to the pandaren up at the top of the stairs. I'm just a visitor... like you. Now if you'll excuse me, my friends and I are trying to decide something. We can talk again afterwards.", ["objectivesText"] = "Listen to Xiao and his companions.", ["rewardXP"] = 12900, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[30087] = { ["id"] = 30087, ["name"] = "FLAG - Kung Fu Intro", ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 30087 }, ["description"] = "Oh, hello. Are you looking for the owner of this place? Then look to the pandaren up at the top of the stairs. I'm just a visitor... like you. Now if you'll excuse me, my friends and I trying to decide something. We can talk again afterwards.", ["objectivesText"] = "Listen to Xiao and his companions.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[30121] = { ["id"] = 30121, ["name"] = "Search Party", ["level"] = 86, ["requiredLevel"] = 86, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 30121 }, ["series"] = { 30179 }, ["description"] = "I sent a diplomat to look for allies in the ruins east of here. My diplomat has not returned and now Kang tells me this jungle is filled with a sinister people known as the mogu. Chezin is my friend and Leza's brother. To lose a brother would cause her to give in to despair. She already has enough to worry about with her fever. Could you investigate the ruins east of here and find out what happened?", ["objectivesText"] = "Search the Krasari Ruins for Chezin Dawnchaser .", ["rewardGold"] = 9800, ["rewardXP"] = 11100, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard" },
[30122] = { ["id"] = 30122, ["name"] = "Silver Filigree Flask", ["requiredLevel"] = 1, ["faction"] = "none", ["requiredProfessions"] = { "alchemy" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["storyline"] = { 30122 }, ["description"] = "You have found a beautiful silver flask decorated with ornate filigree. With the right materials and your skill in alchemy, it could become quite magical.", ["objectivesText"] = "Fill the vial with a potent alchemical mixture.", ["rewardItems"] = { 72234, 72235, 75525, 78912 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[30134] = { ["id"] = 30134, ["name"] = "Wild Things", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 30134 }, ["series"] = { 30135 }, ["description"] = "Welcome to the Order of the Cloud Serpent, <race>. I can see from the spark in your eye that you wish to join the Order. Let me get a good look at you. < Elder Anli gently holds your head and gazes at your face.> Hmm. I see honesty and earnestness in your heart. You have journeyed far to come here, but I am afraid you must go yet further. Your path into the Order begins now. Speak to Instructor Tong at Windward Isle to the northeast to take the first step.", ["objectivesText"] = "Find Instructor Tong at Windward Isle in the Jade Forest .", ["rewardGold"] = 57000, ["rewardXP"] = 118000, ["rewardItems"] = { 38131, 38132, 38169, 38170, 38171, 38172, 199210 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 5549, ["name"] = "Order of the Cloud Serpent", ["orderIndex"] = 0, ["flags"] = 0 } } },
[30135] = { ["id"] = 30135, ["name"] = "Beating the Odds", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 30135 }, ["series"] = { 30134 }, ["description"] = "At first, the Slitherscale were too frightened to approach the wild serpents. Then, I caught them snatching the eggs under the cover of night. Now, they are slaughtering adults and hatchlings alike! If we do not do something, these gentle creatures will be completely wiped out. Then there won't even be an Order of the Cloud Serpent to join! Go and slay these vile Slitherscales, and then we will talk.", ["objectivesText"] = "Kill 8 Slitherscale Rippers or Slitherscale Eggdrinkers. Progress: The Order rarely meddles with the natural balance on this island, but it is too important to save the serpents.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 5549, ["name"] = "Order of the Cloud Serpent", ["orderIndex"] = 1, ["flags"] = 0 } } },
[30136] = { ["id"] = 30136, ["name"] = "Empty Nests", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 30136 }, ["description"] = "When the attacks began, the young hatchlings scattered in terror. They are roaming around the island, lost and scared. If you want to help, take this rope and leash the lost little ones. Take them back to their nests. Return them home.", ["objectivesText"] = "Leash and return 6 Windward Hatchlings to their nests. Progress: Did you return the hatchlings to their nests?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 78947 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 5549, ["name"] = "Order of the Cloud Serpent", ["orderIndex"] = 2, ["flags"] = 0 } } },
[30138] = { ["id"] = 30138, ["name"] = "Choosing the One", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 30138 }, ["description"] = "I have examined each egg, <name>. Out of the lot that you brought me, I have chosen the three eggs with the most promise. You may choose only one egg to take with you. Are you ready to make your final selection?", ["objectivesText"] = "Speak to Instructor Tong at Windward Isle in the Jade Forest .", ["rewardGold"] = 57000, ["rewardXP"] = 118000, ["rewardItems"] = { 78960, 78961, 78962, 79802, 85429, 85430 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 5549, ["name"] = "Order of the Cloud Serpent", ["orderIndex"] = 4, ["flags"] = 0 } } },
[30139] = { ["id"] = 30139, ["name"] = "The Rider's Journey", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 30139 }, ["series"] = { 30140, 30141, 30142 }, ["description"] = "Excellent, just excellent! I will return the other eggs to their nests, undisturbed. In the meantime, deliver your egg to Instructor Skythorn at The Arboretum.", ["objectivesText"] = "Return to Instructor Skythorn at the Arboretum in the Jade Forest . Progress: The wild cloud serpents live in a delicate balance with nature. Their rare eggs are quite vulnerable to enemies.", ["rewardGold"] = 57000, ["rewardXP"] = 118000, ["rewardItems"] = { 78962 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 5549, ["name"] = "Order of the Cloud Serpent", ["orderIndex"] = 5, ["flags"] = 0 } } },
[30140] = { ["id"] = 30140, ["name"] = "The Rider's Journey", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 30140 }, ["series"] = { 30139, 30141, 30142 }, ["description"] = "Excellent, just excellent! I will return the other eggs to their nests, undisturbed. In the meantime, deliver your egg to Instructor Skythorn at The Arboretum.", ["objectivesText"] = "Return to Instructor Skythorn at the Arboretum in the Jade Forest . Progress: The wild cloud serpents live in a delicate balance with nature. Their rare eggs are quite vulnerable to enemies.", ["rewardGold"] = 57000, ["rewardXP"] = 118000, ["rewardItems"] = { 78960 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 5549, ["name"] = "Order of the Cloud Serpent", ["orderIndex"] = 6, ["flags"] = 0 } } },
[30143] = { ["id"] = 30143, ["name"] = "They Grow Like Weeds", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 30143 }, ["series"] = { 30144, 30145, 30187 }, ["description"] = "Ahh, it is you again, <name>. Instructor Windblade is looking for you. You can find her on the ridge to the east. She has some news about your cloud serpent.", ["objectivesText"] = "Speak to Instructor Windblade at The Arboretum. Progress: You are doing well, trainee.", ["rewardGold"] = 57000, ["rewardXP"] = 118000, ["rewardItems"] = { 93229 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 5549, ["name"] = "Order of the Cloud Serpent", ["orderIndex"] = 9, ["flags"] = 0 } } },
[30144] = { ["id"] = 30144, ["name"] = "Flight Training: Ring Round-Up", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 30144 }, ["series"] = { 30143, 30145, 30187 }, ["description"] = "Now that your serpent is fully grown, you are ready to begin flight training. As with all novices, you must start at the beginning. Your first task is simple. Fly through 6 of the cloud rings between the spires to the east.", ["objectivesText"] = "Fly through 6 cloud rings while riding your cloud serpent. Progress: How did your first flight go?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 93229 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 5549, ["name"] = "Order of the Cloud Serpent", ["orderIndex"] = 10, ["flags"] = 0 } } },
[30145] = { ["id"] = 30145, ["name"] = "Flight Training: Full Speed Ahead", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 30145 }, ["series"] = { 30143, 30144, 30187 }, ["description"] = "The next task will be a little harder. Are you ready?", ["objectivesText"] = "Follow Instructor Windblade .", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 93229 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 5549, ["name"] = "Order of the Cloud Serpent", ["orderIndex"] = 11, ["flags"] = 0 } } },
[30146] = { ["id"] = 30146, ["name"] = "Snack Time", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5785, ["storyline"] = { 30146 }, ["description"] = "Cloud serpents love to eat, and one of their favorite treats is the sugar minnow . These fish can be found in salt or fresh water anywhere in Pandaria. I trust you have some skill in fishing, and your own fishing pole to catch them? Bring me a fresh catch and I'm sure the hungry beasts around here will be very grateful.", ["objectivesText"] = "Fish 10 Sugar Minnow from any fresh or salt water in Pandaria. Progress: Did you find a good place to fish?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 74866, 79046 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3284 } },
[30147] = { ["id"] = 30147, ["name"] = "Fragments of the Past", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5785, ["storyline"] = { 30147 }, ["description"] = "The Order of the Cloud Serpent's history stretches back thousands of years, and although we have tried to preserve the old ways, there are ancient techniques that have been lost over time. You can help us recover some of this knowledge by searching Pandaria's dig sites for clues to our past. Use your archaeology skill to survey around Pandaria and bring me whatever you find.", ["objectivesText"] = "Visit archaeology dig sites around Pandaria and use your survey ability to retrieve 6 Serpentrider Relics . Progress: How did the excavation go?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 79049 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3284 } },
[30148] = { ["id"] = 30148, ["name"] = "Just a Flesh Wound", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5785, ["storyline"] = { 30148 }, ["description"] = "Many of the baby hatchlings at Windward Isle have been injured as a result of all the fighting. I have been told that you may be skilled in the art of first aid. Please go northeast and use some of your best bandages to save the injured hatchlings.", ["objectivesText"] = "Use Windwool Bandages or Heavy Windwool Bandages to heal 8 Injured Hatchlings at Windward Isle. Progress: What is your report of the situation at Windward Isle?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 34722, 72985, 72988, 82829, 82830 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3284 } },
[30150] = { ["id"] = 30150, ["name"] = "Sweet as Honey", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5785, ["storyline"] = { 30150 }, ["description"] = "<The hatchling scampers about, then whines and whimpers.> From the cloud serpent's behavior, you have a hunch that it wants a sweet treat. The fragrant trees in The Arboretum are home to many honey hives. It will be a simple matter to collect combs from the nearby honeykeepers.", ["objectivesText"] = "Collect 30 Honeycomb from Angry Honeykeepers in The Arboretum. Progress: <The hatchling spins around in glee as you return.>", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 79030 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3284 } },
[30151] = { ["id"] = 30151, ["name"] = "Catch!", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5785, ["storyline"] = { 30151 }, ["description"] = "<The hatchling looks up at you with a bored, listless expression.> You have a feeling the serpent is tired of being cooped up all day. How about playing a little game of catch?", ["objectivesText"] = "Use the Bouncy Ball . Then, catch and return the ball to your hatchling 8 times. Progress: <The serpent watches you curiously.>", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 23247, 26008, 26022, 26034, 32233, 33235, 33241, 34599, 46007, 67414, 79043 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3284 } },
[30152] = { ["id"] = 30152, ["name"] = "The Sky Race", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5785, ["storyline"] = { 30152 }, ["description"] = "The time for the great race is upon us! Traverse the course among the spires and pass through the checkered flags on each of the 10 balloon checkpoints . Make sure to pass underneath the finish line when you are done. The competition will be fierce, but I wish you luck. Speak to me when you are ready to begin.", ["objectivesText"] = "Complete the Sky Race by flying through 10 checkpoints , then passing underneath the Finish Line at The Arboretum.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 32863, 90537 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3284 } },
[30154] = { ["id"] = 30154, ["name"] = "The Easiest Way To A Serpent's Heart", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5785, ["storyline"] = { 30154 }, ["description"] = "<The hatchling scowls at you.> Uh-oh, looks like someone is in a bad mood today! Luckily, you know just the thing that will cheer up the little beast. Cloud serpents love the taste of tiger meat, but the tender flanks can be... challenging... to acquire. Luckily, you recall there are some fat, juicy tigers to the northwest, on Windward Isle. Sure, you might suffer some scratches and a little mauling, but it's all worth it for your serpent, right?", ["objectivesText"] = "Collect 5 Tiger Flanks . Progress: Looks like the task is done.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 82869, 85282 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3284 } },
[30155] = { ["id"] = 30155, ["name"] = "Restoring the Balance", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5785, ["storyline"] = { 30155 }, ["description"] = "The situation at the islands remains dire, <name>. The Slitherscale saurok have not responded to our attempts at peace, so only one option remains. In order to protect the wild cloud serpents, we must rid the island of their presence. Only then can the cloud serpents be left to live in peace.", ["objectivesText"] = "Kill 8 Slitherscale Rippers or Slitherscale Eggdrinkers. Progress: The poachers will wipe out the cloud serpents completely if they are not stopped.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3284 } },
[30156] = { ["id"] = 30156, ["name"] = "Feeding Time", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5785, ["storyline"] = { 30156 }, ["description"] = "<The serpent darts forward and bites your fingers.> Ouch! It seems, without a doubt, that the little beast is hungry. You recall that some meaty-looking turtles can be found on the wild cloud serpent island to the northeast. Perhaps some turtle meat will fill the hatchling's voracious appetite.", ["objectivesText"] = "Collect 3 Saltback Meat and feed them to your hatchling companion. Progress: <The serpent looks at you with hungry eyes.>", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 79027, 79028 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3284 } },
[30157] = { ["id"] = 30157, ["name"] = "Emptier Nests", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5785, ["storyline"] = { 30157 }, ["description"] = "Oh, thank goodness, another cloud serpent trainer! I just received word that the wild hatchlings at Windward Isle to the northeast are in serious trouble! While the adults fight those terrible saurok, who is watching the cute little babies? No one, that's who! WE HAVE TO SAVE THEM! I'm sending every trainer I can find to go and help. If you aren't too busy, can you make sure the hatchlings are safely delivered back to their mothers' nests?", ["objectivesText"] = "Leash and return 6 Windward Hatchlings to their nests. Progress: How can you resist their cute little faces?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 78947 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3284 } },
[30158] = { ["id"] = 30158, ["name"] = "Disarming the Enemy", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5785, ["storyline"] = { 30158 }, ["description"] = "If we are to stop the poachers, we need to take more aggressive action. If we can remove the enemies' primary tools for killing and capturing serpents, we may be able to stop their operation altogether. I need you to go into their territory on the eastern end of Windward Isle and steal their weapons. A cat without claws cannot strike.", ["objectivesText"] = "Collect 5 Slitherscale Harpoons . Progress: Is it done?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 79025 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3284 } },
[30159] = { ["id"] = 30159, ["name"] = "Preservation", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5785, ["storyline"] = { 30159 }, ["description"] = "Oh no! We must stop them! <name>, is it? The Order needs your help! Do you know what those horrible Slitherscale saurok are doing? They have the audacity to steal cloud serpent eggs straight from the matriarch's nests! While the cloud serpents become ever rarer, those brutes are... are... <Suchi takes a deep breath.> ...they're eat their eggs for dinner! It's horrible! Go to Windward Isle to the northeast and recover any unbroken eggs that you can. As students of the Order, it's our duty!", ["objectivesText"] = "Collect 8 Stolen Eggs . Progress: Will those nasty Slitherscale saurok never give up?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 79067 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3284 } },
[30160] = { ["id"] = 30160, ["name"] = "A Ruby Shard for Ella", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 30160 }, ["objectivesText"] = "Progress: Why <name>, it's nice to see you again.", ["rewardItems"] = { 79264 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[30168] = { ["id"] = 30168, ["name"] = "Thieving Raiders", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 30168 }, ["description"] = "Saurok! These vile creatures are obsessed with killing and stealing. They attacked our settlement without provocation or warning. Please, <class>, can you aid us? Help us recover our lost possessions from these Riverblade raiders that march along the river and we will gladly reward you.", ["objectivesText"] = "Recover 5 pieces of Pillaged Jinyu Loot . Progress: I think they even stole my holy spittoon.", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["rewardItems"] = { 78958, 81532, 81534, 81535, 81536 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard" },
[30169] = { ["id"] = 30169, ["name"] = "Raid Leader Slovan", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 30169 }, ["description"] = "The raiders are led by a particularly violent saurok known as Slovan . The Crane Temple usually comes to our aid when he attacks but now we find ourselves outmatched and outmaneuvered. Please, <class>, aid us by destroying this raid leader. You can find him in his den behind the Krasari Falls.", ["objectivesText"] = "Kill Slovan . Progress: Slovan has always been a nuisance, but with the Crane Temple's defenses down he has become a true threat.", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["rewardItems"] = { 88387 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard" },
[30187] = { ["id"] = 30187, ["name"] = "Flight Training: In Due Course", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 30187 }, ["series"] = { 30143, 30144, 30145 }, ["description"] = "Now that you have learned the basics of the race, you should go learn the course. Explore the spires and collect a race flag from each of the checkpoints . Fly through each checkered flag to collect it.", ["objectivesText"] = "Fly through 10 Race Flags at the Checkpoints floating above the Mistveil Sea. Progress: Do you have what it takes to compete... and win?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 85429, 93229 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 5549, ["name"] = "Order of the Cloud Serpent", ["orderIndex"] = 12, ["flags"] = 0 } } },
[30188] = { ["id"] = 30188, ["name"] = "Riding the Skies", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 30188 }, ["description"] = "I can no longer call myself your teacher, <name>. You have proven yourself worthy of your cloud serpent. Today, you shall join our ranks. Are you ready?", ["objectivesText"] = "Join the Order of the Cloud Serpent.", ["rewardGold"] = 57000, ["rewardXP"] = 118000, ["rewardItems"] = { 79802, 85429, 85430, 89155 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 5549, ["name"] = "Order of the Cloud Serpent", ["orderIndex"] = 13, ["flags"] = 0 } } },
[30189] = { ["id"] = 30189, ["name"] = "A Lovely Apple for Ella", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 30189 }, ["objectivesText"] = "Progress: How are you today, <name>?", ["rewardItems"] = { 79267, 79320 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[30190] = { ["id"] = 30190, ["name"] = "Sprite Plight", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 30190 }, ["description"] = "Sprites again! I hate these things. We need to stop them before they hurt someone or burn down half of the village! If you see any of the pests, please deal with them!", ["objectivesText"] = "Kill 8 Slateskin Troublemakers .", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[30191] = { ["id"] = 30191, ["name"] = "Steer Clear of the Beer Here", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 30191 }, ["description"] = "Someone left some beer out up on the southern rise and now the sprites have developed a taste for our brew. They've been sneaking into town all morning, stealing whatever kegs they find. Bring back what you can. A pandaren worker without brew is just... it won't be very productive. We need the men in good spirits.", ["objectivesText"] = "Recover 10 Stolen Mistfall Kegs . Progress: Did you find any of the stolen kegs?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 85778 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[30192] = { ["id"] = 30192, ["name"] = "My Town, It's on Fire", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 30192 }, ["description"] = "I don't know if you noticed, but my town is burning... The sprites have started kicking the braziers! They're going to set fire to the whole town! Please help us! Stamp out any fires you see!", ["objectivesText"] = "Put out 30 Brazier Fires . Progress: I'm at my wit's end...", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 85782 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[30193] = { ["id"] = 30193, ["name"] = "Meating Expectations", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 30193 }, ["description"] = "Hard workers deserve hearty meals, but I'm all out of good meat! Can you head out into the forest and get me some fresh gazelle meat?", ["objectivesText"] = "Retrieve 10 slabs of Fairlands Gazelle Meat . Progress: No shortage of mouths to feed, that's for sure!", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 79244, 83157 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[30194] = { ["id"] = 30194, ["name"] = "Encroaching Storm", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 30194 }, ["description"] = "The villagers have lost another yak this morning to one of the thundermaw wolves from across the river. The wolves grow bold. This is a sign that they are breeding beyond the vale's ability to sustain them. It's time to thin their numbers again. If you are willing to aid me in this, you would have my sincere appreciation.", ["objectivesText"] = "Kill 8 Thundermaw Wolves. Progress: It is upon us to not diminish the gazelle in the forest too greatly, or it will be upon us that the wolves come to our doorstep seeking new food.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 76897 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[30195] = { ["id"] = 30195, ["name"] = "Blooming Blossoms", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 30195 }, ["description"] = "Would you do a humble merchant a favor? I've been needin' to refresh my stock of eternal blossoms . They grow in the woods nearby. Could you help me out, perhaps?", ["objectivesText"] = "Collect 10 Eternal Blossoms . Progress: Was your flower-gathering bountiful?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 244172 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[30196] = { ["id"] = 30196, ["name"] = "Lushroom Rush", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 30196 }, ["description"] = "Building a new village makes for hungry workers it seems! I have a hearty stew recipe prepared, but I need some lushrooms from the Tu Shen Burial Ground to the east. Apparently there are roused spirits causing trouble up there though, and I'm not very well suited for the violent life. If you're heading up the burial grounds today, could you collect some lushrooms for me?", ["objectivesText"] = "Collect 12 Lushrooms . Progress: I can hear the hungry bellies rumbling throughout the village!", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 85681 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[30197] = { ["id"] = 30197, ["name"] = "Cart Ride", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["storyline"] = { 30197 }, ["description"] = "The vale has been quiet all morning. I'm sending Rook with a cart of supplies out to the XXX Village. You should join him.", ["objectivesText"] = "Ride a delivery cart to XXX Village.", ["rewardGold"] = 57000, ["rewardXP"] = 118000, ["rewardItems"] = { 52919, 52964 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
