[30226] = { ["id"] = 30226, ["name"] = "Blood on the Rise", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 30226 }, ["description"] = "A small group of mogu have been sighted on Ruin's Rise, to the north. Extinguish them.", ["objectivesText"] = "Kill 8 Shao-Tien mogu on Ruin's Rise.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[30227] = { ["id"] = 30227, ["name"] = "Wulon, the Granite Sentinel", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 30227 }, ["description"] = "One of the quilen statues in Guo-Lai Halls came to life and nearly killed my precious Kun. I won't have it! No one threatens my Kun. I want you to go in there and smash the thing to pieces. I'd do it myself, but I need to attend to my lover's wounds first.", ["objectivesText"] = "Kill Wulon , the Granite Sentinel. Progress: Kun's doing okay. Have you smashed that statue for me yet?", ["rewardGold"] = 228000, ["rewardXP"] = 294000, ["rewardItems"] = { 90625 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[30228] = { ["id"] = 30228, ["name"] = "Troubling the Troublemakers", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 30228 }, ["description"] = "The wood sprites are back. I need you to kill them before they cause anymore trouble.", ["objectivesText"] = "Kill 8 Stonebark sprites.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[30234] = { ["id"] = 30234, ["name"] = "Vicejaw", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 30234 }, ["description"] = "Vicejaw ! Sounds absolutely violent, does it not? I came up with it myself, and I think it's very suiting. I tried to wrestle my staff away from him for hours, but he simply would not let go! Okay, it was really more like a few seconds. I like to be truthful to my friends, even if it makes my stories significantly more boring. Anyway, would you be so kind as to release your oh-so-potent wrath upon this crocolisk with a vice-like jaw, and then kindly bring my staff back? Preferably in-tact!", ["objectivesText"] = "Kill Vicejaw and return Ren's Longstaff. Progress: I all truth, this is not the first crocolisk I have named Vicejaw , or even the eleventh. But it's such a fitting name, who can blame me?", ["rewardGold"] = 228000, ["rewardXP"] = 294000, ["rewardItems"] = { 90625 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[30235] = { ["id"] = 30235, ["name"] = "Quid Pro Quo", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 30235 }, ["description"] = "Quid is a very powerful and very ancient water spirit, though you might not know it with his child-like ways. This morning, Quid nearly killed several villagers in the bar when he jokingly caused several of the water kegs to explode. As long as the water flows, Quid will remain. He cannot be slain. But he can be reminded that we do not take his dangerous antics in jest. Would you be willing to carry this message to him on behalf of the village?", ["objectivesText"] = "Defeat Quid , the Spirit of the Misty Falls. Progress: The power of an ancient spirit in the mind of a child is a quite dangerous thing.", ["rewardGold"] = 228000, ["rewardXP"] = 294000, ["rewardItems"] = { 87807, 90625 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[30238] = { ["id"] = 30238, ["name"] = "Return to Rest", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 30238 }, ["description"] = "The spirits of our ancestors are reliving one of the most revered battles in our history at the Tu Shen Burial Grounds to the east. Do as I ask, <race>, and honor their gravestones. Remind them that they are respected even these many years later, and that they are deserving of peaceful rest.", ["objectivesText"] = "Honor 6 Pandaren Gravestones.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[30239] = { ["id"] = 30239, ["name"] = "Lao-Fe the Slavebinder", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 30239 }, ["series"] = { 30237 }, ["description"] = "You can hear the spirit of Lao-Fe , the Slavebinder shouting taunts from the cave at the top of Tu Shen Burial Mound. Defeating him will surely serve to ensure victory for the spirits of the pandaren monks.", ["objectivesText"] = "Kill the Spirit of Lao-Fe , the Slavebinder. Progress: Lao-Fe the Slavebinder was ruthless, even for a mogu. He was one of the first overthrown during the rising of the monks at Tu Shen, and that victory spurred the monks on for the rest of the uprising.", ["rewardGold"] = 228000, ["rewardXP"] = 294000, ["rewardItems"] = { 90625 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[30240] = { ["id"] = 30240, ["name"] = "Survival Ring: Flame", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 30240 }, ["description"] = "This is one of the challenges I put upon my warriors to keep them strong and fast. Let's see how you fare. Survive the ring for 60 seconds without getting pushed out or killed. Stay on your toes.", ["objectivesText"] = "Enter the Survival Ring and survive for 60 seconds without leaving. Progress: The constant danger in the ring prepares us for life or death fighting we have to endure outside the wall.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3280 } },
[30242] = { ["id"] = 30242, ["name"] = "Survival Ring: Blades", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 30242 }, ["description"] = "This is one of the challenges I put upon my warriors to keep them strong and fast. Let's see how you fare. Survive the ring for 60 seconds without getting pushed out or killed. Stay on your toes.", ["objectivesText"] = "Enter the Survival Ring and survive for 60 seconds without leaving. Progress: The constant danger in the ring prepares us for life or death fighting we have to endure outside the wall.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 87890, 89230 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3280 } },
[30243] = { ["id"] = 30243, ["name"] = "Mantid Under Fire", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 30243 }, ["series"] = { 30244, 30249 }, ["description"] = "The mantid are attacking again, and we're a bit short-handed up on the wall. In hopes that you'd help, I saved one of the more fun posts for you: the hot oil! It's a bit more violent and a bit less scandalous than it sounds. It's simple really. Get up on the wall, find one of the oil stations, and dump it on any of the mantid pouring up against the wall. It's very effective.", ["objectivesText"] = "Use a Hot Oil Cauldron to kill 80 mantid near the Gate of the Setting Sun. Progress: The hard part is the cleanup. Fortunately, you're not responsible for that.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 82807 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3280 } },
[30244] = { ["id"] = 30244, ["name"] = "Along the Serpent's Spine", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 30244 }, ["series"] = { 30243, 30249 }, ["description"] = "There are mantid on top of the wall. The defenders on the ramparts are calling for help!", ["objectivesText"] = "Kill 10 Krik'thik mantid on the Gate of the Setting Sun. Progress: What are you doing here? They need you on the wall!", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3280 } },
[30245] = { ["id"] = 30245, ["name"] = "Lost Scouts", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 30245 }, ["series"] = { 30248 }, ["description"] = "We sent some scouts towards the Five Sisters to the north to try and find whatever mogu leader has risen up to direct their movements in the valley. Few have returned. I'd like to think they're just off downing too much ale or being irresponsible with some young pandaren, but they may actually be in some trouble. Can you scout for the scouts? And see if they've turned up any information on that leader while you're at it?", ["objectivesText"] = "Recover 3 Shado-Pan Scout reports. Progress: Go. Missing scouts. Bad mogu leader. Remember?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3280 } },
[30246] = { ["id"] = 30246, ["name"] = "Upon the Ramparts", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 30246 }, ["series"] = { 30251 }, ["description"] = "Some of the mantid have made it on top of the wall. There's some risk they'll route the soldiers we have posted there if their numbers are large enough. I need you to get on top of the wall and help clear out any that have broken through.", ["objectivesText"] = "Kill 10 Krik'thik mantid on top of the Gate of the Setting Sun. Progress: We're spread thin defending so many fronts. This is where the best of us shine.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3280 } },
[30247] = { ["id"] = 30247, ["name"] = "Roll Club: Vale of Eternal Blossoms", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["storyline"] = { 30247 }, ["description"] = "Follow the flags. Make the checkpoints. Round the loop. Get back to me before your time is up. Speak to me when you're ready to roll.", ["objectivesText"] = "Complete the Vale of Eternal Blossoms roll course.", ["rewardGold"] = 228000, ["rewardXP"] = 294000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[30248] = { ["id"] = 30248, ["name"] = "The Butcher", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 30248 }, ["series"] = { 30245 }, ["description"] = "Scouts reports place the displaced Shao-Tien Imperion at the north end of the wall. Angi Autumnlight spelled out your goal in no uncertain terms: find this leader and kill him.", ["objectivesText"] = "Kill Bai-Jin the Butcher . Progress: I've heard that you were passed information regarding the location of the new mogu leader. Did you go all Anji on his arse?", ["rewardGold"] = 228000, ["rewardXP"] = 294000, ["rewardItems"] = { 53226, 53232, 53256, 63003, 63004, 63005, 63006, 90625 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3280 } },
[30249] = { ["id"] = 30249, ["name"] = "Under the Setting Sun", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 30249 }, ["series"] = { 30243, 30244 }, ["description"] = "A giant beast has burrowed under the gate into the courtyard. The defenders need your help!", ["objectivesText"] = "Kill Kri'chon , the Corpse-Reaver. Progress: They need you in the courtyard!", ["rewardGold"] = 228000, ["rewardXP"] = 294000, ["rewardItems"] = { 90625 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3280 } },
[30251] = { ["id"] = 30251, ["name"] = "Vyraxxis, the Krik'thik Swarm-Lord", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 30251 }, ["series"] = { 30246 }, ["description"] = "A giant mantid is terrorizing the inside of the wall. It seems doubtful that the defenders will be able deal with it without you.", ["objectivesText"] = "Kill Vyraxxis , the Krik'thik Swarm-Lord. Progress: Yes, <class>?", ["rewardGold"] = 228000, ["rewardXP"] = 294000, ["rewardItems"] = { 90625 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3280 } },
[30252] = { ["id"] = 30252, ["name"] = "A Helping Hand", ["level"] = 87, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 30252 }, ["description"] = "I've been pushing and shoving and hammering all morning, but it's hopeless. These rocks won't budge! \"It will be a breeze,\" Grandpa said. \"Farming's like breathing!\" he said. Maybe for him, but not for me! How am I supposed to succeed at this whole FARMING thing if I can't even clear my farm for planting? Hey, wait a minute. You look like you've got some muscle on you. Would you be willing to help me out? Just until I can catch my breath.", ["objectivesText"] = "Destroy 8 Unbudging Rocks . Progress: I really wasn't cut out for this type of work. I didn't exactly grow up in the country.", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["rewardItems"] = { 62298 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[30254] = { ["id"] = 30254, ["name"] = "Learn and Grow II: Tilling and Planting", ["level"] = 87, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 30254 }, ["series"] = { 30255, 30256, 30257, 30535, 31945 }, ["description"] = "Okay, now we've got our seeds, it's time to plant them. First, we have to prepare the soil! You gotta till the soil and break it up to make a nice bed for our little sprouts. Till those two plots of soil over there, then plant the seeds in them.", ["objectivesText"] = "Till 2 plots of Untilled Soil to create Tilled Soil . Then, use the EZ-Gro Green Cabbage Seeds on 2 plots of Tilled Soil . Progress: Well, go ahead - bust that soil up and plant the seeds! You aren't giving up already are you? I need your help!", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["rewardItems"] = { 80302 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[30255] = { ["id"] = 30255, ["name"] = "Learn and Grow III: Tending Crops", ["level"] = 87, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 30255 }, ["series"] = { 30254, 30256, 30257, 30535, 31945 }, ["description"] = "My grandfather used to say \"Yoonie, a cabbage is like a woman: ignore her and she'll turn rotten. Pamper her and she'll grow big and plump and you can put a ribbon on her and take her to market to show her off to your frie-\" look, he was from a different time, okay? The point is, now that our cabbages have sprouted, they need attention! Today they look a little dry, so you should water them. Here's the old watering can grandpa left. It will always be near the field if you need it.", ["objectivesText"] = "Use the Rusty Watering Can to water 2 Parched EZ-Gro Green Cabbages at Sunsong Ranch. Progress: Come to think of it, grandpa said a lot of really offensive things. Maybe I should avoid quoting him from now on...", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["rewardItems"] = { 79104 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[30256] = { ["id"] = 30256, ["name"] = "Learn and Grow IV: Harvesting", ["level"] = 87, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 30256 }, ["series"] = { 30254, 30255, 30257, 30535, 31945 }, ["description"] = "It's time for our hard work to pay off! Normally we'd have to wait a day before the crops are ready to harvest. Fortunately, those seeds Greenfield gave us were specially designed to grow FAST. The yield won't be worth much, but they're good for stepping new farmers through the process. Our cabbages should be ready to harvest. I'll let you do the honors, of course!", ["objectivesText"] = "Harvest 2 EZ-Gro Green Cabbages from your field and bring them to Farmer Yoon in Sunsong Ranch. Progress: Look at those... err, what do they say around here? Oh yeah, b'yoots! Look at those b'yoots! I think I'm getting the hang of this farmer thing.", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["rewardItems"] = { 80314 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[30257] = { ["id"] = 30257, ["name"] = "Learn and Grow V: Halfhill Market", ["level"] = 87, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 30257 }, ["series"] = { 30254, 30255, 30256, 30535, 31945 }, ["description"] = "All right friend, all of that farming was just for practice! Are you ready to try the real thing? There's a lady by the name of Gina Mudclaw who runs the Halfhill Market, which is across the street to the south. I heard she's looking to buy some vegetables. Since it's your first time meeting her, you shouldn't go empty-handed. Why don't you look around the ranch and see if there are any items hiding around? Might be that we'll find a good gift to take to our new neighbor!", ["objectivesText"] = "Investigate the Dark Soil underneath Farmer Yoon 's house, then give a gift to Gina Mudclaw at the Halfhill Market. Progress: Hey, haven't seen your face around here before! What's your name?", ["rewardGold"] = 51000, ["rewardXP"] = 64000, ["rewardItems"] = { 79269 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[30258] = { ["id"] = 30258, ["name"] = "Mung-Mung's Vote I: A Hozen's Problem", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 30258 }, ["series"] = { 30259 }, ["description"] = "I've been thinkin' about how to get into the Tiller's good graces, <name>. Now, the Tiller's Union accepts new farmers each year, and there are five members on the voting council. We already got Gina's vote, but we'll have to prove ourselves to the other four members of their board. Why don't you go over and say hello to Mung-Mung ? He works with Mr. Mudclaw out on the Mudclaw's farm to the northwest.", ["objectivesText"] = "Speak to Mung-Mung at Haohan Mudclaw's House in the Valley of the Four Winds .", ["rewardGold"] = 57000, ["rewardXP"] = 118000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[30259] = { ["id"] = 30259, ["name"] = "Mung-Mung's Vote II: Rotten to the Core", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 30259 }, ["series"] = { 30258 }, ["description"] = "Dem virmen's back! They been biting Mr. Mudclaw's carrots. Ruining his crop. And who is gonna pay? Mung-Mung , that's who! You go get the chewed up carrots before Mr. Mudclaw sees. They all over the fields to the southwest, and down under the ground in the virmen's tunnels, too. Otherwise, Mung-Mung in big trouble. You do this for me?", ["objectivesText"] = "Collect 10 Partially Chewed Carrots . Progress: I don't see no chewed up carrots. You don't see no chewed up carrots. Mr. Mudclaw never know, okay?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 74841, 80116 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[30260] = { ["id"] = 30260, ["name"] = "Growing the Farm I: The Weeds", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 30260 }, ["series"] = { 30516 }, ["description"] = "Hey <name>, I've been thinkin' recently about expanding my farm. See that plot there that's just covered in weeds? If we can get rid of those weeds, we could use that land for planting. I heard there's a farmer by the name of Gai Lan who knows a thing or two about weed whackin'. His farm is just out west. Go talk to him and see if he'd be willing to help us.", ["objectivesText"] = "Speak to Gai Lan at The Heartland in the Valley of the Four Winds .", ["rewardGold"] = 57000, ["rewardXP"] = 118000, ["rewardItems"] = { 74841, 74843, 74848, 89812, 93226 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[30261] = { ["id"] = 30261, ["name"] = "Roll Club: Serpent's Spine", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 30261 }, ["description"] = "Get to the bottom of the wall in the fastest time possible. Speak to me when you're ready to roll.", ["objectivesText"] = "Complete the Serpent's Spine roll course. Progress: Ready to roll?", ["rewardGold"] = 228000, ["rewardXP"] = 294000, ["rewardItems"] = { 89155 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3280 } },
[30262] = { ["id"] = 30262, ["name"] = "NOT USED", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["storyline"] = { 30262 }, ["rewardGold"] = 188000, ["rewardXP"] = 86750, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[30263] = { ["id"] = 30263, ["name"] = "Clearing in the Forest", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 30263 }, ["description"] = "The Shao-Tien are on their heels. Most of them retreated to Winterbough Glade after their last defeat. We should press the advantage. Take the fight to these mogu in the clearing to the northwest. Let us leave them no minute of rest as long as they remain in the Vale.", ["objectivesText"] = "Kill 6 Shao-Tien mogu in Winterbough Glade.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[30264] = { ["id"] = 30264, ["name"] = "Enemy at the Gates", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 30264 }, ["description"] = "The mantid forces are pouring against the wall. I've arranged for some flying serpents to cut away at their forces from the air. Would you be willing to take the reigns on one of them?", ["objectivesText"] = "Use a Shado-Pan Sky Serpent to kill 60 Krik'thik attackers, 3 Krik'thik War Wagons , and 3 Krik'thik Catapults . Progress: The mantid sense our weakness during the mogu attacks. They're hoping to take us off-guard. They underestimate me.", ["rewardGold"] = 228000, ["rewardXP"] = 294000, ["rewardItems"] = { 44987 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3280 } },
[30266] = { ["id"] = 30266, ["name"] = "Bloodied Skies", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 30266 }, ["description"] = "We have cannons set up on the top of the towers flanking the main gate. They are our best method to clear the skies when the flying mantid try to pass over the wall, like they are now. Looks like you're on, <name>.", ["objectivesText"] = "Kill 30 Krik'thik Swarmers using a Setting Sun Turret. Progress: The wall... the wall is where we all met. Better times past.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3280 } },
[30267] = { ["id"] = 30267, ["name"] = "Watery Woes", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 30267 }, ["description"] = "I love fishing. I'd be enjoying myself much more, however, if I had my bait and my lures. They were thrown away in a... a misunderstanding with my wife, Rin. < Gladecaster Lang sighs.> Should I let a whole day of fishing be ruined, just because of a little domestic squabble? No! All I need is bugs and feathers, after all, and this glade is filled with those two things. Care to help a fisherman out?", ["objectivesText"] = "Obtain 18 Glade Glimmers and 5 Spindly Bloodfeathers . Progress: I refuse to not fish. Fishing's who I am!", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["rewardItems"] = { 79197, 79198 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[30275] = { ["id"] = 30275, ["name"] = "A Crocolisk Tale", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 30275 }, ["description"] = "How could this crocolisk have grown so large? Certainly, rumors exist of very old crocolisks that have grown to enormous sizes... but this female can't be more than a dozen years old. Perhaps someone in New Cifera can shed some light on the subject.", ["objectivesText"] = "Bring the Enormous Crocolisk Tail to Yan at New Cifera in the Valley of the Four Winds . Progress: What's that you've got there?", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["rewardItems"] = { 79237 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard", ["startItems"] = { 79238 } },
[30277] = { ["id"] = 30277, ["name"] = "The Crumbling Hall", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 30277 }, ["description"] = "An ancient mogu artifact has been uncovered in the Guo-Lai Vault, beyond the Hall of Statues. We've made repeated attempts to retrieve it, but none have been successful. We cannot let this artifact fall into the hands of the Shao-Tien. I need someone capable to retrieve it, and quickly. Are you in?", ["objectivesText"] = "Retrieve the Ancient Guo-Lai Artifact . Progress: Have you recovered the artifact yet?", ["rewardGold"] = 456000, ["rewardXP"] = 471000, ["rewardItems"] = { 37710, 46709, 87779, 87790, 90815, 90816, 103624 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[30280] = { ["id"] = 30280, ["name"] = "The Thunder Below", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 30280 }, ["description"] = "Roars have been echoing out from inside the Guo-Lai Halls. The mogu have awakened some ancient beast, and it will not be long before they attempt to release it upon my men. Find your way to the Hall of the Serpent and slay the beast before it can be unleashed upon us. I would trust no other with such a dangerous and important task.", ["objectivesText"] = "Slay Milau .", ["rewardGold"] = 456000, ["rewardXP"] = 471000, ["rewardItems"] = { 9172, 87779, 90815, 90816, 103624 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[30281] = { ["id"] = 30281, ["name"] = "The Silent Approach", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 30281 }, ["series"] = { 30482 }, ["description"] = "<He leans over and draws a picture of what can only be a mogu, points towards the lake to the west, drags the blunt side of his dagger across his throat, and looks at you expectantly. It seems he wants you to kill mogu at Whitepetal Lake.>", ["objectivesText"] = "Kill 6 Shao-Tien mogu at Whitepetal Lake.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[30282] = { ["id"] = 30282, ["name"] = "Burning Away the Filth", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 30282 }, ["description"] = "The mogu have erected their filthy banners around the lake to the west, claiming it as their own. Take this torch and show them what we think of their banners.", ["objectivesText"] = "Burn 10 Shao-Tien Banners.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 84781 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[30283] = { ["id"] = 30283, ["name"] = "A Smashing Impression", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 30283 }, ["description"] = "Sometimes I feel sorry for these mogu... maybe ripping out the spirits of other races is just their way of coping with family issues at home? Maybe we should be more sympathetic to where all this aggression stems from? Or we could just smash all their soul-stealing ritual objects down at the lake. That sounds more fun to me personally.", ["objectivesText"] = "Destroy the Shao-Tien Ritual Statues.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[30284] = { ["id"] = 30284, ["name"] = "A Thousand Pointy Teeth", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 30284 }, ["description"] = "The water has been frothing with danger this day! Some sort of swarming, meat-eating fishy nastiness has taken up residence in our lake! Deplorable. And just when I was considering stripping down to my nothings to take a mid-day dip! You are adept in the ways of slaughtering any manner of nasty, are you not? Would you put your skills to use this day, in the name of pandaren everywhere desiring a swim? It's a truly noble cause, especially with me among their ranks!", ["objectivesText"] = "Kill 9 Knifetooth Swarmers . Progress: The bubbling water and occasional splotch of redness floating to the top suggest to me that these vicious fish are still at large! Exercise your nastiness upon them, friend!", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[30285] = { ["id"] = 30285, ["name"] = "Wu Kao Scouting Reports", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 30285 }, ["description"] = "There were some scouting reports unaccounted for after the attack. If we're lucky, they're still out in the village, but the mogu may have gotten their hands on some of them as well. If you could bring back any scouting reports you find, it would definitely put my mind at ease. We can't afford to let the mogu in on our positions or any of the artifacts we've found, lest the men be in even more danger than they already are.", ["objectivesText"] = "Recover 3 Wu Kao Scouting Reports . Progress: Any luck finding those reports? I'm worried for the safety of our men in the field if too much information falls into mogu hands.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 86099 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[30286] = { ["id"] = 30286, ["name"] = "Backed Into a Corner", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 30286 }, ["description"] = "Many villagers are cornered and scared, unable to defend themselves. You will need to defend them. Rescue them. Go quickly friend, save as many as you can!", ["objectivesText"] = "Rescue 6 Cornered Mistfall Villagers. Progress: The vale has become a dangerous place with the mogu forces on the move. We will need to teach these villagers to properly defend themselves.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 59765, 59766, 59767 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[30287] = { ["id"] = 30287, ["name"] = "Mogu Make Poor House Guests", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 30287 }, ["description"] = "Leven sent Rook here to stop mogu, but there are more than Rook can kill alone. You help? Rook will tell Leven you helped. Promise.", ["objectivesText"] = "Kill 6 Shado-Tien attackers in Mistfall Village.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[30288] = { ["id"] = 30288, ["name"] = "My Town, It's On Fire Again", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 30288 }, ["description"] = "I don't know if you noticed, but my town is on fire... again. We have water buckets all over town, but no one can get out to put out the fires. Please, please, help us!", ["objectivesText"] = "Use Mistfall Water Buckets to douse 60 fires. Progress: We lost our homes in Kun-Lai already, we can't lose these homes too!", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 85950 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[30289] = { ["id"] = 30289, ["name"] = "Freeing Mind and Body", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 30289 }, ["description"] = "Mogu stealing peoples minds! Making them do evil things. Don't kill them, just kill the mogu, then they forget about all the mogu mind stealing and stop being evil. You should fix people like Rook is.", ["objectivesText"] = "Free 6 Dominated Guards by killing their controllers. Progress: More villagers left that need to forget about mogu mind tricks. Please help Rook.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[30290] = { ["id"] = 30290, ["name"] = "Stonebound Killers", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 30290 }, ["description"] = "Mogu stone dog creatures chasing villagers and hurting them. Rook try to smash some, but they too fast. You help smash some too?", ["objectivesText"] = "Kill 8 Stonebound Quilen . Progress: More dog things all over village. Still need more help please.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[30291] = { ["id"] = 30291, ["name"] = "Stunning Display", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 30291 }, ["description"] = "I've been talking to Tantan here... again... and he insists that fishing is some kind of fabulous. I was skeptical, but I gave it another go. I'm not a big fan of that whole holding a stick and waiting method though, so I tried something a bit more direct. Would you be a doll and go collect any of the still intact fish floating belly up in the lake for me?", ["objectivesText"] = "Collect 12 Stunned Whitepetal Carp . Progress: As an added bonus, my method ensures they're already cooked! If that's not a marvel of modern efficiency, I don't know what is.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 3567, 4598, 81354, 84656, 85500 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[30292] = { ["id"] = 30292, ["name"] = "Rude Awakenings", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 30292 }, ["description"] = "The mogu are taking over the minds of the saurok at the lake to our west and turning them against us! The thing is, they were already against us, so I'm not sure they really thought this thing through fully. Anyway, Anji's the fighter in this pair, I'm more the lover, so I'm looking for someone to do all the weapon swinging and spell flinging and war crying and such. Can you go kill some saurok for me?", ["objectivesText"] = "Kill 8 Dominated Paleblade Flesheaters .", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[30293] = { ["id"] = 30293, ["name"] = "In Enemy Hands", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 30293 }, ["description"] = "The Shao-Tien Mindbenders have taken over the minds of our defenders down at Whitepetal Lake to the west. Get down there and kill the mogu that are controlling them, but don't kill the defenders! Killing their captors should free them from their mind control. Sooner would be better. Anji might try to go down there to help soon, and her ability to restrain herself when in the heat of things is not one of the qualities I married her for.", ["objectivesText"] = "Beat 8 Possessed Whitepetal Defenders until they're freed of mogu possession. Progress: Or you could just dispel them if that's your thing. You seemed like the type that might want to beat some people up though.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[30296] = { ["id"] = 30296, ["name"] = "Gaohun the Soul-Severer", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 30296 }, ["description"] = "Big mogu leader is here! Up behind village. If we kill big mogu leader, Leven be happy with us for sure! You been good at helping Rook. Want to help more maybe? Please?", ["objectivesText"] = "Kill Gaohun the Soul-Severer . Progress: Mogu leader still shouting orders from up the hill. Friend help Rook make him quiet?", ["rewardGold"] = 228000, ["rewardXP"] = 294000, ["rewardItems"] = { 90625 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[30297] = { ["id"] = 30297, ["name"] = "Baolai the Immolator", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 30297 }, ["description"] = "Big mogu leader is here! Up behind village. If we kill big mogu leader, Leven be happy with us for sure! You been good at helping Rook. Want to help more maybe? Please?", ["objectivesText"] = "Kill Baolai the Immolator . Progress: Mogu leader still shouting orders from up the hill. Friend help Rook make him quiet?", ["rewardGold"] = 228000, ["rewardXP"] = 294000, ["rewardItems"] = { 90625 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[30298] = { ["id"] = 30298, ["name"] = "Painting the Ruins Red", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 30298 }, ["description"] = "The mogu think they can inhabit these ruins uncontested. Let's show them the error in their ways.", ["objectivesText"] = "Kill 8 mogu in the Ruins of Guo-Lai. Progress: They underestimate us at every turn, just as they underestimated us during the uprising so many years ago.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[30299] = { ["id"] = 30299, ["name"] = "No Stone Unturned", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 30299 }, ["description"] = "The mogu have forced spirits into their old statues to bring them to life, control them, and turn them against us. The only way to free the bound spirits is to destroy their vessels.", ["objectivesText"] = "Destroy 6 Mogu Statues .", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[30300] = { ["id"] = 30300, ["name"] = "The Key to Success", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 30300 }, ["description"] = "The mogu have taken prisoners. They'll be tortured or worse. Find any way you can to free them from their cages.", ["objectivesText"] = "Find a Shao-Tien Cage Key and free 6 Golden Lotus Prisoners. Progress: I'd rather die than live as a mogu prisoner. They are not kind captors.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 85582 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[30301] = { ["id"] = 30301, ["name"] = "Offering a Warm Welcome", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 30301 }, ["description"] = "There is no more sure message we can send them then to burn the tents the sleep in. Scour the ruins. Destroy every tent you find.", ["objectivesText"] = "Burn 6 Mogu Tents in the Ruins of Guo-Lai.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 85581 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[30302] = { ["id"] = 30302, ["name"] = "The Imperion Threat", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 30302 }, ["description"] = "Scouts spotted a Shao-Tien Imperion entering the Guo-Lai Halls. I need someone I can trust to make sure he doesn't come out of there alive. I think you're the <class> for the job.", ["objectivesText"] = "Kill the Shao-Tien Imperion. Progress: The mogu have repeatedly sent groups of their stronger warriors into those chambers. There is definitely something they want inside.", ["rewardGold"] = 228000, ["rewardXP"] = 294000, ["rewardItems"] = { 90625 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[30303] = { ["id"] = 30303, ["name"] = "NOT USED", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["storyline"] = { 30303 }, ["rewardGold"] = 188000, ["rewardXP"] = 86750, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[30304] = { ["id"] = 30304, ["name"] = "Hard as a Rock", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 30304 }, ["description"] = "Hey! You know what awesome thing happened to me this morning? I was strolling through the ruins with Anji, eyes on the ground so I wouldn't step on anymore of those creepy spider pods, when one of the statues came to life and tried to smash me! Anji ended up doing the smashing. But I'm not satisfied. I think that you should go out there and smash all the statues, whether they're moving or not. It's the only way to be sure.", ["objectivesText"] = "Destroy 10 Mogu Statues . Progress: I'll never trust a statue again.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[30305] = { ["id"] = 30305, ["name"] = "He Knows What He's Doing", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 30305 }, ["description"] = "You know He Softfoot? Sneaky guy, don't talk much. He put traps all over ruins for mogu. He said Rook just need to trick mogu into traps. Rook don't really know how. Maybe you do it? You find traps, you get bad guys into traps? Can you not tell He though, please?", ["objectivesText"] = "Lure 8 enemies into He's Poison Traps. Progress: You were going to do trap thing for Rook, yes? Please?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[30307] = { ["id"] = 30307, ["name"] = "The Eternal Vigil", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 30307 }, ["description"] = "Good to have you with us, <class>. If you're joining the fight, I need more men out up at the Golden Stair to clear out the mogu setting up base there. Can I count on you?", ["objectivesText"] = "Kill 8 Shao-Tien mogu on the Golden Terrace. Progress: They have countless tombs of stone warriors to bring to bear against us. We have the endless enduring nature of the <race> spirit to hold them back.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[30308] = { ["id"] = 30308, ["name"] = "Stone Hard Quilen", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 30308 }, ["description"] = "Leven always says the only good quilen is a dead quilen, and I'm inclined to agree. You here to aid the cause?", ["objectivesText"] = "Kill 6 Granite Quilen . Progress: Years on the wall have prepared me for anything the mogu can throw at us. This war will be short lived.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[30309] = { ["id"] = 30309, ["name"] = "Set in Stone", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 30309 }, ["description"] = "The mogu have been sending their narcissistic stone effigies onto our battlefield today. They're brining them to life up on the Golden Stair. The bigger they are, the harder we hit'm. You in?", ["objectivesText"] = "Destroy 6 Mogu Effigies .", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[30310] = { ["id"] = 30310, ["name"] = "Thundering Skies", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 30310 }, ["description"] = "The mogu have bent the will of sky serpents and turned them against us. The defenders won't fare well against them, but you would. Head northwest towards the Golden Stair and remove them from the sky.", ["objectivesText"] = "Kill 3 Subjugated Serpents .", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[30311] = { ["id"] = 30311, ["name"] = "High Standards", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["storyline"] = { 30311 }, ["description"] = "If I had to pick the most important quality for a battle standard, it would be that it's standing up... and not on fire, but mostly the first one. So needless to say, I'm a bit concerned about our standard situation at the moment. If some unknown <class> were to be so kind as to take a walk out on the battlefield to our northwest and stand our standards back up, both myself and my extremely sexy yet somewhat commanding wife would be very grateful.", ["objectivesText"] = "Erect 6 Golden Lotus Standards.", ["rewardGold"] = 86000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[30312] = { ["id"] = 30312, ["name"] = "Given a Second Chance", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 30312 }, ["description"] = "A foolish contingent attempted to mount an offensive on the Golden Stair through the eastern pass, and were bombarded by cannons. Those that made it back are in bad shape, and there are still wounded out in the field. Here are some bandages. Use these, or any other healing skills you possess, and help get our wounded defenders back to safety. Please hurry, there is little time.", ["objectivesText"] = "Heal 6 Wounded Defenders . Progress: There are more injured in need of attention. Please help if you can.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 84242 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[30313] = { ["id"] = 30313, ["name"] = "The Moving Mists", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 30313 }, ["description"] = "<He looks down at the dead fog creature at his feet, looks up at you, then points out into the mists surrounding the lake. It seems he wants you to find and kill more of these fog creatures.>", ["objectivesText"] = "Kill 8 Fog Walkers . Progress: <He stares at you blankly.>", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[30314] = { ["id"] = 30314, ["name"] = "The Displaced Paleblade", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 30314 }, ["description"] = "<He looks down at the dead saurok at his feet, looks up at you, then points out down the lake shore. It seems he wants you to find and kill more of these saurok.>", ["objectivesText"] = "Kill 8 Paleblade Saurok. Progress: <He stares at you blankly.>", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[30317] = { ["id"] = 30317, ["name"] = "Water, Water Everywhere", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 30317 }, ["description"] = "How'd you like to make yourself useful? The season's been awful dry lately. I need someone to water the crops out in the Heartland. Here's the thing: I need you to water ALL of the crops. I keep a few kites with Wing Nga, the flightmaster across the way. Grab one of those kites, then throw water on any areas that look dry and dusty.", ["objectivesText"] = "Speak with Wing Nga to borrow a kite, then throw water onto 35 Dusty Spots in the Heartland. Progress: Just come back when you're done. And don't break any of my kites.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 24433, 34813 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[30318] = { ["id"] = 30318, ["name"] = "Chasing the Chicken", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 30318 }, ["description"] = "Say, you there! <name>, was it? I've got a problem, and I need someone with better legs than mine to help me solve it. My prize-winning chicken has flown the coop! Now she's out in the open, mingling with the other hens, wild birds, and... <gulp> ill-intentioned roosters. My farm is west of here, south of the Skyrange. Could you find her, and bring her back to me?", ["objectivesText"] = "Pick up Hillpaw's Chickens until you find his Prize-Winning Chicken. Progress: I swear, she's never done this before.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 43352, 80223 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[30319] = { ["id"] = 30319, ["name"] = "Pest Problems", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 30319 }, ["description"] = "One of my farmhands, Wika-Wika, has been tilling the soil in my westernmost field. I understand he's had some problems with pests. He's got plenty of pesticide to spray the bugs that eat my crops, but I'm afraid he has no way to deal with the marmots. Would you lend him a hand? With rampant hozen and virmen attacks, I can't afford to lose crops to simple pests.", ["objectivesText"] = "Speak with Wika-Wika, then stomp on 25 Black-Nose Marmots .", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 42736 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[30320] = { ["id"] = 30320, ["name"] = "Free Spirits", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 30320 }, ["description"] = "I came upon one of the Shao-Tien Soul-Render's daggers. It radiates a strong magic. I've been told it should allow you to enter their spirit vortexes. The mogu use these to harvest spirits and bind them to their will, but I'm hoping you can use it to free the spirits. Enter any of the spirit vortexes you can find up on the Golden Stair, and free all the captive spirits you find.", ["objectivesText"] = "Enter Spirit Vortexes and free 15 pandaren spirits inside. Progress: The mogu are able to force <race> spirits into inanimate objects and bend them to their will, but the spirits still yearn to be free. This may be the tool we need to offer them that freedom.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 89297 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[30321] = { ["id"] = 30321, ["name"] = "Weed War II", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 30321 }, ["description"] = "Ssshhay... d'you know that guy over on the farm, with the... the *hic*... the weed problem? Gai Lan, I think his name was. I love that guy, man. Anywayshh, he said that if I *hic* sent an adventurer over to go pick his weeds, he'd get me some ale. It's jusht a few weeds, not too many, probably. *hic*", ["objectivesText"] = "Speak to Gai Lan, then pick 100 Weeds on his farm. You can pick Weeds while mounted. Progress: What time is it?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 43352, 71153, 89686 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[30322] = { ["id"] = 30322, ["name"] = "Money Matters", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 30322 }, ["description"] = "I love working in the market, although there's one aspect of this job I really dislike: collecting debts. While most pandaren debts are simply due to laziness, there are a few unsavory characters around town who simply don't want to pay, and there's some who are just too poor. A few people here in town owe me money. Could you go talk to them, and remind them about what they owe?", ["objectivesText"] = "Obtain Spicemaster Jin Jao's Payment , Trader Jambeezi's Payment , Innkeeper Lei Lan's Payment , and Lolo Lio's payment . Progress: You know, it's kind of nice having a thug... er, I mean, <class>... like you around.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 80213, 80214, 80215, 80216 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[30323] = { ["id"] = 30323, ["name"] = "They Don't Even Wear Them", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 30323 }, ["description"] = "A few weeks ago, a group of those jumpy little Springtail virmen broke into my lockbox and stole several handfuls of my jewelry. I've since found a few pieces, but they still have most of my collection. If you're headed up to the Springtail Crag, in the cliffs to the north, you should keep an eye out for them. I'd love to get my jewelry back.", ["objectivesText"] = "Obtain a Stolen Circlet , a Ransacked Ring , and a Burglarized Bracelet . Progress: Can you believe how irresponsible and juvenile those virmen are? Don't they know how much that jewelry COST?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 80137, 80138, 80139 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[30324] = { ["id"] = 30324, ["name"] = "Not in Chee-Chee's Backyard", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 30324 }, ["description"] = "Not all hozen are the same. Chee-Chee's tribe was forest hozen... came from Jade Forest. Pretty easy to get along with. The Kunzen invaders... they come from mountains, far to the north. Not nearly as nice as Chee-Chee. They come into our green land, take our things, leave big mess behind. Chee-Chee wants to kill them. You like to help?", ["objectivesText"] = "Kill 8 members of the Kunzen tribe in the Kunzen Village.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[30325] = { ["id"] = 30325, ["name"] = "Where It Counts", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 30325 }, ["description"] = "I've been watching those Kunzen hozen, and I've noticed a consistent pattern. Whenever they're getting ready to attack, they participate in strange, barbaric rituals around their totem. If we can disrupt this ritual, not only will we put off any impending attacks, we can deal a huge blow to their morale! So get in there, rough them up, and make as much of a mess as possible!", ["objectivesText"] = "Throw 8 Kunzen Ritual Candles , kick 4 Blazing Embers , and slay 1 Kunzen Ritualist .", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[30326] = { ["id"] = 30326, ["name"] = "The Kunzen Legend-Chief", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 30326 }, ["description"] = "I've heard people talk about the hozen like they're just some tribe of barely-functional idiots... but that's not true! They have brains, too - they just don't all like to use them that much. I've heard that the Kunzen tribe has two chiefs - one in charge of fighting, and one in charge of stories, lore, and history. What I wouldn't give to see what kind of stories they tell...", ["objectivesText"] = "Obtain a Kunzen Legend-Book from a Kunzen Legend-Chief. Progress: I'll bet hozen legends aren't that much different than our own.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 79866 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[30327] = { ["id"] = 30327, ["name"] = "You Have to Burn the Ropes", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 30327 }, ["description"] = "I, umm... well... Oh, never mind. It was a stupid idea. It's just that, I was thinking that maybe we can stop the Kunzen hozen from attacking us without having to, you know... KILL anything. I noticed a few ropes on the side of the mountain. I think they're using them to climb down to our farms and... No, forget it. It was a silly idea anyways.", ["objectivesText"] = "Burn 6 Kunzen Ropes. Progress: Never mind. I would never ask you to... to do something for plain old me.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[30328] = { ["id"] = 30328, ["name"] = "The Thousand-Year Dumpling", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["requiredProfessions"] = { "cooking" }, ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 30328 }, ["description"] = "One of my most popular recipes is the Thousand-Year Dumpling, which is filled with preserved vegetables . I normally let the vegetables ferment in a hole underneath my house, but when I looked for them this morning, they were gone! I blame those thieving virmen. Bring them back, and I'll let you help me cook!", ["objectivesText"] = "Obtain 7 jars of Preserved Vegetables . Progress: Try not to open any of the jars. If you do open one, you might not want to smell it too closely.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 80133, 90458 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[30329] = { ["id"] = 30329, ["name"] = "Cindergut Peppers", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["requiredProfessions"] = { "cooking" }, ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 30329 }, ["description"] = "A certain few pandaren around here prefer their dishes unbearably spicy. Unfortunately, my access to such peppers is limited. The Kunzen hozen, in the mountains to the west, often carry cindergut peppers . A few of those and I'll be set for a few days. Say, could you collect some for me? You might want to wear gloves if you'll be handling them directly.", ["objectivesText"] = "Obtain 4 Cindergut Peppers . Progress: Just put the peppers down on the cutting board, here. I'd prefer not to touch them myself.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 79864, 80484, 87394, 87400, 87401, 87841, 88855, 89366, 90458 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[30330] = { ["id"] = 30330, ["name"] = "The Truffle Shuffle", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["requiredProfessions"] = { "cooking" }, ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 30330 }, ["description"] = "I like to bake with truffles... when I can find them. They only grow up on the Skyrange, and in very, very scarce amounts. They're a fantastic ingredient, but we can't risk over-farming them. That's why we need to replace what we've taken. Bring me a handful of adult truffles, and plant some of these spores in their place.", ["objectivesText"] = "Obtain 8 Shadelight Truffles , and plant 8 Shadelight Spores. Progress: We won't need many truffles. They're for flavor only, really.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 79833, 80127, 90458 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[30331] = { ["id"] = 30331, ["name"] = "The Mile-High Grub", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["requiredProfessions"] = { "cooking" }, ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 30331 }, ["description"] = "Have you ever tried Mushan Tail Stew ? Chances are, if you have, that it was stringy and tasteless. You see, there's a trick to making the perfect Mushan Tail Stew : you need to cook it at high elevation. I've already gathered the ingredients. Take this pot up to the Kunzen Village, up in the mountains to the west, and prepare the stew over their bonfire.", ["objectivesText"] = "Prepare 20 bowls of Mushan Tail Stew over the bonfire in the Kunzen Village. Progress: I used to make daily trips into the mountains, just to practice making this stew. I was younger, then.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 46349, 79894, 79895, 90458 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[30332] = { ["id"] = 30332, ["name"] = "Fatty Goatsteak", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["requiredProfessions"] = { "cooking" }, ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 30332 }, ["description"] = "You know what? I think I want to grill up some goatsteak today. No, not from the puny little shaghorns they keep around here. They don't have nearly enough fat on them. <The chef pats his voluminous belly.> You think I got to this size eating no-fat-havin' goats? Now, the shaghorns up on the Skyrange, to the west... those'll do just fine.", ["objectivesText"] = "Obtain 4 Fatty Goatsteaks . Progress: <The chef is busy preparing spices and sauces for his imminent steaks.>", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 79867, 86425, 90458 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[30333] = { ["id"] = 30333, ["name"] = "The Lesser of Two Evils", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 30333 }, ["description"] = "Like any farming community, we have the occasional virmen troubles. The most powerful Springtail virmen live high up in the cliffs to the north, and only come down when they run out of veggies to nibble on. Frankly, I've dealt with virmen before. They're nothing but a pest that must be kept in check, and there's no better way to do that than by killing their warren-mother. Easy as that.", ["objectivesText"] = "Slay the Springtail Warren-Mother . Progress: I've had plenty of experience with virmen in the past. Just show them you're stronger than they are, and they'll back off.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[30334] = { ["id"] = 30334, ["name"] = "Stealing is Bad... Re-Stealing is OK", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 30334 }, ["description"] = "The hozen, up in the mountains to the west, continue to steal vegetables from my fellow farmers. Being so close to Halfhill, I very rarely suffer hozen attacks, but my friends have not been so lucky. Seems to me like they steal way more than they can eat. If you can find any intact vegetables up there in those mountains... steal them back!", ["objectivesText"] = "Re-steal 16 Stolen Vegetables . Progress: Have you got them?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 79824 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[30335] = { ["id"] = 30335, ["name"] = "Stalling the Ravage", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 30335 }, ["description"] = "The Kunzen hozen, up in the mountains to the west, have been acting up, lighting their fires and shouting their chants. Based on what I've heard and seen around here, that means that a ravage is coming. There's not much we can do to stop the ravage, but we can at least thin their numbers before they attack.", ["objectivesText"] = "Slay 12 Kunzen Hozen. Progress: The ravage could come any time now. We have to be prepared.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[30336] = { ["id"] = 30336, ["name"] = "The Kunzen Hunter-Chief", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 30336 }, ["description"] = "From what I've gathered, the Kunzen hozen have two chiefs. One is harmless - he deals with potions, medicines, and ancient fables. The other one is in charge of the Kunzen's hunters - and the only thing they've been hunting lately is our crops. The Hunter-Chief is a problem waiting to be solved. I'm sure the local farmers would be grateful if you went up there and, you know, \"took care\" of him.", ["objectivesText"] = "Slay the Kunzen Hunter-Chief. Progress: Mm-hmm.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[30337] = { ["id"] = 30337, ["name"] = "Simian Sabotage", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 30337 }, ["description"] = "The hozen steal from us, and we keep stealing our stuff back. It has to stop sometime. < Farmer Yoon hands you a barrel of fireworks .> Find some of our stolen supplies in their mountain camp to the west, and place these fireworks beside them. Hopefully, if they see the explosions, they'll think our supplies are defective and stop stealing altogether. It's worth a shot, right?", ["objectivesText"] = "Use the Barrel of Fireworks near the Pile of Stolen Weapons, the Pile of Stolen Tools, the Pile of Stolen Beer, and the Pile of Stolen Grain. Progress: Good luck up there, <name>.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 79885 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[30339] = { ["id"] = 30339, ["name"] = "Getting your Hands Dirty", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 30339 }, ["description"] = "Some of the best fishin' in all of pandaria in this lake right here. I brought enough brew to last me all day, but I didn't think to bring any bait. Who can really remember such things? If you'd be willing to gather me some bait along the shore, I'd be willin' to think on you favorably when it comes time to price my merchandise. Oh, and I'll pay you too, of course. How's that sound?", ["objectivesText"] = "Gather 12 Fresh Whitepetal Worms . Progress: So much fishin' in store! I can hardly wait to start my waitin'.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 84240 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[30340] = { ["id"] = 30340, ["name"] = "Stick in the Mud", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 30340 }, ["description"] = "I came out for a beautiful day of fishin', but I didn't think to bring a pole. There are so many things to remember for fishin', I just can't keep it all in my head. Those reeds along the river look alright for makin' a pole out of. If you'd gather me some number of them, I'd be willin' to think on you favorably when it comes time to price my merchandise. Oh, and I'll pay you too, of course. How's that sound?", ["objectivesText"] = "Gather 12 Whitepetal Reeds . Progress: So much fishin' in store! I can hardly wait to start my waitin'.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 84241 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[30341] = { ["id"] = 30341, ["name"] = "Under Watchful Eyes", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 30341 }, ["description"] = "<He looks down at the dead mogu scout at his feet, looks up at you, then points out out down the lake shore. It seems he wants you to find and kill more of these mogu scouts.>", ["objectivesText"] = "Kill 8 Shao-Tien Surveyors . Progress: <He stares at you blankly.>", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 89366 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[30343] = { ["id"] = 30343, ["name"] = "To the Waterline!", ["level"] = 85, ["requiredLevel"] = 85, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6040, ["storyline"] = { 30343 }, ["description"] = "This is Sky-Reaver Stormhowl, captain of the airship Fist of Garrosh and commander of this operation. Your first task is to burn the 7th Fleet to the waterline while it's still at anchor Captain Drok's marines will hold the harbor entrance while your team works. Rig powder barrels in the hold of every ship and then regroup at the harbor entrance to inform Blastmaster Sparkfuse, who will trigger the exposives and signal the airship forward.", ["objectivesText"] = "Rig powder barrels in the hold of all six ships.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6040 } }, ["questType"] = "dungeon" },
[30352] = { ["id"] = 30352, ["name"] = "Crane Mastery", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 30352 }, ["series"] = { 31262 }, ["description"] = "Thing about hunting birds is you need ammo - and I ain't got any. Thing about hunting with Nesingwary is you need to prove you can keep your tally and bragging rights up. Can't hunt, can't brag. And I like bragging so this is no good. Can I hire you to go kill me some carp hunters ? You'll find them up and down the river west of here. There are a bunch of them so don't hesitate to hunt while doing other stuff.", ["objectivesText"] = "Kill 12 Carp Hunters .", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["rewardItems"] = { 88044, 88045, 88046, 88047, 88048, 88049, 88050, 88051, 88052 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard" },
[30358] = { ["id"] = 30358, ["name"] = "Gryphon, Down", ["level"] = 5, ["requiredLevel"] = 5, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6040, ["storyline"] = { 30358 }, ["series"] = { 30343, 30362, 30364, 30377, 30378 }, ["description"] = "The Fist of Garrosh will hold position over the harbor until all other threats from the ground are eliminated. Your next target: Baldruc , Theramore's gryphon master. That mad dwarf and his beasts can't be allowed to attack the airship from above. Slay Baldruc , along with his winged charges.", ["objectivesText"] = "Slay Baldruc and his gryphons.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6040 } }, ["questType"] = "dungeon" },
[30362] = { ["id"] = 30362, ["name"] = "Tanks for Nothing!", ["level"] = 5, ["requiredLevel"] = 5, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6040, ["storyline"] = { 30362 }, ["series"] = { 30343, 30358, 30364, 30377, 30378 }, ["description"] = "The last threat to the airship is Theramore's arsenal of steam tanks. Destroy any active tanks and set bombs on any unmanned vehicles.", ["objectivesText"] = "Destroy any manned tanks and bomb any unmanned ones.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6040 } }, ["questType"] = "dungeon" },
[30364] = { ["id"] = 30364, ["name"] = "Fly, Spy!", ["level"] = 5, ["requiredLevel"] = 5, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6040, ["storyline"] = { 30364 }, ["series"] = { 30343, 30358, 30362, 30377, 30378 }, ["description"] = "The First of Garrosh is going the level Theramore Isle... but not until we free the spy whose intelligence made this operation possible. Enter Foothold Citadel and slay Captain Evencane for his shackles key. Our spy, the Sunreaver mage Thalen Songweaver , is being held beneath the barracks.", ["objectivesText"] = "Slay Hedric Evencane and free Thalen Songweaver in Foothold Citadel.", ["rewardItems"] = { 79261 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6040 } }, ["questType"] = "dungeon" },
[30377] = { ["id"] = 30377, ["name"] = "Minimum Safe Distance", ["level"] = 5, ["requiredLevel"] = 5, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6040, ["storyline"] = { 30377 }, ["series"] = { 30343, 30358, 30362, 30364, 30378 }, ["description"] = "As soon as you and your companions are clear, we're delivering our payload and reducing Theramore Isle to rubble. Return to the Sea Wolf and Captain Drok as soon as possible.", ["objectivesText"] = "Return to the Sea Wolf and report to Captain Drok.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6040 } }, ["questType"] = "dungeon" },
[30378] = { ["id"] = 30378, ["name"] = "The Blastmaster", ["level"] = 5, ["requiredLevel"] = 5, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6040, ["storyline"] = { 30378 }, ["series"] = { 30343, 30358, 30362, 30364, 30377 }, ["description"] = "Regroup at the harbor entrance to inform Blastmaster Sparkfuse of your success. He will trigger the powder barrels and signal the airship forward. Make certain that none of your group is on those ships when they go up!", ["objectivesText"] = "Inform Blastmaster Sparkfuse at the harbor entrance that the powder barrels have been rigged.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6040 } }, ["questType"] = "dungeon" },
[30379] = { ["id"] = 30379, ["name"] = "A Ruby Shard for Gina", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 30379 }, ["objectivesText"] = "Progress: Don't just stand there gawking. Spit it out.", ["rewardItems"] = { 79264 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[30380] = { ["id"] = 30380, ["name"] = "A Lovely Apple for Gina", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 30380 }, ["objectivesText"] = "Progress: It's busy at the market today. What can I do for you?", ["rewardItems"] = { 79267 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[30381] = { ["id"] = 30381, ["name"] = "A Jade Cat for Ella", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 30381 }, ["objectivesText"] = "Progress: Do you have any pets? I like cats, but dogs are nice, too.", ["rewardItems"] = { 79266 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[30382] = { ["id"] = 30382, ["name"] = "A Blue Feather for Ella", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 30382 }, ["objectivesText"] = "Progress: It's a lovely day out, don't you think?", ["rewardItems"] = { 79265 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[30383] = { ["id"] = 30383, ["name"] = "A Marsh Lily for Ella", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 30383 }, ["objectivesText"] = "Progress: Hmm? Oh hello. How are you today?", ["rewardItems"] = { 79268 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
