[30439] = { ["id"] = 30439, ["name"] = "A Dish for Jogu", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 30439 }, ["objectivesText"] = "Progress: You know what goes with a good drink? A good meal.", ["rewardItems"] = { 74643, 74833, 74837, 74839, 74841, 74843, 74848, 74856, 74857, 74859, 74864, 74865, 93226 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[30442] = { ["id"] = 30442, ["name"] = "Blanche's Boomer Brew", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6101, ["storyline"] = { 30442 }, ["description"] = "Brew Blanche's Boomer Brew by Protecting the Brewkegs.", ["objectivesText"] = "Help create the Boomer Brew. If the Brewkegs catch on fire, fix them!", ["rewardGold"] = 456000, ["rewardXP"] = 471000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6101 } }, ["questType"] = "standard" },
[30444] = { ["id"] = 30444, ["name"] = "No Reprieve", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 30444 }, ["description"] = "We've been granted a brief respite from the mogu attacks as they attempt to recoup near the Five Sisters to our north. I would like you to see to it that they not be granted a similar reprieve. Show no mercy.", ["objectivesText"] = "Kill 8 Shao-Tien mogu near the Five Sisters. Progress: These mogu are like roaches. It seems near impossible to do away with them for good.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3280 } },
[30449] = { ["id"] = 30449, ["name"] = "Darkmoon Crane Deck", ["level"] = 90, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 215, ["storyline"] = { 30449 }, ["description"] = "Now that you have gathered all of the Crane cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight. On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\" You have heard that the entrance to this faire appears near Mulgore and Goldshire every month.", ["objectivesText"] = "Return the Crane Deck to the Darkmoon Faire when it comes to town. Progress: I see that you have managed to complete a Crane deck ! Congratulations!", ["rewardItems"] = { 79325, 79330 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 215 } }, ["questType"] = "standard", ["startItems"] = { 79325 } },
[30450] = { ["id"] = 30450, ["name"] = "Darkmoon Ox Deck", ["level"] = 90, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 215, ["storyline"] = { 30450 }, ["description"] = "Now that you have gathered all of the Ox cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight. On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\" You have heard that the entrance to this faire appears near Mulgore and Goldshire every month.", ["objectivesText"] = "Return the Ox Deck to the Darkmoon Faire when it comes to town. Progress: I see that you have managed to complete a Ox deck ! Congratulations!", ["rewardItems"] = { 19287, 19288, 19289, 19290, 31856, 31857, 31858, 31859, 42987, 42988, 42989, 42990, 44253, 44254, 44255, 62047, 62048, 62049, 62050, 62051, 79324, 79327, 79328, 79329, 79330, 79331, 87575, 87576 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 215 } }, ["questType"] = "standard", ["startItems"] = { 79324 } },
[30452] = { ["id"] = 30452, ["name"] = "Darkmoon Tiger Deck", ["level"] = 90, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 215, ["storyline"] = { 30452 }, ["description"] = "Now that you have gathered all of the Tiger cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight. On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\" You have heard that the entrance to this faire appears near Mulgore and Goldshire every month.", ["objectivesText"] = "Return the Tiger Deck to the Darkmoon Faire when it comes to town. Progress: I see that you have managed to complete a Tiger deck ! Congratulations!", ["rewardItems"] = { 79323, 79327, 79328 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 215 } }, ["questType"] = "standard", ["startItems"] = { 79323 } },
[30458] = { ["id"] = 30458, ["name"] = "The Scouts Return", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["storyline"] = { 30458 }, ["series"] = { 29733 }, ["description"] = "<name>, your friends have returned from their scouting mission. They need to see you immediately. I'm afraid... Well, I'd better say no more. You will see for yourself.", ["objectivesText"] = "Speak to Rell Nightwind at the Glassfin Village in the Jade Forest .", ["rewardGold"] = 49000, ["rewardXP"] = 55000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[30471] = { ["id"] = 30471, ["name"] = "A Gift For Chee Chee", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 30471 }, ["description"] = "That crazy Chee Chee is actually pretty neat. Mah always said that hozen were nothing but trouble, but... I guess he's just a better hozen then the rest of them. We should do something nice for him! Those mountain hozen in the west make some really fancy stir fry, and keep bowls of it inside their little hozen houses. I bet Chee Chee would love some!", ["objectivesText"] = "Obtain an Authentic Valley Stir Fry . Progress: Mmm?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 79827 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[30472] = { ["id"] = 30472, ["name"] = "A Gift For Sho", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 30472 }, ["description"] = "Sho - that girl who lives up in the mountains - is in town today. I saw her walking toward the Halfhill Market. Such a long walk... she must be hungry! And I think I know just the thing that she'll like. The hozen up on the Skyrange cook a soup out of fish and apples. It sounds gross, I know... but it's awesome. You'll find it near their big, scary totem.", ["objectivesText"] = "Obtain a bowl of Yu-Ping Soup . Progress: Oh! Hello, <name>.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 79870 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[30473] = { ["id"] = 30473, ["name"] = "A Gift For Fish", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 30473 }, ["description"] = "That Fish Fellreed is kind of weird. First of all, her name's Fish. That's weird. Once you talk to her, though, she's really a nice lady. Did you know that she's an animal lover? I've got an idea! The Kunzen hozen, in the mountains to the west, make little animal statues and put them in their huts to scare off bad guys. I bet Fish would LOVE something weird like that!", ["objectivesText"] = "Obtain a Yak Statuette from the inside of a Kunzen hozen hut. Progress: Hey, <name>! What's up?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 79828 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[30474] = { ["id"] = 30474, ["name"] = "A Gift For Ella", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 30474 }, ["description"] = "That poor Ella . She's so shy! I saw her standing in the Halfhill Market, looking really hungry, but afraid to talk to any of the chefs. We should bring her some food! And not any boring food - something special. The Kunzen hozen make spicy shrimp dumplings from ingredients they've stolen from our farms. I don't like spicy food, but Ella might!", ["objectivesText"] = "Obtain Spicy Shrimp Dumplings . Progress: Oh, umm... hi.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 79871 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[30475] = { ["id"] = 30475, ["name"] = "A Gift For Fung", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 30475 }, ["description"] = "Farmer Fung is pretty mean, and just a little scary. Mah always said that he was one of the best farmers in the valley, though. I think I know the perfect gift for a mean, kind of scary guy like him. There's some big plainshawks that circle the hills to the west of here. You should get one, find a big piece of meat, and then ask Kol Ironpaw to grill it up!", ["objectivesText"] = "Obtain a Bloody Plainshawk Leg from a Monstrous Plainshawk, and then bring it to Kol Ironpaw in the Halfhill Market. Progress: Harrumph!", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 80232, 80233 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[30476] = { ["id"] = 30476, ["name"] = "A Gift For Old Hillpaw", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 30476 }, ["description"] = "Old Hillpaw has about a million chickens on his farm... but that's not what he REALLY loves. I saw. He collects blue feathers. I don't realy know where to get a blue feather around here, but I do know where to find some blue pearls! Check the oysters in Cattail Lake to the northwest. I'm sure a blue pearl will look nice with his feather collection!", ["objectivesText"] = "Find a Blue Freshwater Pearl . Progress: <name>! You startled me.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 80229 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[30477] = { ["id"] = 30477, ["name"] = "A Gift For Haohan", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 30477 }, ["description"] = "Haohan Mudclaw is the big boss of the Tillers union and the richest guy in the Valley! He's been nice to let me stay here, so I want to do something nice for him. He likes expensive stuff, like ruby shards, but I don't have a lot of money, so I need to get him something else. I know! I've seen a great big fish in Cattail Lake! We should get one of its teeth as a gift!", ["objectivesText"] = "Obtain an Enormous Cattail Grouper Tooth . Progress: Need something, <class>?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 80228 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[30478] = { ["id"] = 30478, ["name"] = "A Gift For Jogu", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 30478 }, ["description"] = "Sometimes I feel sad for Jogu. He's the only jinyu around, and I don't think he has any friends. Other than his smelly bottle, of course. You know what? I've got an idea. Farmer Yoon has a basket of craneberries inside his house, and a few apples as well. I'm sure you could bring them to the stillmaster in the Halfhill Market and get him to brew something special for Jogu.", ["objectivesText"] = "Obtain 8 of Yoon's Apples and 50 of Yoon's Craneberries , then bring them to Bobo Ironpaw to brew into Apple-Berry Hooch . Progress: Hmm?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 80234, 80235, 80236 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[30479] = { ["id"] = 30479, ["name"] = "A Gift For Gina", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 30479 }, ["description"] = "Have you seen Gina Mudclaw , the market girl? She has it all - looks, brains, and nice big tummy. Could you deliver a gift for me? I wanted to pick some orchids that grow on top of the big hills to the west, but I can't climb that high. Could you pick a few and bring them to Gina? Oh, and when you see her... tell her I said \"hi\".", ["objectivesText"] = "Obtain a Goldenfire Orchid . Progress: Hey there!", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 80231 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[30481] = { ["id"] = 30481, ["name"] = "Carved in Stone", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 30481 }, ["description"] = "You see the shiny stones in the walls? Rook wants some. The mogu been collecting them, so they have some to take too maybe. If you find stones, you please bring them to Rook? Rook will be your friend.", ["objectivesText"] = "Collect 12 Guo-Lai Runestones . Progress: You find stones for Rook? Please?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 85278 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[30482] = { ["id"] = 30482, ["name"] = "The Soul-Gatherer", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 30482 }, ["series"] = { 30281 }, ["description"] = "A single large mogu performing a ritual on the lake caught your attention while you were killing the other mogu in the area. It seems unwise to let his ritual complete.", ["objectivesText"] = "Kill Shadowmaster Sydow and recover the beads from his corpse. Progress: <He looks at you expectantly.>", ["rewardGold"] = 228000, ["rewardXP"] = 294000, ["rewardItems"] = { 85161, 90625 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[30483] = { ["id"] = 30483, ["name"] = "NOT USED", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["storyline"] = { 30483 }, ["rewardGold"] = 188000, ["rewardXP"] = 86750, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[30490] = { ["id"] = 30490, ["name"] = "Yakity Yak", ["level"] = 88, ["requiredLevel"] = 87, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["storyline"] = { 30490 }, ["description"] = "Yaungols! They come through here taking what they want and destroying whatever's left. I can't have these thugs destroy the last pieces of the Yak Wash here. It's all my boy and I have left. Head over to our old ranch and dish out some pain on them yaungols. I bet if you kill enough of them they'll think twice before attacking anything in this area.", ["objectivesText"] = "Kill 9 Burilgi Despoilers at the Muskpaw Ranch.", ["rewardGold"] = 106000, ["rewardXP"] = 162000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard" },
[30517] = { ["id"] = 30517, ["name"] = "Farmer Fung's Vote I: Yak Attack", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 30517 }, ["series"] = { 30518 }, ["description"] = "The next voting member on the Tiller's council is Farmer Fung , and it's easy to see why. That man's vegetables are the biggest in the valley! I only hope that someday I can grow pumpkins as big as his. If we hope to join the Tillers, he would be the next person to convince.", ["objectivesText"] = "Speak to Farmer Fung at The Heartland or the Halfhill Market in the Valley of the Four Winds .", ["rewardGold"] = 57000, ["rewardXP"] = 118000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[30518] = { ["id"] = 30518, ["name"] = "Farmer Fung's Vote II: On the Loose", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 30518 }, ["series"] = { 30517 }, ["description"] = "You want my vote for Farmer Yoon? Ha! You're joking, right? Listen, I'm not going to vote for some citypaw with no lick a' knowledge about farming the earth. It would be an embarrassment to farm alongside you or that Yoon shmuck. Now let me deal with my own problems. Some devil let my prize yaks loose, and now they're running wild northwest of Halfhill. If I could just get my yaks back, then maybe I'd be able to sleep at night.", ["objectivesText"] = "Return 5 Escaped Shagskins to Farmer Fung 's yak pen at the very north end of the Verdant Belt. Progress: What do you want?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[30519] = { ["id"] = 30519, ["name"] = "Nana's Vote I: Nana's Secret Recipe", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 30519 }, ["series"] = { 31948 }, ["description"] = "The next vote we'll need is from Nana Mudclaw . She's Haohan's grandmother, and she's been a Tiller longer than you and I have been alive! She's still working at the Tillers building in Halfhill. Why don't you pay her a visit?", ["objectivesText"] = "Speak to Nana Mudclaw at Halfhill in the Valley of the Four Winds .", ["rewardGold"] = 57000, ["rewardXP"] = 118000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[30521] = { ["id"] = 30521, ["name"] = "Haohan's Vote I: Bungalow Break-In", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 30521 }, ["series"] = { 30522 }, ["description"] = "This is going to be tough, <name>. The last vote we need comes from Haohan Mudclaw , the head of the Tillers Union. I know he wasn't too keen on us to start, but we've learned so much about farming, I'm sure he'll have a change of heart! Go speak to him. You can be very convincing, right?", ["objectivesText"] = "Speak to Haohan Mudclaw at The Heartland or at Halfhill Market in the Valley of the Four Winds .", ["rewardGold"] = 57000, ["rewardXP"] = 118000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[30523] = { ["id"] = 30523, ["name"] = "Growing the Farm II: The Broken Wagon", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 30523 }, ["series"] = { 30524 }, ["description"] = "Hey <name>. I've been looking at that wagon every day, day in and day out, since the day I moved in. Quite an eyesore, don't you think? I heard in town that Fish Fellreed is quite handy with tools. She might be able to fix it up, and then we could turn that patch of land into a plot for farming. Why don't you talk to her and see if she'd be willing to do the job?", ["objectivesText"] = "Speak to Fish Fellreed at Cattail Lake or the Halfhill Market in the Valley of the Four Winds .", ["rewardGold"] = 57000, ["rewardXP"] = 118000, ["rewardItems"] = { 85225 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[30524] = { ["id"] = 30524, ["name"] = "Growing the Farm II: Knock on Wood", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 30524 }, ["series"] = { 30523 }, ["description"] = "Sure! I know just the wagon that you're talkin' about! I can fix it right up, but I'll need wood. There's a whole lot of it down at the bottom of the lake. If you fish it right out - haha, get it? Fish? Oh I just crack myself up sometimes. Anyway, you bring me here some 'o that wood and then I'll get right to work!", ["objectivesText"] = "Collect 100 Waxed Planks . Progress: That lake is plum full o' treasures! You just gotta know what to look for.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 80136, 89813 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[30525] = { ["id"] = 30525, ["name"] = "Haohan's Vote III: Pure Poison", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 30525 }, ["description"] = "All right, <name>. This is our big chance! Mr. Mudclaw's farm is in big trouble. Those mountain hozen are coming down at night, wrecking his crops and eating his hard-earned harvest. We've got to get rid of them for good, and I know just how to do it. Back in the day, my grandpa showed me how to mix a wounding poison to deal with the pests on the farm. The virmen warrens to the north hold the key ingredients for my mixture. Don't look so worried, <name>! I'm pretty sure this is going to work.", ["objectivesText"] = "Collect 1 Bloodbloom , 1 Cave Lily , 1 Ghostcap , and 1 Violet Lichen . Progress: The hozen are going to get a big surprise!", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 80140, 80141, 80142, 80143 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[30526] = { ["id"] = 30526, ["name"] = "Lost and Lonely", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 30526 }, ["description"] = "The starving, mangy dog whines piteously and attempts a brief wag of its tail. It looks like it could use a good meal right about now.", ["objectivesText"] = "Collect 20 Tasty T-Bone from the Skyrange Mushan on the Skyrange in the Valley of the Four Winds . Progress: A light comes into the dog's eyes. It seems to recognize you.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 63359, 64398, 64399, 80144, 93226 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[30528] = { ["id"] = 30528, ["name"] = "Haohan's Vote V: Chief Yip-Yip", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 30528 }, ["description"] = "You ready for the final step of the plan? The leader of the Kunzen hozen is a brute by the name of Chief Yip-Yip . It's said that he is nearly impervious to pain. I've injected the melons with a toxic mixture, so don't try eating them! Once you get his attention, throw these melons onto the ground. Yip-Yip won't be able to resist a sweet striped melon. When he takes a bite, he'll be temporarily weakened, and you should find yourself an opening to attack.", ["objectivesText"] = "Kill Chief Yip-Yip at Kunzen Cave to the northwest. Progress: Did it work? Is Chief Yip-Yip slain?", ["rewardGold"] = 228000, ["rewardXP"] = 294000, ["rewardItems"] = { 74848 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[30534] = { ["id"] = 30534, ["name"] = "A Second Hand", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 30534 }, ["description"] = "Despite your best efforts, the work is starting to pile up around here. Perhaps you could ask one of your best friends if they'd like to help out at Sunsong Ranch.", ["objectivesText"] = "Speak to one of your best friends and ask them to work on Sunsong Ranch. Progress: It's a sturdy rake.", ["rewardGold"] = 57000, ["rewardXP"] = 118000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[30536] = { ["id"] = 30536, ["name"] = "FLAG - Weed War Training", ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 30536 }, ["description"] = "Oh, hello. Are you looking for the owner of this place? Then look to the pandaren up at the top of the stairs. I'm just a visitor... like you. Now if you'll excuse me, my friends and I trying to decide something. We can talk again afterwards.", ["objectivesText"] = "Listen to Xiao and his companions.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[30566] = { ["id"] = 30566, ["name"] = "FLAG - Pest Problems Training", ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 30566 }, ["description"] = "Oh, hello. Are you looking for the owner of this place? Then look to the pandaren up at the top of the stairs. I'm just a visitor... like you. Now if you'll excuse me, my friends and I trying to decide something. We can talk again afterwards.", ["objectivesText"] = "Listen to Xiao and his companions.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[30567] = { ["id"] = 30567, ["name"] = "Blanche's Boomer Brew", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5785, ["storyline"] = { 30567 }, ["description"] = "Can you smell it in the air? A storm is brewing! And so am I! Meet me at the hilltop when the storm hits and together we'll whip up a keg of my most famous brew. Can I count on your help?", ["objectivesText"] = "Complete the \"Brewing Storm\" Scenario.", ["rewardGold"] = 456000, ["rewardXP"] = 471000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard" },
[30584] = { ["id"] = 30584, ["name"] = "Shocking!", ["requiredLevel"] = 90, ["faction"] = "both", ["requiredProfessions"] = { "fishing" }, ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 30584 }, ["description"] = "Have you ever had a fresh dojani eel <name>? No? Well you have not lived then! Head north up to the dojani river and fish up a few for us. Be careful, those eels can zap you if you're not careful!", ["objectivesText"] = "Fish up 7 Dojani Eels from the Dojani River in Krasarang Wilds. Progress: Were you able to catch the eels?", ["rewardGold"] = 700, ["rewardXP"] = 236000, ["rewardItems"] = { 25978, 33820, 45991, 60218, 74859, 74865, 74866, 80260, 81175, 87557, 87686 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3287 } },
[30585] = { ["id"] = 30585, ["name"] = "What Lurks Below", ["requiredLevel"] = 90, ["faction"] = "both", ["requiredProfessions"] = { "fishing" }, ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 30585 }, ["description"] = "Legend tells of a great beast in the forest to the north. My son is missing and I fear he may have wandered too near its lair.... Head northwest to Krasari Falls and look for a mysterious whirlpool - this is the key to revealing what is hidden there. Kill the wretched beast and recover any clues to my son's whereabouts.", ["objectivesText"] = "Find an Ancient Fishing Pool at Krasari Falls to the northwest and fish in it to lure the beast out of hiding. Progress: What news of my son?", ["rewardGold"] = 700, ["rewardXP"] = 236000, ["rewardItems"] = { 80262 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3287 } },
[30586] = { ["id"] = 30586, ["name"] = "Jagged Abalone", ["requiredLevel"] = 90, ["faction"] = "both", ["requiredProfessions"] = { "fishing" }, ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 30586 }, ["description"] = "Pandaren have been harvesting jagged abalone in this area for generations. Now it's time for you to learn the ritual. The abalone can be found just northeast of here in narsong trench. Be careful, we have noticed increased shark activity in that area recently.", ["objectivesText"] = "Harvest 9 Jagged Abalone Meat from the Jagged Abalone in Narsong Trench to the northeast. Progress: Did you see any sharks down there?", ["rewardGold"] = 8000, ["rewardXP"] = 236000, ["rewardItems"] = { 19979, 80277 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3287 } },
[30589] = { ["id"] = 30589, ["name"] = "Wrecking the Wreck", ["level"] = 9, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5736, ["mapID"] = 378, ["storyline"] = { 30589 }, ["series"] = { 29795, 30590 }, ["description"] = "To dislodge the alliance ship, we need to find our engineer. He parted ways with us when we were escaping the wreckage. You should be able to find him somewhere in the western forest. Tell him Korga sent you and he'll get in line to help.", ["objectivesText"] = "Speak to Makael Bay in the Pei-Wu Forest.", ["rewardGold"] = 300, ["rewardXP"] = 780, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5736 } }, ["questType"] = "standard", ["db2PoiMapID"] = 860, ["db2PoiUiMapID"] = 378, ["questLines"] = { { ["id"] = 573, ["name"] = "The Wandering Isle", ["orderIndex"] = 60, ["flags"] = 0 } } },
[30590] = { ["id"] = 30590, ["name"] = "Handle With Care", ["level"] = 9, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5736, ["mapID"] = 378, ["storyline"] = { 30590 }, ["series"] = { 29795, 30589 }, ["description"] = "We can help you get your ship free, but we'll need more of the explosives we were trying to take back from the Alliance to make it happen. I ordered the men to grab all the explosives they could before making our escape. If you sift through the wreckage and bodies to our south, there should be some explosive bundles among them, those that didn't already blow up anyway. Get me enough of them and I think I can put something together for ya.", ["objectivesText"] = "Recover 6 Packed Explosive Charges. Progress: You're in one piece. That's a good sign. Did you get your hands on what I asked for?", ["rewardGold"] = 300, ["rewardXP"] = 780, ["rewardItems"] = { 74955 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5736 } }, ["questType"] = "standard", ["db2PoiMapID"] = 860, ["db2PoiUiMapID"] = 378, ["questLines"] = { { ["id"] = 573, ["name"] = "The Wandering Isle", ["orderIndex"] = 62, ["flags"] = 0 } } },
[30591] = { ["id"] = 30591, ["name"] = "Preying on the Predators", ["level"] = 9, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5736, ["mapID"] = 378, ["storyline"] = { 30591 }, ["series"] = { 29788, 29789, 29790, 29791, 29792 }, ["description"] = "The forest has become far more dangerous ever since Shen-zin Su began shaking. The tigers are agitated and have begun attacking the refugees, and on occasion, me as well. If these injured and weak survivors are to make it to safety here at the hut, we need to help clear the forest for them.", ["objectivesText"] = "Kill 9 Pei-Wu Tigers .", ["rewardGold"] = 300, ["rewardXP"] = 780, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5736 } }, ["questType"] = "standard", ["db2PoiMapID"] = 860, ["db2PoiUiMapID"] = 378, ["questLines"] = { { ["id"] = 573, ["name"] = "The Wandering Isle", ["orderIndex"] = 58, ["flags"] = 0 } } },
[30596] = { ["id"] = 30596, ["name"] = "A Zandalari Troll?", ["level"] = 87, ["requiredLevel"] = 87, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5841, ["storyline"] = { 30596 }, ["series"] = { 30650 }, ["description"] = "While you've been destroying the reanimated mogu statues, the unmistakable accent of a Zandalari troll has been taunting you. It's clear that the threat to Westerly Rest will not end until he's been dealt with.", ["objectivesText"] = "Kill the Zandalari Soulraiser.", ["rewardGold"] = 204000, ["rewardXP"] = 161000, ["rewardItems"] = { 82487, 82488, 82489, 82490, 82491, 82492, 82493, 82494, 82495 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard" },
[30597] = { ["id"] = 30597, ["name"] = "Strange Spherical Stone", ["requiredLevel"] = 85, ["faction"] = "none", ["requiredProfessions"] = { "alchemy" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["storyline"] = { 30597 }, ["description"] = "This beautiful stone clearly has magical potential... at least to one trained in alchemy. You are certain that with the right herbs native to Pandaria, this stone could become very useful.", ["objectivesText"] = "Infuse the stone with several Golden Lotus .", ["rewardXP"] = 69400, ["rewardItems"] = { 36908, 72238, 75274, 76061, 80240, 89112 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["startItems"] = { 80240 } },
[30598] = { ["id"] = 30598, ["name"] = "Who Knew Fish Liked Eggs?", ["requiredLevel"] = 90, ["faction"] = "both", ["requiredProfessions"] = { "fishing" }, ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 30598 }, ["description"] = "Great cranes have been nesting in this area for generations. The Narsong Spires provide a sheltered area to rear their young. Their pristine eggs are revered as bait for catching the silver goby . Retrieve a crane egg and see if you can catch a goby!", ["objectivesText"] = "Collect a Pristine Egg from the Narsong Spires and use it to catch a Silver Goby . Progress: Did you catch a silver goby ?", ["rewardGold"] = 8000, ["rewardXP"] = 236000, ["rewardItems"] = { 80303, 80310 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3287 } },
[30613] = { ["id"] = 30613, ["name"] = "Armored Carp", ["requiredLevel"] = 90, ["faction"] = "both", ["requiredProfessions"] = { "fishing" }, ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 30613 }, ["description"] = "Armored Carp are a delicacy around these parts. Unfortunately we can't fish them up since they snap our hooks with their powerful jaws. Take this fishing spear and see if you can catch a few for us.", ["objectivesText"] = "Use the Fishing Spear to catch 5 Armored Carp in the waters south of Anglers Wharf. Progress: Any luck with that fishing spear?", ["rewardGold"] = 8000, ["rewardXP"] = 236000, ["rewardItems"] = { 80403, 80437 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3287 } },
[30614] = { ["id"] = 30614, ["name"] = "Oil Stop", ["level"] = 88, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["storyline"] = { 30614 }, ["description"] = "When the yaungols came, they began to dig up oil. What is this \"oil\", I wonder? Perhaps it is thing of much undiscovered luck. This I must know. Here, take this vial, and fill it with yaungol oil from one of their windmills. I will give you many fortunes if you bring me some.", ["objectivesText"] = "Fill the Empty Oil Vial at a Yaungol Oil Derrick. Progress: Yaungols are scary. Yaungols with a luckydo like this \"oil\" are more scary.", ["rewardGold"] = 106000, ["rewardXP"] = 162000, ["rewardItems"] = { 80311, 80312 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard" },
[30615] = { ["id"] = 30615, ["name"] = "A Zandalari Troll?", ["level"] = 87, ["requiredLevel"] = 87, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5841, ["storyline"] = { 30615 }, ["series"] = { 30655 }, ["description"] = "While you've been destroying the reanimated mogu statues, the unmistakable accent of a Zandalari troll has been taunting you. It's clear that the threat to Westerly Rest will not end until he's been dealt with.", ["objectivesText"] = "Kill the Zandalari Soulraiser.", ["rewardGold"] = 204000, ["rewardXP"] = 161000, ["rewardItems"] = { 82487, 82488, 82489, 82490, 82491, 82492, 82493, 82494, 82495 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard" },
[30616] = { ["id"] = 30616, ["name"] = "Traffic Issues", ["level"] = 88, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["storyline"] = { 30616 }, ["series"] = { 30592, 30599, 30600, 30602, 30603, 30604, 30605, 30607, 30608, 30610, 30617 }, ["description"] = "Yaungols are attacking our Burlap Trail. This is most bad fortune for grummles. We use that trail to carry supplies to the Serpent's Spine. Without supplies, the defenders of the wall are in danger. Grummles are packers and explorers, not fighters. Could you be a luckydo for us and stop the yaungol blockade?", ["objectivesText"] = "Defeat 8 Fire Camp Ruqin Yaungols.", ["rewardGold"] = 106000, ["rewardXP"] = 162000, ["rewardItems"] = { 82569, 82570, 82571, 82572, 82573 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard" },
[30617] = { ["id"] = 30617, ["name"] = "Roadside Assistance", ["level"] = 88, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["storyline"] = { 30617 }, ["series"] = { 30592, 30599, 30600, 30602, 30603, 30604, 30605, 30607, 30608, 30610, 30616 }, ["description"] = "A luckydo remembers to bring incense on a journey in to the mountains. The smellier the luck the better. Can you journey up the road to One Keg and light the incense you find along the way? This will give good fortune to grummles that must travel the road. Brother Lintpocket", ["objectivesText"] = "Light 8 Lucky Burlap Incense sticks along the road to One Keg.", ["rewardGold"] = 106000, ["rewardXP"] = 162000, ["rewardItems"] = { 88381 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard" },
[30629] = { ["id"] = 30629, ["name"] = "FLAG - Player Began Finale", ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 30629 }, ["description"] = "Oh, hello. Are you looking for the owner of this place? Then look to the pandaren up at the top of the stairs. I'm just a visitor... like you. Now if you'll excuse me, my friends and I trying to decide something. We can talk again afterwards.", ["objectivesText"] = "Listen to Xiao and his companions.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[30631] = { ["id"] = 30631, ["name"] = "The Shrine of Seven Stars", ["level"] = 87, ["requiredLevel"] = 87, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 30631 }, ["description"] = "Look at this creature, traveler. Only moments after we arrived, this mogu assassin attacked with no warning. His blade was intended for the leader of the Golden Lotus. It is very lucky indeed that we were here to stop the attack. Seeing this attempt on Zhi's life, I fear for the safety of those who have already entered the valley. The caretakers are settling your people into the city to the southeast. Go and speak to the leaders. Make sure they are safe.", ["objectivesText"] = "Speak to Jaluu the Generous , Kuru the Light-Hearted , Lucky Lin, and Matron Vi Vinh in the Vale of Eternal Blossoms . Progress: The cities are springing back to life.", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[30633] = { ["id"] = 30633, ["name"] = "Out with the Scouts", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 30633 }, ["series"] = { 30632, 30635 }, ["description"] = "We'd been briefed on mogu sightings in the Vale, but the situation is worse than we had anticipated. Scouts are swarming all over the ruins to the northwest, gathering intel and stealing treasures. Your objective is clear - dispatch of any scouts you see. An army cannot move if we take out its eyes.", ["objectivesText"] = "Kill 8 Shao-Tien Precursor . Progress: Are the scouts taken care of?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[30634] = { ["id"] = 30634, ["name"] = "Barring Entry", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 30634 }, ["description"] = "Lao Softfoot and I scouted up the ruins to the north. It looks like the mogu are infiltrating the valley through a cave just up the hill, and already they are sending formidable reinforcements through. There are too many enemies to take them head on, so you'll have to meet Lao Softfoot at the entrance to the ruins. He'll help you sneak in under the cover of stealth. Then, plant this keg of explosives at the mouth of the cave. The rest should take care of itself.", ["objectivesText"] = "Speak to Lao Softfoot at the entrance to Ruins Rise and follow him up the trail. Then, plant the Explosive Keg at the Ruins Rise Cave Entrance. Progress: Is the cave closed?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 79864, 80484, 87394, 87400, 87401, 87841, 88855, 89366 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[30636] = { ["id"] = 30636, ["name"] = "Stones of Power", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 30636 }, ["description"] = "Many thousands of years ago, the rulers of the Vale sought energy from a powerful crystal known as Revelite. With this substance, they were able to power cities, factories, and engines of war. Zhi the Harmonious has asked us to collect some crystals and bring them back to the city. Keep an eye out for them while you are in the ruins.", ["objectivesText"] = "Collect 7 Revelite Crystals . Progress: Did you find the crystals?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 80511 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[30637] = { ["id"] = 30637, ["name"] = "The Guo-Lai Halls", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 30637 }, ["description"] = "As you pass by the great door, you hear sounds from deep inside. Anji mentioned that advance mogu scouts had been sighted in this area. Perhaps they made their way down to the depths below. Your senses tingling, you decide to investigate.", ["objectivesText"] = "Investigate the mogu presence in the Guo-Lai Halls. Progress: What did you find in the Halls?", ["rewardGold"] = 228000, ["rewardXP"] = 294000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[30639] = { ["id"] = 30639, ["name"] = "The Secrets of Guo-Lai", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 30639 }, ["description"] = "I just received information from a guard stationed near the Ruins of Guo-Lai that the Shado-Tien leader entered the halls, killing two of my men in the process. They're intent on something inside. We need to stop them. He Softfoot has already followed them in. He should be waiting for you at the entrance to the western chambers. Move quickly, <name>. I don't like the thought that the mogu may be a step ahead of us.", ["objectivesText"] = "Meet with He Softfoot in the Guo-Lai Halls and uncover the mogu's purpose in the western chamber. Progress: What are you waiting for? Find He. Stop the Shao-Tien!", ["rewardGold"] = 228000, ["rewardXP"] = 294000, ["rewardItems"] = { 86592, 87779, 90614, 90615, 90616, 90617, 90618 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[30640] = { ["id"] = 30640, ["name"] = "Battle Spear of the Thunder King", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 30640 }, ["description"] = "I have received some troubling news, <name>. The mogu are plotting to steal three artifacts of power from the Vale. We must retrieve the artifacts immediately and hide them for safekeeping. The first artifact is the Battle Spear of the Thunder King . Upon emperor Lei Shen's death, the spear was placed in an ancient shrine to the northwest. Bring the spear back to me.", ["objectivesText"] = "Retrieve the Battle Spear of the Thunder King . Progress: It was said that the most powerful of ancient mogu could call the powers of the elements. The Thunder King himself could channel the forces of lightning onto his spear.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 80808, 81194 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[30641] = { ["id"] = 30641, ["name"] = "Battle Helm of the Thunder King", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 30641 }, ["description"] = "The second artifact of power is the Battle Helm of the Thunder King . Emperor Lei Shen wore the helm into every battle. It became so well-known that his enemies would flee at the mere sight of it. When the Emperor died, they placed the helm in the very bottom of the Guo-Lai Halls to the west, surrounded by thousands of terracotta soldiers. Thus, they could look upon their leader and follow him into death.", ["objectivesText"] = "Retrieve the Battle Helm of the Thunder King . Progress: History claims that Lei Shen feared no enemy except for one. And in the end, it was death that finally defeated him.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 80222 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[30642] = { ["id"] = 30642, ["name"] = "Battle Axe of the Thunder King", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 30642 }, ["description"] = "The final artifact is the Thunder King's axe. Lei Shen charged into battle with his spear in one hand, and his axe in the other. It is said that he could throw his axe with brutal accuracy, and when it hit its target, it made a sound like crashing thunder. After his death, the axe was placed in a ceremonial chamber to the southwest. Needless to say, we must not let it fall into the mogu's hands.", ["objectivesText"] = "Retrieve the Battle Axe of the Thunder King . Progress: Did you find the axe?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 80807, 90597, 90598, 90599, 90600, 90601, 90602, 90603, 90607, 90609 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[30643] = { ["id"] = 30643, ["name"] = "The Mogu's Message", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 30643 }, ["description"] = "The battle against the mogu rages fiercely with neither side giving quarter. We cannot hold our position forever. Something must be done to strike a blow at the mogu, a blow from which they cannot recover. Go check in with Zhi the Harmonious at The Silent Sanctuary. I wish to hear his thoughts on this matter.", ["objectivesText"] = "Speak to Zhi the Harmonious at The Silent Sanctuary in the Vale of Eternal Blossoms .", ["rewardGold"] = 57000, ["rewardXP"] = 118000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[30644] = { ["id"] = 30644, ["name"] = "What Comes to Pass", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 30644 }, ["description"] = "You had better report back to the Golden Pagoda immediately.", ["objectivesText"] = "Speak to Sun Tenderheart at the Golden Pagoda in the Vale of Eternal Blossoms .", ["rewardGold"] = 57000, ["rewardXP"] = 118000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[30645] = { ["id"] = 30645, ["name"] = "The Might of Three", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 30645 }, ["series"] = { 30646 }, ["description"] = "This is it, <name>. This is the end. If we don't drive the mogu from the valley, they will seize the remnants of their ancient power and use it to break Pandaria to their will. But our forces are few, and tired, and small. We bleed, while their warriors are made of stone. <name>, although all odds are against us, still I must ask you to go and help our forces slay the mogu invaders. I have prayed to the Celestials, begging their aid. I can only hope that they answer our call.", ["objectivesText"] = "Slay 100 mogu invaders at the Summer Fields in the Vale of Eternal Blossoms .", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 87781, 87782, 87783 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[30646] = { ["id"] = 30646, ["name"] = "The Final Power", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 30646 }, ["series"] = { 30645 }, ["description"] = "I never thought it would come to this! Leven went to face Warlord Zhao-Jin the Bloodletter at the top of the palace steps, but our reinforcements cannot get through! We are the only ones who stand between him and the Vale's greatest... and most deadly... powers. Please, <name>, you must find a way to stop him!", ["objectivesText"] = "Kill Warlord Zhao-Jin the Bloodletter .", ["rewardGold"] = 228000, ["rewardXP"] = 294000, ["rewardItems"] = { 90592, 90593, 90594, 90595, 90596 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[30649] = { ["id"] = 30649, ["name"] = "The Shrine of Two Moons", ["level"] = 87, ["requiredLevel"] = 87, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 30649 }, ["description"] = "Look at this creature, traveler. Only moments after we arrived, this mogu assassin attacked with no warning. His blade was intended for the leader of the Golden Lotus. It is very lucky indeed that we were here to stop the attack. Seeing this attempt on Zhi's life, I fear for the safety of those who have already entered the valley. The caretakers are settling your people into the city to the northeast. Go and speak to the leaders. Make sure they are safe.", ["objectivesText"] = "Speak to Jaluu the Generous , Mokimo the Strong , Elder Liao , and Madam Vee Luo in the Vale of Eternal Blossoms . Progress: The cities are springing back to life.", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[30654] = { ["id"] = 30654, ["name"] = "The Guo-Lai Halls", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 30654 }, ["description"] = "The mogu are up to something, I can feel it. They've been sending scouts down into the Guo-Lai Halls. According to the caretakers, the Halls are home to ancient treasures of emperors past. Not only riches, but artifacts of great power. We must prevent the mogu from accessing these treasures! Go down the ramp to the northwest and stop them!", ["objectivesText"] = "Investigate the mogu presence in the Guo-Lai Halls.", ["rewardGold"] = 228000, ["rewardXP"] = 294000, ["rewardItems"] = { 87779 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[30673] = { ["id"] = 30673, ["name"] = "Holed Up", ["level"] = 87, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["storyline"] = { 30673 }, ["description"] = "Thank the heavenly spirits for you, <class>! I don't know how much longer I could've lasted. There are other Firebough Nook survivors, I'm sure of it. Will you help rescue them and get us to the safety of Shado-Pan Fallback?", ["objectivesText"] = "Rescue Jin Warmkeg , Ya Firebough , Old Lady Fung , and Sya Zhong .", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["rewardItems"] = { 88579 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard" },
[30678] = { ["id"] = 30678, ["name"] = "Like Bombing Fish In A Barrel", ["requiredLevel"] = 90, ["faction"] = "both", ["requiredProfessions"] = { "fishing" }, ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 30678 }, ["description"] = "Turns out these rays are not as easy to catch as I thought! You seem like a pretty smart guy, think you can help me out? I made the bombs but have been having trouble using the raft with my hurt leg. The rays are common in the shallows just west of here. Take the bombs and use my raft to bring me back their stingers ! Oh yeah, watch out for the hammerheads!", ["objectivesText"] = "Use the Goblin Fishing Bombs to kill 3 Sting Rays and bring back their stingers to Fiznix . The Rays can be found in the shallows west of Anglers Wharf. Progress: Find any sting rays in the shallows?", ["rewardGold"] = 8000, ["rewardXP"] = 236000, ["rewardItems"] = { 80599, 80600, 85500 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3287 } },
[30680] = { ["id"] = 30680, ["name"] = "Holed Up", ["level"] = 87, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["storyline"] = { 30680 }, ["description"] = "Oh thank you, thank you, thank you. If you hadn't come along... Wait! There must be other survivors in the Nook like me! Please, <class>, I beg you. Rescue the rest of my citizens and deliver us safely to Shado-Pan Fallback.", ["objectivesText"] = "Rescue Jin Warmkeg , Ya Firebough , Old Lady Fung , and Sya Zhong .", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["rewardItems"] = { 88579 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard" },
[30681] = { ["id"] = 30681, ["name"] = "Holed Up", ["level"] = 87, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["storyline"] = { 30681 }, ["description"] = "Oh, thank you! There's no way I could have made it back on my own. Come to think of it, there must be others around Firebough Nook that need to be rescued. Shall we go collect them and then head to the safety of Shado-Pan Fallback?", ["objectivesText"] = "Rescue Jin Warmkeg , Ya Firebough , Old Lady Fung , and Sya Zhong .", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["rewardItems"] = { 88579 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard" },
[30692] = { ["id"] = 30692, ["name"] = "The Burlap Trail: To Kota Basecamp", ["level"] = 88, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 30692 }, ["description"] = "This here's hozen lands. Very dangerous. But grummles must trek through. Supplies must reach the Serpent's Spine. Go, protect the next wave of grummles on their trek to Kota Basecamp. If at least one survives, good fortune will find its way to you.", ["objectivesText"] = "Protect a group of grummles from the Burlap Waystation to the Kota Basecamp. At least one grummle must survive. If you lose your grummles, you can search the Burlap Trial or return to the Burlap Waystation and wait for the next group to leave. Progress: Welcome to Kota Basecamp, friend of grummles.", ["rewardGold"] = 106000, ["rewardXP"] = 162000, ["rewardItems"] = { 82584, 82585, 82586, 82587, 82588 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 560, ["name"] = "Kun-Lai Summit", ["orderIndex"] = 70, ["flags"] = 0 } } },
[30698] = { ["id"] = 30698, ["name"] = "Scavenger Hunt", ["requiredLevel"] = 90, ["faction"] = "both", ["requiredProfessions"] = { "fishing" }, ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 30698 }, ["description"] = "YOU! You're just who I have been looking for! I need more parts for my goblin fishing bombs but I hurt my leg and can't collect them myself. You see those shipwrecks nearby? I bet they have just what I need if you can get to it and fish it out. Take my fishing raft and see what you can find! My buddy has been trying to help me out too so you might find some extra rafts near the wreckage, feel free to use em' too.", ["objectivesText"] = "Use the Goblin Fishing Raft to fish up 15 Rusty Shipwreck Parts out of the floating debris near the shipwrecks. Progress: Did you find the shipwrecks?", ["rewardGold"] = 8000, ["rewardXP"] = 236000, ["rewardItems"] = { 80830, 85500, 85973 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3287 } },
[30700] = { ["id"] = 30700, ["name"] = "Snapclaw", ["requiredLevel"] = 90, ["faction"] = "both", ["requiredProfessions"] = { "fishing" }, ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 30700 }, ["description"] = "A giant, poisonous crab is wrecking havoc on our local abalone stores. I need you to go down into narsong trench and take it out!", ["objectivesText"] = "Kill Snapclaw in a cave at the bottom of Narsong Trench and return with his claw as proof. Progress: Did you take out that nasty crawler?", ["rewardGold"] = 700, ["rewardXP"] = 236000, ["rewardItems"] = { 80831 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3287 } },
[30701] = { ["id"] = 30701, ["name"] = "Viseclaw Soup", ["requiredLevel"] = 90, ["faction"] = "both", ["requiredProfessions"] = { "fishing" }, ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 30701 }, ["description"] = "Nothing tastes quite like viseclaw soup. It's a krasarang specialty! I was just about to start up on a new batch when I realized I am missing a key ingredient, the eyes! I need you to kill the viseclaw fishers on the beach and return with their eyes for the soup!", ["objectivesText"] = "Kill Viseclaw Fishers on the beach and return with 16 eyes to make some yummy soup. Progress: How many of their beady little eyes did you get?", ["rewardGold"] = 8000, ["rewardXP"] = 236000, ["rewardItems"] = { 80832 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3287 } },
[30710] = { ["id"] = 30710, ["name"] = "Provoking the Trolls", ["level"] = 87, ["requiredLevel"] = 87, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["storyline"] = { 30710 }, ["description"] = "We've managed to push them back this far, but I doubt that we will remain safe for long if we do not deal with them once and for all. My husband, coward or fool that he is, does not wish to provoke them. I will not be cowed so. We will do just that. Slay their forward scouts. Perhaps we can provoke - and then defeat - their leader.", ["objectivesText"] = "Kill 10 Zandalari Stalkers and 5 Zandalari Hexers", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[30714] = { ["id"] = 30714, ["name"] = "Destroy the Leaders", ["level"] = 87, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["storyline"] = { 30714 }, ["description"] = "And, now they fear you. Their leaders, a Blademaster and a Mage, lie deeper in the ruins. Kill them. Make them hurt. For us.", ["objectivesText"] = "Kill the Zandalari Blademaster and Zandalari Mage", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[30716] = { ["id"] = 30716, ["name"] = "Chasing Hope", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 30716 }, ["description"] = "Chi-Ji is always with us. Even when he is not here in the Cradle, pieces of his spirit run through the forests and beaches of the island, watching us and testing us. Prove your dexterity in the eyes of Chi-Ji, <name>. Find and catch the spirits of the crane.", ["objectivesText"] = "Touch 3 Spirits of the Crane . Progress: Return when you are finished, <name>. Now go!", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 43001, 67486 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3281 } },
[30717] = { ["id"] = 30717, ["name"] = "Gifts of the Great Crane", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 30717 }, ["description"] = "The cranes of Krasarang are a gift from Chi-Ji. Even the very feathers they leave behind are a gift for us to appreciate. We use these feathers to adorn our garments and to fletch arrows. But first... they must be gathered.", ["objectivesText"] = "Obtain 10 Gifts of the Great Crane . Progress: Even the smallest, flimsiest feather is proof enough that Chi-Ji loves us.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 80938 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3281 } },
[30718] = { ["id"] = 30718, ["name"] = "Students of Chi-Ji", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 30718 }, ["description"] = "Our order prides itself on excellence in combat. We hone these combat skills by dueling one another, here on the Cradle of Chi-Ji. Prove yourself in the eyes of the Red Crane. Venture south, into the center of the island, and duel with your fellow students.", ["objectivesText"] = "Duel 10 Students of Chi-Ji. Progress: Your trial is not yet complete, <name>.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3281 } },
[30725] = { ["id"] = 30725, ["name"] = "Ellia Ravenmane", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 30725 }, ["description"] = "We regularly organize one-on-one duels with trainees that we think are well-suited for one another. We have found one such trainee for you, <name>. Her name is Ellia Ravenmane . This will be her first duel, too. She will be waiting for you at the pavilion just to the south of here.", ["objectivesText"] = "Defeat Ellia Ravenmane at the Angkhal Pavilion. Progress: Yes, you and Ellia should be a perfect match...", ["rewardGold"] = 228000, ["rewardXP"] = 294000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3281 } },
[30726] = { ["id"] = 30726, ["name"] = "Minh Do-Tan", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 30726 }, ["description"] = "Your next challenger is another relatively new trainee. His name is Minh Do-Tan , and he has won his last two matches. He will be waiting for you near the crane statue to the south.", ["objectivesText"] = "Defeat Minh Do-Tan . Progress: Fight hard, <name>.", ["rewardGold"] = 228000, ["rewardXP"] = 294000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3281 } },
[30727] = { ["id"] = 30727, ["name"] = "Ellia Ravenmane: Rematch", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 30727 }, ["description"] = "Ellia Ravenmane requested a rematch with you. She seems to identify you as her \"rival\". We discourage rivalries here within the Cradle of Chi-Ji, but we rarely decline a rematch request. You will find Ellia near the Pedestal of Hope, on the island's eastern side.", ["objectivesText"] = "Defeat Ellia Ravenmane near the base of the Pedestal of Hope.", ["rewardGold"] = 228000, ["rewardXP"] = 294000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3281 } },
[30728] = { ["id"] = 30728, ["name"] = "Fat Long-Fat", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 30728 }, ["description"] = "You have been matched with a... special trainee. His name is Fat Long-Fat . < Thelonius chooses his words carefully.> Fat Long-Fat ... operates outside of the normal rules of combat. He does not fight every day, and when he does, he chooses his competitor. Today, for some reason... he has selected you. You will find him atop Angkhal Pavilion.", ["objectivesText"] = "Defeat Fat Long-Fat at the top of Angkhal Pavilion.", ["rewardGold"] = 228000, ["rewardXP"] = 294000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3281 } },
[30729] = { ["id"] = 30729, ["name"] = "Julia Bates", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 30729 }, ["description"] = "We welcome all kinds here within the Cradle, as long as they recognize and subscribe to the ideologies of the Red Crane. One of our new, more exotic trainees comes from the human kingdoms to the northeast. She goes by the rather foreign-sounding name of Julia Bates . She is your next challenger. You will find her on the island's western shore.", ["objectivesText"] = "Defeat Julia Bates . Progress: Stay strong, <name>.", ["rewardGold"] = 228000, ["rewardXP"] = 294000, ["rewardItems"] = { 85500 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3281 } },
[30730] = { ["id"] = 30730, ["name"] = "Dextrous Izissha", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 30730 }, ["description"] = "Jinyu normally avoid our order, but every few years, we find one that subscribes to the way of the Crane. One such jinyu is Dextrous Izissha . Izissha is your next challenger. He waits for you on the island's southwestern shore.", ["objectivesText"] = "Defeat Dextrous Izissha .", ["rewardGold"] = 228000, ["rewardXP"] = 294000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3281 } },
[30731] = { ["id"] = 30731, ["name"] = "Kuo-Na Quillpaw", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 30731 }, ["description"] = "Most of the duels within the Cradle take place between two trainees. Rarely, when a trainee exhibits a rare amount of skill, they will have an opportunity to duel their trainer. Today, you duel against Kuo-Na. She will be waiting for you at the Pedestal of Hope.", ["objectivesText"] = "Defeat Kuo-Na Quillpaw .", ["rewardGold"] = 228000, ["rewardXP"] = 294000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3281 } },
[30732] = { ["id"] = 30732, ["name"] = "Ellia Ravenmane: Revenge", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 30732 }, ["description"] = "Your \"rival\" has appeared again. Ellia Ravenmane has been avoiding her duties on the island, instead focusing on personal training, with the intent to defeat you in battle. \"I will destroy <name>,\" she said. I have honored her request for a rematch, but I will be keeping a close eye on her. Her motives may be shifting in a dangerous direction.", ["objectivesText"] = "Defeat Ellia Ravenmane at Dome Balrissa.", ["rewardGold"] = 228000, ["rewardXP"] = 294000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3281 } },
[30733] = { ["id"] = 30733, ["name"] = "Tukka-Tuk", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 30733 }, ["description"] = "You are making a name for yourself, <name>. I received a challenge from one of our more skilled competitors. He believes you are not as strong as you seem. His name is Tukka-Tuk , the hozen. If you've ever fought against hozen before, you know that their apparent juvenility belies their battle acumen. Good luck.", ["objectivesText"] = "Defeat Tukka-Tuk .", ["rewardGold"] = 228000, ["rewardXP"] = 294000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3281 } },
[30734] = { ["id"] = 30734, ["name"] = "Huck Wheelbarrow", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 30734 }, ["description"] = "Usually our trainees are adventurers like yourself, or monks from Tian Monastery, or occasionally retired Shado-Pan. Very rarely, though, we will greet trainees that have no fighting experience whatsoever. Huck Wheelbarrow is one such trainee. He has requested a duel with you. Look for him on the island's western shore.", ["objectivesText"] = "Defeat Huck Wheelbarrow .", ["rewardGold"] = 228000, ["rewardXP"] = 294000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3281 } },
[30735] = { ["id"] = 30735, ["name"] = "Mindel Sunspeaker", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 30735 }, ["description"] = "Our highest-ranked trainee is an outsider like you. It is both strange and exciting to live in a time when so many foreigners have embraced the way of the Crane. Your challenger's name is Mindel Sunspeaker , and he awaits you within Angkhal Pavilion.", ["objectivesText"] = "Defeat Mindel Sunspeaker .", ["rewardGold"] = 228000, ["rewardXP"] = 294000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3281 } },
[30736] = { ["id"] = 30736, ["name"] = "Yan Quillpaw", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 30736 }, ["description"] = "You have already defeated Kuo-Na Quillpaw. You have not yet fought her brother, Yan. He will meet you at the Pedestal of Hope, and he will not hold back. His reputation as a trainer is at stake.", ["objectivesText"] = "Defeat Yan Quillpaw at the Pedestal of Hope.", ["rewardGold"] = 228000, ["rewardXP"] = 294000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3281 } },
[30737] = { ["id"] = 30737, ["name"] = "Fat Long-Fat: Rematch", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 30737 }, ["description"] = "Fat Long-Fat has requested another match with you. I find this strange. And concerning. He will be waiting atop the Dome Belrissa.", ["objectivesText"] = "Defeat Fat Long-Fat atop Dome Belrissa.", ["rewardGold"] = 228000, ["rewardXP"] = 294000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3281 } },
[30738] = { ["id"] = 30738, ["name"] = "Thelonius", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 30738 }, ["description"] = "When we last spoke, I promised to tell you the secret of Fat Long-Fat. I still plan to tell you that secret... after I determine your worth. I will meet you on the western shore, and we will duel.", ["objectivesText"] = "Defeat Thelonius .", ["rewardGold"] = 228000, ["rewardXP"] = 294000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3281 } },
[30739] = { ["id"] = 30739, ["name"] = "Ellia Ravenmane: Redemption", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 30739 }, ["description"] = "Ellia Ravenmane , your rival, has returned. She demands that you meet her atop the Pedestal of Hope. You need to understand, <name>... something horrible has happened to her. She has changed. You will see for yourself when you arrive at the pedestal. Good luck, <name>.", ["objectivesText"] = "Defeat Ellia Ravenmane atop the Pedestal of Hope.", ["rewardGold"] = 228000, ["rewardXP"] = 294000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3281 } },
[30740] = { ["id"] = 30740, ["name"] = "Champion of Chi-Ji", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["requiredRaces"] = { 5, 6, 11 }, ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 30740 }, ["description"] = "While you will always hold a place of honor among our order, you are still welcome to participate in our duels. One of our current champions awaits you in the Dome Balrissa. I know that they would be honored to duel with you.", ["objectivesText"] = "Defeat a Champion of Chi-Ji .", ["rewardGold"] = 228000, ["rewardXP"] = 294000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3281 } },
[30753] = { ["id"] = 30753, ["name"] = "Jumping the Shark", ["requiredLevel"] = 90, ["faction"] = "both", ["requiredProfessions"] = { "fishing" }, ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 30753 }, ["description"] = "There is only one way to kill sharks where I come from, with your bare hands! I dumped a good amount of chum in the water just off the dock here, this place should be crawling with the local reef sharks in no time. Hop on the first one you see and take it out!", ["objectivesText"] = "Kill a frenzied reef shark with your bare hands. Progress: Did you show that shark who's boss?", ["rewardGold"] = 700, ["rewardXP"] = 236000, ["rewardItems"] = { 86593 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3287 } },
[30754] = { ["id"] = 30754, ["name"] = "Bright Bait", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["requiredProfessions"] = { "fishing" }, ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 30754 }, ["description"] = "Certain fish are only attracted to bright lights. The forest north of here is home to a local pandaren firefly called a suncrawler . You should be able to find them on the base of the tree trunks all around that area. Bring me back a handful of them and I can use them for bait!", ["objectivesText"] = "Collect 7 Suncrawlers in the forest north of Anglers Wharf. Progress: Any luck with those suncrawlers ?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 81116 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3287 } },
[30757] = { ["id"] = 30757, ["name"] = "Lord of the Shado-Pan", ["level"] = 89, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5918, ["storyline"] = { 30757 }, ["series"] = { 30752, 30759, 31030, 31031 }, ["description"] = "Our lord, Taran Zhu , has been overcome by a sha of pure hatred. The whole monastery has been lost! <class>, you must find a way to free him of this possession. Last I knew, he was meditating in the Grove of Falling Blossoms.", ["objectivesText"] = "Rid Taran Zhu of his possession by the Sha of Hatred.", ["rewardGold"] = 440000, ["rewardXP"] = 392000, ["rewardItems"] = { 87315, 87316, 87317, 87318, 87319, 87320, 87321, 87322, 87323 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5918 } }, ["questType"] = "dungeon" },
[30763] = { ["id"] = 30763, ["name"] = "Piranha!", ["requiredLevel"] = 90, ["faction"] = "both", ["requiredProfessions"] = { "fishing" }, ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 30763 }, ["description"] = "Certain fish are very difficult to catch. The wolf piranha falls squarely into this category. Lucky for me that you showed up! Put those fishing skills to the test and bring me back a few from the krasarang river due northwest of here.", ["objectivesText"] = "Fish up 5 Wolf Piranha from the Krasarang River in Krasarang Wilds. Progress: Any luck?", ["rewardGold"] = 700, ["rewardXP"] = 236000, ["rewardItems"] = { 6256, 6532, 6533, 19022, 25978, 32727, 33820, 44050, 45190, 45194, 45195, 45196, 45198, 45200, 45201, 45991, 46377, 68049, 74859, 74865, 74866, 81122, 84660, 84661, 88496 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3287 } },
[30765] = { ["id"] = 30765, ["name"] = "Regaining Honor", ["level"] = 88, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["storyline"] = { 30765 }, ["series"] = { 30751 }, ["description"] = "<name>, the yaungol warchief, Humongous, killed Shado-Master Zhen. He has his banner. You have to kill Humongous and regain Zhen's honor! If you don't, I will.", ["objectivesText"] = "Retrieve Zhen's Banner .", ["rewardGold"] = 212000, ["rewardXP"] = 203000, ["rewardItems"] = { 80598 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[30766] = { ["id"] = 30766, ["name"] = "Profiting off of the Past", ["level"] = 87, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["storyline"] = { 30766 }, ["description"] = "<A relic drops off of the statue. Hmm, these could prove to be valuable to the right person.> <There's a collector on the outskirts of the ruins. Perhaps he'd be interested in purchasing them from you?>", ["objectivesText"] = "Collect 11 more Mogu Relics.", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["startItems"] = { 80597 } },
[30767] = { ["id"] = 30767, ["name"] = "Risking It All", ["level"] = 9, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5736, ["mapID"] = 378, ["storyline"] = { 30767 }, ["series"] = { 29665, 29798, 29799 }, ["description"] = "Wait, what?! How could he be so reckless? Blowing the ship free is insane! They could kill Shen-zin Su, and all of us with it. I know we don't have much time, but we need to think of another way...", ["objectivesText"] = "Remove the thorn from Shen-zin Su.", ["rewardGold"] = 300, ["rewardXP"] = 780, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5736 } }, ["questType"] = "standard", ["db2PoiMapID"] = 860, ["db2PoiUiMapID"] = 378, ["questLines"] = { { ["id"] = 573, ["name"] = "The Wandering Isle", ["orderIndex"] = 68, ["flags"] = 0 } } },
[30794] = { ["id"] = 30794, ["name"] = "Emergency Care", ["level"] = 87, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["storyline"] = { 30794 }, ["series"] = { 30805 }, ["description"] = "I... am alive... but barely. They killed the rest. My friends... and family... I must return to the village... But, I do not have long, and cannot move on my own... are you a healer? I... have a healing potion in my hut... search my belongings. You can use your magic, if you have it.", ["objectivesText"] = "Heal Sage Liao to get him back on his feet.", ["rewardGold"] = 51000, ["rewardXP"] = 64000, ["rewardItems"] = { 1251, 81177 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard" },
[30805] = { ["id"] = 30805, ["name"] = "Justice", ["level"] = 87, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["storyline"] = { 30805 }, ["series"] = { 30794 }, ["description"] = "After the mercenaries robbed us, most left. But one of them... after the others took all we had, he ran the rest of us through. For sport! Get justice for the fallen. Perhaps news of their death will raise my spirits enough to go on. You'll find them just west of here.", ["objectivesText"] = "Kill Captain Ripflesh and 6 Blackmane Mercenaries.", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["rewardItems"] = { 21395, 21396, 21397, 33271, 39770, 39776, 39778, 39818, 39833, 57829 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard" },
[30806] = { ["id"] = 30806, ["name"] = "The Scent of Life", ["level"] = 87, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["storyline"] = { 30806 }, ["description"] = "Many have perished here. We will need to honor them properly, which means gathering the makings of incense of life. It doesn't just smell nice - it has restorative properties, and can even help plants grow. Maybe I can get a whiff of the ingredients to get me back on my feet. The materials can be found on creatures around here - except for the spices, which were stolen by the mercenaries who pillaged the village.", ["objectivesText"] = "Gather an Opalescent Blue Crab Shell and 8 Stolen Pandaren Spices . Progress: Are those the ingredients for Incense of Life I smell on you? Or... perhaps you haven't bathed recently.", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["rewardItems"] = { 80907, 81261 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard" },
[30807] = { ["id"] = 30807, ["name"] = "By the Falls, For the Fallen", ["level"] = 87, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["storyline"] = { 30807 }, ["description"] = "I do not wish to dishonor my friends and leave them in unmarked graves. Yet, we have never needed to bury so many at once, and I am in no condition to gather materials. Please, visit the lakes that hug the mountains edge along the road to the south. Underneath the waterfalls there, you will find stones that have been polished to a sheen by the falling water. They will make suitable headstones.", ["objectivesText"] = "Gather 3 Waterfall-polished Stones . Progress: The stones - have you brought them?", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["rewardItems"] = { 81269 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard" },
[30808] = { ["id"] = 30808, ["name"] = "A Grummle's Luck", ["level"] = 88, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["storyline"] = { 30808 }, ["series"] = { 30488, 30491, 30492, 31456, 31457 }, ["description"] = "The yaungols stole our luckydos! Mean riders with spears took them from our caravan of brothers coming down the Burlap Trail. This is very bad fortune. If the yaungol discover the secrets of luckydos all grummles will be in big trouble. Recover our luckydos from Fire Camp Ruqin north of here and we will pay many fortunes to you.", ["objectivesText"] = "Find 8 Stolen Luckydos . Progress: A luckydo is a thing of much good fortune. Yaungol know nothing of how to use luckydos... yet.", ["rewardGold"] = 106000, ["rewardXP"] = 162000, ["rewardItems"] = { 81293 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard" },
[30816] = { ["id"] = 30816, ["name"] = "Checking In", ["level"] = 87, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["storyline"] = { 30816 }, ["description"] = "When the trolls came, they brought their mercenary... friends with them. I saw them go past us, to the fishing camp in the northwest. My cousin, a healer, lives there - can you check in with him and make sure he and his village are well?", ["objectivesText"] = "Check on Sage Liao at the Zaochin Strand in Kun-Lai Summit .", ["rewardGold"] = 10200, ["rewardXP"] = 12900, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard" },
[30817] = { ["id"] = 30817, ["name"] = "The Healing of Shen-zin Su", ["level"] = 9, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["storyline"] = { 30817 }, ["series"] = { 30818 }, ["description"] = "This is what comes of such recklessness. How could he think this was even a possibility? Nevermind, there's no time for that now. We need to act to save Shen-zin Su. Find any healers you can! Rescue them, relieve them - whatever you need to do to get them over here healing the wound. Keep the healers safe at all costs!", ["objectivesText"] = "Rescue and defend healers until Shen-zin Su's wound is healed.", ["rewardGold"] = 300, ["rewardXP"] = 780, ["rewardItems"] = { 74600, 74601, 74602 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[30818] = { ["id"] = 30818, ["name"] = "A New Fate", ["level"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["storyline"] = { 30818 }, ["series"] = { 30817 }, ["description"] = "<name>, I'm thankful the plan worked, but just barely. We would be sinking to the bottom of the ocean with all of Shen-zin Su if you hadn't been here. I don't think I can ever forgive Ji for this kind of recklessness. There will be plenty of time for reflection, but for now, we need to return to the Temple of Five Dawns. We need to let them know that Shen-zin Su has been saved, and we need to sort out the fates of these new allies.", ["objectivesText"] = "Return to the Temple of Five Dawns. A cart is waiting near the Skyfire Crash-Site to take you there.", ["rewardGold"] = 350, ["rewardXP"] = 840, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[30819] = { ["id"] = 30819, ["name"] = "Preparing the Remains", ["level"] = 87, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["storyline"] = { 30819 }, ["description"] = "Thank you much, friend. After this tragedy, it is good that fortune has smiled on us and sent you. You have gotten justice for my fallen friends, and gathered the necessary materials to honor them. I will gather their bodies, prepare the materials for their funerals, and meet you at the graveyard. In the meantime, however, please return to my cousin and ask him to gather the villagers for the funeral.", ["objectivesText"] = "Return to Li Hai and tell him about the funeral.", ["rewardGold"] = 10200, ["rewardXP"] = 12900, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard" },
[30820] = { ["id"] = 30820, ["name"] = "A Funeral", ["level"] = 87, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["storyline"] = { 30820 }, ["description"] = "As I said, I will gather the town - we will be at the funeral. As the one who has done so much to honor our friends, we feel it is only right that you will be the one to light the Incense of Life and usher their spirits to the life beyond.", ["objectivesText"] = "Attend the funeral and light the Incense of Life. Progress: You must light the incense to honor the dead.", ["rewardGold"] = 204000, ["rewardXP"] = 161000, ["rewardItems"] = { 82496, 82497, 82498, 82499, 82500, 82501, 82502, 82503, 82504 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard" },
[30821] = { ["id"] = 30821, ["name"] = "The Burlap Grind", ["level"] = 88, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5841, ["storyline"] = { 30821 }, ["description"] = "Alright, it's time to take Kota Kon out for her \"walk.\" We brewed two fresh pots of kafa just for her and she's all fueled up!", ["objectivesText"] = "Speak with Kota Kon at Kota Basecamp to ride her, then kill 100 Hozen along The Burlap Trail. Progress: Kota Kon's waiting for you! She won't let anyone else ride her.", ["rewardGold"] = 106000, ["rewardXP"] = 162000, ["rewardItems"] = { 81183, 82523, 82524, 82525, 82526, 82527, 82528, 82529, 82530, 82531, 97980 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard" },
[30879] = { ["id"] = 30879, ["name"] = "Round 1: Brewmaster Chani", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["storyline"] = { 30879 }, ["series"] = { 30881, 30883, 30907 }, ["description"] = "Welcome, Challenger, to my tournament of champions! Today we test the strengths of Pandaria's most dedicated heroes. Your first opponent awaits you under the eastern gazebo. Defeat her, and you may proceed to the next round. Fight with strength, fight with honor.", ["objectivesText"] = "Defeat Brewmaster Chani . Progress: Without conflict, there can be no growth. The need to change, to persevere, to improve, these are the traits that bring champions to my doorstep.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 31759 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3281 } },
[30880] = { ["id"] = 30880, ["name"] = "Round 1: The Streetfighter", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["storyline"] = { 30880 }, ["series"] = { 30882, 30885, 30902 }, ["description"] = "Welcome, challenger, to my tournament of champions! Today we test the strengths of Pandaria's most dedicated heroes. Your first opponent awaits you under the eastern gazebo. Defeat her, and you may proceed to the next round. Fight with strength, fight with honor.", ["objectivesText"] = "Defeat the Streetfighter. Progress: Without conflict, there can be no growth. The need to change, to persevere, to improve, these are the traits that bring champions to my doorstep.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3281 } },
[30881] = { ["id"] = 30881, ["name"] = "Round 2: Clever Ashyo & Ken-Ken", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["storyline"] = { 30881 }, ["series"] = { 30879, 30883, 30907 }, ["description"] = "You may know your next challengers. They were arguing fiercely when they arrived, so I have charged them with fighting side by side. This will teach them the strength of friendship, and possibly entertain me in the process. Go to the north eastern arena and face this jinyu and hozen. Do not be gentle, they need to learn to work together.", ["objectivesText"] = "Defeat Clever Ashyo and Ken-Ken . Progress: Strength can come from an ally as much as from one's self.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3281 } },
[30882] = { ["id"] = 30882, ["name"] = "Round 2: Kang Bramblestaff", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["storyline"] = { 30882 }, ["series"] = { 30880, 30885, 30902 }, ["description"] = "Your next challenger is a Bramblestaff. Strength is in their blood. I remember a full century of only Bramblestaff champions. No pressure, little <race>. Go to the eastern arena north of here and face this young challenger. See first hand if strength is earned or inherited.", ["objectivesText"] = "Defeat Kang Bramblestaff . Progress: I was once defeated in a match by a Bramblestaff. In my defense, he distracted me with a ball of yarn.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3281 } },
[30883] = { ["id"] = 30883, ["name"] = "Round 3: The Wrestler", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["storyline"] = { 30883 }, ["series"] = { 30879, 30881, 30907 }, ["description"] = "Your next challenger is a favorite of mine. He draws strength from raw force and determination. Plus he has a mask. Face him in the western arena when you are ready, and good luck.", ["objectivesText"] = "Defeat The Wrestler . Progress: Sometimes strength can come from the outside.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3281 } },
[30885] = { ["id"] = 30885, ["name"] = "Round 3: Master Boom Boom", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["storyline"] = { 30885 }, ["series"] = { 30880, 30882, 30902 }, ["description"] = "Your next challenger found his strength on a beach. Particularly in a box labeled \"dynamite.\" He proves however that found strength can be as deadly as personal strength. When you are ready, face this Master Boom Boom in the Western Arena.", ["objectivesText"] = "Defeat Master Boom Boom . Progress: Sometimes strength can come from the outside.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3281 } },
[30902] = { ["id"] = 30902, ["name"] = "Round 4: Master Windfur", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["storyline"] = { 30902 }, ["series"] = { 30880, 30882, 30885 }, ["description"] = "Well done, challenger. You have reached the final round. Your last opponent is a powerful master of the winds. He has defended his people for many years and stood as champion on more than one occasion. Face this Master Windfur in the main arena when you are ready. And challenger... good luck.", ["objectivesText"] = "Defeat Master Windfur . Progress: The Master Windfur 's strength is in the air and winds around him. He has rivaled elementals in his control of such forces.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3281 } },
[30907] = { ["id"] = 30907, ["name"] = "Round 4: The P.U.G.", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["storyline"] = { 30907 }, ["series"] = { 30879, 30881, 30883 }, ["description"] = "And now the final round. I have selected three challengers for you to face. This may seem unfair... to a weakling. You are not a weakling, correct? Go to the main temple, stand in the grand arena, and face these three challengers. Prove you are stronger than their combined power! Good luck, Challenger!", ["objectivesText"] = "Defeat Hackiss , Healiss and Tankiss . Progress: Some find strength in numbers. I respect this idea, when it is properly executed.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3281 } },
[30910] = { ["id"] = 30910, ["name"] = "Greenstone Village", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["storyline"] = { 30910 }, ["series"] = { 30918 }, ["description"] = "Please help! We paid some adventurers to run off all the elemental spirits and now they're back for revenge!", ["objectivesText"] = "Rescue all the villagers.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[30918] = { ["id"] = 30918, ["name"] = "Hui's Vengeance", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6209, ["storyline"] = { 30918 }, ["series"] = { 30910 }, ["description"] = "I am ashamed to ask, but for Greenstone's sake... might we now trouble you to face Vengeful Hui on our behalf...?", ["objectivesText"] = "Defeat Vengeful Hui .", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6209 } }, ["questType"] = "standard" },
[30922] = { ["id"] = 30922, ["name"] = "Natural Antiseptic", ["level"] = 89, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5842, ["storyline"] = { 30922 }, ["description"] = "The Shado-Pan are rare, elite, and quite expensive to train and replace. We can't afford to have any falling to a poisoned weapon or an infected cut. That's why I need you to get... something. Let me be blunt. Mushan urine is a great, natural antiseptic. They produce a large amount of it, which is lucky... because we tend to use a lot.", ["objectivesText"] = "Obtain 5 Full Mushan Bladders . Progress: It's messy work, certainly. Nowhere near as messy as digging graves.", ["rewardGold"] = 110000, ["rewardXP"] = 196000, ["rewardItems"] = { 82387 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard" },
[30929] = { ["id"] = 30929, ["name"] = "Bad Yak", ["level"] = 89, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5842, ["storyline"] = { 30929 }, ["description"] = "Is this the place where they replace defective yaks? Can anybody help me out, here?", ["objectivesText"] = "Help Bluesaddle replace his defective yak. Progress: This yak is not a good yak. Not at all.", ["rewardGold"] = 55000, ["rewardXP"] = 98000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard" },
[30930] = { ["id"] = 30930, ["name"] = "Pick a Yak", ["level"] = 89, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5842, ["storyline"] = { 30930 }, ["description"] = "I can't find a single good yak here. ALL the yaks are bad! Some are too stinky, some too fight-y, others just scared. You look like a lucky <race>. Here, take a lasso. See if you can find a good yak for me.", ["objectivesText"] = "Use the Yak Lasso on Wild Townlong Yaks, then fight against them to see if they are suitable for Bluesaddle . Progress: See? I told you! No good yaks.", ["rewardXP"] = 196000, ["rewardItems"] = { 82467, 82468 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard" },
[30931] = { ["id"] = 30931, ["name"] = "My Father's Crossbow", ["level"] = 89, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5842, ["storyline"] = { 30931 }, ["description"] = "I came here to visit my dad at the temple. As soon as I got here, I saw the most terrifying thing I've ever seen. It was a mantid, walking right past me, carrying my father's crossbow . Something's happened to my dad! We've got to find out what it is... but first, we'll need his crossbow back. I saw him heading west, behind the temple.", ["objectivesText"] = "Obtain Ku-Yao's Crossbow. Progress: Did... did you find it?", ["rewardGold"] = 110000, ["rewardXP"] = 196000, ["rewardItems"] = { 82332 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard" },
[30932] = { ["id"] = 30932, ["name"] = "Father's Footsteps", ["level"] = 89, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5842, ["storyline"] = { 30932 }, ["description"] = "Yes, the boy's father - Sentinel Ku-Yao - has gone missing. He could be any number of places... we have no shortage of enemies these days. You're free to look around, if you wish. You might start by looking for his yak, or by asking Sentinel Yalo what he knows.", ["objectivesText"] = "Find Father's Bedroll , Father's Shield , Ha-Cha , and Sentinel Yalo . Progress: Any luck?", ["rewardGold"] = 110000, ["rewardXP"] = 196000, ["rewardItems"] = { 32375 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard" },
[30933] = { ["id"] = 30933, ["name"] = "Seeking Father", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5842, ["storyline"] = { 30933 }, ["description"] = "I've searched everywhere... but I haven't found my father. I KNOW he's alive still. He just needs his crossbow... then he'll be OK. I've heard that you Shado-Pan guys sometimes fight the mantid on Sra'vess. I don't have any way of getting there. If you ever go over there, can you look for my dad?", ["objectivesText"] = "Search for Sentinel Ku-Yao . Progress: I know he's OK.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard" },
[30952] = { ["id"] = 30952, ["name"] = "The Unending Siege", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5842, ["storyline"] = { 30952 }, ["description"] = "The mantid continue to attack us. Their numbers ebb and flow, but they do not stop. It is no matter. The yak is stamina embodied. We will not bend to them. We will defend his home forever. Will you help us?", ["objectivesText"] = "Defeat 12 Sra'thik attackers at Niuzao Temple.", ["rewardGold"] = 228000, ["rewardXP"] = 294000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3281 } },
[30953] = { ["id"] = 30953, ["name"] = "Fallen Sentinels", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5842, ["storyline"] = { 30953 }, ["description"] = "Our sentinels can fight for days on end, but even they have their limits. Since the mantid swarm began, too many of them have pushed themselves beyond their abilities. Please, aid them in whatever way you can. If you are unable to heal them yourself, you may give them some of this. A mouthful of nutritious yak's milk will give them the strength they need.", ["objectivesText"] = "Heal 8 Wounded Niuzao Sentinels above 50% health. You may use the Yak's Milk Flasks or your own healing spells and abilities. Progress: Things look grim out there.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 82381 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3281 } },
[30954] = { ["id"] = 30954, ["name"] = "A Blade is a Blade", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5842, ["storyline"] = { 30954 }, ["description"] = "This is no time to hold to tradition. Our masons' calloused hands bleed and tremble. Our blacksmiths cannot forge weapons as quickly as our sentinels can break them. It is time to fight smart. Many of the mantid come bearing weapons, and when they die, they simply leave them on the battlefield. It would be a shame to see them go to waste.", ["objectivesText"] = "Obtain 10 Sra'thik Weapons . Progress: Our men are accustomed to fighting with maces and clubs. Unfortunatly, we have little time for customs.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 118, 785, 2449, 5016, 9622, 16742, 21100, 21395, 21413, 21746, 27753, 27754, 27756, 29434, 30787, 30788, 30789, 31425, 31426, 31427, 31428, 31745, 43844, 43859, 43910, 43935, 44987, 45192, 53361, 53367, 53379, 57835, 62982, 62983, 62984, 65487, 82353 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3281 } },
[30955] = { ["id"] = 30955, ["name"] = "Paying Tribute", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5842, ["storyline"] = { 30955 }, ["description"] = "Our patron Niuzao is a mountain on wheels... very difficult to move, even more difficult to stop. My point: once we get him moving, the mantid will have their arms full trying to slow him down. The easiest way to get him moving is to put food in front of him. Luckily for us, food in our temple is plentiful... even in wartime. I will send one of my strongarms with you, to shoulder the load.", ["objectivesText"] = "Obtain 6 stores of Niuzao Food. Your Niuzao Strongarm will carry the food for you. Progress: Niuzao, please... it is time to join the battle...", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3281 } },
[30956] = { ["id"] = 30956, ["name"] = "The Siege Swells", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5842, ["storyline"] = { 30956 }, ["description"] = "Today's mantid swarm is among the worst I've seen. We are lucky to have Niuzao join us in battle. Help him, <class>. Return to the courtyard, and join in the defense of our temple.", ["objectivesText"] = "Defeat 25 Sra'thik attackers at Niuzao Temple.", ["rewardGold"] = 228000, ["rewardXP"] = 294000, ["rewardItems"] = { 82346 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3281 } },
[30957] = { ["id"] = 30957, ["name"] = "The Overwhelming Swarm", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5842, ["storyline"] = { 30957 }, ["description"] = "I command the sentinels of Niuzao. Every defender out there can hold his own against the mantid swarm. The kunchong, however, are something different. They are massive, violent, and without a question the biggest threat to my sentinels' lives. Only Niuzao stands a chance against them. Niuzao... and perhaps you.", ["objectivesText"] = "Defeat 4 Sra'thik Kunchong . Progress: Stay stalwart, <race>. The kunchong would have their way with you.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3281 } },
[30958] = { ["id"] = 30958, ["name"] = "In Battle's Shadow", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5842, ["storyline"] = { 30958 }, ["description"] = "Niuzao's appearance on the battlefield is a blessing... in more ways than one. With the distraction that he's caused, our stonemasons have seized the opportunity to build up our crumbling walls. They could use your help. Toss any loose bricks you find up their way. And hurry! Niuzao will not rampage forever.", ["objectivesText"] = "Throw 10 Loose Stones up to Niuzao Stonemasons. Progress: I recommend you move with haste. Niuzao's distraction will not last forever.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3281 } },
[30959] = { ["id"] = 30959, ["name"] = "The Big Guns", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5842, ["storyline"] = { 30959 }, ["description"] = "The mantid now surround the Temple with their infernal war wagons. The sooner we are rid of those things, the better. You could destroy them with your own weapons and spells, but this will work much faster. <Ogo hands you a few small casks of hastily-packed explosives.> Beware of retaliation from mantid that remain be inside the war wagon when it explodes. In fact, I'd stay as far away from those things as possible.", ["objectivesText"] = "Destroy 3 Sra'thik War Wagons . Progress: We can push these mantid back. We can outlast them.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 82346 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3281 } },
[30961] = { ["id"] = 30961, ["name"] = "Savior of the Inkgill", ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["storyline"] = { 30961 }, ["description"] = "I will go now to return to my kinsmen. Please visit us back at the southwestern edge of the Mere, so that we may thank you.", ["objectivesText"] = "Speak with Waterspeaker Gorai at the southwestern edge of Jinyu Mere.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[30963] = { ["id"] = 30963, ["name"] = "The Field Armorer", ["level"] = 89, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5842, ["storyline"] = { 30963 }, ["description"] = "The Shado-Pan fight. As such, their armor often gets cut, scratched, torn, and burned. And it's my job to repair it. I'm no armorer, but I can repair a broken piece of mail as long as the hole's not too big. I prefer to use shell fragments from the tortoises that live in the wild fields to the northeast. Get some for me, and I can keep more Shado-Pan armored and alive.", ["objectivesText"] = "Obtain 120 Rankbite Shell Fragments . Progress: I refuse to let one of our kind fall just because of a broken set of armor.", ["rewardGold"] = 110000, ["rewardXP"] = 196000, ["rewardItems"] = { 82388, 83680, 83681, 83682, 83683, 83684, 83685, 83686, 83687, 83688 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard" },
[30964] = { ["id"] = 30964, ["name"] = "A Proper Poultice", ["level"] = 89, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5842, ["storyline"] = { 30964 }, ["description"] = "A dry bandage doesn't do much good, other than maybe keeping bugs out of the wound. In some camps, that's the best you can hope for. Not in my camp, though. I prefer to make a paste from whatever soothing herbs I can find, and layer that between bandages. The most soothing herbs I've been able to find in the field are the Mao-Willows from the fields in the northeast. If you run into any, bring them back.", ["objectivesText"] = "Obtain 11 Mao-Willows . Progress: Any luck out there, <name>?", ["rewardGold"] = 110000, ["rewardXP"] = 196000, ["rewardItems"] = { 82389 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard" },
[30969] = { ["id"] = 30969, ["name"] = "A New Enemy", ["level"] = 16, ["requiredLevel"] = 15, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 2437, ["storyline"] = { 30969 }, ["description"] = "The power of these Dark Shaman has attracted many allies, <name>. Former members of the Horde that now work towards some dark purpose. We need to make an example of them before we have another twilight's hammer on our hands. Kill any cultist you come across and bring me their insignia.", ["objectivesText"] = "Collect 5 Corrupted Insignia from any cultist in Ragefire Chasm . Progress: Have you collected the insignia?", ["rewardGold"] = 3300, ["rewardXP"] = 2300, ["rewardItems"] = { 82605 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 2437 } }, ["questType"] = "dungeon" },
[30974] = { ["id"] = 30974, ["name"] = "Raising Spirits", ["level"] = 89, ["requiredLevel"] = 88, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["storyline"] = { 30974 }, ["description"] = "The kegs are full of my worst stock. Good for burning, crap for drinking. I've broken out some tankards of my best spirits and had them carried out amongst the kegs though - those are for my well-deserving men! Spirits to raise their spirits after endless, grueling fighting. Would you be up for spreading the good cheer?", ["objectivesText"] = "Throw 8 Iron Belly Spirits to nearby Dusklight Skirmishers and Dusklight Rangers.", ["rewardGold"] = 110000, ["rewardXP"] = 196000, ["rewardItems"] = { 88587 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[30982] = { ["id"] = 30982, ["name"] = "Animal Control", ["level"] = 16, ["requiredLevel"] = 15, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 2437, ["storyline"] = { 30982 }, ["series"] = { 31034, 31036, 31037 }, ["description"] = "The chasm is overrun with flame hounds and lava worms, and they will be entrenched indefinitely with such a large supply of trogg flesh for food. This infestation needs to be taken care of now, before they endanger the city. You look like you can handle yourself, <name>. I want you to clear a path through the beasts and make certain to take out the largest threats, Adjules and Magnaw.", ["objectivesText"] = "Kill Adarogg and Slagmaw .", ["rewardGold"] = 3300, ["rewardXP"] = 2300, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 2437 } }, ["questType"] = "dungeon" },
[30983] = { ["id"] = 30983, ["name"] = "The Dark Shaman", ["level"] = 16, ["requiredLevel"] = 15, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 2437, ["storyline"] = { 30983 }, ["description"] = "These dark shaman have been down here for months, raising beasts and performing dark rituals. I don't know what they aim to achieve with all of this, but it's clear that they are no friend of the Horde. That's where you come in, <name>. Fight your way through the chasm and kill Dark Shaman Koranthal and Lava Guard Gordoth .", ["objectivesText"] = "Defeat Dark Shaman Koranthal and Lava Guard Gordoth .", ["rewardGold"] = 3300, ["rewardXP"] = 2300, ["rewardItems"] = { 82891, 82892, 82893, 82894, 82895 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 2437 } }, ["questType"] = "dungeon" },
[30984] = { ["id"] = 30984, ["name"] = "No Orc Left Behind", ["level"] = 16, ["requiredLevel"] = 15, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 2437, ["storyline"] = { 30984 }, ["description"] = "This was supposed to be a routine sweep, <name>. Clean up a few troggs, make sure there is no threat to the city and then be in the tavern by midday. Instead I've a group of scouts missing, flame hounds pouring out of the chasm and Xorenth going on about \"the next twilight's hammer.\" < Commander Bagran spits> Go in there and get my scouts back so we can figure out what is going on down here.", ["objectivesText"] = "Rescue 5 Kor'kron Scouts in Ragefire Chasm . Progress: Have you found the scouts?", ["rewardGold"] = 3300, ["rewardXP"] = 2300, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 2437 } }, ["questType"] = "dungeon" },
[30986] = { ["id"] = 30986, ["name"] = "Ancient Mogu Crypt", ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6208, ["storyline"] = { 30986 }, ["description"] = "Our scouting party got DESTROYED. Help!", ["objectivesText"] = "Kill the possessed Shado-Pan Leader and cleanse the Pool of Life.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6208 } }, ["questType"] = "dungeon" },
[30987] = { ["id"] = 30987, ["name"] = "Joining the Alliance", ["level"] = 10, ["faction"] = "alliance", ["requiredRaces"] = { 25 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 30987 }, ["series"] = { 30988, 30989 }, ["description"] = "We have a duty, <name>. It is our responsibility to spread the Tushui philosophy beyond the edges of the Wandering Isle... and there is no better place to start doing that than here: Stormwind City , heart of the Alliance. Let's find out who their leader is. We need allies.", ["objectivesText"] = "Speak with King Varian Wrynn at Stormwind Keep.", ["rewardGold"] = 35, ["rewardXP"] = 85, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1519 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 84, ["questLines"] = { { ["id"] = 573, ["name"] = "The Wandering Isle", ["orderIndex"] = 72, ["flags"] = 0 } } },
[30988] = { ["id"] = 30988, ["name"] = "The Alliance Way", ["level"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 1519, ["storyline"] = { 30988 }, ["series"] = { 30987, 30989 }, ["description"] = "I only recently received word that some of your kind might be coming our way. I'd be glad to call you an ally, if you're willing to join our cause. Walk with me, <name>.", ["objectivesText"] = "Walk with King Varian Wrynn .", ["rewardGold"] = 35, ["rewardXP"] = 85, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1519 } }, ["questType"] = "standard" },
[30989] = { ["id"] = 30989, ["name"] = "An Old Pit Fighter", ["level"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 1519, ["storyline"] = { 30989 }, ["series"] = { 30987, 30988 }, ["description"] = "I need to know if you can fight. There may come a time where you will be called upon for military matters, and I need to know that you can protect my kingdom. I've heard stories about pandaren fighting techniques, but I've never seen them in person. Shall we?", ["objectivesText"] = "Spar with King Varian Wrynn .", ["rewardGold"] = 35, ["rewardXP"] = 85, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1519 } }, ["questType"] = "standard" },
[30990] = { ["id"] = 30990, ["name"] = "Open the Golden Doors", ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6208, ["storyline"] = { 30990 }, ["series"] = { 30986, 31027 }, ["description"] = "Defeat the mogu crypt guardian to open the golden doors.", ["objectivesText"] = "Defeat the Mogu Crypt Guardian .", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6208 } }, ["questType"] = "standard" },
[30995] = { ["id"] = 30995, ["name"] = "No Man Left Behind", ["level"] = 16, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 2437, ["storyline"] = { 30995 }, ["description"] = "I sent recon out over an hour ago and none of them have reported back. And now these damned hounds are pouring out of the chasm. I don't know what's going on down there, but I'm not going anywhere till I get my men back. I want you to head in there and find them, <name>, preferably while they are still alive.", ["objectivesText"] = "Rescue 5 SI:7 Rangers in Ragefire Chasm .", ["rewardGold"] = 3300, ["rewardXP"] = 2300, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 2437 } }, ["questType"] = "dungeon" },
[30996] = { ["id"] = 30996, ["name"] = "The Dark Shaman", ["level"] = 16, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 2437, ["storyline"] = { 30996 }, ["description"] = "These dark shaman have been down here for months, raising beasts and performing dark rituals. I don't know what they aim to achieve with all of this, but it's clear that they are no friend of the Alliance. And I need your help stopping them, <name>. Fight your way through the chasm and kill Dark Shaman Koranthal and Lava Guard Gordoth .", ["objectivesText"] = "Defeat Dark Shaman Koranthal and Lava Guard Gordoth .", ["rewardGold"] = 3300, ["rewardXP"] = 2300, ["rewardItems"] = { 82891, 82892, 82893, 82894, 82895 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 2437 } }, ["questType"] = "dungeon" },
[30997] = { ["id"] = 30997, ["name"] = "Animal Control", ["level"] = 16, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 2437, ["storyline"] = { 30997 }, ["description"] = "I'm glad you're here, <name>. The horde is amassing an army and I'm not going to wait to find out why. We need to strike fast and take down some of the larger beasts they have down here. I want you to head in there and take care of Adarogg and Slagmaw before the horde can use them as weapons against us.", ["objectivesText"] = "Kill Adarogg and Slagmaw .", ["rewardGold"] = 3300, ["rewardXP"] = 2300, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 2437 } }, ["questType"] = "dungeon" },
[30998] = { ["id"] = 30998, ["name"] = "A New Enemy", ["level"] = 16, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 2437, ["storyline"] = { 30998 }, ["description"] = "The horde is using dark magic to control beasts and corrupt their brethren down here, <name>. I intend to put a stop to it, but first I need to know what it is we're fighting against. That's where you come in. Fight through the caverns and collect the insignia that the cultists carry. With them, I can study what type of magic is at work here.", ["objectivesText"] = "Collect 5 Corrupted Insignia from the Dark Shaman cultists. Progress: Have you collected the insignia?", ["rewardGold"] = 3300, ["rewardXP"] = 2300, ["rewardItems"] = { 82605 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 2437 } }, ["questType"] = "dungeon" },
[31012] = { ["id"] = 31012, ["name"] = "Joining the Horde", ["level"] = 10, ["faction"] = "horde", ["requiredRaces"] = { 26 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 14, ["mapID"] = 85, ["storyline"] = { 31012 }, ["series"] = { 31013, 31014 }, ["description"] = "Here we are, <name>... Orgrimmar , heart of the Horde. We can be helpful beyond the edges of the Wandering Isle. There are innumerable problems out there, just waiting for us to solve them. This is what Master Shang Xi would have wanted. There's no better place to start doing that than here, with the aid of the Horde. Let's find out who their leader is. We need allies.", ["objectivesText"] = "Speak with Garrosh Hellscream in Orgrimmar .", ["rewardGold"] = 35, ["rewardXP"] = 85, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 85, ["questLines"] = { { ["id"] = 573, ["name"] = "The Wandering Isle", ["orderIndex"] = 73, ["flags"] = 0 } } },
[31013] = { ["id"] = 31013, ["name"] = "The Horde Way", ["level"] = 10, ["faction"] = "horde", ["requiredRaces"] = { 8, 9, 26 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 1637, ["storyline"] = { 31013 }, ["series"] = { 31012, 31014 }, ["description"] = "I recently received word that some of your kind might be coming our way. I've recently been trying to bolster the strength of the Horde. A few pandaren might do us good. Walk with me, <name>.", ["objectivesText"] = "Walk with Garrosh Hellscream .", ["rewardGold"] = 35, ["rewardXP"] = 85, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1637 } }, ["questType"] = "standard" },
[31014] = { ["id"] = 31014, ["name"] = "Hellscream's Gift", ["level"] = 10, ["faction"] = "horde", ["requiredRaces"] = { 8, 9, 26 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 1637, ["storyline"] = { 31014 }, ["series"] = { 31012, 31013 }, ["description"] = "I need to know if you can fight... that you can kill, and live. Eventually, each of you will be called upon for war, and I need to know that you can be counted on. I mentioned a gift earlier. It lies here, within the Ring of Valor. Step into the arena, right through this door behind me. I will test your skills.", ["objectivesText"] = "Complete Garrosh's test by defeating Oggax, Gadoon, and Frozengore.", ["rewardGold"] = 35, ["rewardXP"] = 85, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1637 } }, ["questType"] = "standard" },
[31015] = { ["id"] = 31015, ["name"] = "Your Private Collection", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 31015 }, ["series"] = { 31016 }, ["description"] = "Pandaria is rich with history, legends, stories, and lore of every sort. While you are traveling throughout the world I would ask that you keep an eye open for artifacts and pieces of information that you feel would be pertinent to our work here. When you accumulate enough knowledge, we will compile it in to a volume for your personal collection here. You can, of course, return whenever you like to review the volumes we are making for you.", ["objectivesText"] = "Clean off the Empty Bookshelf. Progress: So much to learn.", ["rewardGold"] = 11400, ["rewardXP"] = 23600, ["rewardItems"] = { 83780 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[31016] = { ["id"] = 31016, ["name"] = "The Lorewalkers", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["storyline"] = { 31016 }, ["series"] = { 31015 }, ["description"] = "Dear $p, We have uncovered something tremendous in the Vale of Eternal Blossoms . A great repository of books, scrolls, and lore that has remained untouched since the days of the mogu empire. Please, join us at your earliest convenience. You can find this Seat of Knowledge by traveling to the infamous Mogu'shan Vaults, and then flying to the landing just above the entrance. I look forward to your arrival! Sincerely, Lorewalker Cho", ["objectivesText"] = "Speak with Lorewalker Cho at the Seat of Knowledge in the Vale of Eternal Blossoms . Provided item:", ["rewardGold"] = 11400, ["rewardXP"] = 23600, ["rewardItems"] = { 82808 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["startItems"] = { 82808 } },
[31018] = { ["id"] = 31018, ["name"] = "Beneath the Heart of Fear", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6138, ["storyline"] = { 31018 }, ["description"] = "The Klaxxi have detected the existence of another paragon, Wakener. This one was kept well-hidden from us, and for good reason. The Empress already has possession of this one, and her adjuncts work to destroy it even now. They are performing their sorcery in a chamber deep beneath the palace, and they must be stopped. We hold Klaxxi'vess. You must go in our stead. Find the entrance to their chamber from the ledge to the west.", ["objectivesText"] = "Kill Adjunct Ek'vem , Adjunct Ikkess , Adjunct Suruz , and Adjunct Tsikzi, and then free Xaril the Poisoned Mind .", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard" },
[31024] = { ["id"] = 31024, ["name"] = "Kunchong Treats", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6138, ["mapID"] = 422, ["storyline"] = { 31024 }, ["description"] = "As Kovok grows, he will require equal parts discipline and reward. I lack no shortage of discipline, but our supply of meat is almost empty. To the south, you will find turtles roaming north of the Lake of Stars and Kypari Zar. Hunt them. Kovok likes the taste of their flesh.", ["objectivesText"] = "Collect 4 Meaty Turtle Haunches. Progress: What have you brought for Kovok?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 82869 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3278 }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 5556, ["name"] = "Klaxxi Daily Quests", ["orderIndex"] = 0, ["flags"] = 0 } } },
[31027] = { ["id"] = 31027, ["name"] = "Defeat the Abomination", ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6208, ["storyline"] = { 31027 }, ["series"] = { 30986, 30990 }, ["description"] = "Now that the pool of life is cleansed, the way to the crypt's interior is open. Make your way down there and defeat the abomination.", ["objectivesText"] = "Defeat the Abomination of Anger .", ["rewardGold"] = 456000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6208 } }, ["questType"] = "standard" },
[31031] = { ["id"] = 31031, ["name"] = "Into the Monastery", ["level"] = 88, ["requiredLevel"] = 87, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["storyline"] = { 31031 }, ["series"] = { 30752, 30757, 30759, 31030 }, ["description"] = "This... is unspeakable. If the monastery has truly been taken over by the Sha, we will need a great effort to purge the monks inside of corruption. Gather a group of your allies, and meet me inside the Monastery.", ["objectivesText"] = "Meet Ban Bearheart inside the Shado-Pan Monastery.", ["rewardGold"] = 10600, ["rewardXP"] = 16200, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "dungeon" },
[31036] = { ["id"] = 31036, ["name"] = "Enemies Below", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 1638, ["storyline"] = { 31036 }, ["series"] = { 30982, 31034, 31037 }, ["description"] = "Orgrimmar's Ragefire Chasm has been taken by the Dark Shaman. <name>, we cannot allow this to pass unpunished, lest they next set their sights on Thunder Bluff. Go speak with Commander Bagran just inside the Chasm. Help him in any way you can, for our fates are intertwined.", ["objectivesText"] = "Speak with Commander Bagran .", ["rewardGold"] = 70, ["rewardXP"] = 105, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1638 } }, ["questType"] = "dungeon" },
[31037] = { ["id"] = 31037, ["name"] = "Enemies Below", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "horde", ["requiredRaces"] = { 5, 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 1497, ["storyline"] = { 31037 }, ["series"] = { 30982, 31034, 31036 }, ["description"] = "With all his usual grace, Warchief Garrosh has kindly requested your presence in Ragefire Chasm to help retake it from the Dark Shaman. Apparently, his reinforced city isn't as impenetrable as he thought. Go speak with Commander Bagran just inside Ragefire, I'm sure he'll be glad to have competent help.", ["objectivesText"] = "Speak with Commander Bagran .", ["rewardGold"] = 70, ["rewardXP"] = 105, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1497 } }, ["questType"] = "dungeon" },
[31038] = { ["id"] = 31038, ["name"] = "The Challenger's Ring: Snow Blossom", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5842, ["storyline"] = { 31038 }, ["description"] = "News of your feats has been traveling around the camp, <name>. In fact, Snow Blossom would like to test your skill in battle. You had best prepare yourself, <class>. She is not easily defeated. If you can prove your worth to her, you will win a valuable friend.", ["objectivesText"] = "Challenge Snow Blossom and defeat her in the Challenger's Ring. Progress: How did it go?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard" },
[31039] = { ["id"] = 31039, ["name"] = "The Mogu Menace", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5842, ["storyline"] = { 31039 }, ["series"] = { 31040, 31041, 31046, 31049 }, ["description"] = "Our scouts have discovered a heavy mogu force at Shan'ze Dao to the northwest. The island was supposedly uninhabited, so their presence is disturbing news. Even more disturbing is the fact that they are performing sinister experiments on the island. I need a capable <class> to check out the situation. The Shan'ze are likely to give you trouble, and if they do, kill them.", ["objectivesText"] = "Kill 12 Shan'ze Serpentbinders or Shan'ze Beastmasters. Progress: How many were there?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3279 } },
[31040] = { ["id"] = 31040, ["name"] = "Spiteful Sprites", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5842, ["storyline"] = { 31040 }, ["series"] = { 31039, 31041, 31046, 31049 }, ["description"] = "The Darkwoods sprites on Shan'ze Dao have fallen to the mogu's domination. The once sly tricksters are now the full servants of the Shan'ze. They grow bolder each day, stealing and killing to satisfy their masters. They must be eliminated, but be careful. They may look harmless, but they are actually quite vicious.", ["objectivesText"] = "Kill 30 Darkwoods Pixies or Darkwoods Charmers. Progress: The sprites must do as their masters command.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3279 } },
[31041] = { ["id"] = 31041, ["name"] = "Egg Rescue!", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5842, ["storyline"] = { 31041 }, ["series"] = { 31039, 31040, 31046, 31049 }, ["description"] = "Eggs. Yes, you heard me right. I said eggs, and these aren't for eating. Have you ever seen a cloud serpent egg? These rare eggs look like jewels, and were once worth their weight in solid gold. Shan'ze Dao to the north normally teems with wild cloud serpents, but the mogu and the sprites have their eggs on lock-down. We need to save as many of these precious eggs as we can. I'm counting on YOU, <name>.", ["objectivesText"] = "Collect 8 Cloudrunner Eggs . Progress: Did you find any eggs? The serpents lay their eggs in nests on the beach, but the wood sprites are also known to steal them whenever they can.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 83129 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3279 } },
[31042] = { ["id"] = 31042, ["name"] = "Onyx Hearts", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5842, ["storyline"] = { 31042 }, ["series"] = { 31043, 31047, 31061, 31105 }, ["description"] = "The Shan'ze Serpentbinders dominate the minds of wild cloud serpents, but they also create their own dark creatures from stone, metal, blood, and ancient sorcery. Their creations, the Onyx Stormclaws, guard the island to the northwest. I wish to study the magic binding these creatures. Bring me their hearts, so that I can better understand what sorcery we are up against.", ["objectivesText"] = "Collect 4 Onyx Hearts . Progress: The Onyx Stormclaws will never disobey their masters.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 83138 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3279 } },
[31043] = { ["id"] = 31043, ["name"] = "Dark Arts", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5842, ["storyline"] = { 31043 }, ["series"] = { 31042, 31047, 31061, 31105 }, ["description"] = "It is said that Shan'ze Dao was once home to a great mogu temple. There, the Shan'ze studied and practiced the art of subjugating the dead or inanimate. Much of their knowledge still remains on the island to the northwest, buried among the ruins. We need to get our hands on their knowledge - both to keep it out of their hands, and to understand the nature of their experiments.", ["objectivesText"] = "Collect 8 Shan'ze Tablets . Progress: Knowledge is powerful. That is why the mogu are so dangerous.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 83130 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3279 } },
[31044] = { ["id"] = 31044, ["name"] = "Bronze Claws", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5842, ["storyline"] = { 31044 }, ["series"] = { 31045, 31048, 31062, 31106 }, ["description"] = "Among the Shan'ze's fiercest and most loyal creations are their quilen. These beasts will hunt until they kill their prey, or die in the process. I need you to not only cull their numbers, but also to retrieve their bronze claws . Their claws are strong and razor sharp, and we can use them to make weapons and hooks for our cause.", ["objectivesText"] = "Collect 20 Bronze Claws . Progress: The quilen are fierce, but I see fierceness in your eyes as well.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 83153 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3279 } },
[31045] = { ["id"] = 31045, ["name"] = "Illusions Of The Past", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5842, ["storyline"] = { 31045 }, ["series"] = { 31044, 31048, 31062, 31106 }, ["description"] = "<class>, I need your strength to eliminate the Shan'ze Illusionists on Shan'ze Dao, to the northwest. It wearies me to ask of you this difficult task. The illusionists are among the strongest of the Shan'ze's elite sorcerors. They will not be easy to defeat, but I know no <class> who is better suited to the task.", ["objectivesText"] = "Kill 3 Shan'ze Illusionists . Progress: Do not be fooled by their illusions.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3279 } },
[31046] = { ["id"] = 31046, ["name"] = "Little Hatchlings", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5842, ["storyline"] = { 31046 }, ["series"] = { 31039, 31040, 31041, 31049 }, ["description"] = "I have seen the cruel experiments that the Shan'ze are performing on their island to the northwest. The Shan'ze raise baby serpents from the egg. They keep the young in tiny cages, surrounded by squalor and filth. The cruelest gaolers starve and torture them. We must save as many hatchlings as we can. You have my full permission to punish any mogu that gets in your way!", ["objectivesText"] = "Free 20 Cloudrunner Hatchlings . Progress: The mogu are cruel beyond measure.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3279 } },
[31047] = { ["id"] = 31047, ["name"] = "Born Free", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5842, ["storyline"] = { 31047 }, ["series"] = { 31042, 31043, 31061, 31105 }, ["description"] = "Do you know the story of the great cloud serpents of Pandaria, <name>? Someday you must hear it. Unfortunately, there is no time to tell it now. What you must know is that the wild cloudrunner serpents of Townlong are in trouble. The mogu are capturing wild serpents and corrupting their minds, bending them to their sinister will. Go to Shan'ze Dao, to the northwest. Free the adult serpents from their chains. Save them!", ["objectivesText"] = "Free 6 Wild Cloudrunners from their chains. Progress: The wild cloudrunners should remain free.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3279 } },
[31048] = { ["id"] = 31048, ["name"] = "Grave Consequences", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5842, ["storyline"] = { 31048 }, ["series"] = { 31044, 31045, 31062, 31106 }, ["description"] = "We've found ancient mogu burial urns among the ruins on Shan'ze Dao. This is normally no problem, except these urns are home to angry mogu spirits. Not only do these urns pose a danger to anyone unlucky enough to find one, but they could be used for destruction if they were to fall into the wrong hands. We must rid Shan'ze Dao of their presence.", ["objectivesText"] = "Kill 24 Shan'ze Ancestors . Shan'ze Ancestors may be found inside Mogu Burial Urns. Progress: Did the spirits cause you any problems?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3279 } },
[31049] = { ["id"] = 31049, ["name"] = "In Sprite Of Everything", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5842, ["storyline"] = { 31049 }, ["series"] = { 31039, 31040, 31041, 31046 }, ["description"] = "The sprites of Shan'ze Dao have always been capricious tricksters, but now they have fallen under the mogu's influence. Even as we speak, they gather under a new leader. We cannot allow this to happen. Their mischievous pranks were one thing, but united, their dark magic is too powerful and too dangerous to comprehend. Take out their leader before it is too late.", ["objectivesText"] = "Kill the Darkwoods Faerie . Progress: The sprites are easily manipulated, and too dangerous to ignore.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3279 } },
[31055] = { ["id"] = 31055, ["name"] = "Between a Saurok and a Hard Place", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 31055 }, ["description"] = "Dear $p, We have received your research on the saurok and believe we have pieced together clues about their past. If you visit us at the Seat of Knowledge in Vale of Eternal Blossoms we can add this contribution to your personal collection. Thank you for your diligence! Sincerely, Lorewalker Cho", ["objectivesText"] = "Bring Between a Saurok and a Hard Place to Lorewalker Cho . Provided item:", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 83076 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard", ["startItems"] = { 83076, 83769 } },
[31058] = { ["id"] = 31058, ["name"] = "The Funky Monkey Brew", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6309, ["storyline"] = { 31058 }, ["description"] = "Pirates! Our shores have been scoured by the most ill-tempered, ill-mannered, ill-hygienic, and ill-good hozen that ever was found in Pandaria. And to make matters worse, they claim to serve the legendary Captain Ook ! We see them every night partying and brewing punch on their island Unga Ingoo. I say we take their brew for a change! I think I can even improve their mix. Gather up some friends and meet me on the southern side of Unga Ingoo. It is time for a Brew Run!", ["objectivesText"] = "Defeat Captain Ook . Progress: These hozen pack some mean toys and some meaner brews.", ["rewardGold"] = 228000, ["rewardXP"] = 294000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6309 } }, ["questType"] = "standard" },
[31061] = { ["id"] = 31061, ["name"] = "Riding the Storm", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5842, ["storyline"] = { 31061 }, ["series"] = { 31042, 31043, 31047, 31105 }, ["description"] = "Shan Bu, the leader of the Shan'ze, is performing some kind of dark ritual at the summit of the island to the northwest. We believe that the subjugated Shan'ze Cloudrunners are powering the spell. How, we still do not know. We believe that the Shan'ze Cloudrunners can still be saved from the corruption that taints them. Take these bronze claws . Use them to mount the back of a Shan'ze Cloudrunner. Attack them. Beat some sense back into their heads!", ["objectivesText"] = "Use the Bronze Claws to mount 8 Shan'ze Cloudrunners. Attack them to free them of their corruption. Progress: How did it go?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 83134 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3279 } },
[31062] = { ["id"] = 31062, ["name"] = "When The Dead Speak", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5842, ["storyline"] = { 31062 }, ["series"] = { 31044, 31045, 31048, 31106 }, ["description"] = "The Shan'ze's experiments are overseen by a powerful necromancer known as a Shan'ze Deathspeaker . If we are to put an end to their operations, we must eliminate their leader.", ["objectivesText"] = "Kill the Shan'ze Deathspeaker . Progress: What would possess the mogu to perform such hideous experiments?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3279 } },
[31083] = { ["id"] = 31083, ["name"] = "Promises of Gold", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6138, ["storyline"] = { 31083 }, ["description"] = "As soon as the creature died, a strange group of sprites appeared and took its pearl away. The sprites have a village nearby, called Rikkitun Village. Perhaps you should investigate.", ["objectivesText"] = "Report to Chief Rikkitun at Rikkitun Village in Dread Wastes .", ["rewardGold"] = 342000, ["rewardXP"] = 353000, ["rewardItems"] = { 88417 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard" },
[31093] = { ["id"] = 31093, ["name"] = "Hozen in the Mist", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 31093 }, ["description"] = "Dear $p, Your research into the hozen has proven quite enlightening. If you visit us at the Seat of Knowledge in Vale of Eternal Blossoms we can add this contribution to your personal collection. Thank you for your diligence! Sincerely, Lorewalker Cho", ["objectivesText"] = "Bring Hozen in the Mist to Lorewalker Cho at the Seat of Knowledge. Provided item:", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 83770 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard", ["startItems"] = { 83770 } },
[31094] = { ["id"] = 31094, ["name"] = "Fish Tales", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 31094 }, ["description"] = "Dear $p, I have thoroughly enjoyed reading your research in to the jinyu. A fascinating people and quite clever too. If you visit us at the Seat of Knowledge in Vale of Eternal Blossoms we can add this contribution to your personal collection. Thank you for your diligence! Sincerely, Lorewalker Cho", ["objectivesText"] = "Bring Fish Tails to Lorewalker Cho at the Seat of Knowledge. Provided item:", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 83771 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard", ["startItems"] = { 83771 } },
[31095] = { ["id"] = 31095, ["name"] = "The Dark Heart of the Mogu", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 31095 }, ["description"] = "Dear $p, We have always known the mogu to be dark and sinister. Your research however would imply that they are far worse. If you visit us at the Seat of Knowledge in Vale of Eternal Blossoms we can add this contribution to your personal collection. Thank you for your diligence! Sincerely, Lorewalker Cho", ["objectivesText"] = "Bring The Dark Heart of the Mogu to Lorewalker Cho at the Seat of Knowledge. Provided item:", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 83772 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard", ["startItems"] = { 83772 } },
[31097] = { ["id"] = 31097, ["name"] = "Heart of the Mantid Swarm", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 31097 }, ["description"] = "Dear $p, While we appreciate your efforts to investigate the lore of Pandaria, the documents you sent us on the mantid managed to rob me of several nights sleep. Terrifying stuff. If you visit us at the Seat of Knowledge in Vale of Eternal Blossoms we can add this contribution to your personal collection. Thank you for your diligence! Sincerely, Lorewalker Cho", ["objectivesText"] = "Bring Heart of the Mantid Swarm to Lorewalker Cho at the Seat of Knowledge. Provided item:", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 83773 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard", ["startItems"] = { 83773 } },
[31100] = { ["id"] = 31100, ["name"] = "The Song of the Yaungol", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 31100 }, ["description"] = "Dear $p, Your research in to the yaungol has proven most insightful. If you visit us at the Seat of Knowledge in Vale of Eternal Blossoms we can add this contribution to your personal collection. Thank you for your diligence! Sincerely, Lorewalker Cho", ["objectivesText"] = "Bring The Song of the Yaungol to Lorewalker Cho at the Seat of Knowledge. Provided item:", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 83777 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard", ["startItems"] = { 83777 } },
[31102] = { ["id"] = 31102, ["name"] = "The Seven Burdens of Shaohao", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 31102 }, ["description"] = "Dear $p, It would seem you have discovered the full tale of Shaohao, the last emperor of Pandaria. If you visit us at the Seat of Knowledge in Vale of Eternal Blossoms we can add this contribution to your personal collection. Thank you for your diligence! Sincerely, Lorewalker Cho", ["objectivesText"] = "Bring The Seven Burdens of Shaohao to Lorewalker Cho at the Seat of Knowledge. Provided item:", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 83779 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard", ["startItems"] = { 83779 } },
[31103] = { ["id"] = 31103, ["name"] = "The Ballad of Liu Lang", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 31103 }, ["description"] = "Dear $p, At long last thanks to your research we have the full Ballad of Liu Lang . If you visit us at the Seat of Knowledge in Vale of Eternal Blossoms we can add this contribution to your personal collection. Thank you for your diligence! Sincerely, Lorewalker Cho", ["objectivesText"] = "Bring The Ballad of Liu Lang to Lorewalker Cho at the Seat of Knowledge. Provided item:", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 83780 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard", ["startItems"] = { 83780 } },
[31104] = { ["id"] = 31104, ["name"] = "The Challenger's Ring: Yalia Sagewhisper", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5842, ["storyline"] = { 31104 }, ["description"] = "The Shado-Pan brothers and sisters continue to whisper of your deeds, <name>. In fact, Yalia herself has taken quite an interest in your studies. She wishes to challenge you in the training ring. You would do well to impress her. If you do, she just may be willing to help you in the future.", ["objectivesText"] = "Challenge Yalia Sagewhisper and defeat her in the Challenger's Ring. Progress: Did you speak to Yalia?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard" },
[31105] = { ["id"] = 31105, ["name"] = "The Mogu Menace", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5842, ["storyline"] = { 31105 }, ["series"] = { 31042, 31043, 31047, 31061 }, ["description"] = "Our scouts have discovered a heavy mogu force at Shan'ze Dao to the northwest. The island was supposedly uninhabited, so their presence is disturbing news. Even more disturbing is the fact that they are performing sinister experiments on the island. I need a capable <class> to check out the situation. The Shan'ze are likely to give you trouble, and if they do, kill them.", ["objectivesText"] = "Kill 12 Shan'ze Serpentbinders or Shan'ze Beastmasters. Progress: How many were there?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3279 } },
[31106] = { ["id"] = 31106, ["name"] = "The Mogu Menace", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5842, ["storyline"] = { 31106 }, ["series"] = { 31044, 31045, 31048, 31062 }, ["description"] = "Our scouts have discovered a heavy mogu force at Shan'ze Dao to the northwest. The island was supposedly uninhabited, so their presence is disturbing news. Even more disturbing is the fact that they are performing sinister experiments on the island. I need a capable <class> to check out the situation. The Shan'ze are likely to give you trouble, and if they do, kill them.", ["objectivesText"] = "Kill 12 Shan'ze Serpentbinders or Shan'ze Beastmasters. Progress: How many were there?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3279 } },
[31109] = { ["id"] = 31109, ["name"] = "Culling the Swarm", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6138, ["mapID"] = 422, ["storyline"] = { 31109 }, ["description"] = "The Empress continues to amass her forces. Without intervention, they WILL overrun that wall - even if it means smothering it in the corpses of a million swarmborn. Let us find a better place for those corpses. Let me know when you are ready to depart for the clutches - I will gladly drop you in from above.", ["objectivesText"] = "Slay 40 Shek'zeer Mantid in the Clutches of Shek'zeer. Speak with Kil'ruk the Wind-Reaver for an air-drop. Progress: We must kill faster than they can multiply. It is that simple.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3278 }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 5556, ["name"] = "Klaxxi Daily Quests", ["orderIndex"] = 1, ["flags"] = 0 } } },
[31110] = { ["id"] = 31110, ["name"] = "Through the Portal", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5842, ["storyline"] = { 31110 }, ["description"] = "Ah, just the <class> I wanted to see! We've finally figured out why the portal is not working. We need more arcane powder! It would take us months to get a shipment sent out to us, but luckily, the mogu on this island carry plenty for their own spells. They tend to use some older stuff, so we're going to need a lot of it.", ["objectivesText"] = "Collect 1000 Ancient Arcane Powder . Progress: Did you find the powders?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 84102 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3279 } },
[31111] = { ["id"] = 31111, ["name"] = "Eradicating the Zan'thik", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6138, ["mapID"] = 422, ["storyline"] = { 31111 }, ["description"] = "The warriors of Zan'vess are some of the most feared and respected in the empire, for good reason. Impalers are unmatched in their mastery of the polearm - no doubt Malik trained among the Zan'thik in his time. Their manipulators command terrifying sonic power with the ease and subtlety of a breath. Both will need to be dealt with.", ["objectivesText"] = "Kill 6 Zan'thik Impalers and 6 Zan'thik Manipulators in Zan'vess.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3278 }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 5556, ["name"] = "Klaxxi Daily Quests", ["orderIndex"] = 2, ["flags"] = 0 } } },
[31113] = { ["id"] = 31113, ["name"] = "Assault Fire Camp Gai-Cho", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5842, ["storyline"] = { 31113 }, ["description"] = "The Yaungol are a constant nuisance, but the group at Fire Camp Gai-Cho, to the northeast, conspired with the Osul yaungol in their recent incursion into Kun-Lai. We cannot allow such an incursion to go unpunished. Go, attack Fire Camp Gai-Cho. We need to make sure they remain occupied, so that they cannot rise up and threaten The Ox Gate again.", ["objectivesText"] = "Kill 16 Gai-Cho Yaungol , Earthtalkers or Pitchthrowers. Progress: Is your raid on Gai-Cho complete?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 84762 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3279 } },
[31114] = { ["id"] = 31114, ["name"] = "Assault Deadtalker's Plateau", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5842, ["storyline"] = { 31114 }, ["description"] = "We have always left the Deadtalkers alone. For so long, they were just responsible for maintaining the sacred burial grounds of the yaungol tribes. Now, though, they are practicing dark magic, defiling the corpses of their former clanmates... I know not where they learned those dark magics, or why they no longer treat their dead with respect, but we do not have time to find out. We need to stop them.", ["objectivesText"] = "Kill 8 Deadtalker Corpsedefilers and 1 Deadtalker Crusher . Progress: Have you defeated the Deadtalkers?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3279 } },
[31116] = { ["id"] = 31116, ["name"] = "Spirit Dust", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5842, ["storyline"] = { 31116 }, ["description"] = "The spirits that the Yaungol are entrapping from the remains of their ancestors still have a bit of the essence of life within them. If you defeat the spirits in battle, you can collect essence from the spirits as dust, and then return it to the corpses in the area, which will send the spirits, finally, to the next life. This is the only way to set right what the Deadtalkers have done. It will also help keep us safe.", ["objectivesText"] = "Return 8 spirits to their remains at the Deadtalker Plateau in Townlong Steppes .", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 84727 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3279 } },
[31117] = { ["id"] = 31117, ["name"] = "Uruk!", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5842, ["storyline"] = { 31117 }, ["description"] = "Uruk is the Deadtalker of the Townlong yaungol. Your mission will not be truly complete until you defeat him. Go to it!", ["objectivesText"] = "Kill Uruk at Deadtalker's Plateau in Townlong Steppes . Progress: How goes the mission?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3279 } },
[31119] = { ["id"] = 31119, ["name"] = "The Enemy of My Enemy... Is Still My Enemy!", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5842, ["storyline"] = { 31119 }, ["description"] = "The mantid are our enemies. As are the yaungol at Fire Camp Gai-Cho. It is fortunate, then, that they are also each other's enemies. Mantid from Kri'vess constantly attack the Gai-Cho yaungol, who hold them off at their front gates. I want you to wreak havoc. \"Borrow\" some highly explosive oil barrels from camp Gai-Cho, and toss them down onto the battlefield from the air. I don't care which ones you kill, just kill a lot of them.", ["objectivesText"] = "Use Highly Explosive Yaungol Oil Barrels to kill 100 mantid or yaungol on the Gai-Cho Battlefield. Progress: How goes the battle?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 84762 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3279 } },
[31120] = { ["id"] = 31120, ["name"] = "Cheng Bo!", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5842, ["storyline"] = { 31120 }, ["description"] = "Cheng Bo is the Warbringer of Fire Camp Gai-Cho. While you've made a dent in their operations, you now have an opportunity to strike a major blow. Slay the Warbringer!", ["objectivesText"] = "Kill Cheng-Bo at Fire Camp Gai-Cho in Townlong Steppes Progress: How goes the assualt?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 84762 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3279 } },
[31124] = { ["id"] = 31124, ["name"] = "Chose Brewmaster", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["storyline"] = { 31124 }, ["rewardItems"] = { 128938 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[31127] = { ["id"] = 31127, ["name"] = "The Challenger's Ring: Chao the Voice", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5842, ["storyline"] = { 31127 }, ["description"] = "It looks like you're quite the fighter, $p. Chao heard about it, and she's been talking about how she'd kick your... Well, let's just say I think you should challenge her and try to get her respect.", ["objectivesText"] = "Challenge Chao the Voice, and then defeat her in combat at Shado-Pan Garrison in Townlong Steppes . Progress: Well? How did it go?", ["rewardGold"] = 228000, ["rewardXP"] = 294000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard" },
[31128] = { ["id"] = 31128, ["name"] = "The Challenger's Ring: Lao-Chin the Iron Belly", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5842, ["storyline"] = { 31128 }, ["description"] = "Lao-Chin seems to have his head in the clouds... or, rather, in his beer. After all of his recent battles, he seems completely obsessed with with trying to develop the perfect brew for fighting. That's well and good, but we need him to actually do some fighting! You should go challenge him, see if you can snap him out of his rut. If you beat him, he'll probably want to go out and help fight just to try to one-up you!", ["objectivesText"] = "Challenge Lao-Chen the Iron Belly and then defeat him in combat at Shado-Pan Garrison in Townlong Steppes . Progress: Well?", ["rewardGold"] = 228000, ["rewardXP"] = 294000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard" },
[31131] = { ["id"] = 31131, ["name"] = "Whitepetal Lake", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 31131 }, ["description"] = "Reports suggest that things are quiet at Whitepetal Lake today, but I've dispatched Ren Firetongue and He Softfoot to make sure it stays they way. If you want to aid the effort further, head to the west to the lake, meet up with He, and help him keep things secure from any hostile threats.", ["objectivesText"] = "Speak to He Softfoot at Whitepetal Lake.", ["rewardGold"] = 57000, ["rewardXP"] = 118000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[31135] = { ["id"] = 31135, ["name"] = "The Future of Gnomeregan", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredClasses"] = { 10 }, ["requiredRaces"] = { 7 }, ["categories"] = {}, ["flags"] = { "class" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6457, ["mapID"] = 469, ["storyline"] = { 31135 }, ["series"] = { 26197, 26199, 26202, 26203, 26205, 26206, 26208, 26222, 26421, 26422, 26423, 26424, 26425, 26566, 31137 }, ["description"] = "It's a victory for us every time we're able to help another survivor escape from the contaminated halls of Gnomeregan. <class>s like you will play an important part in the future of Gnomeregan. To that end, our leader, High Tinker Mekkatorque, has assembled a team of trainers to help you learn your arts. Xi, Friend of the Small has visited us from a faraway land and will help oversee your training and adjustment to life on the surface. She's waiting for you on the small practice field across the road.", ["objectivesText"] = "Meet with Xi, Friend of the Small in New Tinkertown.", ["rewardGold"] = 8, ["rewardXP"] = 40, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6457 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 469, ["questLines"] = { { ["id"] = 5398, ["name"] = "Gnomeregan", ["orderIndex"] = 11, ["flags"] = 0 } } },
[31136] = { ["id"] = 31136, ["name"] = "Behind Our Lines", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 31136 }, ["description"] = "Scouts bring me reports of a powerful Imperion that slipped through our lines in the south and is now heading for the road in the eastern vale. I need someone I can trust to stop it. Find it and kill it quickly, <name>.", ["objectivesText"] = "Kill General Temuja . Progress: Did you hunt down the Imperion as I requested?", ["rewardGold"] = 228000, ["rewardXP"] = 294000, ["rewardItems"] = { 90625 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[31137] = { ["id"] = 31137, ["name"] = "Meet the High Tinker", ["level"] = 2, ["requiredLevel"] = 2, ["faction"] = "alliance", ["requiredRaces"] = { 7 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6457, ["mapID"] = 469, ["storyline"] = { 31137 }, ["series"] = { 26197, 26199, 26202, 26203, 26205, 26206, 26208, 26222, 26421, 26422, 26423, 26424, 26425, 26566, 31135 }, ["description"] = "I don't know if you'll remember Mekkatorque or not. Nevin and the other gnomes have mentioned that memory loss is pretty common for you survivors. Anyways, High Tinker Mekkatorque is the leader of all the gnomes. He has made a habit of meeting with every rescued survivor personally. You should introduce yourself to him. He'll be with his war council beneath the tent in the center of town.", ["objectivesText"] = "Introduce yourself to High Tinker Mekkatorque in New Tinkertown.", ["rewardXP"] = 15, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6457 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 469, ["questLines"] = { { ["id"] = 5398, ["name"] = "Gnomeregan", ["orderIndex"] = 18, ["flags"] = 0 } } },
[31138] = { ["id"] = 31138, ["name"] = "The Arts of a Monk", ["level"] = 3, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredClasses"] = { 10 }, ["requiredRaces"] = { 7 }, ["categories"] = {}, ["flags"] = { "class" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6457, ["storyline"] = { 31138 }, ["description"] = "When you fight, you grow in skill. As you grow in skill, you will begin to figure out new moves. Go, explore, learn, and show me what you figure out.", ["objectivesText"] = "Reach level 3 to learn Tiger Palm . Once you've learned it, use it twice at a Training Dummy in New Tinkertown.", ["rewardGold"] = 40, ["rewardXP"] = 190, ["rewardItems"] = { 59042 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6457 } }, ["questType"] = "standard" },
[31139] = { ["id"] = 31139, ["name"] = "Beating Them Back!", ["level"] = 3, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredClasses"] = { 10 }, ["requiredRaces"] = { 1 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6170, ["mapID"] = 425, ["storyline"] = { 31139 }, ["series"] = { 287, 3100, 3101, 3102, 3103, 3104, 3105, 26910, 26913, 26914, 26915, 26916, 26917, 26918, 26919, 28757, 28759, 28762, 28763, 28764, 28765, 28766, 28767, 28769, 28770, 28771, 28772, 28773, 28774, 28780, 28784, 28785, 28786, 28787, 28788, 28789, 29078, 29079, 29080, 31140, 31141, 31142, 31143 }, ["description"] = "So you're the new recruit from Stormwind, eh? I'm Marshal McBride , commander of this garrison. Glad to have you on board... <McBride looks through some papers.> <name>. It is <name>, right? You've arrived just in time. The Blackrock orcs have managed to sneak into Northshire through a break in the mountain. My soldiers are doing the best that they can to push them back, but I fear they will be overwhelmed soon. Head northwest into the forest and kill the attacking Blackrock worgs! Help my soldiers!", ["objectivesText"] = "Kill 6 Blackrock Battle Worgs . Progress: Have you beaten back the Blackrock battle worgs ?", ["rewardGold"] = 50, ["rewardXP"] = 500, ["rewardItems"] = { 57253, 57254, 57255 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6170 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 425, ["questLines"] = { { ["id"] = 1226, ["name"] = "Northshire", ["orderIndex"] = 2, ["flags"] = 0 } } },
[31140] = { ["id"] = 31140, ["name"] = "Lions for Lambs", ["level"] = 3, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredClasses"] = { 10 }, ["requiredRaces"] = { 1 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6170, ["mapID"] = 425, ["storyline"] = { 31140 }, ["series"] = { 287, 3100, 3101, 3102, 3103, 3104, 3105, 26910, 26913, 26914, 26915, 26916, 26917, 26918, 26919, 28757, 28759, 28762, 28763, 28764, 28765, 28766, 28767, 28769, 28770, 28771, 28772, 28773, 28774, 28780, 28784, 28785, 28786, 28787, 28788, 28789, 29078, 29079, 29080, 31139, 31141, 31142, 31143 }, ["description"] = "The invading orcs aren't fools. They are sizing us up, making sure that when they attack it will be to their advantage. In the forest, to the northwest, are Blackrock spies. They peer at us through spyglasses, watching our every move - waiting. I want you take the fight to them! Kill the Blackrock spies! We must show them that we know they are watching us and that we are prepared!", ["objectivesText"] = "Kill 8 Blackrock Spies .", ["rewardGold"] = 40, ["rewardXP"] = 500, ["rewardItems"] = { 57386, 57387, 57388 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6170 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 425, ["questLines"] = { { ["id"] = 1226, ["name"] = "Northshire", ["orderIndex"] = 11, ["flags"] = 0 } } },
[31141] = { ["id"] = 31141, ["name"] = "Calligraphed Letter", ["level"] = 3, ["requiredLevel"] = 2, ["faction"] = "alliance", ["requiredClasses"] = { 10 }, ["requiredRaces"] = { 4 }, ["categories"] = {}, ["flags"] = { "class" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6170, ["storyline"] = { 31141 }, ["series"] = { 287, 3100, 3101, 3102, 3103, 3104, 3105, 26910, 26913, 26914, 26915, 26916, 26917, 26918, 26919, 28757, 28759, 28762, 28763, 28764, 28765, 28766, 28767, 28769, 28770, 28771, 28772, 28773, 28774, 28780, 28784, 28785, 28786, 28787, 28788, 28789, 29078, 29079, 29080, 31139, 31140, 31142, 31143 }, ["description"] = "I was asked to bring this to your attention as soon as you returned from dealing with the Blackrock spies, <name>. It appears to be a letter sealed with the insignia of Bao , a pandaren who is visiting us from a faraway land. I wouldn't hesitate to read it before you go about any other business here in the Abbey.", ["objectivesText"] = "Read the Calligraphed Letter and speak to Bao in Northshire Abbey. Progress: Ah, you got my letter, <name>... good. I've come from afar to teach your people the ways of the <class>.", ["rewardXP"] = 125, ["rewardItems"] = { 85160 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6170 } }, ["questType"] = "standard" },
[31142] = { ["id"] = 31142, ["name"] = "Palm of the Tiger", ["level"] = 3, ["requiredLevel"] = 2, ["faction"] = "alliance", ["requiredClasses"] = { 10 }, ["requiredRaces"] = { 4 }, ["categories"] = {}, ["flags"] = { "class" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6170, ["storyline"] = { 31142 }, ["series"] = { 287, 3100, 3101, 3102, 3103, 3104, 3105, 26910, 26913, 26914, 26915, 26916, 26917, 26918, 26919, 28757, 28759, 28762, 28763, 28764, 28765, 28766, 28767, 28769, 28770, 28771, 28772, 28773, 28774, 28780, 28784, 28785, 28786, 28787, 28788, 28789, 29078, 29079, 29080, 31139, 31140, 31141, 31143 }, ["description"] = "Now that you've had the chance to test your abilities in battle, it's time to explain one more reason why training is so important. As you get more experience, you'll be able to do new techniques you never thought of. Go, get some experience, learn a new skill, and demonstrate it on one of the training dummies.", ["objectivesText"] = "Reach level 3 to learn Tiger Palm , then practice using it on a Training Dummy south of the entrance to Northshire Abbey. Progress: Well, did you give it a try?", ["rewardGold"] = 50, ["rewardXP"] = 250, ["rewardItems"] = { 87265 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6170 } }, ["questType"] = "standard" },
[31143] = { ["id"] = 31143, ["name"] = "Join the Battle!", ["level"] = 3, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredClasses"] = { 10 }, ["requiredRaces"] = { 1 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6170, ["mapID"] = 425, ["storyline"] = { 31143 }, ["series"] = { 287, 3100, 3101, 3102, 3103, 3104, 3105, 26910, 26913, 26914, 26915, 26916, 26917, 26918, 26919, 28757, 28759, 28762, 28763, 28764, 28765, 28766, 28767, 28769, 28770, 28771, 28772, 28773, 28774, 28780, 28784, 28785, 28786, 28787, 28788, 28789, 29078, 29079, 29080, 31139, 31140, 31141, 31142 }, ["description"] = "While you were out training I received an urgent message from Sergeant Willem . Turns out that the Blackrock orcs have hired goblin assassins. They ambushed our battalion behind the abbey. Willem has asked me to send him a hero. You have to go help them, <name>! Find Sergeant Willem north of the abbey at the command tent. Go!", ["objectivesText"] = "Report to Sergeant Willem behind Northshire Abbey in Elwynn Forest .", ["rewardGold"] = 13, ["rewardXP"] = 65, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6170 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 425, ["questLines"] = { { ["id"] = 1226, ["name"] = "Northshire", ["orderIndex"] = 20, ["flags"] = 0 } } },
[31144] = { ["id"] = 31144, ["name"] = "They Sent Assassins", ["level"] = 3, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredRaces"] = { 1 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6170, ["mapID"] = 425, ["storyline"] = { 31144 }, ["series"] = { 287, 3100, 3101, 3102, 3103, 3104, 3105, 26910, 26913, 26914, 26915, 26916, 26917, 26918, 26919, 28757, 28759, 28762, 28763, 28764, 28765, 28766, 28767, 28769, 28770, 28771, 28772, 28773, 28774, 28780, 28784, 28785, 28786, 28787, 28788, 28789, 29078, 29079, 29080, 31139, 31140, 31141, 31142, 31143 }, ["description"] = "Have you ever seen a goblin, <name>? They're wretched little green-skinned monsters that love only two things: gold and themselves. The Blackrock orcs have enlisted the aid of goblin assassins to kill our soldiers. If you look to the field in the north you can barely make out their silhouettes, sneaking about in the grass. I need you to head out there and kill every goblin that you see. They need to learn that nobody messes with the Alliance!", ["objectivesText"] = "Kill 8 Goblin Assassins .", ["rewardGold"] = 50, ["rewardXP"] = 250, ["rewardItems"] = { 2186, 2691, 11192 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6170 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 425, ["questLines"] = { { ["id"] = 1226, ["name"] = "Northshire", ["orderIndex"] = 29, ["flags"] = 0 } } },
[31145] = { ["id"] = 31145, ["name"] = "The Rear is Clear", ["level"] = 4, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredClasses"] = { 10 }, ["requiredRaces"] = { 4 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6170, ["mapID"] = 425, ["storyline"] = { 31145 }, ["series"] = { 287, 3100, 3101, 3102, 3103, 3104, 3105, 26910, 26913, 26914, 26915, 26916, 26917, 26918, 26919, 28757, 28759, 28762, 28763, 28764, 28765, 28766, 28767, 28769, 28770, 28771, 28772, 28773, 28774, 28780, 28784, 28785, 28786, 28787, 28788, 28789, 29078, 29079, 29080, 31139, 31140, 31141, 31142, 31143 }, ["description"] = "Excellent work, <name>! The rear is now officially clear. We'll take care of the stragglers. I want you to go back to Marshal McBride , standing in front of Northshire Abbey, south of here, and let him know that the goblin situation is under control. Farewell, <class>.", ["objectivesText"] = "Report to Marshal McBride in front of Northshire Abbey in Elwynn Forest .", ["rewardGold"] = 7, ["rewardXP"] = 35, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6170 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 425, ["questLines"] = { { ["id"] = 1226, ["name"] = "Northshire", ["orderIndex"] = 38, ["flags"] = 0 } } },
[31146] = { ["id"] = 31146, ["name"] = "Scribbled Scroll", ["level"] = 3, ["requiredLevel"] = 2, ["faction"] = "horde", ["requiredClasses"] = { 10 }, ["requiredRaces"] = { 5 }, ["categories"] = {}, ["flags"] = { "class" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6454, ["storyline"] = { 31146 }, ["series"] = { 3095, 3096, 3097, 3098, 3099, 24961, 24962, 24964, 24965, 24966, 24967, 24968, 24969, 24970, 24971, 24973, 26802, 28651, 28672, 31147, 31148 }, ["description"] = "Ah, while you were off dealing with the mindless Scourge, this scroll arrived for you. The pandaren visitor, Ting, sent it for you. Maybe you monks can read this garbage, but I can't. You should go talk to her. She's in the Inn across the way.", ["objectivesText"] = "Read the Elegant Scroll and speak to Ting, Strong of Stomach in Deathknell. Progress: Oh, yes, I sent that for you. I hope to prove that Forsaken can learn the arts of the <class> - perhaps you can help?", ["rewardXP"] = 125, ["rewardItems"] = { 85164 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6454 } }, ["questType"] = "standard" },
[31147] = { ["id"] = 31147, ["name"] = "Tiger Palm", ["level"] = 3, ["requiredLevel"] = 2, ["faction"] = "horde", ["requiredClasses"] = { 10 }, ["requiredRaces"] = { 5 }, ["categories"] = {}, ["flags"] = { "class" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6454, ["storyline"] = { 31147 }, ["series"] = { 3095, 3096, 3097, 3098, 3099, 24961, 24962, 24964, 24965, 24966, 24967, 24968, 24969, 24970, 24971, 24973, 26802, 28651, 28672, 31146, 31148 }, ["description"] = "As you overcome great challenges in your journey to master struggles both internal and external, you will begin to uncover new abilities hidden inside yourself. Go, now, and develop a mastery of yourself, such that you uncover the Tiger Palm technique. Then, go practice it on a training dummy.", ["objectivesText"] = "Reach level 3 to learn Tiger Palm , then practice using it on a Training Dummy.", ["rewardGold"] = 25, ["rewardXP"] = 125, ["rewardItems"] = { 87265 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6454 } }, ["questType"] = "standard" },
[31148] = { ["id"] = 31148, ["name"] = "Novice Elreth", ["level"] = 3, ["requiredLevel"] = 2, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["storyline"] = { 31148 }, ["series"] = { 3095, 3096, 3097, 3098, 3099, 24961, 24962, 24964, 24965, 24966, 24967, 24968, 24969, 24970, 24971, 24973, 26802, 28651, 28672, 31146, 31147 }, ["description"] = "Actually, before I go - you should speak with Novice Elreth. She had some work for you, and you would do well to help others and improve your skills. The next time you see me, I will be in Undercity.", ["objectivesText"] = "Speak to Novice Elreth at Deathknell in Tirisfal Glades .", ["rewardXP"] = 25, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[31150] = { ["id"] = 31150, ["name"] = "Elegant Rune", ["level"] = 3, ["requiredLevel"] = 2, ["faction"] = "alliance", ["requiredClasses"] = { 10 }, ["requiredRaces"] = { 3 }, ["categories"] = {}, ["flags"] = { "class" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6176, ["storyline"] = { 31150 }, ["series"] = { 31151 }, ["description"] = "<name>, this rune was given to me to pass on to ye. Take some time to read it when ye have a chance. I'm thinkin' it came from our visitor from afar, Lo . Take a gander at it and go find him inside Anvilmar.", ["objectivesText"] = "Read the Elegant Rune and speak to Lo in Coldridge Valley. Progress: I like it here, <name>. Your people have quite an appreciation for the finer things!", ["rewardGold"] = 25, ["rewardXP"] = 125, ["rewardItems"] = { 85174 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6176 } }, ["questType"] = "standard" },
[31156] = { ["id"] = 31156, ["name"] = "Calligraphed Parchment", ["level"] = 3, ["requiredLevel"] = 2, ["faction"] = "horde", ["requiredClasses"] = { 10 }, ["requiredRaces"] = { 2 }, ["categories"] = {}, ["flags"] = { "class" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6451, ["storyline"] = { 31156 }, ["series"] = { 31157 }, ["description"] = "Ah, while you were gone a parchment came for you, <name>. Read it when you have time. If I'm not mistaken, it came from our Pandaren friend, Gato . He visits from afar to grant us the honor of his wisdom, and to teach the ways of the monk. Do not shame your people by failing at his lessons!", ["objectivesText"] = "Read the Calligraphed Parchment and speak with Gato in the Valley of Trials. Progress: Ahh, you have come.", ["rewardXP"] = 125, ["rewardItems"] = { 85196 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6451 } }, ["questType"] = "standard" },
[31157] = { ["id"] = 31157, ["name"] = "Tiger Palm", ["level"] = 3, ["requiredLevel"] = 2, ["faction"] = "horde", ["requiredClasses"] = { 10 }, ["requiredRaces"] = { 2 }, ["categories"] = {}, ["flags"] = { "class" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6451, ["storyline"] = { 31157 }, ["series"] = { 31156 }, ["description"] = "As you walk the road of your training, you will begin to discover within yourself the power to unlock new techniques. You need not even learn them from me, or another more experienced monk - you will find that they come to you on their own. For now, you should go and practice the basics. Gather more experience, and develop a new technique - once you have, you can practice it on the dummies nearby to master it.", ["objectivesText"] = "Reach level 3 to learn Tiger Palm . Locate a Training Dummy and practice using Tiger Palm 2 times.", ["rewardGold"] = 50, ["rewardXP"] = 125, ["rewardItems"] = { 87265 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6451 } }, ["questType"] = "standard" },
[31158] = { ["id"] = 31158, ["name"] = "The Basics: Hitting Things", ["level"] = 2, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6453, ["mapID"] = 463, ["storyline"] = { 31158 }, ["series"] = { 31159, 31160, 31161, 31162, 31163 }, ["description"] = "Alright, mon. We start with da basics. I need ta know dat you know how ta swing dat weapon you're totin' around. Go thrash dose tiki targets . Take it slowly. Natural-like. I'll watch ya fighting form and we'll go from dere.", ["objectivesText"] = "Destroy 6 Tiki Targets .", ["rewardGold"] = 35, ["rewardXP"] = 215, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6453 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 463, ["questLines"] = { { ["id"] = 5430, ["name"] = "Echo Isles", ["orderIndex"] = 14, ["flags"] = 0 } } },
[31159] = { ["id"] = 31159, ["name"] = "The Rise of the Darkspear", ["level"] = 2, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6453, ["mapID"] = 463, ["storyline"] = { 31159 }, ["series"] = { 31158, 31160, 31161, 31162, 31163 }, ["description"] = "Tha Darkspear tribe have long been victims. Outcasts. We found ourselves fleein' our homes time 'n time again... but dis time, it's not fleein' dat drives us here. Vol'jin has offered us leadership through wisdom, and it has kept us alive dis long. Now dat same wisdom offers portents of a chaotic future for tha Horde unda Garrosh Hellscream. No, dis time we not fleein'. Dis time, we are fightin' for a home dat will last. It's time to begin ya trainin', <name>. Speak with Zabrax to the east.", ["objectivesText"] = "Meet with Zabrax in the Darkspear Training Grounds.", ["rewardGold"] = 25, ["rewardXP"] = 170, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6453 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 463, ["questLines"] = { { ["id"] = 5430, ["name"] = "Echo Isles", ["orderIndex"] = 8, ["flags"] = 0 } } },
[31160] = { ["id"] = 31160, ["name"] = "A Rough Start", ["level"] = 3, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6453, ["mapID"] = 463, ["storyline"] = { 31160 }, ["series"] = { 31158, 31159, 31161, 31162, 31163 }, ["description"] = "Lets put dose skills ta use. I'll start ya off easy, mon. There be cats killing our boars. Dat food ain't for sharin'. Dose boars are gonna need ta be alive if ya be wanting food tonight. Dey're all over the island. Bring me some cat pelts.", ["objectivesText"] = "Retrieve 6 Wildmane Cat Pelts . Progress: I doubt dey too much of a challenge, mon, but they'll still claw up ya ankles if ya don't stay quick footed.", ["rewardGold"] = 50, ["rewardXP"] = 380, ["rewardItems"] = { 50222 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6453 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 463, ["questLines"] = { { ["id"] = 5430, ["name"] = "Echo Isles", ["orderIndex"] = 26, ["flags"] = 0 } } },
[31161] = { ["id"] = 31161, ["name"] = "Proving Pit", ["level"] = 3, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6453, ["mapID"] = 463, ["storyline"] = { 31161 }, ["series"] = { 31158, 31159, 31160, 31162, 31163 }, ["description"] = "Ya done quite well for ya'self, <class>. I'm sure I could teach ya a trick or two here and dere, but I not be wastin' ya time on tiki targets no longer. l put one last trial before ya den, mon. Head over to da provin' pit in the middle of dis area and fight a real baddy - one dat wants ta kill ya back. Just let the jailor by the pit know when ya ready.", ["objectivesText"] = "Speak to a Darkspear Jailor , then enter the proving pit and kill a Captive Spitescale Scout .", ["rewardGold"] = 50, ["rewardXP"] = 380, ["rewardItems"] = { 52870, 52872, 52873, 52874, 52875, 52876, 52889, 85574 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6453 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 463, ["questLines"] = { { ["id"] = 5430, ["name"] = "Echo Isles", ["orderIndex"] = 35, ["flags"] = 0 } } },
[31162] = { ["id"] = 31162, ["name"] = "The Arts of a Monk", ["level"] = 3, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredClasses"] = { 10 }, ["categories"] = {}, ["flags"] = { "class" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6453, ["storyline"] = { 31162 }, ["series"] = { 31158, 31159, 31160, 31161, 31163 }, ["description"] = "As ya get bettah' at fightin', you'll start to find new tings that ya nevah knew you could do. Wanna see? Go, train up some, and learn someting new. 'Den come back and ya can show me.", ["objectivesText"] = "Reach level 3 to learn Tiger Palm . Practice using Tiger Palm against a Tiki Target.", ["rewardGold"] = 40, ["rewardXP"] = 190, ["rewardItems"] = { 59042 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6453 } }, ["questType"] = "standard" },
[31163] = { ["id"] = 31163, ["name"] = "More Than Expected", ["level"] = 3, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6453, ["mapID"] = 463, ["storyline"] = { 31163 }, ["series"] = { 31158, 31159, 31160, 31161, 31162 }, ["description"] = "Ya definitely more den expected, mon. I'm sure dere's more important stuff we can be usin' ya talents on now. Ya don't need ta hang out with da newbloods no more. Head down to da village to da southeast and make yaself known. Lend a hand here and there and I'm sure ya make yer way up to sometin' more prestigious quick enough.", ["objectivesText"] = "Report to Vol'jin at Darkspear Hold.", ["rewardGold"] = 25, ["rewardXP"] = 125, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6453 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 463, ["questLines"] = { { ["id"] = 5430, ["name"] = "Echo Isles", ["orderIndex"] = 44, ["flags"] = 0 } } },
[31166] = { ["id"] = 31166, ["name"] = "Tiger Palm", ["level"] = 3, ["requiredLevel"] = 2, ["faction"] = "horde", ["requiredClasses"] = { 10 }, ["requiredRaces"] = { 6 }, ["categories"] = {}, ["flags"] = { "class" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6452, ["storyline"] = { 31166 }, ["series"] = { 31165 }, ["description"] = "You have done well. As you continue along your path, you will grow, learning new techniques that you couldn't have imagined before. Your first lesson is the power of experience. Go, learn a new ability, and demonstrate it for me.", ["objectivesText"] = "Reach level 3 to learn Tiger Palm . Locate a Training Dummy in Camp Narache and practice using it.", ["rewardGold"] = 50, ["rewardXP"] = 125, ["rewardItems"] = { 87265 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6452 } }, ["questType"] = "standard" },
[31170] = { ["id"] = 31170, ["name"] = "Monk Training", ["level"] = 3, ["requiredLevel"] = 2, ["faction"] = "horde", ["requiredClasses"] = { 10 }, ["requiredRaces"] = { 10 }, ["categories"] = {}, ["flags"] = { "class" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6455, ["storyline"] = { 31170 }, ["description"] = "As you advance within your class, you will want to take advantage of the training that your class trainer can provide you. For young monks here on Sunstrider Isle, your trainer is Pao , our Pandaren visitor. Speak with her and see what training she has available for you. Pao - as with all the trainers on Sunstrider Isle - is inside the Sunspire on the lower level.", ["objectivesText"] = "Speak with Pao , the Monk class trainer, inside the Sunspire on Sunstrider Isle.", ["rewardXP"] = 65, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6455 } }, ["questType"] = "standard" },
[31171] = { ["id"] = 31171, ["name"] = "Tiger Palm", ["level"] = 3, ["requiredLevel"] = 2, ["faction"] = "horde", ["requiredClasses"] = { 10 }, ["requiredRaces"] = { 10 }, ["categories"] = {}, ["flags"] = { "class" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6455, ["storyline"] = { 31171 }, ["description"] = "Good. You are off to a bright start. This road will be long, and as you become more accomplished, you will begin to discover that you can do things you could never have imagined before. Go, get more experience, and learn a new technique. Once you have, demonstrate it on one of the training dummies.", ["objectivesText"] = "Reach level 3 to learn Tiger Palm . Locate a Training Dummy outside the Sunspire and practice using it. Progress: Have you practiced your Tiger Palm ?", ["rewardGold"] = 50, ["rewardXP"] = 250, ["rewardItems"] = { 87265 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6455 } }, ["questType"] = "standard" },
[31172] = { ["id"] = 31172, ["name"] = "Monk Training", ["level"] = 3, ["requiredLevel"] = 2, ["faction"] = "alliance", ["requiredClasses"] = { 1 }, ["requiredRaces"] = { 11 }, ["categories"] = {}, ["flags"] = { "class" }, ["sharable"] = false, ["expansion"] = 4, ["storyline"] = { 31172 }, ["series"] = { 31173 }, ["rewardXP"] = 125, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[31173] = { ["id"] = 31173, ["name"] = "The Tiger Palm", ["level"] = 3, ["requiredLevel"] = 2, ["faction"] = "alliance", ["requiredClasses"] = { 10 }, ["requiredRaces"] = { 11 }, ["categories"] = {}, ["flags"] = { "class" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6456, ["storyline"] = { 31173 }, ["series"] = { 31172 }, ["description"] = "I hope your people are all alright... the crash was unbelievably loud and destructive! <Mojo looks you over, evaluating your potential.> Yes, you'll do fine. They've said that they need more people to fight, and they don't want me to hurt myself. I'm not afraid, but I don't want to intrude. So, I'll teach you. As you may have discovered, your experiences in combat will unlock new potential within you. Go, see if you can master a new ability. Show it to me. You'll get the hang of things.", ["objectivesText"] = "Reach level 3 to learn Tiger Palm . Find a Training Dummy on the northwest side of the Crash Site and practice using it.", ["rewardGold"] = 50, ["rewardXP"] = 250, ["rewardItems"] = { 87265 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6456 } }, ["questType"] = "standard" },
[31194] = { ["id"] = 31194, ["name"] = "Slitherscale Suppression", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5785, ["storyline"] = { 31194 }, ["description"] = "The Slitherscale take orders from their leader, the Slitherscale Lizard-Lord . He can be found celebrating his victories on the southeastern corner of Windward Isle. If we can destroy this leader, we can deal their tribe a great blow. Without their lord, the Slitherscale will think twice before attacking the gentle cloud serpents of the east.", ["objectivesText"] = "Kill the Slitherscale Lizard-Lord . Progress: A snake without a head cannot strike.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3284 } },
[31196] = { ["id"] = 31196, ["name"] = "Sra'vess Wetwork", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5842, ["storyline"] = { 31196 }, ["description"] = "The mantid outnumber us quite badly. Hundreds of them for each of us. And, they surround us on two sides - at Gao-Ran in the south we're holding them off, but to the west, on the island they call Sra'vess, they continue to mass unabated. We're not stupid. We're not going to launch a full scale attack on them. We can't sustain an intense battle on multiple fronts. Instead, we're going to send you, and one of our Wu Kao, to do some dirty work. Sounds fun, doesn't it?", ["objectivesText"] = "Kill any 15 non-elite mantid near Sra'vess. Progress: The mission isn't complete, <name>.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3279 } },
[31197] = { ["id"] = 31197, ["name"] = "The Bigger They Come...", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5842, ["storyline"] = { 31197 }, ["description"] = "Killing the smaller mantid works mostly as a distraction. It forces them to replenish their numbers before they consider any serious offensive. The big ones, though - we kill a few of those, and we really disrupt operations on the island. That buys ourselves a substantial amount of time. With mantid, it's like their size is directly proportional to their importance in the empire. So kill some of the big ones for me, while you're out there.", ["objectivesText"] = "Kill any 4 elite mantid at Sra'vess. Progress: I don't think you're done yet.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 86536 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3279 } },
[31198] = { ["id"] = 31198, ["name"] = "A Morale Victory", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5842, ["storyline"] = { 31198 }, ["description"] = "The mantid have statues built on Sra'vess. We don't know exactly what they use them for. They may have some sort of religious significance, or maybe they assist with their sonic communication. When you fight your opponent, you don't just engage them physically, you also engage them mentally. Whatever they use them for, the fact is that those statues are important to them. Which is why I want you to blow them up. Losing something important will be a substantial hit to morale.", ["objectivesText"] = "Destroy the Southern, Central, Eastern and Western Idols at Sra'vess. Progress: The statues?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3279 } },
[31199] = { ["id"] = 31199, ["name"] = "Destroy the Siege Weapons!", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5842, ["storyline"] = { 31199 }, ["description"] = "The mantid don't just attack in swarms. They're smart. They use alchemy, bombs... and what's worst, they've got siege weapons. Those have the potential to be incredibly destructive if they attack with them. We've got reports that they're building up a force of siege weapons to the west at Sra'vess. Go and destroy them.", ["objectivesText"] = "Destroy the four mantid siege weapons at Sra'vess in Townlong Steppes . Progress: You need to take out those siege weapons, <name>!", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3279 } },
[31200] = { ["id"] = 31200, ["name"] = "Fumigation", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5842, ["storyline"] = { 31200 }, ["description"] = "Our alchemists have cooked up a set of gas bombs that will discourage mantid from staying anywhere that we set them off. If we plant these in the critical structures of Sra'vess, they'll need to evacuate. That should sow some chaos and delay any action from the mantid there for days. Get to it, <name>.", ["objectivesText"] = "Plant Shado-Pan Gas Bombs within the 5 targeted structures on Sra'vess. Progress: Have you planted the gas bombs?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 86532 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3279 } },
[31201] = { ["id"] = 31201, ["name"] = "Friends, Not Food!", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5842, ["storyline"] = { 31201 }, ["description"] = "Our scouts have sent a very troubling report. Three of our trainees have gone missing, and our scouts found them... They've been captured by the mantid and sent to their Kunchong pits. Their Kunchong FEEDING pits. We're lucky that the Kunchong don't eat that often. I need you to get in there, give them these escape kites, and get them out!", ["objectivesText"] = "Rescue a Shado-Pan Trainee in each of the north, central and south Kunchong feeding pits. Progress: The trainees, <name>! You have to save them!", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3279 } },
[31203] = { ["id"] = 31203, ["name"] = "Target of Opportunity: Sra'thik Swarmlord", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5842, ["storyline"] = { 31203 }, ["description"] = "While we're here, we should do one more thing. The Sra'thik Swarmlord is responsible for directing the mantid forces from the air. If we leave it alive, it's going to cause trouble for the garrison. So we're not going to leave it alive. Let's take it out, $p.", ["objectivesText"] = "Kill the Sra'thik Swarmlord at Sra'vess in Townlong Steppes . Progress: We need to take down the Swarmlord!", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 86534, 86536 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3279 } },
[31204] = { ["id"] = 31204, ["name"] = "Target of Opportunity: Sra'thik Hivelord", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5842, ["storyline"] = { 31204 }, ["description"] = "Near the ocean, on the eastern side of Sra'vess, there is a cavern that leads to a network of caves. From there, the Sra'thik Hivelord maintains Sra'vess and plots against us. If we manage to take him out, we'll disrupt their operations for days. Let's go to it.", ["objectivesText"] = "Defeat the Sra'thik Hivelord . Progress: We've got to kill the Hivelord.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3279 } },
[31206] = { ["id"] = 31206, ["name"] = "The Crucible of Carnage: The Bloodeye Bruiser!", ["level"] = 85, ["requiredLevel"] = 84, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["storyline"] = { 31206 }, ["description"] = "I'll tell you what, buddy, this place is a far cry from the rolling plains of Nagrand or the bloodbowl in Zul'Drak, but hey, I go where the gold's at! So welcome to Twi-Hi, pal. You're new to this pit, so let me set you straight. I'm the fight promoter and this feisty troll next to me is Wodin, my bodyguard. You're the entertainment. When you wanna fight, let me know and I'll set up the match. If you're ready and got a group of friends with you, we can start! What do you say?", ["objectivesText"] = "Get in the arena at the Crucible of Carnage and defeat Hurp'derp!", ["rewardGold"] = 282000, ["rewardXP"] = 104100, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "group" },
[31207] = { ["id"] = 31207, ["name"] = "The Arena of Annihilation", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6852, ["storyline"] = { 31207 }, ["description"] = "Ah, I can still remember running fights out of a muddy hole in the ground back in Nagrand. We've come a long way, eh, Wodin? I tell you, there's nothing more these Tiger monks like than a good scrap. So much so that they've paid good coin for me to set up shop here and help draw the strongest fighters from all around! So how about it? You and a couple friends up for a few rounds in the Arena of Annihilation...? Big money, big prizes!", ["objectivesText"] = "Enter and complete the Arena of Annihilation scenario. Afterwards, collect your reward from Wodin the Troll-Servant . Progress: What are you waiting for? The monks are spoiling for a good show.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 86520, 90459, 90460, 90461, 90462, 90463, 90464, 90465, 90466 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6852 } }, ["questType"] = "standard" },
[31208] = { ["id"] = 31208, ["name"] = "Venomous Intent", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6138, ["storyline"] = { 31208 }, ["description"] = "If we are to strike against the Empress, we must arm ourselves with weapons. My own choice of weapon is of a particularly toxic design. The scorpions wandering the ledge produce a deadly venom that they store in their tails. Bring me their stingers, and I will show you how I earned the title of paragon.", ["objectivesText"] = "Collect 8 Venomous Stingers . Progress: Did you feel the venomtail's sting? Such lovely pain.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 85571 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard" },
[31209] = { ["id"] = 31209, ["name"] = "Dark Wings, Dark Things", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6138, ["storyline"] = { 31209 }, ["description"] = "I require another ingredient to create my first poison, Wakener. This ingredient you can easily find on the scarabs nearby. Kill them and bring me their wings.", ["objectivesText"] = "Collect 150 Scarab Wings . Progress: Scarab wings can be crushed to produce a very fine white, deadly powder.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 85572 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard" },
[31210] = { ["id"] = 31210, ["name"] = "A Shade of Dread", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6138, ["storyline"] = { 31210 }, ["description"] = "The last ingredient is perhaps the deadliest. The dreadshade flower grows all along these hills. It is by eating these poisonous plants that the local wildlife has become so venomous. A single drop of dreadshade nectar can stop a kunchong's heart. Go and bring me some of these flowers. Do not be tempted to taste them.", ["objectivesText"] = "Collect 8 Dreadshade . Progress: Sometimes, the most beautiful things are also the most dangerous.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 85573 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard" },
[31211] = { ["id"] = 31211, ["name"] = "The Poisoned Mind", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6138, ["storyline"] = { 31211 }, ["description"] = "Before we return to Klaxxi'vess, I wish to look upon the empire. The Klaxxi Council told me that the enemy gathers outside the Empress's palace. My poisons are ready. What better way to announce my return than with death and destruction? Just be careful not to mix the two serums... at least not while you're holding the vessels. Speak to me when you are ready to fly.", ["objectivesText"] = "Speak to Xaril the Poisoned Mind . Kill 200 mantid and 3 kunchong while flying with him. Progress: Fight from above.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 84065, 84066, 84067, 84068, 84069 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard" },
[31216] = { ["id"] = 31216, ["name"] = "Dark Skies", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6138, ["mapID"] = 422, ["storyline"] = { 31216 }, ["description"] = "The swarm begins, Wakener! The mantid amass at the Heart of Fear. Already they fill the skies with their wings and rend the earth with their claws. They shall not stop the dark march until their bodies are laid open and bleeding upon the ground. This we shall gladly do. We will attack them from above. While I fly, use my poisons to destroy their advance. Do not mix the two serums until you are ready to attack. The reaction can be quite... violent. Speak to me when you are ready to go.", ["objectivesText"] = "Kill 200 Mantid and 3 Kunchong or Dread Behemoths while flying with Xaril the Poisoned Mind . Progress: Such wonderful destruction!", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3278 }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 5556, ["name"] = "Klaxxi Daily Quests", ["orderIndex"] = 3, ["flags"] = 0 } } },
[31220] = { ["id"] = 31220, ["name"] = "The Challenger's Ring: Hawkmaster Nurong", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5842, ["storyline"] = { 31220 }, ["description"] = "You've really been building up respect with the Shado-Pan, <name>. Nurong's interested in trying out his skills against you. The good news is, if you win, I'll allow him to go with you on your missions. The bad news is, I really don't think you'll win.", ["objectivesText"] = "Challenge Hawkmaster Nurong, and then defeat him in combat at Shado-Pan Garrison in Townlong Steppes . Progress: Not up to the challenge? I understand.", ["rewardGold"] = 228000, ["rewardXP"] = 294000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard" },
[31231] = { ["id"] = 31231, ["name"] = "Dreadspinner Extermination", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6138, ["mapID"] = 422, ["storyline"] = { 31231 }, ["description"] = "Back in Gurthani Terrace where you found me, dreadspinners continue to occupy the attention of Shado-Pan marksmen who could otherwise be thinning out this wretched swarm. Eradicate those spiders and offer some relief to the archers on that wall.", ["objectivesText"] = "Slay 8 Dreadspinner Tenders in the Terrace of Gurthan. Speak with Kil'ruk the Wind-Reaver for an air-drop.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3278 }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 5556, ["name"] = "Klaxxi Daily Quests", ["orderIndex"] = 4, ["flags"] = 0 } } },
[31232] = { ["id"] = 31232, ["name"] = "An Ancient Empire", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6138, ["mapID"] = 422, ["storyline"] = { 31232 }, ["description"] = "My brothers speak of an ancient mogu empire that once dwelled in the ruins to the east. Once, this tribe knew untold secrets of sorcery and subjugation. I have a curious mind, Wakener, and I wish to learn of the empires that ruled after my time. Knowledge of the past will determine our future. Go search the ruins for their ancient tablets. I will study their secrets and make them our own.", ["objectivesText"] = "Collect 8 Gurthani Tablets . Progress: What knowledge do you bring?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 85634 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3278 }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 5556, ["name"] = "Klaxxi Daily Quests", ["orderIndex"] = 19, ["flags"] = 0 } } },
[31233] = { ["id"] = 31233, ["name"] = "Sap Tapping", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6138, ["mapID"] = 422, ["storyline"] = { 31233 }, ["description"] = "I found a grove of young amber trees to the east, Wakener. I've placed tapping devices on these trees, but I have been too busy to retrieve the sap. I need someone to find the extractors. Activate them, then bring me samples of the amber.", ["objectivesText"] = "Collect 6 Amber Sap . Progress: These trees are still young. They are not yet kypari. Their sap is like water, while the sap of a true kypari tree is like wine. They must be allowed to grow.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 85664 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3278 }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 5556, ["name"] = "Klaxxi Daily Quests", ["orderIndex"] = 20, ["flags"] = 0 } } },
[31234] = { ["id"] = 31234, ["name"] = "Putting An Eye Out", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6138, ["mapID"] = 422, ["storyline"] = { 31234 }, ["description"] = "Ah! Wakener! You must help me! (You will help me, or else I will help myself to you!) I need more materials for my experiments, yes yes! (Blood and guts, hearts and brains, tongues and eyes, eyes, eyes!) To the west, I have seen creatures of mist and fog. They possess such big, round, wonderful globes! Big for seeing, round and unblinking! Go now, little Wakener. Bring me back a single pristine eye!", ["objectivesText"] = "Collect 1 Pristine Mire Beast Eye . Progress: Ooooh, what wonderful, tasty parts have you brought me?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 85635 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3278 }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 5556, ["name"] = "Klaxxi Daily Quests", ["orderIndex"] = 21, ["flags"] = 0 } } },
[31235] = { ["id"] = 31235, ["name"] = "Nope Nope Nope", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6138, ["mapID"] = 422, ["storyline"] = { 31235 }, ["description"] = "I recovered this weapon on a recent scouting run near the wall. It would seem ideal for helping your Shado-Pan with their infestation problem in Gurthani Terrace. The more they are focused on keeping spiders off the wall, the less time they are killing fear-gripped swarmborn.", ["objectivesText"] = "Use the Shado-Pan Dragon Gun to destroy 20 Dreadspinner Eggs in Gurthani Terrace.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 82807, 84037, 84038, 84039, 84040, 84041, 84042, 84043, 84044, 84045, 88995 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3278 }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 5556, ["name"] = "Klaxxi Daily Quests", ["orderIndex"] = 22, ["flags"] = 0 } } },
[31237] = { ["id"] = 31237, ["name"] = "Debugging the Terrace", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6138, ["mapID"] = 422, ["storyline"] = { 31237 }, ["description"] = "If this Empress is truly possessed by fear and paranoia, she will have sent scouts to every corner of the land in order to cement her control. These scout grubs are likely everywhere, but difficult to spot with the naked eye. Better to track them by the pheromone trails they leave behind. I've already... gifted you... a reactive toxin that will reveal these trails to you for a brief time after experiencing the thrill of victory. Go now to the Terrace of Gurthan and root out these spies.", ["objectivesText"] = "Stomp out 6 Eyes of the Empress around the Terrace of Gurthan. Killing anything will grant you Pheromone Tracking, helping you detect them. Progress: Best not to ask how I afflicted you with the toxin - you have become quite useful to us, and it would be a shame if we drove you mad with horror just yet.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3278 }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 5556, ["name"] = "Klaxxi Daily Quests", ["orderIndex"] = 23, ["flags"] = 0 } } },
[31238] = { ["id"] = 31238, ["name"] = "Brain Food", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6138, ["mapID"] = 422, ["storyline"] = { 31238 }, ["description"] = "Kovok is growing at an accelerated rate, but his brain may not be able to keep up. He'll require a special diet to ensure that he does not outgrow the capacity to control his own body. Mushan tongue is rich in the nutrients that promote brain growth in kunchong, but they normally eat the beasts whole and fill up quickly. If we feed Kovok only mushan tongues every couple of days or so, it should balance out his growth. Greatback mushan graze the hills east of here, near the Gurthani Terrace.", ["objectivesText"] = "Bring 4 Mushan Tongues to Kaz'tik the Manipulator at Klaxxi'vess. Progress: Have you found a suitable meal for Kovok?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 85665 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3278 }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 5556, ["name"] = "Klaxxi Daily Quests", ["orderIndex"] = 24, ["flags"] = 0 } } },
[31240] = { ["id"] = 31240, ["name"] = "Guo-Lai Infestation", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 31240 }, ["description"] = "Anji came by and asked for you. Said she was heading to the northeast ruins. Oh, Anji, such a fiery spirit, that girl! Probably better for your long-term health if you not keep her waiting.", ["objectivesText"] = "Speak to Anji Autumnlight at the Ruins of Guo-Lai.", ["rewardGold"] = 57000, ["rewardXP"] = 118000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[31242] = { ["id"] = 31242, ["name"] = "Mistfall Village", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 31242 }, ["description"] = "My scouts have spotted no mogu near Mistfall Village today, but I've been hearing of some troubles with local wildlife and spirits in the graveyard. I dispatched Che to assess the situation, but he'll most likely need your help. Find your way southwest to the village and meet Che there. Do what you can.", ["objectivesText"] = "Speak to Che Wildwalker at Mistfall Village.", ["rewardGold"] = 57000, ["rewardXP"] = 118000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[31243] = { ["id"] = 31243, ["name"] = "Attack on Mistfall Village", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 31243 }, ["description"] = "Mogu have been sighted at Mistfall Village to the southwest. I dispatched Rook and Sun immediately, but I need another capable hand there as soon as possible. Don't delay. The villagers need you.", ["objectivesText"] = "Speak to Sun Tenderheart at Mistfall Village.", ["rewardGold"] = 57000, ["rewardXP"] = 118000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[31244] = { ["id"] = 31244, ["name"] = "Guo-Lai Encampment", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 4, ["storyline"] = { 31244 }, ["description"] = "Leven came by in quite a huff! Said something about mogu in the ruins. Best be off to find him I think. Angry Leven is not a fun Leven.", ["objectivesText"] = "Speak to Leven Dawnblade at the Ruins of Guo-Lai.", ["rewardGold"] = 57000, ["rewardXP"] = 118000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[31248] = { ["id"] = 31248, ["name"] = "The Ruins of Guo-Lai", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 31248 }, ["description"] = "I've instructed Anji and Kun to resume investigation of the Ruins of Guo-Lai. We have no reports of any significant mogu presence there today, but it seems to be one of their central interests here in the Vale, and want it under thorough watch consider their attack on the lake. That's why I'm sending you as well. Head west, past the lake, to the ruins. Anji will instruct you further.", ["objectivesText"] = "Speak to Anji Autumnlight at the Ruins of Guo-Lai.", ["rewardGold"] = 57000, ["rewardXP"] = 118000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[31249] = { ["id"] = 31249, ["name"] = "Mistfall Village", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 31249 }, ["description"] = "Everything I've heard suggests the village has been unaffected by the Shao-Tien offensive at the lake, but I won't take any risks. I'm dispatching you and Che Wildwalker to keep watch at the village, and aid the townsfolk while you're there.", ["objectivesText"] = "Speak to Che Wildwalker at Mistfall Village.", ["rewardGold"] = 57000, ["rewardXP"] = 118000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[31250] = { ["id"] = 31250, ["name"] = "Setting Sun Garrison", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 31250 }, ["description"] = "We've taken losses from the mogu forces descending the Golden Stair and their flanking attackers at Whitepetal Lake. Our lines are thin. I'm dispatching Anji and Kun to the Setting Sun Garrison to double our efforts at training new recruits. I'd like you there with them, <name>. Show them what a true <class> is made of.", ["objectivesText"] = "Speak to Anji Autumnlight at the Setting Sun Garrison.", ["rewardGold"] = 57000, ["rewardXP"] = 118000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[31254] = { ["id"] = 31254, ["name"] = "The Road to Kun-Lai", ["level"] = 87, ["requiredLevel"] = 87, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 31254 }, ["series"] = { 30457, 31255 }, ["description"] = "Ah! Greetings friend of Lorewalker Cho. I have a message for you. <The strange little creature hands you a battered scroll case.> The Lorewalker waits for you in Kun-Lai. Very dangerous to travel there, yes, very dangerous. Look for guides along the road to help you find your way.", ["objectivesText"] = "Travel through the Veiled Stair to Binan Village. Progress: More strangers? This day is testing my limits.", ["rewardGold"] = 10200, ["rewardXP"] = 12900, ["rewardItems"] = { 85688 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[31260] = { ["id"] = 31260, ["name"] = "Profit Mastery: Chasheen", ["level"] = 86, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 31260 }, ["series"] = { 30353 }, ["description"] = "I am totally on to another great scam! When I was flying overhead I saw a really ancient tigress prowling about. Do you know how much her blood would go for on the black market? Not to mention if I convince some warlocks it adds extra potency to their summoning spells or something. If you bring me back some of her blood I will cut you in on the scam. She was prowling about on the far side of the Dojani River from here.", ["objectivesText"] = "Collect Ancient Tiger's Blood . Progress: I thought about taking that tiger on myself but to be honest I like living...", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 85774 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard" },
[31261] = { ["id"] = 31261, ["name"] = "Captain Jack's Dead", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["storyline"] = { 31261 }, ["description"] = "Gore from Captain Jack's head drips and mysteriously seeps into the ground as you examine your hard-won trophy. Strange, but no time to investigate that now. There's too much work to be done. The chieftain of your newfound friends will doubtlessly be impressed with this proof of your grookin' skills.", ["objectivesText"] = "Bring Captain Jack's head to Chief Kah Kah at Grookin Hill. Provided item:", ["rewardGold"] = 196000, ["rewardXP"] = 138000, ["rewardItems"] = { 85783 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["startItems"] = { 85783 } },
[31262] = { ["id"] = 31262, ["name"] = "Crane Mastery: Needlebeak", ["level"] = 86, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 31262 }, ["series"] = { 30352 }, ["description"] = "So, now that you've got a vibe for how cranes fight, I've got a doozy for you. Needlebeak! Or at least, that's what I'm calling him. Biggest crane I ever saw. And its beak is so sharp it's like a sword. Northwest of here you'll find the big water fall that kicks off the Dojani River. Needlebeak likes to hang out by the waterfall. You bring me its beak as a trophy and I will talk you up a good game to Nesingwary.", ["objectivesText"] = "Acquire the Needlebeak . Progress: I watched that bird stab a tiger through the face. What kind of place is this where birds are the predators for tigers?", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["rewardItems"] = { 85854, 88044, 88045, 88046, 88047, 88048, 88049, 88050, 88051, 88052 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard" },
[31266] = { ["id"] = 31266, ["name"] = "Mogu Incursions", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5842, ["storyline"] = { 31266 }, ["series"] = { 31277 }, ["description"] = "We've heard reports of a group of Mogu infiltrating the coast here in Townlong. I have no idea what they are doing. Frankly, I don't care. You've proven yourself, so we've decided to give this mission to you. What's going to happen is this - you're going to go, find them, and kill them. Our scouts reported the first group landed to the north, between here and Deadtalker's Plateau. Go there and wipe them out.", ["objectivesText"] = "Find and kill the Shan'ze Spymaster . Progress: Why aren't they dead already?", ["rewardGold"] = 57000, ["rewardXP"] = 118000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard" },
[31267] = { ["id"] = 31267, ["name"] = "Mistblade Destruction", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6138, ["mapID"] = 422, ["storyline"] = { 31267 }, ["description"] = "Korven has told me of his findings. There is an enormous amber deposit sitting at the bottom of the Lake of Stars. Unfortunately, a hostile saurok tribe lives at the edge of the lake, and revere the amber as their own. They will not allow us to enter their territory easily. Go south to the lake. Kill the Mistblade saurok, so that we can more easily harvest the nearby amber.", ["objectivesText"] = "Kill 6 Mistblade Rippers . Progress: Have you eliminated the opposition?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3278 }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 5556, ["name"] = "Klaxxi Daily Quests", ["orderIndex"] = 5, ["flags"] = 0 } } },
[31268] = { ["id"] = 31268, ["name"] = "A Little Brain Work", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6138, ["mapID"] = 422, ["storyline"] = { 31268 }, ["description"] = "Far to the south, the swarm breeds weapons of destruction - enormous, nearly unbreakable amber scorpions. Like all other creatures, they are subject to manipulation, but unlike other creatures, they have not yet submitted to my mind control. It appears that further research is necessary before I can dominate them for our own purposes. I must study their brains, and you must retrieve some specimens for me. Take this sonic emitter . I have found it to be quite effective against the beasts.", ["objectivesText"] = "Collect 3 Amber-Encrusted Brains from Ik'thik Amberstingers. Progress: They continue to resist my sonic manipulation. I must understand why.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 85884, 85885 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3278 }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 5556, ["name"] = "Klaxxi Daily Quests", ["orderIndex"] = 6, ["flags"] = 0 } } },
[31269] = { ["id"] = 31269, ["name"] = "The Scale-Lord", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6138, ["mapID"] = 422, ["storyline"] = { 31269 }, ["description"] = "The saurok at the Lake of Stars take their orders from their Scale-Lord, a vicious, merciless leader who guards his territory fiercely. If we can eliminate this leader, then we can gain access to the enormous amber lode beneath the lake. Go. Their leader gives his orders from his underground dwelling, at the southern edge of the lake.", ["objectivesText"] = "Kill the Mistblade Scale-Lord .", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3278 }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 5556, ["name"] = "Klaxxi Daily Quests", ["orderIndex"] = 7, ["flags"] = 0 } } },
[31270] = { ["id"] = 31270, ["name"] = "The Fight Against Fear", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6138, ["mapID"] = 422, ["storyline"] = { 31270 }, ["description"] = "When we discovered the sha influence at Kypari Zar, I had hoped the corruption could still be cleansed. Unfortunately, the Klaxxi Council has confirmed that the sha of fear's corruption is deep-seated, and continues to spread. To the south, I have observed some of the local wildlife consumed by an unnamed terror. The sha can warp and twist its victims into unimaginable horrors. We must stop the corruption before it becomes worse. Seek out the sha-infected Horrorscale Scorpids . Eliminate them.", ["objectivesText"] = "Kill 15 Horrorscale Scorpid .", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3278 }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 5556, ["name"] = "Klaxxi Daily Quests", ["orderIndex"] = 8, ["flags"] = 0 } } },
[31271] = { ["id"] = 31271, ["name"] = "Bad Genes", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6138, ["mapID"] = 422, ["storyline"] = { 31271 }, ["description"] = "Far to the south, Wakener, the Empress's genemancers set about their dark experiments. (Dark yes, but not as dark as mine!) They dissect and mutate the nearby wildlife, breeding creatures of their own design. (Their design, which will become my design!) We must not let them succeed! (No, no! Only I am allowed such power!) Their mutations are already being unleashed for war. Go! Destroy them at any cost!", ["objectivesText"] = "Kill 3 Ik'thik Genemancers and 6 Ik'thik Egg-Drones . Progress: Is it done? Are my competitio - I mean, our enemies - dead?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 9603 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3278 }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 5556, ["name"] = "Klaxxi Daily Quests", ["orderIndex"] = 9, ["flags"] = 0 } } },
[31272] = { ["id"] = 31272, ["name"] = "Infection", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6138, ["mapID"] = 422, ["storyline"] = { 31272 }, ["description"] = "The Empress's genemancers play with dangerous toys. To the south, they are injecting local wildlife with pheromone-laden parasites, in an attempt to create monstrous mutations for war. Carelessly, they have allowed their parasitic worms to escape into the local ecosystem. Left unchecked, the infection will spread from one animal to another, until we have an outbreak. I will inject you with a mild toxin. With it, you will be able to identify infected creatures. Kill the carriers at once.", ["objectivesText"] = "Kill 6 infected wildlife. Infected wildlife may include Bonedust Moths, Bluehide Mushan, and Mutating Scorpid. Progress: Do not worry. I have given you a weak toxin that allows you to share my ability to sense pheromones. It has no effect on mantid.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3278 }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 5556, ["name"] = "Klaxxi Daily Quests", ["orderIndex"] = 10, ["flags"] = 0 } } },
[31274] = { ["id"] = 31274, ["name"] = "LFGDungeons - Mists - Raid Finder - 1st", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["storyline"] = { 31274 }, ["rewardGold"] = 549600, ["rewardXP"] = 9580, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[31277] = { ["id"] = 31277, ["name"] = "Surprise Attack!", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5842, ["storyline"] = { 31277 }, ["series"] = { 31266 }, ["description"] = "Those damnable Mogu... Those scouts were a distraction! While we were hunting their spies, the main force moved on Niuzao Temple. Corrupted serpents, Mogu everywhere... this is a disaster! Thankfully, Ban was able to make it past their lines with the most elite members of our order. If you can slip past, too, meet up with him. We need to put a stop to this!", ["objectivesText"] = "Meet up with Ban Bearheart outside Niuzao Temple in Townlong Steppes , and put a stop to the Mogu Invasion there.", ["rewardGold"] = 342000, ["rewardXP"] = 353000, ["rewardItems"] = { 81194, 86592, 87768, 93220, 93229 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard" },
[31278] = { ["id"] = 31278, ["name"] = "Figuring out how to make quests", ["level"] = 83, ["requiredLevel"] = 81, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["storyline"] = { 31278 }, ["description"] = "Whee! You get to make a breadcrumb quest! Now figure out what to do next.", ["objectivesText"] = "Make a breadcrumb quest.", ["rewardGold"] = 258000, ["rewardXP"] = 65850, ["rewardItems"] = { 80689, 87286 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[31279] = { ["id"] = 31279, ["name"] = "Everything I Know About Cooking", ["level"] = 90, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 31279 }, ["description"] = "I'm so glad you enjoy my food. Are you interested in the recipes? If so, you should learn them properly, from my teachers in Halfhill Market. Everything I know about the kitchen, I learned from them. Say, if you happen to pass through there, would you deliver this note to Sungshin Ironpaw for me? She was my favorite teacher, and I want her to know that I miss her.", ["objectivesText"] = "Deliver the Letter to Sungshin Ironpaw . She teaches in Halfhill Market. Progress: You have a letter for me?", ["rewardGold"] = 11400, ["rewardXP"] = 23600, ["rewardItems"] = { 86392 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[31280] = { ["id"] = 31280, ["name"] = "Ways of Cooking", ["level"] = 90, ["requiredLevel"] = 85, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["storyline"] = { 31280 }, ["description"] = "There are many ways of cooking, and each creates dishes with unique properties. The Pandaren Ways of Cooking are the Ways of the Grill, the Wok, the Pot, the Steamer, the Oven and the Brew. You seem to already have the basics of each way, from your experience in faraway lands. If you wish to progress further, speak with my siblings and learn the first advanced recipe each of them teaches. Find out which Way suits you the best.", ["objectivesText"] = "Learn the recipes for Charbroiled Tiger Steak , Jade Forest Fried Rice, Swirling Mist Soup , Shrimp Dumplings , Wildfowl Roast and Ginseng Tea from the masters in Halfhill Market.", ["rewardGold"] = 11400, ["rewardXP"] = 23600, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[31285] = { ["id"] = 31285, ["name"] = "The Spring Drifter", ["level"] = 87, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6006, ["storyline"] = { 31285 }, ["description"] = "Nobody really travels up the Ancient Passage on foot. That is just asking for a faceful of saurok if you are not careful. Tell you what, Egg Shell and I were just about to set off upriver to Binan Village. Want a lift?", ["objectivesText"] = "Survive a trip on the Spring Drifter . Progress: It is always good luck to have a grummle aboard when traveling through a saurok infested cave.", ["rewardGold"] = 10200, ["rewardXP"] = 12900, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6006 } }, ["questType"] = "standard" },
[31286] = { ["id"] = 31286, ["name"] = "Robbing Robbers of Robbers", ["level"] = 87, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6006, ["storyline"] = { 31286 }, ["description"] = "Ah, a <class>. I could make good use of your skills. A convoy was struck just up the road by a band of marauding saurok. These marauders made off with some... merchandise... her ladyship, the Madam Goya, had a mind to sell. One does not steal from her ladyship. If you recover these items I will gladly provide you a finders fee.", ["objectivesText"] = "Recover 7 Black Market Merchandise . Progress: Saurok are seldom this bold.", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["rewardItems"] = { 85981 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6006 } }, ["questType"] = "standard" },
[31287] = { ["id"] = 31287, ["name"] = "Educating Saurok", ["level"] = 87, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6006, ["storyline"] = { 31287 }, ["description"] = "The Spring Road is under the protection of her ladyship, the esteemed Madam Goya. The saurok of Hatescale Burrow northeast of here require \"education\" in this fact. We have warned them before but sadly they seem to have a very short memory. Travel northeast to this burrow and find their shaman leader. Eliminate him and you will have the gratitude of her ladyship. As well as an appropriate bounty.", ["objectivesText"] = "Defeat Leechfingers . Progress: It is unwise to challenge the domain of Madam Goya.", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6006 } }, ["questType"] = "standard" },
[31288] = { ["id"] = 31288, ["name"] = "Research Project: The Mogu Dynasties", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 31288 }, ["description"] = "Ah, an explorer. Just what I could use. I am on the verge of discovering the dark secrets of the mogu. Not all of the secrets, mind you. They kept a lot of dark secrets. But I am on the verge of discovering \"a\" secret at least. If, in your travels, you come across some fragments of the mogu past, bring them to me and I will happily reimburse you for them.", ["objectivesText"] = "Obtain 20 Mogu Archaeology Fragments . Progress: It is dangerous to forget our past.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 87399 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[31289] = { ["id"] = 31289, ["name"] = "Research Project: The Pandaren Empire", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 4, ["storyline"] = { 31289 }, ["description"] = "Ah, adventurer. You come at a most opportune time. My daughter and I are researching the history of our people and have hit a roadblock in our research. Should you come across fragments of the pandaren past, please, bring them to us here. We would benefit greatly from the additional information.", ["objectivesText"] = "Obtain 20 Pandaren Archaeology Fragments .", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[31291] = { ["id"] = 31291, ["name"] = "Uncovering the Past", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 31291 }, ["description"] = "Interested in being a Lorewalker? There is lots of digging and reading and digging and more reading. I have entire days where I stare at a broken vase trying to figure out how it goes back together. Should give it a try. Go solve one artifact of Pandaria and we will appreciate you sharing the knowledge of how you did it.", ["objectivesText"] = "Solve 1 artifact from Pandaria. Progress: I am beginning to wonder if I'll ever get the hang of this stuff.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 87399 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[31293] = { ["id"] = 31293, ["name"] = "Mogu Make Poor House Guests", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 31293 }, ["description"] = "Leven sent Rook here to stop mogu, but there are more than Rook can kill alone. You help? Rook will tell Leven you helped. Promise.", ["objectivesText"] = "Kill 8 Shado-Tien attackers in Mistfall Village.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[31294] = { ["id"] = 31294, ["name"] = "The Ruins of Guo-Lai", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 31294 }, ["description"] = "I have my heartfelt thanks for your continued aid. Anji awaits at the Ruins of Guo-Lai to northwest. Go with courage in your heart, young <class>.", ["objectivesText"] = "Speak to Angi Autumnlight at the Ruins of Guo-Lai.", ["rewardGold"] = 57000, ["rewardXP"] = 118000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[31295] = { ["id"] = 31295, ["name"] = "Mogu within the Ruins of Guo-Lai", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 31295 }, ["description"] = "Thank you for your help, <class>. I would enjoy your company for longer, but Leven is leading an attack on the mogu within the Ruins of Guo-Lai to the northwest, and awaits your capable hands. May the celestials protect you, young one.", ["objectivesText"] = "Speak to Leven Dawnblade at the Ruins of Guo-Lai.", ["rewardGold"] = 57000, ["rewardXP"] = 118000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[31296] = { ["id"] = 31296, ["name"] = "The Ruins of Guo-Lai", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 31296 }, ["description"] = "The villagers seem to be safe and the mogu are losing their foothold. We should be able to handle the rest from here. Thank you for your kind aid, <name>. Anji lead a group to investigate and clear out the Ruins of Guo-Lai to the northwest this morning. I am certain she would appreciate someone as capable as yourself. You should go to her.", ["objectivesText"] = "Speak to Anji Autumnlight at the Ruins of Guo-Lai.", ["rewardGold"] = 57000, ["rewardXP"] = 118000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[31297] = { ["id"] = 31297, ["name"] = "Setting Sun Garrison", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 31297 }, ["description"] = "The mogu will not be able to maintain this attack much longer. We should be able to handle it here, thanks to your kind aid. Might you be willing to find Anji at the Setting Sun Training Camp to the west? She's been tasked with preparing fresh-faced pandaren to aid the cause. You could show them a thing or two as well, I imagine.", ["objectivesText"] = "Speak to Anji Autumnlight at the Setting Sun Training Camp.", ["rewardGold"] = 57000, ["rewardXP"] = 118000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[31302] = { ["id"] = 31302, ["name"] = "Ready for Greatness", ["level"] = 90, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 31302 }, ["description"] = "You seem to know your way around the kitchen. Demonstrate to me your skills and make me 5 bowls of rice pudding .", ["objectivesText"] = "Make 5 Rice Pudding and give them to the Guide to the Ways. Progress: I believe you have the potential to be a great chef, but the proof is in the pudding, so to speak.", ["rewardGold"] = 11400, ["rewardXP"] = 23600, ["rewardItems"] = { 86069 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[31311] = { ["id"] = 31311, ["name"] = "Way of the Grill", ["level"] = 90, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 31311 }, ["description"] = "The Pandaren Way of the Grill produces foods that increase your physical strength. Bring some raw tiger steaks to the Master of the Grill, and he will teach you what you can do with them. There are many tigers in the Jade Forest and the Krasarang Wilds, but you can also find them in other places.", ["objectivesText"] = "Bring 5 Raw Tiger Steaks to the Master of the Grill. Progress: If you wish to learn the Way of the Grill , bring me some raw tiger steaks .", ["rewardGold"] = 11400, ["rewardXP"] = 23600, ["rewardItems"] = { 74643, 74644, 74645, 74646, 74647, 74649, 74651, 74652, 74655, 74656, 74833, 74839, 74841, 74845, 74856, 74857, 75026, 75038 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[31312] = { ["id"] = 31312, ["name"] = "The Old Map", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 31312 }, ["description"] = "The old, faded leather is falling apart, but still legible. Scrawled on it is some kind of map, and the following lines: Deep in the valley where four winds blow, The maiden laughs behind her golden fan. At the feet of her ancestors' stair, She whispers secrets into the echoing dark.", ["objectivesText"] = "Show the map to Fish Fellreed at Cattail Lake or Halfhill Market in the Valley of the Four Winds . Provided item:", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 86404, 86428 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard", ["startItems"] = { 86404 } },
[31313] = { ["id"] = 31313, ["name"] = "Just A Folk Story", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 31313 }, ["description"] = "What!?! This don't make any sense! <Fish's face falls.> What's this mumber jumber about a maiden and an ancestor and a buncha stairs? I can't make any reason outta this, can you? Well, there are lotsa folks 'round here who're much older than you and me, <name>. Can you go talk to the folks in Halfhill? I betcha they might know somethin'!", ["objectivesText"] = "Speak to Grainsorter Pei , Stonecarver Mac , Mama Min , and Old Man Whitewhiskers .", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 86404, 86428 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[31314] = { ["id"] = 31314, ["name"] = "Old Man Thistle's Treasure", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 31314 }, ["series"] = { 31315 }, ["description"] = "Well high golly! This is turning into a real life treasure hunt! There's gotta be some kind of entrance or opening to the north, where the mountains meet Cattail Lake. I'll meet ya at the entrance! Let's go get that treasure!", ["objectivesText"] = "Find the cave entrance and recover Old Man Thistle's hidden treasure . Progress: If I weren't seeing it fer myself, I could hardly believe it!", ["rewardXP"] = 236000, ["rewardItems"] = { 86404, 86428 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[31315] = { ["id"] = 31315, ["name"] = "The Heartland Legacy", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 31315 }, ["series"] = { 31314 }, ["description"] = "At the very bottom of the treasure chest, you find a stack of scrolls and a soft leather sack with seeds. Unrolling the scrolls, you see they contain detailed farming notes, drawings of plants, numbers and calculations, locations of nearby water springs, and countless other snippets. There might be someone at the Tillers Union who would like to see this.", ["objectivesText"] = "Take Old Man Thistle's Almanac to Seedkeeper Shing Sing at Halfhill in the Valley of the Four Winds . Progress: What do you have there?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 86404, 86421, 86428 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[31316] = { ["id"] = 31316, ["name"] = "Julia, The Pet Tamer", ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 1519, ["mapID"] = 37, ["storyline"] = { 31316 }, ["series"] = { 31724, 31725, 31726, 31728, 31729, 31917, 32008 }, ["description"] = "I can tell you have been honing your pet battle skills, <name>. I think it's time for you to take on a real challenge. Julia Stevens can be found at the Maclure Vineyards south of Stormwind. She is an up and coming wild pet tamer and I think it's time you faced her in battle!", ["objectivesText"] = "Defeat Julia Stevens in a pet battle. Progress: How is your team coming along? I have two snakes so far!", ["rewardGold"] = 62000, ["rewardXP"] = 80, ["rewardItems"] = { 89125 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1519 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 37, ["questLines"] = { { ["id"] = 289, ["name"] = "Battle Pet Tamers", ["orderIndex"] = 0, ["flags"] = 0 } } },
[31320] = { ["id"] = 31320, ["name"] = "Buy A Fish A Drink?", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 31320 }, ["description"] = "Heeeey buddy, how'sh it goin'? You wanna buy a jinyu a drink?", ["objectivesText"] = "Bring 1 Four Wind Soju to Jogu the Drunk . Four Wind Soju can be purchased from most bartenders in Pandaria. Progress: Thirsty...", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 81407, 84101 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[31321] = { ["id"] = 31321, ["name"] = "Buy A Fish A Round?", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 31321 }, ["description"] = "Heeeey it's my friend, the <race>! I guesh you've seen me hanging 'round, but I should 'splain that I'm not drunk. I mean, look at me now! Shober as a freshwater fish! Sure I like to drown my sorrowsh in some good brew now and then, but you can't inebriate a jinyu! Might as well try to drown a fish! No, the brewsh make me shleepy, and when I shleep, I have vishions of the future. The shtronger the brew, the more potent my dreamsh! If you bring me a drink, I'll owe you one.", ["objectivesText"] = "Bring 5 Pandaren Plum Wine to Jogu the Drunk . Pandaren Plum Wine can be purchased from most bartenders in Pandaria. Progress: What do you mean I talk like I'm drunk? Thish ish how I shpeak!", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 81415, 84101 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[31322] = { ["id"] = 31322, ["name"] = "Buy A Fish A Keg?", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 31322 }, ["description"] = "My dreams grow dim recently, <race>. I need something powerful to kick myshelf back into gear! I heard there'sh a delishush drink that folksh are making nowadays. It'sh called Jade Witch Brew . I'd sure like to taste some.", ["objectivesText"] = "Bring 10 Jade Witch Brew to Jogu the Drunk . Jade Witch Brew can be made using the cooking profession. Progress: Any luck?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 74845, 74846, 74847, 75026, 75037 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[31323] = { ["id"] = 31323, ["name"] = "Buy A Fish A Brewery?", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 31323 }, ["description"] = "All right, <name>, in order to continue my vishions, I must now have my own brewery. ... Just kidding! You should have sheen your own face! Hilarioush... hic! Anyway, I heard of a new drink that is unlike any other, and I would like a tashte. Have you heard of the Mad Brewer'sh Breakfasht? If you can bring me some of thish shtuff, you will be my friend for life.", ["objectivesText"] = "Bring 20 Mad Brewer's Breakfast to Jogu the Drunk . Mad Brewer's Breakfasts can be made using the cooking profession. Progress: Have you tried it?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 74643, 74661, 74841, 74853, 75038, 79267, 86425, 87707, 90735 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[31324] = { ["id"] = 31324, ["name"] = "Family Secrets", ["level"] = 87, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5963, ["storyline"] = { 31324 }, ["description"] = "Our secret recipes! I was gathering them up. But then... hozen? <Auntie looks very confused.> How is Gao to brew anything? He needs those recipes or disaster is sure to strike!", ["objectivesText"] = "Collect 5 Stormstout Secrets . Progress: Well, hello!", ["rewardGold"] = 408000, ["rewardXP"] = 258000, ["rewardItems"] = { 80866, 86431, 87310, 87311, 87312, 87313, 87314 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5963 } }, ["questType"] = "dungeon" },
[31325] = { ["id"] = 31325, ["name"] = "A Very Nice Necklace", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 31325 }, ["description"] = "The beautiful necklace is only partly smudged by dirty hozen hands. There's only one person in the Valley who would own such a beautiful piece of jewelry.", ["objectivesText"] = "Bring the necklace to Tina Mudclaw at Haohan's House or Halfhill Market in the Valley of the Four Winds . Provided item:", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 86433 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard", ["startItems"] = { 86433 } },
[31326] = { ["id"] = 31326, ["name"] = "Tina's Tasteful Tiara", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 31326 }, ["description"] = "It's a dazzling diamond tiara. Who in the valley would be wealthy enough to own such a piece of jewelry? Whoever it is, they might be willing to give a nice reward.", ["objectivesText"] = "Bring the Tasteful Tiara to Tina Mudclaw at Haohan's House or Halfhill Market in the Valley of the Four Winds . Provided item:", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 86434 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard", ["startItems"] = { 86434 } },
[31327] = { ["id"] = 31327, ["name"] = "Trouble Brewing", ["level"] = 87, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5963, ["storyline"] = { 31327 }, ["series"] = { 30075, 30078, 30085 }, ["description"] = "With the brewery infested by hozen and... and who knows what else, I'm sure that the brewers are in trouble. Would you mind helping me find out what's going on, my friend?", ["objectivesText"] = "Kill Yan-Zhu the Uncasked .", ["rewardGold"] = 408000, ["rewardXP"] = 258000, ["rewardItems"] = { 87301, 87302, 87303, 87304, 87305, 87306, 87307, 87308, 87309, 88578 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5963 } }, ["questType"] = "dungeon" },
[31328] = { ["id"] = 31328, ["name"] = "An Exquisite Earring", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 31328 }, ["description"] = "You unhook the earring off the furry creature's ear. It looks like he was having some fun wearing the dangly hoop. TOO much fun. Perhaps the owner of this dainty bauble would like to see it returned. You don't have to tell her where you found it... or who was wearing it.", ["objectivesText"] = "Bring the Exquisite Earring to Tina Mudclaw at Haohan's House or Halfhill Market in the Valley of the Four Winds . Provided item:", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 86435, 86436 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard", ["startItems"] = { 86435 } },
[31329] = { ["id"] = 31329, ["name"] = "A Beautiful Brooch", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 31329 }, ["description"] = "It is a very old, antique brooch with very detailed molding and filigree worked into the edges. It looks very valuable. There's only one person who keeps losing jewelry to furry hooligans, and she would probably want to see this heirloom returned.", ["objectivesText"] = "Bring the Beautiful Brooch to Tina Mudclaw at Haohan's House or Halfhill Market in the Valley of the Four Winds . Provided item:", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 86433, 86434, 86435, 86436 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard", ["startItems"] = { 86436 } },
[31331] = { ["id"] = 31331, ["name"] = "Figuring out how to make quests", ["level"] = 83, ["requiredLevel"] = 81, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["storyline"] = { 31331 }, ["description"] = "Whee! You get to make a breadcrumb quest! Now figure out what to do next.", ["objectivesText"] = "Make a breadcrumb quest.", ["rewardGold"] = 258000, ["rewardXP"] = 65850, ["rewardItems"] = { 80689, 87286 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[31332] = { ["id"] = 31332, ["name"] = "Lesson 1: Sliced Peaches", ["level"] = 90, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 4, ["storyline"] = { 31332 }, ["description"] = "I'm excited to start my training. We start with sliced peaches , right?", ["objectivesText"] = "Obtain a 5 Pandaren Peaches for Nomi 's cooking lesson. Progress: I really want to be a chef, but the other kids already started a couple of months ago. There's no way I can catch up without your help.", ["rewardGold"] = 11400, ["rewardXP"] = 23600, ["rewardItems"] = { 74660, 86057, 86425 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
