[31334] = { ["id"] = 31334, ["name"] = "Lesson 3: Toasted Fish Jerky", ["level"] = 90, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 4, ["storyline"] = { 31334 }, ["description"] = "Cooking is harder than I thought. It's so easy to burn things.", ["objectivesText"] = "Obtain 5 Golden Carp for Nomi 's Lesson. Progress: I hope I don't burn myself. Eep.", ["rewardGold"] = 11400, ["rewardXP"] = 23600, ["rewardItems"] = { 74866, 81402, 86425 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[31335] = { ["id"] = 31335, ["name"] = "Lesson 4: Dried Needle Mushrooms", ["level"] = 90, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 4, ["storyline"] = { 31335 }, ["description"] = "I'm not very fond of mushrooms... but I'll do my best to learn.", ["objectivesText"] = "Obtain 5 Needle Mushrooms for Nomi 's Lesson. Progress: Ick.", ["rewardGold"] = 11400, ["rewardXP"] = 23600, ["rewardItems"] = { 81404, 85583, 86425 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[31336] = { ["id"] = 31336, ["name"] = "Lesson 5: Pounded Rice Cake", ["level"] = 90, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 4, ["storyline"] = { 31336 }, ["description"] = "I love rice cakes. I'll do my best to make good ones!", ["objectivesText"] = "Obtain 5 Rice for Nomi 's Lesson. Progress: I can't wait to see how they turn out!", ["rewardGold"] = 11400, ["rewardXP"] = 23600, ["rewardItems"] = { 74851, 81400, 86425 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[31337] = { ["id"] = 31337, ["name"] = "A Token of Appreciation", ["level"] = 90, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 4, ["storyline"] = { 31337 }, ["description"] = "Thanks for checking to make sure I'm doing well! I've been able to help out the Ironpaws today, and they said I could give this to you.", ["objectivesText"] = "Receive Nomi 's gift.", ["rewardItems"] = { 74646, 74648, 74656, 75016, 75038, 86425, 90735 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[31338] = { ["id"] = 31338, ["name"] = "Lost Sheepie", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 31338 }, ["description"] = "Chee Chee 's prize sheep, Sheepie , is missing! That bad sheep is always wandering off the farm. Stupid sheep! I looked everywhere and couldn't find him. Can you help me, <race>?", ["objectivesText"] = "Find Sheepie and return him to Chee Chee . Progress: Did you find my Sheepie ? Oh, I was so worried.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 86446 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[31339] = { ["id"] = 31339, ["name"] = "Lost Sheepie... Again", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 31339 }, ["description"] = "That stupid sheep! He wandered off again! Can you find him for me again?", ["objectivesText"] = "Find Sheepie and bring him back to Chee Chee . Progress: Oh, poor Sheepie . He's probably so scared and alone...", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 86446 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[31340] = { ["id"] = 31340, ["name"] = "Oh Sheepie...", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 31340 }, ["series"] = { 31341 }, ["description"] = "Sigh... you guessed it... Sheepie is gone... AGAIN. Stupid sheep! Gives me so much trouble! I hate to ask you again, but I promise this will be the last time. Can you find him for me?", ["objectivesText"] = "Find Sheepie . Progress: Where's Sheepie ?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 85275 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[31341] = { ["id"] = 31341, ["name"] = "A Wolf In Sheep's Clothing", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 31341 }, ["series"] = { 31340 }, ["description"] = "AAAIIIIEEUUGGHHHH!!!! This is the last straw! Those stupid hozen on the mountain killed my SHEEPIE! I know exactly who did this, and it is time for REVENGE. If you are willing to help me, take this old sheepskin . Use it to disguise yourself anywhere on the mountain to the north, wait for that little dooker Krungko to come out of hiding, and then break his bones!", ["objectivesText"] = "Use the old sheepskin anywhere in the Skyrange or Kunzen Village, then kill Krungko.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 86465 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[31342] = { ["id"] = 31342, ["name"] = "The Path to Respect Lies in Violence", ["level"] = 89, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5918, ["storyline"] = { 31342 }, ["description"] = "You have proven yourself in battle. Still, if you would aid us further, I must ask something else of you. The Sha of Violence awaits beyond within the Sealed Chambers. Destroy it if you would earn my respect.", ["objectivesText"] = "Kill the Sha of Violence .", ["rewardGold"] = 440000, ["rewardXP"] = 392000, ["rewardItems"] = { 87324, 87325, 87326, 87327, 87328, 87329, 87330, 87331, 87332 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5918 } }, ["questType"] = "dungeon" },
[31356] = { ["id"] = 31356, ["name"] = "Deep Doubts, Deep Wisdom", ["level"] = 87, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5956, ["storyline"] = { 31356 }, ["description"] = "There is an ancient pandaren saying that states, \"With deep doubts comes deep wisdom.\" The Sha of Doubt has infested the Heart of Jade within the temple. It must be destroyed. I dare say that you are about to become all the wiser, <class>.", ["objectivesText"] = "Kill the Sha of Doubt . Progress: The Sha of Doubt must be destroyed, <name>, or we are all lost.", ["rewardGold"] = 408000, ["rewardXP"] = 258000, ["rewardItems"] = { 87283, 87284, 87285, 87286, 87287, 87288, 87289, 87290, 87291 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5956 } }, ["questType"] = "dungeon" },
[31357] = { ["id"] = 31357, ["name"] = "Relics of the Four Kings", ["level"] = 89, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6182, ["storyline"] = { 31357 }, ["description"] = "The mogu have reawakened and are a threat to all of Pandaria. They are on the cusp of becoming even more dangerous. There are four great mogu kings of legend: Zian of the Endless Shadow, Meng the Demented, Qiang the Merciless, and Subetai the Swift. Four artifacts of these kings are secreted away in the Vault of Kings Past, below. You must retrieve these relics before the mogu discover them and become unstoppable.", ["objectivesText"] = "Collect the Lantern of the Sorcerer King , Mad King Meng's Balance , Qiang's \"The Science of War\", and Subetai's Bow of the Swift . Progress: We must retrieve the lantern, balance, scroll, and bow before Xin and his clans uncover them.", ["rewardGold"] = 440000, ["rewardXP"] = 392000, ["rewardItems"] = { 86476, 86477, 86478, 86479, 87342, 87343, 87344, 87345, 87346, 87347, 87348, 87349, 87350 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6182 } }, ["questType"] = "dungeon" },
[31363] = { ["id"] = 31363, ["name"] = "Lighting the Way", ["level"] = 90, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5976, ["storyline"] = { 31363 }, ["description"] = "We need reinforcements! Someone has to fight through and light the signal flame. It's all up to you, <class>. No pressure or anything.", ["objectivesText"] = "Light the Signal Flame.", ["rewardGold"] = 456000, ["rewardXP"] = 471000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5976 } }, ["questType"] = "dungeon" },
[31368] = { ["id"] = 31368, ["name"] = "The Lorewalkers", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 31368 }, ["description"] = "So you are interested in learning more of the lore of this land? Very well! You should speak to Lorewalker Cho at the Seat of Knowledge. He can be found in the room above the entrance to the Mogu'shan Palace. Speak with Mishi for a ride.", ["objectivesText"] = "Speak to Lorewalker Cho at the Seat of Knowledge in the Vale of Eternal Blossoms . Progress: Welcome, traveler.", ["rewardGold"] = 11400, ["rewardXP"] = 23600, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[31369] = { ["id"] = 31369, ["name"] = "The Anglers", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 31369 }, ["description"] = "If you want to explore all the secrets of the deep ocean, and catch some big fish, speak to Haito at the Anglers Wharf in Krasarang Wilds . I'm sure he'd love to show you a thing or two about reeling!", ["objectivesText"] = "Speak to Fisherman Haito at the Anglers Wharf in the Krasarang Wilds .", ["rewardGold"] = 11400, ["rewardXP"] = 23600, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[31372] = { ["id"] = 31372, ["name"] = "The Tillers", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 31372 }, ["description"] = "The Tillers do their business at Halfhill in the Valley of the Four Winds . If you're interested in getting started, I hear there's a new farmer in town by the name of Farmer Yoon . I betcha he'll be looking for help.", ["objectivesText"] = "Speak to Farmer Yoon at Sunsong Ranch in the Valley of the Four Winds .", ["rewardGold"] = 11400, ["rewardXP"] = 23600, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[31373] = { ["id"] = 31373, ["name"] = "The Order of the Cloud Serpent", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 31373 }, ["description"] = "The Order of the Cloud Serpent is always searching for talented riders. If you wish to follow our way, you should speak to Instructor Skythorn at The Arboretum in the Jade Forest . I wish you luck, <race>.", ["objectivesText"] = "Speak to Instructor Skythorn at The Arboretum in The Jade Forest .", ["rewardGold"] = 11400, ["rewardXP"] = 23600, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
