[31378] = { ["id"] = 31378, ["name"] = "Challenge At The Temple of the Red Crane", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 31378 }, ["description"] = "The Temple of the Red Crane still reels from the aftermath of the sha's presence, and has only recently gathered to rebuild and retrain its warriors. If you wish to help at the temple, speak to Thelonius at the Cradle of Chi-Ji.", ["objectivesText"] = "Speak to Thelonius at the Cradle of Chi-Ji in the Krasarang Wilds .", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
