[31380] = { ["id"] = 31380, ["name"] = "Trial At The Temple of the White Tiger", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 31380 }, ["description"] = "Xuen , the great Celestial of the North, seeks the greatest champions in the land. Today, he holds trials of battle at his temple in Kun-Lai Summit . If you wish to test yourself against skilled fighters from all across Pandaria, then go to him and enter the challenger's ring!", ["objectivesText"] = "Speak to Xuen at the Temple of the White Tiger in Kun-Lai Summit .", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
