[31382] = { ["id"] = 31382, ["name"] = "Defense At Niuzao Temple", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 31382 }, ["description"] = "Niuzao Temple, far to the west, is under attack by the mantid. The great Celestial holds them back for now, but he cannot stand alone forever. Go and help the defenders, <class>. The Temple must not fall!", ["objectivesText"] = "Speak to Ogo the Elder at Niuzao Temple in the Townlong Steppes .", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
