[31384] = { ["id"] = 31384, ["name"] = "The Golden Lotus", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 31384 }, ["description"] = "The Golden Lotus have guarded the Vale for centuries, keeping it safe and hidden from harm. Recent events have unleashed terrible horrors upon our sacred vale, but allies of the Golden Lotus still stand against them, attempting to bring peace. If you wish to help, you had best join them at the Setting Sun Garrison.", ["objectivesText"] = "Speak to Anji Autumnlight at the Setting Sun Garrison in the Vale of Eternal Blossoms .", ["rewardGold"] = 11400, ["rewardXP"] = 23600, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[31386] = { ["id"] = 31386, ["name"] = "The Shado-Pan Offensive", ["level"] = 89, ["requiredLevel"] = 88, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 31386 }, ["description"] = "We Shado-Pan have amassed our forces for the first time in many ages. The Sha of Hatred has escaped beyond the Serpent's Spine, and it is our sacred duty to imprison it once more. However, our warriors are great, but our numbers too few. Help from a capable <class> may not be turned away. If you wish to join the offensive, speak to Taran Zhu in the Townlong Steppes .", ["objectivesText"] = "Speak to Taran Zhu at Longying Outpost in the Townlong Steppes .", ["rewardGold"] = 11000, ["rewardXP"] = 19600, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[31387] = { ["id"] = 31387, ["name"] = "Understanding The Shado-Pan", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["storyline"] = { 31387 }, ["description"] = "The Shado-Pan rank among Pandaria's oldest defenders. For years we train in our snow-capped monastery high in the Kun-Lai Summit, perfecting the martial secrets passed down by our ancestors. Our numbers may seem few, but a single Shado-Pan can be deadlier than a hundred trained soldiers. To join the Shado-Pan order is a long journey full of hardship. If this is the path you seek, then you must first prove your worth. There is urgent work to be done here. Help the Golden Lotus defend the Vale.", ["objectivesText"] = "Earn Revered standing with the Golden Lotus .", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[31388] = { ["id"] = 31388, ["name"] = "The Shado-Pan Offensive", ["level"] = 89, ["requiredLevel"] = 88, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 31388 }, ["description"] = "We Shado-Pan have amassed our forces for the first time in many ages. The Sha of Hatred has escaped beyond the Serpent's Spine, and it is our sacred duty to imprison it once more. However, our warriors are great, but our numbers too few. Help from a capable <class> may not be turned away. If you wish to join the offensive, speak to Taran Zhu in the Townlong Steppes .", ["objectivesText"] = "Speak to Taran Zhu at Longying Outpost in the Townlong Steppes .", ["rewardGold"] = 11000, ["rewardXP"] = 19600, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[31389] = { ["id"] = 31389, ["name"] = "Understanding The Shado-Pan", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["storyline"] = { 31389 }, ["description"] = "The Shado-Pan rank among Pandaria's oldest defenders. For years we train in our snow-capped monastery high in the Kun-Lai Summit, perfecting the martial secrets passed down by our ancestors. Our numbers may seem few, but a single Shado-Pan can be deadlier than a hundred trained soldiers. To join the Shado-Pan order is a long journey full of hardship. If this is the path you seek, then you must first prove your worth. There is urgent work to be done here. Help the Golden Lotus defend the Vale.", ["objectivesText"] = "Earn Revered standing with the Golden Lotus .", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[31390] = { ["id"] = 31390, ["name"] = "The Klaxxi", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 31390 }, ["description"] = "The Klaxxi are only rumored to exist, far beyond the wall in the Dread Wastes . Few have ventured into that territory, and none have returned to tell the tale. If you are set on finding these... Klaxxi... there is a small group of Shado-Pan manning the wall to the far southwest who may know more.", ["objectivesText"] = "Speak to Bowmistress Li at the Gate of the Setting Sun between the Vale of Eternal Blossoms and the Dread Wastes .", ["rewardGold"] = 11400, ["rewardXP"] = 23600, ["rewardItems"] = { 84055, 84056, 84057, 84058, 84059 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[31391] = { ["id"] = 31391, ["name"] = "The Klaxxi", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 31391 }, ["description"] = "The Klaxxi are only rumored to exist, far beyond the wall in the Dread Wastes . Few have ventured into that territory, and none have returned to tell the tale. If you are set on finding these... Klaxxi... there is a small group of Shado-Pan manning the wall to the far southwest who may know more.", ["objectivesText"] = "Speak to Bowmistress Li at the Gate of the Setting Sun between the Vale of Eternal Blossoms and the Dread Wastes .", ["rewardGold"] = 11400, ["rewardXP"] = 23600, ["rewardItems"] = { 84055, 84056, 84057, 84058, 84059 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[31392] = { ["id"] = 31392, ["name"] = "Temple of the White Tiger", ["level"] = 87, ["requiredLevel"] = 87, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["storyline"] = { 31392 }, ["series"] = { 31394, 31512 }, ["description"] = "Have you heard the news, traveller? There's been at attack at one of our most sacred places, the Vale of Eternal Blossoms! Even now, there's a human prince within the White Tiger Temple arguing that you and the other races from beyond the mists should be allowed within. The temple is in the northeast of Kun-Lai. Maybe you can convince the White Tiger to allow you inside? I only hope the Vale has not been utterly destroyed...", ["objectivesText"] = "Speak to Anduin Wrynn at the Temple of the White Tiger in Kun-Lai Summit .", ["rewardGold"] = 77000, ["rewardXP"] = 97000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard" },
[31393] = { ["id"] = 31393, ["name"] = "Temple of the White Tiger", ["level"] = 87, ["requiredLevel"] = 87, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["storyline"] = { 31393 }, ["series"] = { 31395, 31511 }, ["description"] = "Have you heard the news, traveller? There's been at attack at one of our most sacred places, the Vale of Eternal Blossoms! Even now, there's a human prince within the White Tiger Temple arguing that you and the other races from beyond the mists should be allowed within. The temple is in the northeast of Kun-Lai. Maybe you can convince the White Tiger to allow you inside? I only hope the Vale has not been utterly destroyed...", ["objectivesText"] = "Speak to Dezco at the Temple of the White Tiger in Kun-Lai Summit .", ["rewardGold"] = 77000, ["rewardXP"] = 97000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard" },
[31439] = { ["id"] = 31439, ["name"] = "Dropping Our Signal", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6138, ["storyline"] = { 31439 }, ["series"] = { 31441 }, ["description"] = "The beacon in Amberglow Hollow seems to have been tampered with. Right before the signal cut out the Klaxxi'va picked up a signal for another paragon nearby. They believe he is hidden in that wretched little swamp, Duskroot Fen. I will meet you in the fen to set up a temporary beacon until I can get Amberglow operational again. You will wake the paragon and then you will help me.", ["objectivesText"] = "Awaken the paragon in Duskroot Fen.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 83062, 87202 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard" },
[31441] = { ["id"] = 31441, ["name"] = "Corruption Runs Deep", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6138, ["storyline"] = { 31441 }, ["series"] = { 31439 }, ["description"] = "Today you learn that no one can be trusted in times of war, Wakener. Even those closest to the Klaxxi are susceptible to corruption. Who knows how long this traitor has been corrupted. He must be destroyed! You appear confused. Do you not see the traitor in our midst? Allow me to adjust your vision.", ["objectivesText"] = "Defeat the traitor in the Duskroot Fen.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard" },
[31443] = { ["id"] = 31443, ["name"] = "Flying Tiger Gourami", ["requiredLevel"] = 85, ["faction"] = "both", ["requiredProfessions"] = { "fishing" }, ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 31443 }, ["description"] = "You've caught a unique fish... with wings. Perhaps it deserves the expert opinion of Nat Pagle in Anglers Wharf.", ["objectivesText"] = "Bring the Flying Tiger Gourami to Nat Pagle at Anglers Wharf. Progress: Flying fish?", ["rewardGold"] = 8000, ["rewardItems"] = { 86542, 86544, 86545 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["startItems"] = { 86542 } },
[31444] = { ["id"] = 31444, ["name"] = "Spinefish Alpha", ["requiredLevel"] = 85, ["faction"] = "both", ["requiredProfessions"] = { "fishing" }, ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5785, ["storyline"] = { 31444 }, ["description"] = "You have fished up something special. It looks pretty aggressive. Maybe Nat Pagle at the Anglers Wharf might know more about it?", ["objectivesText"] = "Bring the Spinefish Alpha to Nat Pagle at Anglers Wharf. Progress: Strange fish?", ["rewardGold"] = 8000, ["rewardItems"] = { 86542, 86544, 86545 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["startItems"] = { 86544 } },
[31445] = { ["id"] = 31445, ["name"] = "zzOld", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["storyline"] = { 31445 }, ["description"] = "If you want to explore all the secrets of the deep ocean, and catch some big fish, speak to my brother Haito at the Anglers Wharf in Krasarang Wilds. I'm sure he'd love to show you a thing or two about reeling!", ["objectivesText"] = "Speak to Fisherman Haito at the Anglers Wharf in the Krasarang Wilds.", ["rewardGold"] = 100, ["rewardXP"] = 450, ["rewardItems"] = { 35745 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[31446] = { ["id"] = 31446, ["name"] = "Mimic Octopus", ["requiredLevel"] = 85, ["faction"] = "both", ["requiredProfessions"] = { "fishing" }, ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5785, ["storyline"] = { 31446 }, ["description"] = "You aren't sure how, but you've caught an extraordinary cephalopod. Nat Pagle at Anglers Wharf would be very interested to see it.", ["objectivesText"] = "Bring the Mimic Octopus to Nat Pagle at Anglers Wharf. Progress: Camouflage octopus?", ["rewardGold"] = 8000, ["rewardItems"] = { 86542, 86544, 86545, 86596 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["startItems"] = { 86545 } },
[31447] = { ["id"] = 31447, ["name"] = "An End to the Suffering", ["level"] = 43, ["requiredLevel"] = 38, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6066, ["storyline"] = { 31447 }, ["description"] = "The key to lifting the curse of this place rests in the final death of Darkmaster Gandling . Do it, $p, and make him suffer!", ["objectivesText"] = "Kill Darkmaster Gandling .", ["rewardGold"] = 24000, ["rewardXP"] = 10100, ["rewardItems"] = { 39789, 39825, 39858, 39893, 87379, 87380, 87381, 87382, 87383, 87384, 87385, 87386, 87387 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6066 } }, ["questType"] = "dungeon" },
