[31450] = { ["id"] = 31450, ["name"] = "A New Fate", ["level"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5736, ["mapID"] = 85, ["storyline"] = { 31450 }, ["series"] = { 29800 }, ["description"] = "These new allies have shed light on a great and important truth: it is not just Shen-zin Su that is ailing, but all of the land beyond the clouds. The world needs healing, and I think that you should be the ones to heal it. I would like you, Ji, and Aysa to leave and bring your strength and wisdom to the world. These Alliance and Horde have different ideals, but at the core of both lies noble intent. I will leave the choice of who you wish to accompany to you.", ["objectivesText"] = "Speak to the Spirit of Master Shang Xi , and choose whether you leave with the Alliance or the Horde.", ["rewardGold"] = 85, ["rewardXP"] = 210, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5736 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 85, ["questLines"] = { { ["id"] = 573, ["name"] = "The Wandering Isle", ["orderIndex"] = 71, ["flags"] = 0 } } },
[31451] = { ["id"] = 31451, ["name"] = "The Missing Merchant", ["level"] = 87, ["requiredLevel"] = 87, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["storyline"] = { 31451 }, ["description"] = "Usually, Merchant Shi comes through Kun-Lai Summit to trade with the Jinyu and Grummle. We've heard word that he hadn't been seen at Binan, and we haven't seen him here... I'm worried something has happened to him. Can you go to the Inkgill Mere and see if he's there?", ["objectivesText"] = "Speak with Merchant Shi at Inkgill Mere in Kun-Lai Summit .", ["rewardGold"] = 10200, ["rewardXP"] = 12900, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard" },
[31452] = { ["id"] = 31452, ["name"] = "The Missing Merchant", ["level"] = 87, ["requiredLevel"] = 87, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["storyline"] = { 31452 }, ["description"] = "Usually, Merchant Shi comes through Kun-Lai Summit to trade with the Jinyu and Grummle. We've heard word that he hadn't been seen at Binan, and we haven't seen him here... I'm worried something has happened to him. Can you go to the Inkgill Mere and see if he's there?", ["objectivesText"] = "Speak with Merchant Shi at Inkgill Mere in Kun-Lai Summit .", ["rewardGold"] = 10200, ["rewardXP"] = 12900, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard" },
[31454] = { ["id"] = 31454, ["name"] = "A Legend in the Making", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6006, ["storyline"] = { 31454 }, ["series"] = { 31488, 31489 }, ["description"] = "Our world finds itself at a crossroads. The next few months will shape everything to come - presuming we are to have a future at all. Ah! But I am getting ahead of myself. Let me back up. Come, share a drink with me. Let's talk about the future of Azeroth.", ["objectivesText"] = "Share a drink with Wrathion . He's buying. Progress: Is everything clear?", ["rewardGold"] = 28500, ["rewardXP"] = 59000, ["rewardItems"] = { 72095, 76132, 87208, 87209, 87262, 94593, 94594 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6006 } }, ["questType"] = "standard" },
[31456] = { ["id"] = 31456, ["name"] = "Muskpaw Ranch", ["level"] = 87, ["requiredLevel"] = 87, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["storyline"] = { 31456 }, ["series"] = { 30488, 30491, 30492, 30808, 31457 }, ["description"] = "There's another Pandaren settlement out here, Muskpaw Ranch. I don't know if they're alright, what with everything that's been going on with the Yaungol invasion. You've been so helpful - you should go check up on them, friend!", ["objectivesText"] = "Travel to Muskpaw Ranch in Kun-Lai Summit and speak with Lao Muskpaw .", ["rewardGold"] = 10200, ["rewardXP"] = 12900, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard" },
[31457] = { ["id"] = 31457, ["name"] = "Muskpaw Ranch", ["level"] = 87, ["requiredLevel"] = 87, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["storyline"] = { 31457 }, ["series"] = { 30488, 30491, 30492, 30808, 31456 }, ["description"] = "There's another Pandaren settlement out here, Muskpaw Ranch. I don't know if they're alright, what with everything that's been going on with the Yaungol invasion. You've been so helpful - you should go check up on them, friend!", ["objectivesText"] = "Travel to Muskpaw Ranch in Kun-Lai Summit and speak with Lao Muskpaw .", ["rewardGold"] = 10200, ["rewardXP"] = 12900, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard" },
[31458] = { ["id"] = 31458, ["name"] = "Damage Control", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6138, ["storyline"] = { 31458 }, ["description"] = "Kor'ik has been sending signals to the empress for weeks. Everything the Klaxxi have done, the empress knows about. That stops now! Kypari Ik will be the first to receive news of Kor'ik's demise. It would benefit us to make sure that message does not make it to the empress. Destroying the whisperers and beacon there will buy us enough time to come up with a plan before the empress can act.", ["objectivesText"] = "Destroy 5 Ik'thik Whisperers and deactivate the Kypari Ik Beacon. Progress: Information is power, Wakener. Those with the most information always have the most power.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 87269 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard" },
[31459] = { ["id"] = 31459, ["name"] = "Cho's Missive", ["level"] = 87, ["requiredLevel"] = 87, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["storyline"] = { 31459 }, ["series"] = { 30601, 30999, 31460 }, ["description"] = "One of those grummles came by and said that Lorewalker Cho sent for you. You should go ahead and meet up with him, he might have something important to say. The grummel said he's at Onekeg, to the north.", ["objectivesText"] = "Speak with Lorewalker Cho at Onekeg in Kun-Lai Summit .", ["rewardGold"] = 10200, ["rewardXP"] = 12900, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard" },
[31460] = { ["id"] = 31460, ["name"] = "Cho's Missive", ["level"] = 87, ["requiredLevel"] = 87, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["storyline"] = { 31460 }, ["series"] = { 30601, 30999, 31459 }, ["description"] = "One of those adorable little grummles came by and said that Lorewalker Cho sent for you. You should meet up with him! The grummel said he's at Onekeg, to the north.", ["objectivesText"] = "Speak with Lorewalker Cho at Onekeg in Kun-Lai Summit .", ["rewardGold"] = 10200, ["rewardXP"] = 12900, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard" },
[31467] = { ["id"] = 31467, ["name"] = "Strong as a Tiger", ["level"] = 90, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 31467 }, ["description"] = "With the grill, you can transform those raw tiger steaks into food that makes you stronger. Learn the recipe for charbroiled tiger steaks from me. Show me what you can do.", ["objectivesText"] = "Train the recipe for Charbroiled Tiger Steak from the Master of the Grill, then give him 5 Charbroiled Tiger Steaks . Progress: Learn the recipe from me and demonstrate what you have learned.", ["rewardGold"] = 11400, ["rewardXP"] = 23600, ["rewardItems"] = { 74642 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[31468] = { ["id"] = 31468, ["name"] = "Trial of the Black Prince", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6006, ["storyline"] = { 31468 }, ["description"] = "I have on good authority that you are a champion among champions, but if you'll permit me this indulgence, I would like to test your mettle for myself. The mogu who assault the Vale of Eternal Blossoms, the mogu minions who inhabit Shan'ze Dao, and the sha-corrupted mantid swarming the Dread Wastes... these may provide an adequate challenge for one of your stature. Prove yourself to me. No rush - I expect this to take you some time.", ["objectivesText"] = "Earn an Honored Reputation with the Black Prince . Level 90 mogu and mantid in the Vale of Eternal Blossoms, Townlong Steppes and the Dread Wastes will earn reputation.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 64399, 64401, 64402, 72095, 76091, 76132, 86226, 86227, 86321, 86328, 86331, 86335, 86386, 86387, 86391, 86864, 86865, 86879, 86886, 86889, 86893, 86905, 86906, 86910, 86988, 86990, 87156, 87164, 87166, 87168, 87170, 87173, 87176, 87208, 87209, 87210, 87212, 87261, 87262, 89873, 89881, 89882, 94593, 94594 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6006 } }, ["questType"] = "standard" },
[31470] = { ["id"] = 31470, ["name"] = "Way of the Wok", ["level"] = 90, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 31470 }, ["description"] = "If you wish to make dishes that enhance agility, you should bring some carrots and rice to the Master of the Wok. The virmen around here tend to carry a lot of carrots around. You can also grow your own, if you have a farm.", ["objectivesText"] = "Bring 5 Juicycrunch Carrots to the Master of the Wok. Progress: Hello, young chef. Do you wish to learn the Way of the Wok ?", ["rewardGold"] = 11400, ["rewardXP"] = 23600, ["rewardItems"] = { 74643, 74644, 74645, 74646, 74647, 74649, 74651, 74652, 74655, 74656, 74833, 74839, 74841, 74844, 74845, 74856, 74857, 75026, 75038, 87707 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[31471] = { ["id"] = 31471, ["name"] = "Agile as a Tiger", ["level"] = 90, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 31471 }, ["description"] = "To cook with the wok, you need to be nimble. Your first lesson is sauteed carrots .", ["objectivesText"] = "Train the recipe for Sauteed Carrots from the Master of the Wok, then give her 5 Sauteed Carrots . Progress: Let me teach you how to make sauteed carrots .", ["rewardGold"] = 11400, ["rewardXP"] = 23600, ["rewardItems"] = { 74643 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[31472] = { ["id"] = 31472, ["name"] = "Way of the Pot", ["level"] = 90, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 31472 }, ["description"] = "The cuisine of the Way of the Pot help expand your intellect. Bring some jade lungfish to the Master of the Pot and she will teach you. You can fish for jade lungfish in the Jade Forest.", ["objectivesText"] = "Bring 5 Jade Lungfish to the Master of the Pot. Progress: Want to learn the recipe for swirling mist soup? Bring me some jade lungfish .", ["rewardGold"] = 11400, ["rewardXP"] = 23600, ["rewardItems"] = { 74643, 74644, 74645, 74646, 74647, 74649, 74651, 74652, 74655, 74656, 74833, 74839, 74841, 74845, 74856, 74857, 75026, 75038, 87707, 87721 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[31474] = { ["id"] = 31474, ["name"] = "The Soup of Contemplation", ["level"] = 90, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 31474 }, ["description"] = "Watching over the pot, you get a lot of time to think. Let me show you how to make swirling mist soup and you'll know what I mean.", ["objectivesText"] = "Train the recipe for Swirling Mist Soup from the Master of the Pot, then give her 5 Swirling Mist Soup . Progress: If you want to learn the Way of the Pot, you have to start with swirling mist soup .", ["rewardGold"] = 11400, ["rewardXP"] = 23600, ["rewardItems"] = { 74644 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[31475] = { ["id"] = 31475, ["name"] = "Way of the Steamer", ["level"] = 90, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 31475 }, ["description"] = "A great meal can lift your spirits, and none more so than food from the Way of the Steamer . Bring the Master some giant mantis shrimp and he will show you. You can fish for giant mantis shrimp in the ocean.", ["objectivesText"] = "Bring 5 Giant Mantis Shrimp to the Master of the Steamer. Progress: If you want to learn the Way of the Steamer , you'll need some shrimp.", ["rewardGold"] = 11400, ["rewardXP"] = 23600, ["rewardItems"] = { 74643, 74644, 74645, 74646, 74647, 74649, 74651, 74652, 74655, 74656, 74833, 74839, 74841, 74845, 74856, 74857, 74864, 75026, 75038, 87707 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[31476] = { ["id"] = 31476, ["name"] = "The Spirit of Cooking", ["level"] = 90, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 31476 }, ["description"] = "When I cook with steam, I infuse the food with my love. Let me teach you the recipe for shrimp dumplings .", ["objectivesText"] = "Train the recipe for Shrimp Dumplings from the Master of the Steamer, then give him 5 Shrimp Dumplings . Progress: Let me teach you how to make shrimp dumplings .", ["rewardGold"] = 11400, ["rewardXP"] = 23600, ["rewardItems"] = { 74651 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[31477] = { ["id"] = 31477, ["name"] = "Endurance", ["level"] = 90, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 31477 }, ["description"] = "They say that the crane appointed sentry by its flock stands guard with a stone in its beak, so that, should it fall asleep, the stone drops and it awakens. To be skilled with the oven, you need to have endurance and patience. Learn the recipe for wildfowl roast and show me that you understand.", ["objectivesText"] = "Train the recipe for Wildfowl Roast from the Master of the Oven, then give him 5 Wildfowl Roast . Progress: Learn the recipe for wildfowl roast from me and let's see what you can do.", ["rewardGold"] = 11400, ["rewardXP"] = 23600, ["rewardItems"] = { 74654 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[31479] = { ["id"] = 31479, ["name"] = "Way of the Brew", ["level"] = 90, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 31479 }, ["description"] = "The Pandaren Way of the Brew produces... Well, I'll let the Master of the Brew explain it. Bring him some ginseng and he will show you the way.", ["objectivesText"] = "Bring 1 Ginseng to the Master of the Brew. Ginseng can be bought from Sungshin Ironpaw . Progress: You'd like to learn the Way of the Brew ?", ["rewardGold"] = 11400, ["rewardXP"] = 23600, ["rewardItems"] = { 74643, 74644, 74645, 74646, 74647, 74649, 74651, 74652, 74655, 74656, 74833, 74839, 74841, 74845, 74856, 74857, 75026, 75038 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[31480] = { ["id"] = 31480, ["name"] = "Have a Drink", ["level"] = 90, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 31480 }, ["description"] = "My siblings are so serious. I think life's too short to be so serious all the time. Let's have some tea together. Let me teach you how to make ginseng tea .", ["objectivesText"] = "Train the recipe for Ginseng Tea from the Master of the Brew, then give him 1 Ginseng Tea . Progress: Let me teach you how to make ginseng tea .", ["rewardGold"] = 11400, ["rewardXP"] = 23600, ["rewardItems"] = { 75026 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[31481] = { ["id"] = 31481, ["name"] = "Fear Itself", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6006, ["storyline"] = { 31481 }, ["description"] = "I've picked up a few motes of pandaren wisdom during my time here. I particularly enjoy this one: \"The timid feel fear before trouble starts; the cowards feel fear as trouble happens. The bravest among us feel fear only after the troubles have been taken care of.\" Is that true? Let's find out. The Sha of Fear has fled into the Terrace of Endless Spring. Pursue it there, defeat it, and rip out its spirit - presuming it has one. Your bravery will be handsomely rewarded.", ["objectivesText"] = "This item is part of Mists of Pandaria's legendary questline. To learn more, check out Wowhead's Guide . Defeat the Sha of Fear in the Terrace of Endless Spring and acquire the Chimera of Fear . Progress: Another bit of pandaren wisdom: \"Fear is not a criminal we must lock away. It is a teacher we must seek to understand.\" In facing our fears, we gain great strength. Have you faced your fears, <name>?", ["rewardGold"] = 342000, ["rewardXP"] = 353000, ["rewardItems"] = { 87210 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6006 } }, ["questType"] = "standard" },
[31482] = { ["id"] = 31482, ["name"] = "Breath of the Black Prince", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6006, ["storyline"] = { 31482 }, ["series"] = { 29744, 29745, 29747, 29748, 29749, 29751 }, ["description"] = "< Wrathion 's piercing red eyes fixate on you.> You are among a rare breed, <name>. You are just what I am looking for - an individual with the potential to shape events on a global scale. Come now, I promised you a reward, and you shall have it! East of this tavern is a series of stone steps leading up to a vista that the locals have named \"Mason's Folly.\" Meet me there.", ["objectivesText"] = "Go to the top of the stone steps at Mason's Folly and meet Wrathion there to accept your reward. Progress: I will meet you outside the tavern, at Mason's Folly.", ["rewardGold"] = 57000, ["rewardXP"] = 118000, ["rewardItems"] = { 86226, 86227, 86321, 86328, 86331, 86335, 86386, 86387, 86391, 86473, 86864, 86865, 86879, 86886, 86889, 86893, 86905, 86906, 86910, 86988, 86990, 87156, 87164, 87166, 87168, 87170, 87173, 87176, 89873, 89881, 89882 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6006 } }, ["questType"] = "standard" },
[31483] = { ["id"] = 31483, ["name"] = "Incoming...", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6006, ["storyline"] = { 31483 }, ["description"] = "The Pandaren campaign is only beginning! We turn our attention now to the ongoing conflict between the Alliance and the Horde. My contacts in Ravenholdt tell me that the Alliance 7th Legion and a considerable Horde invasion force are converging toward Pandaria's southern shores. Like it or not, Pandaria may soon become a battlefield. We are done for now, but I want you to contact me when your fleet arrives. Then... together we will spring into action!", ["objectivesText"] = "Contact Wrathion once your naval fleet makes landfall on the southern coast of Pandaria.", ["rewardXP"] = 5050, ["rewardItems"] = { 20494, 20495 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6006 } }, ["questType"] = "standard" },
[31486] = { ["id"] = 31486, ["name"] = "Everything I Know About Cooking", ["level"] = 90, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6142, ["storyline"] = { 31486 }, ["description"] = "I'm so glad you enjoy my food. Are you interested in the recipes? If so, you should learn them properly, from my teachers in Halfhill Market. Everything I know about the kitchen, I learned from them. Say, if you happen to pass through there, would you deliver this note to Sungshin Ironpaw for me? She was my favorite teacher, and I want her to know that I miss her.", ["objectivesText"] = "Deliver the Letter to Sungshin Ironpaw . She teaches in Halfhill Market. Progress: You have a letter for me?", ["rewardGold"] = 11400, ["rewardXP"] = 23600, ["rewardItems"] = { 86392 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6142 } }, ["questType"] = "standard" },
[31487] = { ["id"] = 31487, ["name"] = "Sonic Disruption", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6138, ["mapID"] = 422, ["storyline"] = { 31487 }, ["description"] = "Relying on sonic whispers to manipulate the kunchong was only the most primitive stage of my research, and yet the Empire seems to have adopted the practice wholly. The manipulators of the Shek'zeer are too impatient to form a proper bond with their kunchong. Their laziness will cost them dearly. Strike this tuning fork near the dread kunchong in the clutches - watch as they reel in confusion and lash out at their masters. Use this to your advantage and put them down.", ["objectivesText"] = "Kill 4 Dread Kunchong and 6 Shek'zeer Manipulators in the Clutches of Shek'zeer. The Sonic Disruption Fork will weaken and confuse the kunchong.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 79864, 80484, 87394, 87400, 87401, 87841, 88855, 89366 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3278 }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 5556, ["name"] = "Klaxxi Daily Quests", ["orderIndex"] = 11, ["flags"] = 0 } } },
[31488] = { ["id"] = 31488, ["name"] = "Stranger in a Strange Land", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5841, ["storyline"] = { 31488 }, ["series"] = { 31454, 31489 }, ["description"] = "Excuse me, <class>. Is your name <name>? A figure in a dark cloak asked that I give this to you. She was a traveler from beyond the mists, like yourself, but - well, I didn't trust her. The message comes from a tavern in the veiled stair. I'll give you the note but... you should watch your back if you venture up there!", ["objectivesText"] = "Seek out \"The Black Prince\" at the Tavern in the Mists in the Veiled Stair. Progress: So, my note found its way to you!", ["rewardGold"] = 57000, ["rewardXP"] = 118000, ["rewardItems"] = { 72095, 76132, 87208, 87209, 87261, 87262, 94593, 94594 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard" },
[31489] = { ["id"] = 31489, ["name"] = "Stranger in a Strange Land", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5842, ["storyline"] = { 31489 }, ["series"] = { 31454, 31488 }, ["description"] = "Excuse me, <class>. Is your name <name>? A figure in a dark cloak asked that I give this to you. She was a traveler from beyond the mists, like yourself, but - well, I didn't trust her. She mentioned the name \" Wrathion .\" Does that ring any bells for you? I'll give you the note but... you should watch your back if you're going to deal with these people.", ["objectivesText"] = "Seek out Wrathion at the Tavern in the Mists in the Veiled Stair. Progress: So, we meet again!", ["rewardGold"] = 57000, ["rewardXP"] = 118000, ["rewardItems"] = { 87262 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard" },
[31490] = { ["id"] = 31490, ["name"] = "Rank and File", ["level"] = 31, ["requiredLevel"] = 26, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6052, ["storyline"] = { 31490 }, ["description"] = "First things first; let's kill us some crusaders. And when I say kill the Scarlet Crusade, I mean wipe them out, root and branch, rank and file.", ["objectivesText"] = "Kill 50 members of the Scarlet Crusade within the Scarlet Halls . Progress: You know, I've been killing the ones that you can't see behind closed doors. But I need to maintain this disguise. So if you could just take care of all of the ones out there in the open, that'd be great.", ["rewardGold"] = 12000, ["rewardXP"] = 5080, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6052 } }, ["questType"] = "dungeon" },
[31492] = { ["id"] = 31492, ["name"] = "The Torch of Strength", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5841, ["storyline"] = { 31492 }, ["description"] = "Xuen has this challenge he says helps \"refine strength.\" I am starting to think the word \"strength\" means something different to him than the rest of us. Here, take this torch to the top of the gates of the temple. If you can get it there without the torch being extinguished, you pass the challenge. Whatever you do, do not try carrying the torch on a mount. It will blow out if you do. Trust me on that one.", ["objectivesText"] = "Carry the Torch of Strength to the gates of the Temple of the White Tiger without it extinguishing. Progress: Need another torch?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 40727, 43391, 76096, 86579, 86590, 87890, 88801, 94154 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3281 } },
[31493] = { ["id"] = 31493, ["name"] = "Just for Safekeeping, Of Course", ["level"] = 31, ["requiredLevel"] = 26, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6052, ["storyline"] = { 31493 }, ["description"] = "There is a book of great value to me here in the halls. Unfortunately, it's in the possession of Flameweaver Koegler. I've tried to get close to him before, but it's never quite worked out. You might have better luck. Just watch out -- I hear that he's gone well and truly insane. The Flameweaver plans to burn every tome they have in the library. He'll probably burn the Scarlet Halls down in the process.", ["objectivesText"] = "Collect the Codex of the Crusade . Progress: It's imperative that I get my hands on the codex.", ["rewardGold"] = 12000, ["rewardXP"] = 5080, ["rewardItems"] = { 87267, 87370, 87371, 87372, 87373, 87374, 87375, 87376, 87377, 87378 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6052 } }, ["questType"] = "dungeon" },
[31494] = { ["id"] = 31494, ["name"] = "Free From Her Clutches", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6138, ["mapID"] = 422, ["storyline"] = { 31494 }, ["description"] = "The Shek'zeer manipulators are corralling young kunchong into that clutch and exposing them to raw fear energies, twisting them and accelerating their growth. Disgusting! I will not allow it! Break open the cages and set those hatchlings free.", ["objectivesText"] = "Break open Kunchong Cages to release 8 Kunchong Hatchlings in the Clutches of Shek'zeer.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3278 }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 5556, ["name"] = "Klaxxi Daily Quests", ["orderIndex"] = 12, ["flags"] = 0 } } },
[31495] = { ["id"] = 31495, ["name"] = "Rank and File", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6052, ["storyline"] = { 31495 }, ["description"] = "First things first; let's kill us some crusaders. And when I say kill the Scarlet Crusade, I mean wipe them out, root and branch, rank and file.", ["objectivesText"] = "Kill 50 members of the Scarlet Crusade within the Scarlet Halls . Progress: You know, I've been killing the ones that you can't see behind closed doors. But I need to maintain this disguise. So if you could just take care of all of the ones out there in the open, that'd be great.", ["rewardGold"] = 456000, ["rewardXP"] = 471000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6052 } }, ["questType"] = "standard" },
[31496] = { ["id"] = 31496, ["name"] = "Sampling the Empire's Finest", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6138, ["mapID"] = 422, ["storyline"] = { 31496 }, ["description"] = "The wonders of the kypari sap never cease to amaze me. Among its numerous properties and applications, the sap can be refined into a nutritious and extremely delectable elixir. Nowhere in the Empire will you find a finer execution of this brew than the palace itself. Surely, the homes of the loyalists have feeders brimming with this sweet nectar. Fill this jar at their feeders and return it to me. I long to sample the imperial ambrosia once more.", ["objectivesText"] = "Use the Sap Jar at Imperial Feeders outside the Heart of Fear 4 times to fill it.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 79030, 79864, 80484, 87394, 87400, 87401, 87841, 88855, 89366 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3278 }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 5556, ["name"] = "Klaxxi Daily Quests", ["orderIndex"] = 13, ["flags"] = 0 } } },
[31497] = { ["id"] = 31497, ["name"] = "Just for Safekeeping, Of Course", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6052, ["storyline"] = { 31497 }, ["description"] = "There is a book of great value to me here in the halls. Unfortunately, it's in the possession of Flameweaver Koegler. I've tried to get close to him before, but it's never quite worked out. You might have better luck. Just watch out -- I hear that he's gone well and truly insane. The Flameweaver plans to burn every tome they have in the library. He'll probably burn the Scarlet Halls down in the process.", ["objectivesText"] = "Collect the Codex of the Crusade . Progress: It's imperative that I get my hands on the codex.", ["rewardGold"] = 456000, ["rewardXP"] = 471000, ["rewardItems"] = { 87268, 87370, 87371, 87372, 87373, 87374, 87375, 87376, 87377, 87378 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6052 } }, ["questType"] = "standard" },
[31502] = { ["id"] = 31502, ["name"] = "Wing Clip", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6138, ["mapID"] = 422, ["storyline"] = { 31502 }, ["description"] = "The young fliers of this era are fascinating. Their exceptional agility and endurance were, in my time, the feats of incredibly skilled or mature fliers. This would seem to indicate some kind of evolution in wing structure... Or perhaps a result of advancements in training? Induced genetic mutation? Selective breeding? Gah! There's no way to know for certain without tissue samples. Bring me their wings! And try not to ruin them in the process, will you? I need them intact!", ["objectivesText"] = "Collect 24 Needler Wings from Shek'zeer Needlers in the Clutches of Shek'zeer. Progress: Do you have the specimens?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 39804, 39854, 39855, 39867, 79864, 80484, 87394, 87400, 87401, 87841, 88855, 89366 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3278 }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 5556, ["name"] = "Klaxxi Daily Quests", ["orderIndex"] = 14, ["flags"] = 0 } } },
[31503] = { ["id"] = 31503, ["name"] = "Shortcut to Ruin", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6138, ["mapID"] = 422, ["storyline"] = { 31503 }, ["description"] = "There is a champion among the loyalists, Vess-Guard Na'kal , whose strength comes not from experience or development, but from genetic modification. He was meant to be an example of the future of mantid - the sick idea that we can be born strong, without earning it. He's a mockery of my work! Gene augmentation was meant for mature, post-swarm veterans ONLY! End him. Perhaps it will serve as a lesson to Grand Empress Shek'zeer that taking shortcuts leads to ruin.", ["objectivesText"] = "Kill Vess-Guard Na'kal outside the Heart of Fear.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3278 }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 5556, ["name"] = "Klaxxi Daily Quests", ["orderIndex"] = 25, ["flags"] = 0 } } },
[31504] = { ["id"] = 31504, ["name"] = "Ordnance Disposal", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6138, ["mapID"] = 422, ["storyline"] = { 31504 }, ["description"] = "If the Grand Empress's agents are still operating under security standards from my time, they would have hidden powerful pheromone mines all around the clutches. With mere whisper she could detonate them all simultaneously, engulfing the palace and rendering entire siege armies powerless. If we hope to have any success in a large scale standoff, we need to disable those mines. My... \"gift\" to you when we met will allow you to see the mines. Disturb them and get to a safe distance.", ["objectivesText"] = "Disable 8 Pheromone Mines around the Clutches of Shek'zeer and the Heart of Fear. Progress: We cannot hope to re-take the clutches as long as those mines are still present is such quantities.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3278 }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 5556, ["name"] = "Klaxxi Daily Quests", ["orderIndex"] = 26, ["flags"] = 0 } } },
[31505] = { ["id"] = 31505, ["name"] = "Vess-Guard Duty", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6138, ["mapID"] = 422, ["storyline"] = { 31505 }, ["description"] = "Vess-Guard Vik'az co-ordinates the defense forces at Zan'vess. He is worth ten mantid in battle, and his presence inspires the Zan'thik who fight alongside him. Needless to say, we need him dead. He patrols the housing area at the center of the island.", ["objectivesText"] = "Kill Vess-Guard Vik'az in Zan'vess.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3278 }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 5556, ["name"] = "Klaxxi Daily Quests", ["orderIndex"] = 27, ["flags"] = 0 } } },
[31506] = { ["id"] = 31506, ["name"] = "Shackles of Manipulation", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6138, ["mapID"] = 422, ["storyline"] = { 31506 }, ["description"] = "The Zan'thik employ a sizable force of... indentured labor. Yaungol are bound in special shackles which enhance and prolong the effects of sonic manipulation. It is this technology that allows the Zan'thik manipulators to command such large quantities of thralls to endlessly toil for them in the quarries. I would like to study these shackles.", ["objectivesText"] = "Collect 6 Zan'thik Shackles from Thought-Bound Miners and Thought-Bound Brutes in Zan'vess. Progress: Surely this is something you can handle, is it not?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 87813 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3278 }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 5556, ["name"] = "Klaxxi Daily Quests", ["orderIndex"] = 28, ["flags"] = 0 } } },
[31507] = { ["id"] = 31507, ["name"] = "Meltdown", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6138, ["mapID"] = 422, ["storyline"] = { 31507 }, ["description"] = "The venomsting scorpions on Zan'vess are fed sap from a young age, causing a fascinating mutation in which their natural armor plating becomes infused with amber. Effectively, it's organic kyparite, the same substance used in forging most of the empire's weapons and armor. I think I've found a way to chemically break down kyparite, but it needs testing. Use these grenades on the Zan'thik venomstings and observe the results.", ["objectivesText"] = "Slay 6 Zan'thik Venomstings in Zan'vess. Use Korven's Experimental Grenade to counter their armor plating. Progress: The kypari truly are amazing. They color the entire ecosystem around them in ways I had never thought possible.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 79864, 80484, 84240, 87394, 87400, 87401, 87841, 88855, 89366 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3278 }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 5556, ["name"] = "Klaxxi Daily Quests", ["orderIndex"] = 29, ["flags"] = 0 } } },
[31508] = { ["id"] = 31508, ["name"] = "Specimen Request", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6138, ["mapID"] = 422, ["storyline"] = { 31508 }, ["description"] = "Kyparite worms have shown extreme adaptations in order to mimic the environment around them. They can also grow to immense sizes at rates which are nearly unheard of for most creatures. Their physiology could provide valuable insight into further mutations. Bring me sample shards from the muck tunnelers in the shallows near Zan'vess.", ["objectivesText"] = "Collect 6 Kyparite Shards from Muck Tunnelers in The Briny Muck. Progress: Do you have the specimens?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 87874 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3278 }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 5556, ["name"] = "Klaxxi Daily Quests", ["orderIndex"] = 30, ["flags"] = 0 } } },
[31509] = { ["id"] = 31509, ["name"] = "Fear Takes Root", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6138, ["mapID"] = 422, ["storyline"] = { 31509 }, ["description"] = "The fallout from Shek'zeer's madness will continue long after her reign has ended. We will struggle to heal our lands for many years to come, and even then our efforts may prove fruitless. A new species of sha-twisted flora has begun taking root near Zan'vess. Destroy any that you find, but beware - there is no telling what kind of sinister defenses it may have.", ["objectivesText"] = "Destroy 15 Dreadspore Bulbs in Zan'vess and The Briny Muck.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3278 }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 5556, ["name"] = "Klaxxi Daily Quests", ["orderIndex"] = 31, ["flags"] = 0 } } },
[31510] = { ["id"] = 31510, ["name"] = "Quiet Now", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6138, ["mapID"] = 422, ["storyline"] = { 31510 }, ["description"] = "On the southwestern corner of Zan'vess lie the Whispering Stones. Much like the towers here, they are critical in transmitting long-range sonic signals. An adjunct of the Empress operates the stones, keeping her in communication with the Zan'thik forces. Disrupt the signal, then silence him.", ["objectivesText"] = "Interact with the Zan'thik Resonating Crystal at the Whispering Stones in Zan'vess to incite Adjunct Sek'ot , then slay him. Progress: Information is power.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3278 }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 5556, ["name"] = "Klaxxi Daily Quests", ["orderIndex"] = 32, ["flags"] = 0 } } },
[31513] = { ["id"] = 31513, ["name"] = "Blades of the Anointed", ["level"] = 34, ["requiredLevel"] = 28, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6109, ["storyline"] = { 31513 }, ["series"] = { 31514 }, ["description"] = "The problem with the Scarlet Crusade is that they keep coming back, even after death. Behind those resurrections is High Inquisitor Whitemane. With her death, so goes the Crusade. To give her the final rest, we need two swords of legend, each with a lost but storied history. Luckily for me... er, us, these two blades of the anointed are at rest here within the monastery. Find them and once you've killed Whitemane, plunge the blades into her corpse to make the death permanent.", ["objectivesText"] = "Collect the two Blades of the Anointed . Progress: <With one blade already in your possession, you move to take the other.> <An inscription on the statue behind the sword reads, \"The Hand of Providence\".>", ["rewardXP"] = 6200, ["rewardItems"] = { 87282 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6109 } }, ["questType"] = "dungeon" },
[31514] = { ["id"] = 31514, ["name"] = "Unto Dust Thou Shalt Return", ["level"] = 34, ["requiredLevel"] = 28, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6109, ["storyline"] = { 31514 }, ["series"] = { 31513 }, ["description"] = "<You take the second anointed blade in hand and feel the power of both swords course through you.> <There is but one thing left to do. As the mysterious, hooded woman explained, to put an end to the Scarlet Crusade, you must thrust both blades into the corpse of High Inquisitor Whitemane.>", ["objectivesText"] = "Use the Blades of the Anointed on the corpse of High Inquisitor Whitemane to send her permanently to her final rest. Progress: <The deed is not yet done. There can be no end to the Scarlet Crusade while Whitemane can come back from the dead.>", ["rewardGold"] = 14000, ["rewardXP"] = 6200, ["rewardItems"] = { 87361, 87362, 87363, 87364, 87365, 87366, 87367, 87368, 87369, 87388 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6109 } }, ["questType"] = "dungeon" },
[31515] = { ["id"] = 31515, ["name"] = "Blades of the Anointed", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6109, ["storyline"] = { 31515 }, ["series"] = { 31516 }, ["description"] = "The problem with the Scarlet Crusade is that they keep coming back, even after death. Behind those resurrections is High Inquisitor Whitemane. With her death, so goes the Crusade. To give her the final rest, we need two swords of legend, each with a lost but storied history. Luckily for me... er, us, these two blades of the anointed are at rest here within the monastery. Find them and once you've killed Whitemane, plunge the blades into her corpse to make the death permanent.", ["objectivesText"] = "Collect the two Blades of the Anointed . Progress: <With one blade already in your possession, you move to take the other.> <An inscription on the statue behind the sword reads, \"The Hand of Providence\".>", ["rewardXP"] = 471000, ["rewardItems"] = { 87389 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6109 } }, ["questType"] = "standard" },
[31517] = { ["id"] = 31517, ["name"] = "Contending With Bullies", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["storyline"] = { 31517 }, ["description"] = "We honor strength here, not brutality. It is unfortunate but there are some who come to my doorstep oblivious to this distinction. I have turned away one such challenger. In retaliation, he sacked the village of Yinying. Go to Yinying Village southeast of the temple, and face this \" Shonuf .\" Give him a lesson in true strength.", ["objectivesText"] = "Defeat Shonuf . Progress: It is a fine line between proving one's strength, and bullying.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3281 } },
[31518] = { ["id"] = 31518, ["name"] = "The Vale of Eternal Blossoms", ["level"] = 87, ["requiredLevel"] = 87, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["storyline"] = { 31518 }, ["description"] = "It's been many lifetimes since the gates to the valley were open, <name>. I wouldn't miss this for the world, and neither should you! Meet me at the southen edge of Kun-Lai Summit . I'll wait for you there.", ["objectivesText"] = "Speak to Anduin at the Gate of the August Celestials.", ["rewardGold"] = 228000, ["rewardXP"] = 294000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard" },
[31519] = { ["id"] = 31519, ["name"] = "A Worthy Challenge: Yan-zhu the Uncasked", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 31519 }, ["description"] = "<name>, I need you to assemble a hearty group and lead them into Stormstout Brewery . Activate the Challenger's Orb therein, and evaporate Yan-zhu the Uncasked. Return to me when you've completed this challenge, and I shall reward you handsomely.", ["objectivesText"] = "Complete the Stormstout Brewery Challenge Mode.", ["rewardGold"] = 456000, ["rewardXP"] = 471000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[31520] = { ["id"] = 31520, ["name"] = "A Worthy Challenge: Sha of Doubt", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 31520 }, ["description"] = "<name>, I need you to assemble a hearty group and lead them into the Temple of the Jade Serpent . Activate the Challenger's Orb therein, and vanquish the Sha of Doubt. Return to me when you've completed this challenge, and I shall reward you handsomely.", ["objectivesText"] = "Complete the Temple of the Jade Serpent Challenge Mode.", ["rewardGold"] = 456000, ["rewardXP"] = 471000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[31521] = { ["id"] = 31521, ["name"] = "To Be a Master", ["level"] = 90, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 31521 }, ["description"] = "There will come a day when you have mastered all that we have to teach you. When that day comes, it will be time for you to teach others in turn. When you have proven to yourself that you have mastered all the Ways, come back and speak with me.", ["objectivesText"] = "Make Black Pepper Steak, Sea Mist Rice Noodles , Mogu Fish Stew , Steamed Crab , Chun Tian Spring Roll and Mad Brewer's Breakfast , then return to the Guide to the Ways. Progress: There will come a day when you must pass knowledge onto others, as we have passed knowledge onto you.", ["rewardGold"] = 11400, ["rewardXP"] = 23600, ["rewardItems"] = { 4108, 4119, 25589, 25591, 25592, 29787, 29788, 29789, 29791, 37270, 37353, 37441, 37479, 39323, 39331, 39333, 39374, 39375, 39377, 39429, 39431, 39451, 39453, 39461, 39480, 39503, 61107, 61108, 61109, 61110, 61111, 61112, 61451, 61452, 61453, 63216, 63217, 63218, 65467, 65468, 74035, 74646, 74648, 74650, 74653, 74656, 74661, 74662, 74833, 74834, 74837, 74838, 74839, 74840, 74841, 74842, 74843, 74844, 74845, 74846, 74847, 74848, 74849, 74850, 74853, 74856, 74857, 74859, 74860, 74861, 74863, 74864, 74865, 75013, 75014, 75017, 75038, 81494, 81495, 81496, 81497, 81498, 81499, 81500, 81501, 81502, 81819, 81820, 81821, 81822, 81823, 81854, 81855, 81856, 81857, 81858, 81859, 83078, 86069, 86393, 86425, 87266, 87333, 87334, 87335, 87336, 87337, 87338, 87339, 87340, 87341, 88044, 88045, 88046, 88047, 88048, 88049, 88050, 88051, 88052, 89125, 89548, 89549, 89550, 89551, 89553, 89555, 89556, 89558, 89561, 89562, 89564, 89565, 89567, 89569, 89576, 89577, 89606, 90542, 90545, 90622 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[31522] = { ["id"] = 31522, ["name"] = "A Worthy Challenge: Sha of Hatred", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 31522 }, ["description"] = "<name>, I need you to assemble a tranquil group and lead them into the Shado-Pan Monastery . Activate the Challenger's Orb therein, and rescue Taran Zhu from the Sha of Hatred. Return to me when you've completed this challenge, and I shall reward you handsomely.", ["objectivesText"] = "Complete the Shado-Pan Monastery Challenge Mode.", ["rewardGold"] = 456000, ["rewardXP"] = 471000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[31523] = { ["id"] = 31523, ["name"] = "A Worthy Challenge: Xin the Weaponmaster", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 31523 }, ["description"] = "<name>, I need you to assemble a nimble group and lead them into Mogu'shan Palace . Activate the Challenger's Orb therein, and put an end to Xin the Weaponmaster. Return to me when you've completed this challenge, and I shall reward you handsomely.", ["objectivesText"] = "Complete the Mogu'shan Palace Challenge Mode.", ["rewardGold"] = 456000, ["rewardXP"] = 471000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[31524] = { ["id"] = 31524, ["name"] = "A Worthy Challenge: Raigonn", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 31524 }, ["description"] = "<name>, I need you to assemble a cracking group and lead them into the Gate of the Setting Sun . Activate the Challenger's Orb therein and lay waste to Raigonn. Return to me when you've completed this challenge, and I shall reward you handsomely.", ["objectivesText"] = "Complete the Gate of the Setting Sun Challenge Mode.", ["rewardGold"] = 456000, ["rewardXP"] = 471000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[31527] = { ["id"] = 31527, ["name"] = "A Worthy Challenge: Flameweaver Koegler", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 31527 }, ["description"] = "<name>, I need you to assemble a cunning group and venture forth into the depths of Scarlet Halls . Activate the Challenger's Orb therein, and put a stop to Flameweaver Koegler's book-burning ways.", ["objectivesText"] = "Complete the Scarlet Halls Challenge Mode.", ["rewardGold"] = 456000, ["rewardXP"] = 471000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[31528] = { ["id"] = 31528, ["name"] = "A Worthy Challenge: Darkmaster Gandling", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 31528 }, ["description"] = "<name>, I need you to assemble a fearless group and lead them into the depths of Scholomance . Activate the Challenger's Orb, and cleanse Scholomance of Darkmaster Gandling's evil presence. Return to me when you've completed this challenge and I shall reward you handsomely.", ["objectivesText"] = "Complete the Scholomance Challenge Mode.", ["rewardGold"] = 342000, ["rewardXP"] = 471000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[31530] = { ["id"] = 31530, ["name"] = "Mission: The Hozen Dozen", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 31530 }, ["description"] = "I've been watching the hozen since I arrived, and I don't like the pattern of activity that I'm seeing in their camp. Multiple hozen travel down the mountain under the cover of night, pillaging supplies from the farmlands below. We must stop their rampant theft. I have been thinning their numbers when I can, but one soldier alone is not enough. I need your help. Kill as many of the hozen as you can.", ["objectivesText"] = "Kill 12 Springtail vermin.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[31531] = { ["id"] = 31531, ["name"] = "Mission: Aerial Threat", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 31531 }, ["description"] = "I've identified another high risk target, one that most people would not suspect. The cliff kites soaring above the hills to the east are quite dangerous. I have seen them swooping down to the farms, snatching grain and seed when no one is looking. In order to protect the farms, we must thin their numbers.", ["objectivesText"] = "Kill 12 Cliff Kites .", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[31532] = { ["id"] = 31532, ["name"] = "Mission: Predator of the Cliffs", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 31532 }, ["description"] = "During my routine patrol of the mountains this morning, I spotted a huge white bird diving down to the farmlands. It lifted an entire yak in its talons and disappeared among the cliffs. Today a yak, tomorrow a farmhand! We must eliminate this bird before it chooses its next victim.", ["objectivesText"] = "Kill the Great Cliff Hawk . Progress: This mission is of utmost importance.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 79267 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[31534] = { ["id"] = 31534, ["name"] = "The Beginner's Brew", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 31534 }, ["description"] = "Can you keep a secret, <name>? I've been trying my hand at brewing. All I've got is this old hand-made still, but it still works pretty good. I've got an idea for a new brew, but I need some ingredients. I'm awful shy around the townsfolk, but I've seen you making friends all around. Would you be willing to ask the farmers for some ingredients for me?", ["objectivesText"] = "Collect 1 Sweet Lakemelon from Haohan Mudclaw, 1 Fuzzy Peach from Gina Mudclaw, 1 Black Cherries from Fish Fellreed, and 1 Red Radish from Farmer Fung. Progress: I don't know what it is. Maybe it's staring at that brewery day in and day out, but I just feel... like I want to brew the best beer in the Valley... no... all of Pandaria! Oh, it's a silly dream, isn't it?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 87553, 87554, 87555, 87556 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[31536] = { ["id"] = 31536, ["name"] = "Preserving Freshness", ["level"] = 90, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 31536 }, ["description"] = "To preserve maximum freshness, cooking ingredients need to be stored properly. Fortunately, Merchant Cheng over there sells good containers. I hate to send you on such a menial errand, but would you go purchase an empty tiger meat basket for me?", ["objectivesText"] = "Bring Nam Ironpaw an Empty Tiger Meat Basket. Progress: Ingredients will spoil if not stored properly.", ["rewardGold"] = 11400, ["rewardXP"] = 23600, ["rewardItems"] = { 74833, 74839, 74841, 74856, 74857, 87658 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[31537] = { ["id"] = 31537, ["name"] = "Ella's Taste Test", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 31537 }, ["description"] = "Well, I finally got the brew made, but I won't know if it's any good unless some people taste it. Would you take my brew and see what the folks in Halfhill think? I... I couldn't face them myself.", ["objectivesText"] = "Ask Jogu the Drunk, Bobo Ironpaw, Farmer Yoon, and Nana Mudclaw what they think of Ella's Brew . Progress: I think my brew tastes pretty wild, but that's just me. I need some second opinions.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 87558, 87763 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[31538] = { ["id"] = 31538, ["name"] = "A Worthy Brew", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 31538 }, ["description"] = "There's one final person who needs to taste my brew. I've heard that he's traveled far and wide, and tasted drinks from all over the world. He happens to be in town, and I'd like to know what he thinks of my skills.", ["objectivesText"] = "Ask Chen Stormstout to taste Ella's Brew .", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 87763 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[31539] = { ["id"] = 31539, ["name"] = "A Thing of Beauty", ["level"] = 90, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["storyline"] = { 31539 }, ["description"] = "We live in a world of magic.The few among us who are skilled can imbue this magic into the things we craft and give them power. Such things are valued. Fewer still, however, are those among us who can create things that are cherished through the ages not because they are imbued with power, but because of their great beauty. The Temple of the Jade Serpent has commissioned us for such a work, and I believe you are the worthiest among us. Will you accept the commission?", ["objectivesText"] = "Craft a Commissioned Painting and bring it to Inkmaster Wei at the Arboretum in the Jade Forest. The recipe can be found in your Inscription pane under Quests. Progress: This is a grand project. It will take much time and effort, even from a craftsman such as you.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 79340, 79731, 87811, 87812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard" },
[31540] = { ["id"] = 31540, ["name"] = "Staves for Tian Monastery", ["level"] = 90, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["storyline"] = { 31540 }, ["description"] = "It seems like the Tian Monsatery is training a lot of monks this year. We've received a huge commission for staves. And by huge, I mean HUGE.", ["objectivesText"] = "Craft 3 Ghost Iron Staves and 2 Rain Poppy Staves. Bring them to Inkmaster Wei at the Arboretum in the Jade Forest. Progress: So many staves! How many monks do they have?!", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 72096, 72237, 76061, 79254, 79339, 79342, 79731, 79740 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard" },
[31541] = { ["id"] = 31541, ["name"] = "Set in Jade", ["level"] = 90, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["storyline"] = { 31541 }, ["description"] = "One of the greatest poets of our time is Master Kwang. He has composed a poem of great beauty, and a merchant in Halfhill would like to have these words inscribed in stone, to display proudly in her home. She has requested a scribe of great skill to take on this job. Will you accept the commission?", ["objectivesText"] = "Craft an Engraved Jade Disc and bring it to Inkmaster Jo Po at the Arboretum, in the Jade Forest. The recipe can be found in your Inscription pane under Quests. Progress: How is it coming along?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 79731, 87814, 87815 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard" },
[31544] = { ["id"] = 31544, ["name"] = "A Tribute to the Dead", ["level"] = 90, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["storyline"] = { 31544 }, ["description"] = "All things must come to an end - even the life of a good man. A family in Kun Lai has commissioned a monument for their beloved patriarch who has passed on recently. Will you accept the commission?", ["objectivesText"] = "Create an Inscribed Monument Stone and bring it to Inkmaster Jo Po at the Arboretum, in the Jade Forest. The recipe can be found in your Inscription pane under Quests. Progress: Respect for the dead is part of our traditions.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 76061, 79255, 79731, 87831, 88807 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard" },
[31545] = { ["id"] = 31545, ["name"] = "The Finer Things", ["requiredLevel"] = 1, ["faction"] = "none", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["storyline"] = { 31545 }, ["description"] = "The Pandaria Treasure Society is interested in purchasing finely crafted goods from skilled jewelcrafters such as yourself. The items will be catalogued, and the most exceptional cuts stored in a secret vault, while the rest are sold to refresh our funds. Our goal is to eventually create a unique collection for a special event.", ["objectivesText"] = "Bring the requested goods to any member of the Pandaria Treasure Society in The Valley of Eternal Blossoms.", ["rewardXP"] = 80, ["rewardItems"] = { 76668 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[31548] = { ["id"] = 31548, ["name"] = "Learning the Ropes", ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 1, ["storyline"] = { 31548 }, ["series"] = { 31549, 31551, 31822 }, ["description"] = "Now that you are a pet trainer, it's time to test your skills! Head out into the valley and pick a fight with a battle pet. Come back to me after you have won and I will continue your training. Good luck!", ["objectivesText"] = "Win a pet battle.", ["rewardGold"] = 3000, ["rewardXP"] = 4600, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Epic" },
[31549] = { ["id"] = 31549, ["name"] = "On The Mend", ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 1, ["storyline"] = { 31549 }, ["series"] = { 31548, 31551, 31822 }, ["description"] = "Now that you have won a battle, we need to heal up your pets so they can fight another day! Visit Shelby Stoneflint, our local stable master, to heal and revive your pets.", ["objectivesText"] = "Heal your pets to full health by visiting Shelby Stoneflint the Stable Master.", ["rewardGold"] = 8000, ["rewardXP"] = 22050, ["rewardItems"] = { 63777, 63778, 63779 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Epic" },
[31550] = { ["id"] = 31550, ["name"] = "Got one!", ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredRaces"] = { 7, 11 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 12, ["storyline"] = { 31550 }, ["series"] = { 31308, 31309, 31785 }, ["description"] = "Great work so far <name>. You are going to be a pro at this pet stuff before you know it. Now it's time to catch a pet of your own! Head back out and find a battle pet to fight, engage it in battle and throw your trap once it's low on health. Bring your catch back for me to see once you are finished. Remember, you need at least one pet at level 3 to use your trap!", ["objectivesText"] = "Catch a battle pet.", ["rewardGold"] = 6500, ["rewardXP"] = 20100, ["rewardItems"] = { 34863, 63621, 63622, 63623 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12 } }, ["questType"] = "standard" },
