[31606] = { ["id"] = 31606, ["name"] = "The Dissector Wakens", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6138, ["storyline"] = { 31606 }, ["series"] = { 31605 }, ["description"] = "You are... not like the others... I hear the Klaxxi calling... <cough> I just need a moment.", ["objectivesText"] = "Hold off the Zan'thik while Rik'kal wakens. Progress: <cough cough> My head...", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 84046, 84047, 84048, 84049, 84050, 84051, 84052, 84053, 84054 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard" },
[31609] = { ["id"] = 31609, ["name"] = "The Wrath of Shek'zeer", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6138, ["storyline"] = { 31609 }, ["series"] = { 31612, 31959 }, ["description"] = "The rest of the freed paragons are scattered around the Heart of Fear, fighting off the mantid swarm. They may need your help!", ["objectivesText"] = "Rout the Mantid Swarm by slaying Akkolon , Shox'tik , the Manifestation of Terror , and 25 mantid subjugates.", ["rewardGold"] = 228000, ["rewardXP"] = 294000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard" },
[31611] = { ["id"] = 31611, ["name"] = "The Kun-Lai Kicker", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6426, ["storyline"] = { 31611 }, ["description"] = "Have you ever seen the Brewmoon Festival ? The good folks of Binan Village host quite a party. And tonight's festivities are brew-catered by none other than your's truly here. I am making my famous Kun-Lai Kicker! Think you might come and join us for the festivities? It should be a completely relaxing event with absolutely no danger whatsoever.", ["objectivesText"] = "Protect the Brewmoon Festival . Progress: Ah, still alive I see...", ["rewardGold"] = 456000, ["rewardXP"] = 471000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6426 } }, ["questType"] = "standard" },
[31612] = { ["id"] = 31612, ["name"] = "Shadow of the Empire", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6138, ["storyline"] = { 31612 }, ["series"] = { 31609, 31959 }, ["description"] = "You only understand part of our order. You are an outsider, and have been treated as such. It is no longer appropriate that we keep our secrets from you. There is something you should see.", ["objectivesText"] = "Accompany Kil'ruk the Wind-Reaver into the chamber below Klaxxi'vess. Progress: There is something you should see.", ["rewardGold"] = 228000, ["rewardXP"] = 294000, ["rewardItems"] = { 83779, 90858, 90859, 90860, 90861, 90862 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard" },
[31613] = { ["id"] = 31613, ["name"] = "Volatile Greenstone Brew", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6209, ["storyline"] = { 31613 }, ["description"] = "I am working on a batch of my famous Volatile Greenstone Brew. Should be superb in countering the rascals and mischievous elementals we have been seeing around the mines lately. Tell you what, how about you round up some of your friends and bring them back here to try out a round. First one's on the house!", ["objectivesText"] = "Aid in the defense of Greenstone Village. Progress: Sprites, jade destroyers, rocks that talk. This world is becoming a troublesome one. But... nothing that can not be solved with a strong brew and winning smile. And a solid punch or two.", ["rewardGold"] = 456000, ["rewardXP"] = 471000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6209 } }, ["questType"] = "standard" },
[31614] = { ["id"] = 31614, ["name"] = "LFGDungeons - Mists - Heroic Random - 1st", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["storyline"] = { 31614 }, ["rewardGold"] = 549600, ["rewardXP"] = 2830, ["rewardItems"] = { 98134 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
