[31664] = { ["id"] = 31664, ["name"] = "An Angler's Quest", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "none", ["requiredProfessions"] = { "fishing" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5785, ["storyline"] = { 31664 }, ["description"] = "This journal provides a hazy recollection of Nat Pagle's grand adventures. Simply reading it will undoubtedly provide a useful insight into fishing.", ["objectivesText"] = "Read Nat's Fishing Journal .", ["rewardGold"] = 24335, ["rewardXP"] = 25, ["rewardItems"] = { 86542, 86544, 86545, 88563, 88604 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["startItems"] = { 88563 } },
[31669] = { ["id"] = 31669, ["name"] = "The Cabbage Test", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 31669 }, ["description"] = "Grandpa always said that the bellweather of a true farmer lies in the quality of his cabbage. Any time a new farmer came into town, he'd buy a few heads of cabbage to see what they knew. Now, I'm the new farmer, and this is my big chance to prove myself. Could you plant some cabbage for me?", ["objectivesText"] = "Plant a Green Cabbage in Sunsong Ranch. You can purchase seeds from Merchant Greenfield in the Halfhill Market. Progress: Good farmers grow good cabbage. Bad farmers, bad cabbage. Pretty simple.", ["rewardGold"] = 57000, ["rewardXP"] = 118000, ["rewardItems"] = { 74840, 79102 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[31671] = { ["id"] = 31671, ["name"] = "Why Not Scallions?", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 31671 }, ["description"] = "I heard Haohan mentioning that he was going to plant scallions today. I'm not sure if today's the best day for scallions, but I'd like to hope that he knows what he's doing. He is the head of the Tillers' union, after all. Could you plant a scallion for me?", ["objectivesText"] = "Plant a Scallion in Sunsong Ranch. You can purchase seeds from Merchant Greenfield in the Halfhill Market. Progress: What do you mean, I have dirt on my nose? What's that supposed to mean, <name>? Are you calling me a brown-noser? Oh, I see. I DID have a little bit of dirt on my nose. Thank you for the helpful tip.", ["rewardGold"] = 57000, ["rewardXP"] = 118000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[31672] = { ["id"] = 31672, ["name"] = "A Pumpkin-y Perfume", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 31672 }, ["description"] = "I heard a rumor around the market that Gina Mudclaw loves the smell of pumpkin blossoms. Maybe if I grow some pumpkins in my farm, she might come and visit a little more often. Could you plant a pumpkin for me?", ["objectivesText"] = "Plant a Mogu Pumpkin in Sunsong Ranch. You can purchase seeds from Merchant Greenfield in the Halfhill Market. Progress: Did you plant the pumpkin yet?", ["rewardGold"] = 57000, ["rewardXP"] = 118000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[31673] = { ["id"] = 31673, ["name"] = "Red Blossom Leeks, You Make the Croc-in' World Go Down", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 31673 }, ["description"] = "Grandpa once told me that the smell of leeks will keep crocolisks off of your property. He must have had a point... he always grew leeks, and I never saw a crocolisk anywhere NEAR his farm. We're pretty far from the water... but I suppose you can never be too sure.", ["objectivesText"] = "Plant a Red Blossom Leek in Sunsong Ranch. You can purchase seeds from Merchant Greenfield in the Halfhill Market. Progress: Come to think of it, Grandpa didn't live near the water either...", ["rewardGold"] = 57000, ["rewardXP"] = 118000, ["rewardItems"] = { 62461 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[31674] = { ["id"] = 31674, ["name"] = "The Pink Turnip Challenge", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 31674 }, ["description"] = "Old Hillpaw bet me that my land couldn't grow a pink turnip. I'll show him. My land will grow the biggest, pinkest turnip that old coot's ever seen!", ["objectivesText"] = "Plant a Pink Turnip in Sunsong Ranch. You can purchase seeds from Merchant Greenfield in the Halfhill Market. Progress: Old Hillpaw... what a maroon.", ["rewardGold"] = 57000, ["rewardXP"] = 118000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[31675] = { ["id"] = 31675, ["name"] = "The White Turnip Treatment", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 31675 }, ["description"] = "Grandpa often told me to \"Keep my drawers clean and my dirt cleaner.\" It sounds like a joke, but he makes a good point. Vegetables tend to leave behind bits of root that can contaminate your soil... but a nice, big, white turnip will clean that gunk right up. Think you could plant a white turnip for me?", ["objectivesText"] = "Plant a White Turnip in Sunsong Ranch. You can purchase seeds from Merchant Greenfield in the Halfhill Market. Progress: Now keepin' your drawers clean, that's more of a personal thing. Grandpa made a good point there, too.", ["rewardGold"] = 57000, ["rewardXP"] = 118000, ["rewardItems"] = { 89880 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[31685] = { ["id"] = 31685, ["name"] = "Valley of the Four Winds", ["level"] = 87, ["requiredLevel"] = 85, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["storyline"] = { 31685 }, ["description"] = "Yarr, the Jade Forest be goin through some violent reconstruction, but the Valley of the Four Winds is ripe for explorin. Talk with me when ye be ready to go and I can give ye a ride ta where ya need to go. Talk to me cohort on the other side 'ta get some equipment to aid ya on yer journey.", ["objectivesText"] = "Teleport to Valley of the Four Winds and speak to Private Tim P. O'Rary .", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[31690] = { ["id"] = 31690, ["name"] = "Inscribed Tiger Staff", ["level"] = 90, ["requiredLevel"] = 85, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["storyline"] = { 31690 }, ["description"] = "As powerful it is, at some point you know you will outgrow this staff. When that time comes, one of the Inkmasters in the Arboretum would most likely be interested in taking it from you.", ["objectivesText"] = "Bring your Inscribed Tiger Staff to Inkmaster Glenzu in the Arboretum.", ["rewardItems"] = { 79343, 79731 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[31691] = { ["id"] = 31691, ["name"] = "Inscribed Crane Staff", ["level"] = 90, ["requiredLevel"] = 85, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["storyline"] = { 31691 }, ["description"] = "As powerful it is, at some point you know you will outgrow this staff. When that time comes, one of the Inkmasters in the Arboretum would most likely be interested in taking it from you.", ["objectivesText"] = "Bring your Inscribed Crane Staff to Inkmaster Jo Po in the Arboretum.", ["rewardItems"] = { 79340, 79731 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[31692] = { ["id"] = 31692, ["name"] = "Inscribed Serpent Staff", ["level"] = 90, ["requiredLevel"] = 85, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["storyline"] = { 31692 }, ["description"] = "As powerful it is, at some point you know you will outgrow this staff. When that time comes, one of the Inkmasters in the Arboretum would most likely be interested in taking it from you.", ["objectivesText"] = "Bring your Inscribed Serpent Staff to Inkmaster Wei in the Arboretum.", ["rewardItems"] = { 79341, 79731 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[31693] = { ["id"] = 31693, ["name"] = "Julia Stevens", ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 12, ["storyline"] = { 31693 }, ["description"] = "Think you can take me again?", ["objectivesText"] = "Defeat Julia Stevens in a pet battle.", ["rewardGold"] = 62000, ["rewardXP"] = 80, ["rewardItems"] = { 98715 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12 } }, ["questType"] = "standard" },
[31695] = { ["id"] = 31695, ["name"] = "Beyond the Wall", ["level"] = 88, ["requiredLevel"] = 88, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5841, ["storyline"] = { 31695 }, ["description"] = "We received word the Shado-Pan have begun a counter attack in to Townlong Steppes . It sounds like they are going after the root of the yaungol invasion. The pandaren have not traveled in force in to Townlong for thousands of years. The Shado-Pan are strong and brave, but they are also proud and few. They will need help from heroes like yourself. Can you travel through the Gate of Winter's Blossom in the northwest? Find the Shado-Pan leaders and lend your help and experience?", ["objectivesText"] = "Speak with Taran Zhu at the Longying Outpost in Townlong Steppes .", ["rewardGold"] = 10600, ["rewardXP"] = 16200, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard" },
[31698] = { ["id"] = 31698, ["name"] = "Thinning The Pack", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5785, ["storyline"] = { 31698 }, ["description"] = "The past few seasons have been plentiful, and as a result, the wild tiger population on Windward Isle has exploded. The savage creatures have hunted out all the nearby game, and are beginning to encroach upon the cloud serpent nests. As a result, as the tigers thrive, the cloud serpents decline. If we are not careful, the predatory cats could completely wipe them out. We must thin the tigers' numbers, <race>.", ["objectivesText"] = "Kill 8 Windward Tigers or Windward Alphas.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3284 } },
[31699] = { ["id"] = 31699, ["name"] = "Sprite Fright", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5785, ["storyline"] = { 31699 }, ["description"] = "Oh bother, how am I supposed to get my tasks done, now? Instructor Skythorn asked me to go kill some tigers at Windward Isle, but I heard the area was overrun with sprites! Ugh! I hate sprites! They totally give me the creeps! They're so small, and... and... they jump on you and... and... they have cold, dead little stick hands! Auuugh! You have to help me, <name>. Get rid of those things, please!", ["objectivesText"] = "Kill 7 Shadowfae Tricksters . Progress: So I don't like sprites. What's the big deal?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3284 } },
[31701] = { ["id"] = 31701, ["name"] = "Dark Huntress", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5785, ["storyline"] = { 31701 }, ["description"] = "I have learned that a vicious beast, a Windward Huntress , terrorizes the wood on the northwest side of the island. She has already slain several serpents, and injured more than one serpent rider sent to subdue her. She must be removed before she can pose a danger to anyone else. Can you perform this task?", ["objectivesText"] = "Kill the Windward Huntress .", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3284 } },
[31702] = { ["id"] = 31702, ["name"] = "On The Prowl", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5785, ["storyline"] = { 31702 }, ["description"] = "I have heard report of a great white beast that stalks the wood on the northwestern side of the wild serpent island. This savage creature is mate to the Windward Huntress, and already he has taken down several of the adult cloud serpent matriarchs. We cannot have such a fearsome predator roaming the island unchecked. Go and deal with this creature. Let us see if your training has paid off.", ["objectivesText"] = "Kill the Windward Saber .", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3284 } },
[31703] = { ["id"] = 31703, ["name"] = "Madcap Mayhem", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5785, ["storyline"] = { 31703 }, ["description"] = "There is another task I must ask of you. The leader of the woodland sprites is the Shadowfae Madcap . If there is trouble brewing, he is the mastermind pulling the puppet strings. We do not have time to deal with the sprites' tiresome pranks and insolence. Take out the Shadowfae Madcap , and be quick about it.", ["objectivesText"] = "Kill the Shadowfae Madcap .", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3284 } },
[31704] = { ["id"] = 31704, ["name"] = "Pooped", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5785, ["storyline"] = { 31704 }, ["description"] = "<Your serpent catches your gaze and ducks its head bashfully.> You can tell that someone has gotten out of its pen and had \"an accident.\" Well, at the rate that the hatchling's been eating, it had to come out the other end... somewhere. You had better find the serpent's poop and clean it up before the Serpent Masters find out.", ["objectivesText"] = "Collect 5 Tiny Bags of Poop . Progress: <The hatchling watches you innocently.>", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 89052 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3284 } },
[31705] = { ["id"] = 31705, ["name"] = "Needle Me Not", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5785, ["storyline"] = { 31705 }, ["description"] = "The Arboretum is our home, a safe haven where we raise young hatchlings and train our students. Unfortunately, there are other, more dangerous creatures who wish to make this their home as well. To the north, beyond the river, we have seen a great wasp feeding on the nectar blossoms. This creature has already stung several of our students. Use this honey to lure the wasp out of hiding. Then, destroy it before it harms anyone else.", ["objectivesText"] = "Use the honey at the northern clearing in The Arboretum, and then kill the Orchard Needler . Progress: The nectar attracts many unsavory creatures.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 81404, 88044, 88045, 88046, 88047, 88048, 88049, 88050, 88051, 88052, 89113 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3284 } },
[31706] = { ["id"] = 31706, ["name"] = "Weeping Widows", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5785, ["storyline"] = { 31706 }, ["description"] = "The spiders near Sri-La Village have grown very aggressive. They pose a severe problem to the anglers who fish along the coast. For their safety, I need you to go and eliminate the Weeping Widows in The Widow's Wail. You can find the cave along the coast to the north.", ["objectivesText"] = "Kill 7 Weeping Widows .", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3284 } },
[31707] = { ["id"] = 31707, ["name"] = "A Tangled Web", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5785, ["storyline"] = { 31707 }, ["description"] = "We have had a disturbing report from the Anglers fishermen of Sri-La Village, <name>. Many of their villagers are missing, taken by the spiders who live in The Widow's Wail, a cave along the coast to the north. The victims are dragged into the dark depths, wrapped in cocoons, and left to become the spiders' next meal. We believe that some of the people may still be alive. There is still time to save them! I need you to go and rescue as many villagers as you can find.", ["objectivesText"] = "Destroy Widow's Webs to free 5 Sri-La Villagers.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3284 } },
[31708] = { ["id"] = 31708, ["name"] = "Serpent's Scale", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5785, ["storyline"] = { 31708 }, ["description"] = "I see you have gained your own hatchling, <race>. Have you been feeding it, cleaning after it, and playing with it properly? Only by doing so will it become strong and healthy. Now let me tell you a trainer's secret. To the north, in The Widow's Wail, you can find a mushroom known as Serpent's Scale . It is difficult to acquire, but this mushroom has powerful properties and important nutrients. Your serpent won't like eating it, but who likes eating their vegetables?", ["objectivesText"] = "Collect 25 Serpent's Scale . Progress: <Your serpent greets you happily.>", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 88895 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3284 } },
[31709] = { ["id"] = 31709, ["name"] = "Lingering Doubt", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5785, ["storyline"] = { 31709 }, ["description"] = "I heard that there has been some strange behavior down at The Widow's Wail to the north. Hyacinth and I went to investigate, and I am certain that some presence of the sha has found its way into the cavern. I created this device to measure sha energy levels. If you are going that way, would you mind taking measurements of any sha disturbances? The disturbances look like streams of white and black sha energy pouring from the ground.", ["objectivesText"] = "Use the Sha Attunement Device at the Sha Disturbances in The Widow's Wail. The entrance to The Widow's Wail can be found to the north along the coast, south of Sri-La Village.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 88966 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3284 } },
[31710] = { ["id"] = 31710, ["name"] = "Tiny Treats", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5785, ["storyline"] = { 31710 }, ["description"] = "As you near, your serpent opens its mouth and begins drooling. It looks quite hungry since you last left it. From the way it whimpers and slaps its tail, you can tell it is not looking for just any treat, but a special favorite snack. Your serpent loves to munch on tiny spider eyes , but this delicacy comes only from the Widowspawn spiders in the cave along the coast to the north. Well, what's a rider to do? Your serpent is waiting.", ["objectivesText"] = "Collect 100 Tiny Spider Eyes . Progress: Your serpent perks up at your return.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 88907 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3284 } },
[31711] = { ["id"] = 31711, ["name"] = "The Seed of Doubt", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5785, ["storyline"] = { 31711 }, ["description"] = "The problem with the sha of doubt, <race>, is its deceitful pervasiveness. Once the seed of doubt is planted, it can grow like an unwelcome weed. Such a seed has been planted in The Widow's Wail to the north, and like a weed, we must extinguish its presence immediately. I need you to destroy the lingering fragment of doubt before it can infect any more victims.", ["objectivesText"] = "Kill the Seed of Doubt . Progress: Doubt is a difficult enemy to vanquish because in a sense, we are fighting ourselves. Stand tall and be confident in your own actions, <name>.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3284 } },
[31712] = { ["id"] = 31712, ["name"] = "Monkey Mischief", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5785, ["storyline"] = { 31712 }, ["description"] = "Strange tales have reached our ears from Sri-La Village. It seems that a hozen tribe has made itself comfortable in Oona Kagu, a cave along the coast south of the fishing village. Too comfortable, in fact. The tribe members are stealing and pillaging resources all along the coast. We must teach them a lesson... one that can only be taught by force. They have already overstayed their welcome.", ["objectivesText"] = "Kill 13 Oona hozen. Progress: We serve the people of The Jade Forest . We will ensure their protection and well-being.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3284 } },
[31713] = { ["id"] = 31713, ["name"] = "The Big Brew-haha", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5785, ["storyline"] = { 31713 }, ["description"] = "It's a disaster, <name>! When I went to visit the Dancing Serpent Inn yesterday, they were all out of brew. They said the shipment from Sri-La Village had been stolen. STOLEN! Turns out those Oona hozen have been making all kinds of trouble down at the docks, including taking all the brew to their cave at Oona Kagu along the coast. I can't handle a dry spell. A life without brew is not a life worth living! Someone needs to go and save the brew!", ["objectivesText"] = "Collect 100 Sri-La Stout. Progress: Is the brew recovered yet? I'm... I'm starting to lose it...", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 79864, 80484, 87394, 87400, 87401, 87841, 88855, 89366 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3284 } },
[31714] = { ["id"] = 31714, ["name"] = "Saving the Serpents", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5785, ["storyline"] = { 31714 }, ["description"] = "Those Oona hozen have gone too far this time. Do you know what they are doing with wild cloud serpents? Captured hatchlings are forced to fight one another in the pits, for nothing more than the Oona's amusement. Savages! If the young hatchlings learn such aggressive behavior at a young age, they may become violent and corrupted adults. A malicious cloud serpent is not something we want to deal with. We must save the hatchlings.", ["objectivesText"] = "Collect 10 Rescued Serpents . Progress: The Order of the Cloud Serpent has worked for centuries to make the cloud serpents into loyal companions. Our kindness brings out the best in these creatures. Unfortunately, violence and anger can quickly turn them into destructive monsters.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 88894 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3284 } },
[31715] = { ["id"] = 31715, ["name"] = "The Big Kah-Oona", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5785, ["storyline"] = { 31715 }, ["description"] = "The leader of the Oona hozen is a brigand by the name of Lord Oona . I have heard fearsome tales of this roaming sea captain and his crew. Everywhere he takes his tribe, destruction follows. The Oona land their boats on fertile soil, pillage the local villages, and drain the land dry before moving on to their next conquest. We shall not allow the same to occur on our shores, not while I am still in charge. I need someone to go eradicate him now.", ["objectivesText"] = "Kill Lord Oona .", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3284 } },
[31716] = { ["id"] = 31716, ["name"] = "Pooped", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5785, ["storyline"] = { 31716 }, ["description"] = "<As you approach the pen, the serpent zips into a corner and hides.> As it looks at you with bashful eyes, you can tell that someone has gotten out of its pen and had... an accident. Well, at the rate that the serpent's been eating, it had to come out the other end... somewhere. You had better find the serpent's poop and clean it up before the Serpent Masters find out.", ["objectivesText"] = "Collect 5 Big Bags of Poop . Progress: <The serpent watches you in amusement.>", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 89053 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3284 } },
[31717] = { ["id"] = 31717, ["name"] = "The Trainer's Challenge: Ace Longpaw", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5785, ["storyline"] = { 31717 }, ["description"] = "You are rising up the ranks of our students, <name>. Just as a sword must be forged through fire, so must our students test themselves against one another. Today, you will spar against one of our brightest disciples, Ace Longpaw . In order to defeat him, you will need to make use of your defensive capabilities. Speak to him in the training ring to begin the challenge. Good luck.", ["objectivesText"] = "Speak to Ace Longpaw , then defeat him. Progress: How did the challenge go?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3284 } },
[31718] = { ["id"] = 31718, ["name"] = "The Trainer's Challenge: Big Bao", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5785, ["storyline"] = { 31718 }, ["description"] = "Are you ready for another lesson, <name>? Today, you will spar against Big Bao . He is large of stature and of heart, and he will not give up until he is wholly beaten. If you wish to defeat him, you will need to persevere. Speak to him in the training ring to begin the challenge. Good luck.", ["objectivesText"] = "Speak to Big Bao , then defeat him. Progress: How did the challenge go?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3284 } },
[31719] = { ["id"] = 31719, ["name"] = "The Trainer's Challenge: Ningna Darkwheel", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5785, ["storyline"] = { 31719 }, ["description"] = "You show much promise, <name>. However, talent is worth little without discipline and humility. Today, you will face Ningna Darkwheel . Her natural strength makes her one of our most talented students. If you hope to defeat her, you will need to act with the utmost control. Speak to her in the training ring to begin the challenge. Good luck.", ["objectivesText"] = "Speak to Ningna Darkwheel , then defeat her.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3284 } },
[31720] = { ["id"] = 31720, ["name"] = "The Trainer's Challenge: Suchi the Sweet", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5785, ["storyline"] = { 31720 }, ["description"] = "Today you will face Suchi the Sweet in the training ring. Despite her sweet exterior, she is a tough opponent. She attacks swiftly and surely, but such potent attacks can become tiring over time. If you hope to defeat her, you will need to concentrate your damage when she is weakened. Speak to Suchi to begin the duel. Good luck.", ["objectivesText"] = "Speak to Suchi the Sweet , then defeat her.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3284 } },
[31721] = { ["id"] = 31721, ["name"] = "The Trainer's Challenge: Qua-Ro Whitebrow", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5785, ["storyline"] = { 31721 }, ["description"] = "Qua-Ro Whitebrow is commonly considered the best student of the Order. He seems quite without weakness. He is quick of intellect, strong of arm, hard-working, and talented. When you face him in the training ring, you will be testing yourself against our best. Speak to him to begin the duel. No matter the outcome, you will learn much from challenging him.", ["objectivesText"] = "Speak to Qua-Ro Whitebrow , then defeat him.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3284 } },
[31723] = { ["id"] = 31723, ["name"] = "Valley of the Four Winds", ["level"] = 87, ["requiredLevel"] = 85, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["storyline"] = { 31723 }, ["description"] = "Yarr, the Jade Forest be goin through some violent reconstruction, but the Valley of the Four Winds is ripe for explorin. I can help ye on yer way if ye wants to explore it. Be sure to check out me wares for some equipment that may help ye on yer journey.", ["objectivesText"] = "Speak to Private Tim P. O'Rary in the Valley of the Four Winds.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[31724] = { ["id"] = 31724, ["name"] = "Old MacDonald", ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 12, ["mapID"] = 52, ["storyline"] = { 31724 }, ["series"] = { 31316, 31725, 31726, 31728, 31729, 31917, 32008 }, ["description"] = "You're tough for just starting out! Old MacDonald taught me everything I know about battling. I think fighting him would be a great learning experience for you! He can be found just across the bridge leading to Westfall. Don't let his age fool you, he's already beaten quite a few up-and-coming trainers like yourself.", ["objectivesText"] = "Defeat Old MacDonald in a pet battle. Progress: You must think you're a real ace, don't you?", ["rewardGold"] = 8000, ["rewardXP"] = 80, ["rewardItems"] = { 89125 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 52, ["questLines"] = { { ["id"] = 289, ["name"] = "Battle Pet Tamers", ["orderIndex"] = 1, ["flags"] = 0 } } },
[31725] = { ["id"] = 31725, ["name"] = "Lindsay", ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 40, ["mapID"] = 49, ["storyline"] = { 31725 }, ["series"] = { 31316, 31724, 31726, 31728, 31729, 31917, 32008 }, ["description"] = "Are you ready to show off what you can do? There's a little girl up in Redridge Mountains that has made a real storm on the battle scene. Find Lindsay at the dock at Camp Everstill. She may be young, but her impressive record is nothing to be scoffed at!", ["objectivesText"] = "Defeat Lindsay in a pet battle. Progress: Who taught you how to fight, mister?", ["rewardGold"] = 56000, ["rewardXP"] = 80, ["rewardItems"] = { 89125 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 40 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 49, ["questLines"] = { { ["id"] = 289, ["name"] = "Battle Pet Tamers", ["orderIndex"] = 2, ["flags"] = 0 } } },
[31726] = { ["id"] = 31726, ["name"] = "Eric Davidson", ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 44, ["mapID"] = 47, ["storyline"] = { 31726 }, ["series"] = { 31316, 31724, 31725, 31728, 31729, 31917, 32008 }, ["description"] = "I heard all my friends talking about a scary worgen called Eric Davidson in Duskwood that nobody ever fights with their pets. I bet if you found and beat him, people might talk about you instead!", ["objectivesText"] = "Defeat Eric Davidson in a pet battle.", ["rewardGold"] = 78000, ["rewardXP"] = 80, ["rewardItems"] = { 64372, 85871, 89125 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 44 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 47, ["questLines"] = { { ["id"] = 289, ["name"] = "Battle Pet Tamers", ["orderIndex"] = 3, ["flags"] = 0 } } },
[31727] = { ["id"] = 31727, ["name"] = "Gambling Problem", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6138, ["storyline"] = { 31727 }, ["series"] = { 31181 }, ["description"] = "If this war is to be won we cannot afford to leave anything unchecked, outsider. There is a disturbance along the coast that needs to be investigated. The presence there is not our kind and are of no value to us. However, their supplies could prove very valuable. If there is anything of use there we must get to it before the empress.", ["objectivesText"] = "Speak with Deck Boss Arie at Soggy's Gamble in Dread Wastes .", ["rewardGold"] = 11400, ["rewardXP"] = 23600, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard" },
[31728] = { ["id"] = 31728, ["name"] = "Bill Buckler", ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 33, ["mapID"] = 210, ["storyline"] = { 31728 }, ["series"] = { 31316, 31724, 31725, 31726, 31729, 31917, 32008 }, ["description"] = "My longtime friend, fellow trainer, and infamous drunkard Bill Buckler of the Cape of Stranglethorn, has issued an open challenge to prepared trainers! You should answer his call and really put your skills to the test. He tends to wander the southern roads of the Cape.", ["objectivesText"] = "Defeat Bill the Pirate in a pet battle. Progress: You aren't sho tough ...hic!", ["rewardGold"] = 8000, ["rewardXP"] = 80, ["rewardItems"] = { 89125 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 33 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 210, ["questLines"] = { { ["id"] = 289, ["name"] = "Battle Pet Tamers", ["orderIndex"] = 5, ["flags"] = 0 } } },
[31729] = { ["id"] = 31729, ["name"] = "Steven Lisbane", ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 10, ["mapID"] = 50, ["storyline"] = { 31729 }, ["series"] = { 31316, 31724, 31725, 31726, 31728, 31917, 32008 }, ["description"] = "If you thought I was tough, prepare yourself. The road only gets harder from here. Find Steven Lisbane wandering the roads in the southern parts of Northern Stranglethorn. Seek him out and see who the superior tamer is!", ["objectivesText"] = "Defeat Steven Lisbane in a pet battle. Progress: Where did you acquire such an intriguing team?", ["rewardGold"] = 65000, ["rewardXP"] = 80, ["rewardItems"] = { 89125 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 50, ["questLines"] = { { ["id"] = 289, ["name"] = "Battle Pet Tamers", ["orderIndex"] = 4, ["flags"] = 0 } } },
[31730] = { ["id"] = 31730, ["name"] = "A Not So Friendly Request", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6138, ["storyline"] = { 31730 }, ["series"] = { 31067, 31069 }, ["description"] = "Scouts have reported a non-mantid presence near Kor'vess. Their intrusion and their theft of amber would normally be dealt with swiftly, but our forces are needed elsewhere. This task seems suited to you, Wakener. You will convince them to leave this land, or you will destroy them in the name of the Klaxxi'va.", ["objectivesText"] = "Speak with Sapmaster Vu at The Brewgarden in Dread Wastes .", ["rewardGold"] = 11400, ["rewardXP"] = 23600, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard" },
[31754] = { ["id"] = 31754, ["name"] = "Cannonfire", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 31754 }, ["description"] = "Those mogu cannons up on the Golden Stair are bombarding us from a distance. Sure would be nice if they somehow spontaneously broke, don't you think?", ["objectivesText"] = "Destroy 7 Shao-Tien Cannons . Progress: Oh my pounding head! So loud, so obnoxious, these cannons firing all through the night... These mogu really aren't a very considerate bunching.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 40110, 89123 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[31755] = { ["id"] = 31755, ["name"] = "Acts of Cruelty", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 31755 }, ["description"] = "I can hear the screams of the captured soldiers and villagers up on the Golden Stair. They're torturing them! Please, please, you have to save them!", ["objectivesText"] = "Rescue 5 Golden Lotus Guards or Mistfall Villagers. Progress: No one deserved the agony the mogu bring upon us...", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[31756] = { ["id"] = 31756, ["name"] = "High Chance of Rain", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 31756 }, ["description"] = "The mogu are conjuring some kind of sinister storm upon the Golden Stair. Generally, mogu and lightning are not a particularly pleasant mix. I say we stop them. You should be able to find their Stormcaller staves pretty easily, considering the giant arcs of lightning extending up from them. Mind knocking them over or destroying them or something for me? I sure would sleep better.", ["objectivesText"] = "Destroy the Stormcaller staves. Progress: If they were rice farmers, they could make a killing with rain on demand. These mogu really are reaching for the wrong calling in life.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[31757] = { ["id"] = 31757, ["name"] = "Unleashed Spirits", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 31757 }, ["description"] = "The Shao-Tien have unleashed their captive tortured spirits upon us. They flood down from the Golden Stair, with no end in sight. Kill as many of these unleashed spirits as you can. They are fragile, but if you are not alert, they can easily overrun you. Good luck.", ["objectivesText"] = "Kill 12 Unleashed Spirits .", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[31758] = { ["id"] = 31758, ["name"] = "Laosy Scouting", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 31758 }, ["description"] = "Lao Softfoot got himself captured again up on the Golden Stair. I'm not going to make any excuses for him, he's a lousy rogue. We probably shouldn't just leave him there though. Could you go find him?", ["objectivesText"] = "Rescue Lao Softfoot . Progress: Lao needs to take a lesson from his brother, He. When you're sneaking around a hostile mogu camp, being a loudmouth isn't an asset. Not that it ever is, I guess.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[31760] = { ["id"] = 31760, ["name"] = "Striking First", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 31760 }, ["description"] = "The mogu are empowering some giant stone monstrosity up on the Golden Stair, with the sure intent of unleashing it upon us. How about you go and let them know our opinion on the matter? Make sure the point strikes home.", ["objectivesText"] = "Stop the Shao-Tien Behemoth from being empowered. Progress: Go, go, share our diplomacy with the Shao-Tien.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[31762] = { ["id"] = 31762, ["name"] = "Crumbling Behemoth", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 31762 }, ["description"] = "The mogu have succeeded in empowering an enormous stone statue with the intent of unleashing it upon us. In response, I would like to unleash you upon it. It approaches from the Golden Stair. Bring it to its knees...", ["objectivesText"] = "Destroy the Shao-Tien Behomoth. Progress: The sounds of battle get my blood pumping...", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[31772] = { ["id"] = 31772, ["name"] = "Priorities!", ["level"] = 86, ["requiredLevel"] = 85, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["storyline"] = { 31772 }, ["description"] = "Just look at this mess! All that brew gone to waste! Taran Zhu warned us against speaking to you outsiders, but I'll take any help I can get. We were on our way to Dawn's Blossom when the fighting broke out. Now all of our brew has been lost! You want to make it up to us? Maybe you can find some of our Honeybrew barrels that haven't been broken. Then it wouldn't be a complete loss.", ["objectivesText"] = "Find 6 Barrels of Honeybrew in Honeydew Glade.", ["rewardGold"] = 98000, ["rewardXP"] = 111000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard" },
[31780] = { ["id"] = 31780, ["name"] = "Old MacDonald", ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 40, ["storyline"] = { 31780 }, ["description"] = "I won't be such a pushover this time around!", ["objectivesText"] = "Defeat Old MacDonald in a pet battle.", ["rewardGold"] = 62000, ["rewardXP"] = 80, ["rewardItems"] = { 98715 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 40 } }, ["questType"] = "standard" },
[31781] = { ["id"] = 31781, ["name"] = "Lindsay", ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 44, ["storyline"] = { 31781 }, ["description"] = "Think you can take me again? I'm always up for challenge!", ["objectivesText"] = "Defeat Lindsay in a pet battle.", ["rewardGold"] = 62000, ["rewardXP"] = 80, ["rewardItems"] = { 98715 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 44 } }, ["questType"] = "standard" },
[31782] = { ["id"] = 31782, ["name"] = "Overthrone", ["level"] = 90, ["requiredLevel"] = 87, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6138, ["storyline"] = { 31782 }, ["description"] = "The council is in harmony, wakener. Our ritual will bring about the demise of the empress and allow us to secure the future of our great empire. Behold the power of the Klaxxi!", ["objectivesText"] = "Speak to Klaxxi'va Vor in Klaxxi'vess.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 84028, 84029, 84030, 84031, 84032, 84033, 84034, 84035, 84036 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard" },
