[31785] = { ["id"] = 31785, ["name"] = "Level Up!", ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 12, ["storyline"] = { 31785 }, ["series"] = { 31308, 31309, 31550 }, ["description"] = "Good, good. It's important to keep your pets healthy and ready for battle. My next task for you is to fight a few battles and raise a pet to level 3. Once you do that, come back and see me and we can talk about catching your own pets!", ["objectivesText"] = "Raise a pet to level 3.", ["rewardGold"] = 8000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12 } }, ["questType"] = "standard" },
