[31808] = { ["id"] = 31808, ["name"] = "Rampage Against the Machine", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6138, ["mapID"] = 422, ["storyline"] = { 31808 }, ["description"] = "Kovok has progressed at an astonishing rate. Perhaps the years in hibernation effected his growth process... Whatever the reason, this could not have come at a better time. I believe it is time to test his abilities. You have done so much to aid in his training. It is only fitting that you assist him in his first battle. I've already guided him to the edge of the scar. Find him and destroy Shek'zeer's army!", ["objectivesText"] = "Kill 200 Mantid while controlling Kovok in the Scar. Progress: Was the battle glorious?! How many of Shekzeer's army fell to Kovok ?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3278 }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 5556, ["name"] = "Klaxxi Daily Quests", ["orderIndex"] = 17, ["flags"] = 0 } } },
[31809] = { ["id"] = 31809, ["name"] = "Remnants of Anger", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5842, ["storyline"] = { 31809 }, ["description"] = "As you look upon the severed claw of the defeated Sha of Anger, you realize that Ban Bearheart , commander of the Shado-Pan in Townlong Steppes , would want to know of your victory.", ["objectivesText"] = "Deliver the Claw of Anger to Ban Bearheart at the Shado-Pan Garrison in Townlong Steppes . Progress: <Ban looks at you with narrowed eyes.> Something about you is... different. Changed.", ["rewardGold"] = 456000, ["rewardItems"] = { 89317, 90906, 90907, 90908, 90909, 90910, 90911, 90912, 90913, 90914 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard", ["startItems"] = { 89317 } },
[31810] = { ["id"] = 31810, ["name"] = "Riding the Skies", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 31810 }, ["description"] = "I can no longer call myself your teacher, <name>. You have proven yourself worthy of your cloud serpent. Today, you shall join our ranks. Are you ready?", ["objectivesText"] = "Join the Order of the Cloud Serpent.", ["rewardGold"] = 57000, ["rewardXP"] = 118000, ["rewardItems"] = { 79802, 85429, 85430, 89155 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371, ["questLines"] = { { ["id"] = 5549, ["name"] = "Order of the Cloud Serpent", ["orderIndex"] = 14, ["flags"] = 0 } } },
