[31812] = { ["id"] = 31812, ["name"] = "Zunta, The Pet Tamer", ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 1637, ["mapID"] = 1, ["storyline"] = { 31812 }, ["series"] = { 31813, 31814, 31815, 31817, 31870, 31918, 32009 }, ["description"] = "I can tell you have been honing your pet battle skills, <name>. I think it's time for you to take on a real challenge. Zunta can be found near the Tor'kren Farm south of Orgrimmar. He is an up and coming wild pet tamer and I think it's time you faced him in battle!", ["objectivesText"] = "Defeat Zunta in a pet battle. Progress: Who be sendin' you to face Zunta ?", ["rewardGold"] = 90000, ["rewardXP"] = 80, ["rewardItems"] = { 89125 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1, ["questLines"] = { { ["id"] = 290, ["name"] = "Battle Pet Tamers", ["orderIndex"] = 0, ["flags"] = 0 } } },
[31813] = { ["id"] = 31813, ["name"] = "Dagra the Fierce", ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 14, ["mapID"] = 10, ["storyline"] = { 31813 }, ["series"] = { 31812, 31814, 31815, 31817, 31870, 31918, 32009 }, ["description"] = "Der be another trainer not far from here that you ought to fight to test your worth. Dagra the Fierce waits on the northern slope of Thorn Hill, east of The Crossroads. If you be beatin' her, you just might have what it takes.", ["objectivesText"] = "Defeat Dagra the Fierce in a pet battle. Progress: I fear nothing. I will not be defeated!", ["rewardGold"] = 110000, ["rewardXP"] = 80, ["rewardItems"] = { 89125 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 14 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 10, ["questLines"] = { { ["id"] = 290, ["name"] = "Battle Pet Tamers", ["orderIndex"] = 1, ["flags"] = 0 } } },
[31814] = { ["id"] = 31814, ["name"] = "Analynn", ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 17, ["mapID"] = 63, ["storyline"] = { 31814 }, ["series"] = { 31812, 31813, 31815, 31817, 31870, 31918, 32009 }, ["description"] = "Determination is naught without proper challenge. Find Analynn wandering the roads in western Ashenvale. She is a bit...eccentric...but a fine trainer nonetheless! Fighting her will harden your team.", ["objectivesText"] = "Defeat Analynn in a pet battle. Progress: You're a curious sort.", ["rewardGold"] = 82000, ["rewardXP"] = 80, ["rewardItems"] = { 89125 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 17 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 63, ["questLines"] = { { ["id"] = 290, ["name"] = "Battle Pet Tamers", ["orderIndex"] = 2, ["flags"] = 0 } } },
