[31926] = { ["id"] = 31926, ["name"] = "Grand Master Antari", ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 3520, ["storyline"] = { 31926 }, ["description"] = "You capitalized on my mistake last time and emerged victorious. This time, you will not be so fortunate, <race>.", ["objectivesText"] = "Defeat Bloodknight Antari in a pet battle. Progress: Your performance is astonishing.", ["rewardGold"] = 53000, ["rewardXP"] = 80, ["rewardItems"] = { 89125, 89587, 98715 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 3520 } }, ["questType"] = "standard" },
[31927] = { ["id"] = 31927, ["name"] = "Battle Pet Tamers: Northrend", ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 1519, ["mapID"] = 127, ["storyline"] = { 31927 }, ["series"] = { 31928, 31929, 31981, 31982 }, ["description"] = "Outland's finest have fallen to your skill, but Northrend now awaits you! There are four tamers that you must now defeat: Beegle Blastfuse in Howling Fjord, Nearly Headless Jacob in Crystalsong Forest, Okrut Dragonwaste in Dragonblight, and Gutretch in Zul'drak. If you are able to best all of them, then Northrend's Grand Master will surely challenge you!", ["objectivesText"] = "Defeat Beegle Blastfuse , Nearly Headless Jacob , Okrut Dragonwaste , and Gutretch in pet battles.", ["rewardGold"] = 3000, ["rewardXP"] = 80, ["rewardItems"] = { 89125 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1519 } }, ["questType"] = "standard", ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 127, ["questLines"] = { { ["id"] = 289, ["name"] = "Battle Pet Tamers", ["orderIndex"] = 10, ["flags"] = 0 } } },
[31928] = { ["id"] = 31928, ["name"] = "Grand Master Payne", ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 210, ["mapID"] = 170, ["storyline"] = { 31928 }, ["series"] = { 31927, 31929, 31981, 31982 }, ["description"] = "In my opinion, my fellow tamers have been far too lenient on your training. True pet taming requires militaristic discipline. I shall honor you with the pleasure of seeing firsthand what that discipline can produce. Come to the Argent Tournament Grounds in Icecrown and see firsthand what you could become!", ["objectivesText"] = "Defeat Major Payne in a pet battle. Progress: Perhaps other methods may be useful in certain cases.", ["rewardGold"] = 8500, ["rewardXP"] = 80, ["rewardItems"] = { 39563, 54436, 89125 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 210 } }, ["questType"] = "standard", ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 170, ["questLines"] = { { ["id"] = 289, ["name"] = "Battle Pet Tamers", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 290, ["name"] = "Battle Pet Tamers", ["orderIndex"] = 11, ["flags"] = 0 } } },
[31929] = { ["id"] = 31929, ["name"] = "Battle Pet Tamers: Northrend", ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 1637, ["mapID"] = 127, ["storyline"] = { 31929 }, ["series"] = { 31927, 31928, 31981, 31982 }, ["description"] = "Outland's finest have fallen to your skill, but Northrend now awaits you! There are four tamers that you must now defeat: Beegle Blastfuse in Howling Fjord, Nearly Headless Jacob in Crystalsong Forest, Okrut Dragonwaste in Dragonblight, and Gutretch in Zul'drak. If you are able to best all of them, then Northrend's Grand Master will surely challenge you!", ["objectivesText"] = "Defeat Beegle Blastfuse , Nearly Headless Jacob , Okrut Dragonwaste , and Gutretch in pet battles.", ["rewardGold"] = 74000, ["rewardXP"] = 80, ["rewardItems"] = { 89125 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 127, ["questLines"] = { { ["id"] = 290, ["name"] = "Battle Pet Tamers", ["orderIndex"] = 10, ["flags"] = 0 } } },
[31930] = { ["id"] = 31930, ["name"] = "Battle Pet Tamers: Pandaria", ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 1519, ["mapID"] = 422, ["storyline"] = { 31930 }, ["series"] = { 31951, 31952, 31985, 31986 }, ["description"] = "You must now face the toughest tamers in all of Azeroth, <name>. They make their home in Pandaria, training ground of the grand masters. There are six grand masters left to defeat: Hyuna of the Shrines in The Jade Forest, Farmer Nishi in Valley of the Four Winds, Mo'ruk in Krasarang Wilds, Courageous Yon in Kun-Lai Summit, Seeker Zusshi in Townlong Steppes, and Wastewalker Shu in Dread Wastes. If you think yourself ready, seek out these champions of the trade and prove yourself!", ["objectivesText"] = "Defeat Hyuna of the Shrines , Farmer Nishi , Mo'ruk , Courageous Yon , Seeker Zusshi , and Wastewalker Shu in pet battles.", ["rewardGold"] = 74000, ["rewardXP"] = 80, ["rewardItems"] = { 89125 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1519 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 289, ["name"] = "Battle Pet Tamers", ["orderIndex"] = 14, ["flags"] = 0 } } },
[31932] = { ["id"] = 31932, ["name"] = "Nearly Headless Jacob", ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 2817, ["storyline"] = { 31932 }, ["description"] = "Time and time again you defy my wisdom. What is it that brings you back to these woods? Ah, you wish to do battle once more. Very well then.", ["objectivesText"] = "Defeat Nearly Headless Jacob in a pet battle. Progress: Your intentions are clear.", ["rewardGold"] = 8000, ["rewardXP"] = 80, ["rewardItems"] = { 98715 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 2817 } }, ["questType"] = "standard" },
[31933] = { ["id"] = 31933, ["name"] = "Okrut Dragonwaste", ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 65, ["storyline"] = { 31933 }, ["description"] = "You dare interrupt our work? Then you must battle me again! Take out your pets, and I'll give you a taste of Hellscream's wrath!", ["objectivesText"] = "Defeat Okrut Dragonwaste in a pet battle. Progress: You...fool.", ["rewardGold"] = 8000, ["rewardXP"] = 80, ["rewardItems"] = { 98715 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 65 } }, ["questType"] = "standard" },
[31934] = { ["id"] = 31934, ["name"] = "Gutretch", ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 66, ["storyline"] = { 31934 }, ["description"] = "Me like fighting you. You not so easy like the others. We fight again?", ["objectivesText"] = "Defeat Gutretch in a pet battle.", ["rewardGold"] = 8000, ["rewardXP"] = 80, ["rewardItems"] = { 98715 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 66 } }, ["questType"] = "standard" },
[31935] = { ["id"] = 31935, ["name"] = "Grand Master Payne", ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 210, ["storyline"] = { 31935 }, ["description"] = "The rebel <class> comes once again to test <his/her> might again that of a Grand Master. Your bravery will be your undoing this time!", ["objectivesText"] = "Defeat Major Payne in a pet battle.", ["rewardGold"] = 350, ["rewardXP"] = 80, ["rewardItems"] = { 88801, 89125, 89587, 98715 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 210 } }, ["questType"] = "standard" },
[31936] = { ["id"] = 31936, ["name"] = "The \"Jinyu Princess\" Irrigation System", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 31936 }, ["description"] = "<The back of the box features a caricature of a jinyu maiden surrounded by marketing copy.> \"Hey there, greenthumb. Are you pouting over parched pumpkins? Crying over crusty cabbage? Are your leeks lame and your melons melancholy? Then it's time you brought home the Jinyu Princess! She'll wash over your garden like a sweet spring rain, dousing that drought with a deep draught of...\" <It goes on like this for six paragraphs.>", ["objectivesText"] = "Bring the \"Jinyu Princess\" Irrigation System to Farmer Yoon at Sunsong Ranch or Halfhill market. Provided item:", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 89812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard", ["startItems"] = { 89812 } },
[31937] = { ["id"] = 31937, ["name"] = "\"Thunder King\" Pest Repellers", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 31937 }, ["description"] = "<An imposing image of a mogu face dominates this box, casting its gaze downward at neatly ordered rows of bold text.> \"DO NOT LET WEAK, DISGUSTING INSECTS INFEST YOUR GLORIOUS CROPS. CONQUER THEM WITH THE MIGHT OF THE THUNDER KING AND PROTECT YOUR LEGACY.\" <The rest of the space is dedicated to cartoon depictions of various insects crying out in lament or fleeing in terror.>", ["objectivesText"] = "Bring the \"Thunder King\" Pest Repellers to Farmer Yoon at Sunsong Ranch or Halfhill Market. Provided item:", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 89813 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard", ["startItems"] = { 89813 } },
[31938] = { ["id"] = 31938, ["name"] = "The \"Earth-Slasher\" Master Plow", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 31938 }, ["description"] = "<The box art depicts a pandaren farmer of impossible physique standing proudly astride a widening rift in the earth, a mighty plow in his grasp. Cubs wrestle playfully on his shoulders and dangle from his muscular arms. At his side, a stoic female - of equally impossible physique - balances a massive, overflowing cornucopia gracefully on her head while kicking a virmen in the face.> \"The Earth-Slasher. Master the land. Master your life.\"", ["objectivesText"] = "Bring the \"Earth-Slasher\" Master Plow to Farmer Yoon at Sunsong Ranch or Halfhill Market. Provided item:", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 89814, 89815 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard", ["startItems"] = { 89814 } },
[31941] = { ["id"] = 31941, ["name"] = "Squash Those Foul Odors", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 31941 }, ["description"] = "Grandpa always said, \"A squash a week, and your tail won't reek.\" <Yoon subtly sniffs the air.> Yup. I think it's been about a week. Could you help me plant a Jade Squash?", ["objectivesText"] = "Plant a Jade Squash in Sunsong Ranch. You can purchase seeds from Merchant Greenfield in the Halfhill Market. Progress: You might want to have a little squash too, <name>. Just sayin'.", ["rewardGold"] = 57000, ["rewardXP"] = 118000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[31942] = { ["id"] = 31942, ["name"] = "It's Melon Time", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 31942 }, ["description"] = "< Farmer Yoon looks up at the sky and sniffs the air.> Hmm... <He licks his paw and holds it up in the air, sticks a toenail into the soil, and then inspects the length of his shadow.> Yup. It's melon time. Could you grab some seeds and help me plant a Striped Melon?", ["objectivesText"] = "Plant a Striped Melon in Sunsong Ranch. You can purchase seeds from Merchant Greenfield in the Halfhill Market. Progress: Hurry up! Melon time doesn't last forever!", ["rewardGold"] = 57000, ["rewardXP"] = 118000, ["rewardItems"] = { 89329, 89880 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[31943] = { ["id"] = 31943, ["name"] = "Which Berries? Witchberries.", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 31943 }, ["description"] = "That young'un over there, Andi, is going to grow up to be a heck of a farmer some day. I can tell just by lookin' at him. I think I'll plant him some witchberries. Kids love witchberries - it'll be a nice surprise.", ["objectivesText"] = "Plant Witchberries in Sunsong Ranch. You can purchase seeds from Merchant Greenfield in the Halfhill Market. Progress: The trick to a good witchberry crop is to wait until they're nice and sweet. It's not as easy as it sounds. I remember when I was a just a cub, puckerin' on some not-even-half-ripe witchberries because I couldn't wait like Grandpa told me to.", ["rewardGold"] = 57000, ["rewardXP"] = 118000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[31944] = { ["id"] = 31944, ["name"] = "Complete Your Training: The Final Test", ["requiredLevel"] = 90, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = {}, ["flags"] = { "class" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5841, ["storyline"] = { 31944 }, ["description"] = "Welcome back, <name>. The time has come for you to complete the last step of your training. Head to the Training Grounds for your final test.", ["objectivesText"] = "Go the the Training Grounds at the Peak of Serenity and complete your final test.", ["rewardXP"] = 353000, ["rewardItems"] = { 85183, 85185, 90010, 90011, 90012 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard" },
[31946] = { ["id"] = 31946, ["name"] = "Mung-Mung's Vote III: The Great Carrot Caper", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 31946 }, ["description"] = "Mung-Mung don't care who steals carrots. Only care what Mr. Mudclaw does to poor Mung-Mung when he finds his crop is ruined! < Mung-Mung rubs his chin thoughtfully.> Wait! Mung-Mung have bright idea. You go and grow some juicycrunch carrots . Then, we take your carrots and pretend they are Mr. Mudclaw's. Yes!", ["objectivesText"] = "Plant and harvest 2 Juicycrunch Carrots , then deliver 10 Juicycrunch Carrots to Mung-Mung . Juicycrunch Carrot Seeds can be purchased from Merchant Greenfield at Halfhill Market. After tilling and tending your plant, you must wait until the next day to harvest ripe Juicycrunch Carrots . Progress: Virmens love carrots, but they hate turnips. I hate turnips, too.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 74840, 74841, 74846, 74848, 79102, 80590, 89326, 89329, 89880 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[31947] = { ["id"] = 31947, ["name"] = "Farmer Fung's Vote III: Crazy For Cabbage", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 31947 }, ["description"] = "< Farmer Fung is beaming with a radiant smile.> Thanks to you, I got my precious yaks back! Unfortunately, I noticed that their time out in the wild left them rather gaunt. They must be starving, but I don't feed my prize yaks just any regular old grass. No sir, they eat only the leafiest green cabbages you can find here in the Valley. My stores are a bit low. If you bring me some cabbages for my yaks, I will reward you handsomely.", ["objectivesText"] = "Plant and harvest 3 Green Cabbages , then deliver 15 Green Cabbages to Farmer Fung . Green Cabbage Seeds can be purchased from Merchant Greenfield at Halfhill Market. After tilling and tending your plant, you must wait until the next day to harvest ripe Green Cabbages . Progress: I have pet nicknames for all of my yaks. There's Hairy, and Shaggy, and Fluffy, and Woolly, and...", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 74840, 74846, 74848, 89326, 89329 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[31948] = { ["id"] = 31948, ["name"] = "Nana's Vote II: The Sacred Springs", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 31948 }, ["series"] = { 30519 }, ["description"] = "You caught me at a good time, <name>. I was just hankering to make a fresh batch of Witchberry Julep. Have you ever heard of this wondrous brew? Each sip takes ten years off your face! How do you think I still look so good? Anyway, I need a special ingredient - thousand-year water - which can be collected from the mouth of the waterfall to the north. I'm afraid the journey is too treacherous for an old matron like me, but if you can get your hands on a pitcher, I'll let you share my brew.", ["objectivesText"] = "Use the Empty Pitcher at the Golden Falls to collect Thousand-Year Water . Progress: The water in this valley flows from the Vale of Eternal Blossoms to the north. It is said that these waters have wondrous, magical properties.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 89902, 89903 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[31949] = { ["id"] = 31949, ["name"] = "Nana's Vote III: Witchberry Julep", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 31949 }, ["description"] = "Now that we have the water, I can almost taste the icy cold witchberry julep! Now, we just need to find ourselves some sweet witchberries . My grandson's berries this season have been total slop, so I need to seek a decent harvest elsewhere. Say, do you have any witchberries in the ground this year? How about you bring me some from your farm? If your berries are up to the standard, we'll make ourselves a grand old batch of the old juice!", ["objectivesText"] = "Plant and harvest 3 Witchberries , then deliver 15 Witchberries to Nana Mudclaw . Witchberry Seeds can be purchased from Merchant Greenfield at Halfhill Market. After tilling and tending your plant, you must wait until the next day to harvest ripe Witchberries . Progress: Hurry it up, will ya? I'm an old woman. I don't have all the time in the world, and I want one more taste of the sauce before I croak!", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 74846, 74848, 89329 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[31951] = { ["id"] = 31951, ["name"] = "Grand Master Aki", ["level"] = 90, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5840, ["mapID"] = 390, ["storyline"] = { 31951 }, ["series"] = { 31930, 31952, 31985, 31986 }, ["description"] = "You have fought hard and well against the trainers of Azeroth. Even the grand masters have fallen to your cunning tactics. I now await you in the Vale of Eternal Blossoms, for you have earned the privilege to face me in battle. Come, <name>, and let us see if you have what it takes to defeat me.", ["objectivesText"] = "Defeat Aki the Chosen in a pet battle. Progress: I have heard much about your techniques. Hopefully that does not alter the outcome of our bout.", ["rewardGold"] = 114000, ["rewardXP"] = 80, ["rewardItems"] = { 89125, 92744 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 390, ["questLines"] = { { ["id"] = 289, ["name"] = "Battle Pet Tamers", ["orderIndex"] = 15, ["flags"] = 0 }, { ["id"] = 290, ["name"] = "Battle Pet Tamers", ["orderIndex"] = 15, ["flags"] = 0 } } },
[31953] = { ["id"] = 31953, ["name"] = "Grand Master Hyuna", ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5785, ["storyline"] = { 31953 }, ["description"] = "You seek to do battle once more? Very well, it will strengthen me to better protect the sacred sites of my people.", ["objectivesText"] = "Defeat Hyuna of the Shrines in a pet battle. Progress: You are a noble fighter.", ["rewardGold"] = 700, ["rewardXP"] = 80, ["rewardItems"] = { 89125, 89587, 92738, 98715 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard" },
[31954] = { ["id"] = 31954, ["name"] = "Grand Master Mo'ruk", ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 31954 }, ["description"] = "This time I'm gonna do the beating! You watch!", ["objectivesText"] = "Defeat Mo'ruk in a pet battle. Progress: No! Me win!", ["rewardGold"] = 700, ["rewardXP"] = 80, ["rewardItems"] = { 89125, 89587, 98715 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard" },
[31955] = { ["id"] = 31955, ["name"] = "Grand Master Nishi", ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 31955 }, ["description"] = "My pets continue to grow in strength thanks to the fertile land we train on. You don't stand a chance!", ["objectivesText"] = "Defeat Farmer Nishi in a pet battle. Progress: You're good, I'll give you that.", ["rewardGold"] = 700, ["rewardXP"] = 80, ["rewardItems"] = { 89125, 89587, 92738, 98715 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[31957] = { ["id"] = 31957, ["name"] = "Grand Master Shu", ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6138, ["storyline"] = { 31957 }, ["description"] = "You venture into the heart of the wastes to face me again, only to suffer defeat at the hands of a true grand master. Noble, but foolish.", ["objectivesText"] = "Defeat Wastewalker Shu in a pet battle.", ["rewardGold"] = 700, ["rewardXP"] = 80, ["rewardItems"] = { 89125, 89587, 98715 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard" },
[31958] = { ["id"] = 31958, ["name"] = "Grand Master Aki", ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 31958 }, ["description"] = "You wish to test yourself against me once more? Very well, let us fight.", ["objectivesText"] = "Defeat Aki the Chosen in a pet battle. Progress: The journey to greatness is never complete.", ["rewardGold"] = 8000, ["rewardXP"] = 80, ["rewardItems"] = { 89125, 89587, 98715 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[31959] = { ["id"] = 31959, ["name"] = "The Empress' Gambit", ["level"] = 90, ["requiredLevel"] = 89, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6138, ["storyline"] = { 31959 }, ["series"] = { 31609, 31612 }, ["description"] = "Grand Empress Shek'zeer has finally lost her patience with us. We have learned of an enormous army, massing in the shadows of the Heart of Fear, with orders to crush Klaxxi'vess. We have been fortunate to hold out this long, but we cannot survive a siege of this scale. Wakener, you have been invaluable to our efforts. Come, take your place on the field among we paragons. I will see you on the battlefield!", ["objectivesText"] = "Report to Malik the Unscathed outside the Heart of Fear.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 92522 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard" },
[31966] = { ["id"] = 31966, ["name"] = "Battle Pet Tamers: Cataclysm", ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 1519, ["mapID"] = 241, ["storyline"] = { 31966 }, ["series"] = { 31967, 31970, 31983, 31984 }, ["description"] = "You have defeated Northrend's finest tamers, but you need more preparation before you are ready to face the grand masters of Pandaria. Ready yourself and hone your skills by defeating these elite tamers: Brok in Mount Hyjal, Bordin Steadyfist in Deepholm, and Goz Banefury in Twilight Highlands. Once you have triumphed over them, you will be ready to journey to Pandaria to face the ultimate challenge.", ["objectivesText"] = "Defeat Brok , Bordin Steadyfist , and Goz Banefury in pet battles.", ["rewardGold"] = 90000, ["rewardXP"] = 80, ["rewardItems"] = { 89125 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1519 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 241, ["questLines"] = { { ["id"] = 289, ["name"] = "Battle Pet Tamers", ["orderIndex"] = 12, ["flags"] = 0 } } },
