[31970] = { ["id"] = 31970, ["name"] = "Grand Master Obalis", ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5034, ["mapID"] = 1527, ["storyline"] = { 31970 }, ["series"] = { 31966, 31967, 31983, 31984 }, ["description"] = "You think yourself ready to challenge Pandaria? You truly believe that you can defeat the most powerful tamers in all of Azeroth? I shall be the judge of that notion, <race>. Face me atop the Vir'naal Dam in Uldum, and we shall see if you are truly ready.", ["objectivesText"] = "Defeat Obalis in a pet battle. Progress: I admire your passion, young one.", ["rewardGold"] = 8000, ["rewardXP"] = 80, ["rewardItems"] = { 20769, 89125 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5034 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527, ["questLines"] = { { ["id"] = 289, ["name"] = "Battle Pet Tamers", ["orderIndex"] = 13, ["flags"] = 0 }, { ["id"] = 290, ["name"] = "Battle Pet Tamers", ["orderIndex"] = 13, ["flags"] = 0 } } },
