[32016] = { ["id"] = 32016, ["name"] = "Elder Charms of Good Fortune", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 32016 }, ["description"] = "Greetings, <name>. I am privileged to offer you an excellent opportunity. Through the centuries, we've honed a method by which the very laws of chance themselves can be bent. With an Elder Charm of Good Fortune , valuable artifacts will find their way into your hands more frequently.", ["objectivesText"] = "Collect 50 Lesser Charms of Good Fortune . Progress: May these charms bring you great luck, <name>.", ["rewardGold"] = 456000, ["rewardXP"] = 471000, ["rewardItems"] = { 85330, 94222 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
