[32018] = { ["id"] = 32018, ["name"] = "His Name Was... Stormstout", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["storyline"] = { 32018 }, ["series"] = { 29907, 29908, 29909, 29911, 29912, 29940, 32019 }, ["description"] = "An unusual pandaren came through town a few days back. He told a better tale than Pan, drank twice as much as Lee, and then beat me up in front of the bar. All while his little niece made fun of us. It was awesome. They said they were headed to the Valley of the Four Winds . You should meet him! Just... watch out for that right hook.", ["objectivesText"] = "Speak with Chen Stormstout at the Thunderfoot Fields in the Valley of the Four Winds .", ["rewardGold"] = 10200, ["rewardXP"] = 12900, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard" },
[32019] = { ["id"] = 32019, ["name"] = "They Call Him... Stormstout", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5785, ["storyline"] = { 32019 }, ["series"] = { 29907, 29908, 29909, 29911, 29912, 29940, 32018 }, ["description"] = "Things were not always like this, <race>. Oh no, they were much, much worse. Not three weeks ago, we were under siege by saurok bandits. They stole our jade, befouled our food stores, and terrorized our cubs. We needed a hero, and a hero arrived. He drove back their forces, defeated their leader, and returned our stolen jade. All he asked in return was a serpent ride for his niece. I was never able to thank him. If you are headed to the Valley of the Four Winds , would you relay our thanks?", ["objectivesText"] = "Speak with Chen Stormstout at the Thunderfoot Fields in the Valley of the Four Winds .", ["rewardGold"] = 10200, ["rewardXP"] = 12900, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard" },
[32035] = { ["id"] = 32035, ["name"] = "Got Silk?", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 32035 }, ["series"] = { 30072 }, ["description"] = "Strange noises comin' from over at the Silken Fields. Strange smells, too. Almost makes you think that they could use a cash-strapped <class> to complete a few odd jobs for 'em. Make a few pieces of gold. Or not.", ["objectivesText"] = "Report to Silkmaster Tsai at the Silken Fields in Valley of the Four Winds .", ["rewardGold"] = 10200, ["rewardXP"] = 12900, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[32045] = { ["id"] = 32045, ["name"] = "Children of the Water", ["level"] = 87, ["requiredLevel"] = 86, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 32045 }, ["description"] = "We are all children of the water here in the Valley of the Four Winds . It nourishes us, it grows our vegetables, it brings us life. Some creatures, however, drink too deeply from the water. They grow too large, and must be eliminated before they cause havoc to those around them. I am but a simple stonecarver. You, on the other hand...", ["objectivesText"] = "Slay Kracor , Thundergill , and Succula .", ["rewardGold"] = 102000, ["rewardXP"] = 129000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[32097] = { ["id"] = 32097, ["name"] = "Short-Supply Reward", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["storyline"] = { 32097 }, ["rewardItems"] = { 69903, 90818 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
