[32105] = { ["id"] = 32105, ["name"] = "Pristine Monument Ledger", ["level"] = 90, ["requiredLevel"] = 85, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["storyline"] = { 32105 }, ["description"] = "This artifact has been restored to a remarkably excellent condition. Perhaps you will put it on display at the Seat of Knowledge, so that lorewalkers and archaeologists can study it.", ["objectivesText"] = "Put the artifact on display.", ["rewardItems"] = { 79869, 87399, 89209 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[32107] = { ["id"] = 32107, ["name"] = "Flying Tiger Gourami", ["requiredLevel"] = 85, ["faction"] = "none", ["requiredProfessions"] = { "fishing" }, ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 4, ["storyline"] = { 32107 }, ["description"] = "You've caught a unique fish... with wings. Perhaps it deserves the expert opinion of Nat Pagle in Anglers Wharf.", ["objectivesText"] = "Bring the Flying Tiger Gourami to Nat Pagle at Anglers Wharf.", ["rewardGold"] = 8000, ["rewardItems"] = { 86542 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[32114] = { ["id"] = 32114, ["name"] = "So, You Wanted to Test Daily Quests?", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["storyline"] = { 32114 }, ["description"] = "You wanna test dailies? Well alright then.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[32115] = { ["id"] = 32115, ["name"] = "Shackles of the Past", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 32115 }, ["description"] = "The mogu are a bunch of right bastards! They enslaved the pandaren who worked these caves even after their death. Ye' gotta go free their spirits! It's just not right. Be careful though... so much trauma, they don't know what's a friend and what's an enemy. So they'll probably fight back.", ["objectivesText"] = "Free 14 Troubled Slave Spirits .", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3282 } },
[32116] = { ["id"] = 32116, ["name"] = "Priorities, People!", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 32116 }, ["description"] = "When I ordered the excavation of the tunnel to the northwest, I thought we'd find something useful. Gold, iron... anything! Instead, we found mogu artifacts, and I get a bunch of dwarves from the Explorers' League to baby-sit. I hear from the soldiers that there's trouble in the mines. I have orders from Wrynn that I have to support the Explorers' League, but I can't spare any troops. Can you get down there and find out what's going on?", ["objectivesText"] = "Meet with Hilda Hornswaggle at the Ruins of Ogudei in Krasarang Wilds.", ["rewardGold"] = 11400, ["rewardXP"] = 23600, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3282 } },
[32118] = { ["id"] = 32118, ["name"] = "Taking Advantage", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 32118 }, ["series"] = { 32449 }, ["description"] = "The fools in the Explorers' League have excavated an ancient mogu ruin to the northeast. And - of course - in their bumbling, they've disturbed the mogu spirits within. We are going to take advantage of their ineptitude. Take this portal and meet with Kaelis Sunsoar , my contact within the ruins.", ["objectivesText"] = "Use the portal at Sparkrocket Outpost to meet with Kaelis Sunsoar at the Ruins of Ogudei in Krasarang Wilds.", ["rewardGold"] = 11400, ["rewardXP"] = 23600, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3283 } },
[32119] = { ["id"] = 32119, ["name"] = "It Is A Mystery", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 32119 }, ["description"] = "There's somethin' down there that was spookin' the workers. Some kind o' anomaly... looks like a ghost, or a magic spell... like nothing I've ever seen. I did manage to get a reading on it and put together this device to try to track it down. The display on the device will let you know roughly how close you are. Once you get close enough, you can use it to draw out the anomaly and get rid of it for good!", ["objectivesText"] = "Use Hilda's Anomaly Tracker to find and disperse an anomaly. Progress: We need to get that anomaly gone so our workers won't be spooked!", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 1217, 38133, 38173, 38174, 38202, 38763, 38764, 38765, 53404, 53435, 55896, 55897, 55898, 199210 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3282 } },
[32120] = { ["id"] = 32120, ["name"] = "Legacy of Ogudei", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 32120 }, ["description"] = "The ruins which we are occupying were built by Ogudei - an ancient mogu ruler. We know little about who he was, though the rise of the spirits in this area seems to indicate that it was related to spirit binding. When you destroy these spirits, a small amount of their essence will remain in this world. Bring it to us - we will analyze it and hopefully learn more about Ogudei's history - and his power.", ["objectivesText"] = "Collect 5 Ancient Mogu Essence . Progress: You'll need to destroy the spirits to collect their essence. Go to it.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 92704 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3283 } },
[32121] = { ["id"] = 32121, ["name"] = "The Spirit Trap", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 32121 }, ["description"] = "In the ruins there are a bunch of right nasty blue crystals. Look at 'em the wrong way and bloody angry ghosts run out at ya. I'm gonna be needing ye' to go in and clear some of them out so we can get our people back to work.", ["objectivesText"] = "Destroy 3 Spirit Traps .", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 86580, 92708 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3282 } },
[32122] = { ["id"] = 32122, ["name"] = "Ogudei's Lieutenants", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 32122 }, ["description"] = "When we dug through to an ancient section of the mogu ruins, that's when all this nasty business went down - and that's where the two worst o' these ghosties emerged. We need them gone, friend.", ["objectivesText"] = "Kill Meng-do, Strength of Mountains , and Gen-li, Twister of Words .", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3282 } },
[32123] = { ["id"] = 32123, ["name"] = "Death on Two Legs", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 32123 }, ["description"] = "The Alliance has made landfall. If we do not defeat them here, any hope of a Horde presence on this continent is lost. Go to the battlefield south of here and slay Alliance you find. Show them how any Horde who still stands on two legs will be the death of ten Alliance!", ["objectivesText"] = "Defeat 10 Alliance soldiers in Domination Point. Progress: The Alliance must find no purchase on these shores.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3283 } },
[32126] = { ["id"] = 32126, ["name"] = "Tear It Up", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 32126 }, ["description"] = "The Alliance may be cowardly, but they are not fools. Their assault would be formidable, if it were directed at lesser creatures. To sustain a siege and put pressure on our troops they are air dropping in supplies to support their ground forces. Search the beaches and docks to the south for any airdropped supplies and smash them. Let the Alliance see their food and ammunition destroyed before their eyes and despair.", ["objectivesText"] = "Destroy 8 Alliance Supply Drops .", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 21436, 21513, 26005, 26019, 26030 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3283 } },
[32128] = { ["id"] = 32128, ["name"] = "Another One Bites the Dust", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 32128 }, ["series"] = { 32235 }, ["description"] = "The Alliance have planted themselves off our southern coast and continue to pepper our ground forces with cannon fire. Let us see how great their siege is without such support. Board the enemy vessels and destroy their reserve ammunition. This will take the teeth out of their bite.", ["objectivesText"] = "Detonate the explosive cargo of The Defiant and Valor's Edge.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3283 } },
[32129] = { ["id"] = 32129, ["name"] = "Defense Daily 06", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["storyline"] = { 32129 }, ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[32130] = { ["id"] = 32130, ["name"] = "Good Luck, Have Fun", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 32130 }, ["description"] = "I've got some customers lined up that wanna collect some good old fashioned ears. But not any old ears. They only want the absolute waxiest ears money can buy! Guess they think they're lucky or something'. Anyways, I need you to go get 'em for me. I don't want to hurt any animals, so you'll need to get 'em from the Alliance over at Lion's Landing. Have fun - and remember, only bring me the waxiest!", ["objectivesText"] = "Collect 10 Extra-Waxy Alliance Ears at Lion's Landing in Krasarang Wilds. Progress: Ears, <name>, I wanna see some ears!", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 92474 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3283 } },
[32131] = { ["id"] = 32131, ["name"] = "We Require More Minerals!", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 32131 }, ["description"] = "Gnomes are excavating a stone quarry to the northeast. They're building stuff with it! <Zazzix rolls his eyes.> They're too stupid to realize it's special mogu stone for creating animated statues. WE can mix with a little Goblin magic juice to make some real big explosions! But the stuff is heavy. They've got some of their stupid bomb-bots there for excavating the stone. Blow 'em up near slabs and you'll get chunks small enough to carry. Or, just kill 'em and take it. Whatever works.", ["objectivesText"] = "Collect 20 Animatable Stone chunks from the Lion's Landing quarry. Lion's Landing Engineers carry them, or you can destroy stone slabs with collateral damage to blow them into chunks you can carry. Progress: You got some stone? I wanna blow stuff up!", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 91823 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3283 } },
[32132] = { ["id"] = 32132, ["name"] = "Worker Harassment", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 32132 }, ["description"] = "Our goblin friends do not have the grasp of strategy necessary to win a long term engagement, I'm afraid. The key to eliminating any permanent establishment is to attack their ability to replenish their troops and to rebuild. In this case, that means taking out their Peasants. Kill them, and you weaken the foundation. The rest of the keep is bound to crumble.", ["objectivesText"] = "Kill 30 Lion's Landing Peasants.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3283 } },
[32133] = { ["id"] = 32133, ["name"] = "Sentry Wards", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 32133 }, ["description"] = "We've spotted heavy air support over their base, in the form of way too many dwarves on way too many griffons. Means we can't get any vision of the area from above. A troll... friend of mine gave us a set of Sentry Wards, which we can use to spy on their base and get a vantage point on what's going on in there. Bad news, friend - you're going to be the one going in there.", ["objectivesText"] = "Place Sentry Wards on the Docks, in the Town Hall, and on the Second Floor of the Barracks at Lion's Landing.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3283 } },
[32134] = { ["id"] = 32134, ["name"] = "Hard Counter", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 32134 }, ["description"] = "We've managed to get some Demolishers on the beach, but the stupid dwarves are also out there with their stupid mortar tubes, preventing the Demolishers from pushing forward and assaulting the keep itself! Get out there, kill some dwarves, and blow up some mortar tubes.", ["objectivesText"] = "Kill 8 Lion's Landing Mortar Team Engineers and destroy 2 Lion's Landing Mortar Tubes.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3283 } },
[32135] = { ["id"] = 32135, ["name"] = "Hero Killer", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 32135 }, ["series"] = { 32450 }, ["description"] = "There are some situations in which taking out one of their soldiers is more important than killing hundreds. They've deployed some of their heroes to the battlefield to help rally their defenders. Not only will killing them soften their defense, it will also leave their morale crippled. So go, take one down for me. You can handle it.", ["objectivesText"] = "Kill an Alliance Hero at Lion's Landing in Krasarang Wilds.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3283 } },
[32136] = { ["id"] = 32136, ["name"] = "Work Order: Fuel", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 32136 }, ["description"] = "Our fuel supplies are running low. Without fuel we won't be able to operate the machinery that's building this place. They might even expect me to start helping them build! I was not built for manual labor! See these nails?! I just had them done! Get down to the refinery and get this fuel order filled! Hurry! They were fitting me for a tool-belt this morning. It didn't even match my outfit!", ["objectivesText"] = "Find Grizzle Gearslip in Bilgewater Beach.", ["rewardGold"] = 11400, ["rewardXP"] = 23600, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3283 } },
[32137] = { ["id"] = 32137, ["name"] = "Runnin' On Empty", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 32137 }, ["description"] = "I've never seen this quality of oil! Problem is the oil needed a little extra refinin'. I heard of this system where you use ocean water to speed up the process. I don't have time to waste down here, so I just threw the barrels into the bay. Pretty good idea, I know. Problem is, I'm not sure how to pull it out of the bay... Maybe someone of your expertise could help me out.", ["objectivesText"] = "Retrieve 9 \"Distilled\" Fuel Barrels from the Blacksand Spillway. Progress: So he found a use for the bay after all? Waste not, want not I guess!", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 91846 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3283 } },
[32139] = { ["id"] = 32139, ["name"] = "Stacked!", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 32139 }, ["series"] = { 32138 }, ["description"] = "We just filled an order this morning. How could they possibly need more already?! My team has been workin' double-time to get these trees chopped and processed. Problem is we have an infestation of Lion's Landing troops down here. I already risked my neck once today, I'm not goin' back out there! Goob will go with you and help you fill this order. He's not the brightest, but he can do the heavy liftin'.", ["objectivesText"] = "Gather 9 Pieces of Domination Point Lumber from the Lumber Farm.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3283 } },
[32140] = { ["id"] = 32140, ["name"] = "Work Order: Iron", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 32140 }, ["series"] = { 32141 }, ["description"] = "When they said they found some amazing rocks in that mine I envisioned diamonds. Everyone knows all mines have diamonds, silly! At the very least rubies! Instead, all I got was this strange iron! What am I supposed to do with this? Oh well, no one said this job would be glamorous. I just do what I can to add a little class. We just got another work order for iron. Go see Daxil down near Oregrind's Dig and get it filled pronto!", ["objectivesText"] = "Find Daxil \"The Gem\" Oregrind near Oregrind's Dig.", ["rewardGold"] = 11400, ["rewardXP"] = 23600, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3283 } },
[32141] = { ["id"] = 32141, ["name"] = "Power Metal", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 32141 }, ["series"] = { 32140 }, ["description"] = "<Daxil narrows her eyes and speaks in a hushed tone.> Sometimes we dig too deep, <class>. Sometimes, we uncover something so horrible we wish we hadn't started diggin'... Just kidding! I mean, don't get me wrong, we did find something unexpected. The ore we're finding down there is not your average run-of-the-mill iron. There is just one problem; Shale Spiders! We're struggling to keep these orders filled. Maybe you can lend us a hand?", ["objectivesText"] = "Obtain 7 chunks of Energized Ore from Oregrind's Dig. Progress: Did you happen to find anything sparkly while you were down there?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 91848 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3283 } },
[32142] = { ["id"] = 32142, ["name"] = "We Will Rock You", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 32142 }, ["series"] = { 32451 }, ["description"] = "The orcs can NOT be allowed a foothold in this land. They will defile it just as they did Kalimdor. $p, I need boots on the ground and horde in their graves. Get down to the coastline and bring the full force of Alliance wrath down on their heads! Slay any orcs you find. Take the wind out of their sails. For the King!", ["objectivesText"] = "Slay 10 Orcs at Domination Point. Progress: Glory to the Alliance.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3282 } },
[32143] = { ["id"] = 32143, ["name"] = "A Kind of Magic", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 32143 }, ["series"] = { 32145 }, ["description"] = "Greetings $p! I have heard a lot about your success in the field. I would like to use your services to test my latest \"Siege-o-Matic\", a device of terrible and varied abilities. I promise it is mostly harmless to its users. When you are around Domination Point be on the look out for my Scout-o-Meters. They have been dispatched to get info on good siege targets. When you find one, activate it and I will pilot a Siege-o-Matic to your location. See you in the field... as it were.", ["objectivesText"] = "Find the three Scout-o-Matics in Domination Point.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3282 } },
[32144] = { ["id"] = 32144, ["name"] = "Under Pressure", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 32144 }, ["description"] = "The Horde are consumed by pride and will fight to the death without a second thought. We need to find a way to break their will that does not involve massive loss of our numbers. Look for the Horde supplies along the coastline and near their ships. Smash their supplies. Nothing breaks the will of a defender like seeing their hope of food go up in a puff of smoke. When you are done, find Sully behind enemy lines. He has the next task for you.", ["objectivesText"] = "Destroy 8 Horde Supply Crates .", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3282 } },
[32145] = { ["id"] = 32145, ["name"] = "Don't Lose Your Head", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 32145 }, ["series"] = { 32143 }, ["description"] = "My probes have detected three very dangerous targets in the courtyard of Domination Keep. They have an ogre emissary, a Kor'kron officer, and an insane goblin bomb maker. My siege-o-matics are not ready for one on one combat so it is up to you to eliminate the targets. Good luck! Report back to me on the Skyfire when done.", ["objectivesText"] = "Defeat Stone Guard Ruk'ra , Bombgineer Snicklefritz, and Or'Dac .", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3282 } },
[32146] = { ["id"] = 32146, ["name"] = "Hammer to Fall", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 32146 }, ["description"] = "It looks like the Horde thinks they can hide behind their heavy hitting mooks. The mooks are tough, powerful, and dumber than an ogre with a hangover. Go down there and bring the hammer of the Alliance fury down on them!", ["objectivesText"] = "Kill 5 Heavy Mooks .", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3282 } },
[32147] = { ["id"] = 32147, ["name"] = "Attack Daily 06", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["storyline"] = { 32147 }, ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[32148] = { ["id"] = 32148, ["name"] = "Attack! Move!", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 32148 }, ["description"] = "Sure, they've got about plenty of grunts out there, pounding on our door, waiting to cut our heads off. I'm not worried about grunts. But they've got shamans and raiders, too. The shamans use their magic to empower the grunts, and the raiders are fast and specialize in taking out our buildings. I need you to get out there and kill some of those shamans and raiders. Go! Attack! Move!", ["objectivesText"] = "Kill 12 Dominance Shamans or Dominance Raiders.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3282 } },
[32149] = { ["id"] = 32149, ["name"] = "Resource Gathering", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 32149 }, ["description"] = "Oh, the poor peasants... They are cowards, yes, of course. But they don't know how to fight, and they go out to collect lumber for our efforts... the Horde targets them... It's just awful all around! But, we need that lumber if we're going to hold out. Go out and collect any they've dropped.", ["objectivesText"] = "Collect 12 Lion's Landing Lumber by recovering it from piles of Hastily Abandoned Lumber. Progress: Did you gather the lumber yet?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 91907 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3282 } },
[32150] = { ["id"] = 32150, ["name"] = "Supply Block", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 32150 }, ["description"] = "The Horde decided to put goblins in charge of their logistics. And where you have goblins, you have carelessly placed explosives. Scouts have reported that they have their supplies in carts that also contain demolisher ammunition. Look at those crates the wrong way, and they'll blow sky high. With enough Horde resources destroyed, we'll put a time limit on their attack and save lives. So go and take out those carts!", ["objectivesText"] = "Destroy 8 Domination Point Supply Carts .", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3282 } },
[32151] = { ["id"] = 32151, ["name"] = "Tower Defense", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 32151 }, ["description"] = "The gnomes are running our quarry operation to the northwest. The stone there is especially tough - the gnomes tell me the mogu used it to fashion their constructs. I don't know. What I do know is that we use that stone to build our towers, and the Horde has dispatched the Bilgewater goblins to steal it from us. Get out there and get some back. By the way - collateral damage may break up the stone slabs there. If so, pick that up, too.", ["objectivesText"] = "Collect 20 Animatable Stone at the Lion's Landing Quarry from Bilgewater Goblins or by destroying stone slabs there with collateral damage. Progress: You brought us the stone yet?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 93022 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3282 } },
[32152] = { ["id"] = 32152, ["name"] = "Siege Damage", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 32152 }, ["description"] = "The Horde got the bright idea to send Bilgewater goblins to attack our quarry. They've been packing heavy explosives - heavy explosives that will react with the ammunition in their demolishers. Kill the Bilgewater goblins until you find an explosive, plant it on one of the demolishers... and BOOM! Siege ended.", ["objectivesText"] = "Find a Bilgewater Blasting Cap on a Bilgewater Sapper, and then plant it on a Domination Point Demolisher . Progress: We need you to take out those demolishers, soldier!", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 92493 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3282 } },
[32153] = { ["id"] = 32153, ["name"] = "Hero Killer", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 32153 }, ["description"] = "Look, you're tough. Tougher than the rest of the men and women I've got here. Which means I need you for a special mission. The Horde is throwing their best against us. Heroes of their armies - Blademasters, Tauren Chieftans, you name it. I need you to go take one out. It'll be a huge blow, not just to their offensive but also to morale.", ["objectivesText"] = "Kill a Horde Hero.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3282 } },
[32155] = { ["id"] = 32155, ["name"] = "Necessary Breaks", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["storyline"] = { 32155 }, ["description"] = "It goes against me nature to break things on purpose, but in this case it's necessary. That rig the goblins are usin' is held together by a wish an' some bubblegum. We need to exploit the situation a little more. We have some saboteurs down there already, but we can use someone of your expertise to hurry the job along. Get down there an' start breakin' and stealin' some valves!", ["objectivesText"] = "Steal 7 Rusty Valves from the fuel operation on Bilgewater Beach.", ["rewardGold"] = 114000, ["rewardXP"] = 200, ["rewardItems"] = { 93191 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2LabelIDs"] = { 3282 } },
[32156] = { ["id"] = 32156, ["name"] = "It's Only Right", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 32156 }, ["description"] = "This is barbaric warfare, <class>! We've lost so many trying to keep the Bilgewater operation from spreading any further. Those fallen soldiers fought honorably and deserved to be given their last rights. At the very least we need to be able to notify their next of kin. Perhaps you can collect their identification tags so we can honor them in some small way.", ["objectivesText"] = "Retrieve 7 Shieldwall Soldier Dog Tags from the Fallen Shieldwall Soldiers in and around Bilgewater Beach. Progress: Even warfare should have some courtesies.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 93009 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3282 } },
[32157] = { ["id"] = 32157, ["name"] = "The Only Good Goblin...", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 32157 }, ["series"] = { 32452 }, ["description"] = "The destruction in Krasarang is unforgivable, <class>. The only way to put an end to this is to destroy the Bilgewater operation. This is for the greater good of Pandaria and the Alliance. Go to Bilgewater Beach and cut them down! No doubt the Horde will come to their assistance. Destroy them!", ["objectivesText"] = "Kill 10 Bilgewater Goblins in and around Bilgewater Beach.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3282 } },
[32158] = { ["id"] = 32158, ["name"] = "Two Step Program", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 32158 }, ["description"] = "Shredmaster Packle is responsible for much of the devastation down there, <class>. Rumor has it he modified the shredders to work more quickly with less regard for the collateral damage they can inflict. Imagine the agony the trees must endure being hacked at. It will be difficult to recover from this level of destruction. The first step in any recovery is acknowledging the problem. Step two is eliminating that problem.", ["objectivesText"] = "Destroy Shredmaster Packle in Quickchop's Lumber Farm.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3282 } },
[32159] = { ["id"] = 32159, ["name"] = "Circle of Life", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["storyline"] = { 32159 }, ["description"] = "We should attempt to offset the destruction being wrought on this continent as much as possible. For every tree they destroy, we will plant a new one! Take these seeds and begin the regrowth process, <name>. Do not linger for too long though. Nature is unpredictable, and no doubt the anger and hate exuding from Domination Point has seeped into the ground. I cannot guarantee that the plant that springs from these seeds will not be hostile.", ["objectivesText"] = "Plant 11 Energized Seeds near Quickchop's Lumber Farm.", ["rewardGold"] = 114000, ["rewardXP"] = 200, ["rewardItems"] = { 92558 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2LabelIDs"] = { 3282 } },
[32161] = { ["id"] = 32161, ["name"] = "Beastmaster's Hunt: The Crane", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 32161 }, ["description"] = "Along with the snare, you get some advice on crane hunting: The greatest cranes of the Krasarang Wilds are not tempted by simple things like food. You will need to play on the creatures' emotions if you wish to draw them from their hiding places in the jungle. Cranes abound on both the Cradle of Chi-ji and the Narsong Spires, both of which can be found east of here. Pluck those cranes' quills, then place them in a visible spot near the Crane Temple. Your quarry will come running to you.", ["objectivesText"] = "Obtain 5 Pristine Golden Crownfeathers and a Pristine Jet Crownfeather . Progress: This is the spot, near the Crane Temple.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 74839, 91814, 91815, 91819, 91821, 91822, 91838, 91877 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3283 }, ["startItems"] = { 91819 } },
[32162] = { ["id"] = 32162, ["name"] = "Beastmaster's Hunt: The Tiger", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6138, ["storyline"] = { 32162 }, ["description"] = "Along with the trap, you get some advice on tiger hunting: Tigers are gluttonous creatures, and large game is hard to come by in this jungle. If you wish to tempt the most elder cats out of their hiding places, you may do so with a meal. Just on the other side of the Serpent's Spine, you will find a herd of yaks. Slay them, bring their meat to the jungle's edge, set up your trap, and wait.", ["objectivesText"] = "Obtain 25 Unbruised Yak Haunches. Progress: This looks like an ideal spot for a tiger trap.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 91816, 91819, 91821, 91822, 91838 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3283 }, ["startItems"] = { 91821 } },
[32163] = { ["id"] = 32163, ["name"] = "Beastmaster's Hunt: The Crab", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 32163 }, ["description"] = "Along with the crate, you get some advice on crab hunting: Crabs are strange, primordial creatures, with wildly different motivations than you or I. Small crabs are easy to find and hunt, but the large ones hide beneath the sands, out of danger and out of our reach. To draw them out, we play on their sense of smell. The Unga villagers to the southeast allow their fish to ferment before they eat them. Bring enough rotten fish together, and you will catch yourself a colossal crab.", ["objectivesText"] = "Obtain 30 Funky Rotten Fish from Unga Villagers in Unga Ingoo. Progress: This looks like a good place to catch a crab.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 91817, 91819, 91821, 91822, 91838 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3283 }, ["startItems"] = { 91822 } },
[32164] = { ["id"] = 32164, ["name"] = "Beastmaster's Hunt: The Crane", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 32164 }, ["description"] = "Along with the snare, you get some advice on crane hunting: The greatest cranes of the Krasarang Wilds don't care about simple things like food. You need to play on the creatures' emotions if you want to draw them out of the jungle. There's plenty of cranes on the Cradle of Chi-ji and on the Narsong Spires, both to the west of here. Pluck some of those cranes' quills, then put them in a visible spot near the Crane Temple. Your quarry will come running to you.", ["objectivesText"] = "Obtain 5 Pristine Golden Crownfeathers and a Pristine Jet Crownfeather . Progress: This is the spot, near the Crane Temple.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 723, 74839, 79867, 81203, 81221, 88567, 89112, 91814, 91815, 91819, 91821, 91822, 91838, 91854 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3282 }, ["startItems"] = { 91854 } },
[32165] = { ["id"] = 32165, ["name"] = "Beastmaster's Hunt: The Tiger", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6138, ["storyline"] = { 32165 }, ["description"] = "Along with the trap, you get some advice on tiger hunting: Tigers are gluttons, and big game is hard to come by in this jungle. If you want to tempt the elder cats out of their hiding places, you need a tempting meal. Just on the other side of the Serpent's Spine, you can find a herd of yaks. Kill them, bring their meat to the jungle's edge, set up your trap, and wait.", ["objectivesText"] = "Obtain 25 Unbruised Yak Haunches. Progress: This looks like an ideal spot for a tiger trap.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 91816, 91855 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3282 }, ["startItems"] = { 91855 } },
[32166] = { ["id"] = 32166, ["name"] = "Beastmaster's Hunt: The Crab", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 32166 }, ["description"] = "Along with the crate, you get some advice on crab hunting: Crabs are strange, old creatures, with different motivations than us. Small crabs are easy to find and hunt, but the big ones hide beneath the sands, out of danger and out of our reach. To draw them out, we play on their sense of smell. The Unga villagers to the southwest allow their fish to ferment before they eat them. Bring enough rotten fish together, and you will catch yourself a colossal crab.", ["objectivesText"] = "Obtain 30 Funky Rotten Fish from Unga Villagers in Unga Ingoo. Progress: This looks like a good place to catch a crab.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 91817, 91856 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3282 }, ["startItems"] = { 91856 } },
[32167] = { ["id"] = 32167, ["name"] = "Ancient's Fall", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 32167 }, ["description"] = "The crane has fallen.", ["objectivesText"] = "Speak with Jorn Skyseer at Domination Point in Krasarang Wilds.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3283 } },
