[32189] = { ["id"] = 32189, ["name"] = "A Shabby New Face", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 32189 }, ["description"] = "A strange fellow in a pointy hat showed up this morning trying to sell some kinda special seeds. Claimed they were magic. I welcome a little competition - business is business, after all - but this gentleman had a certain... shabby look to him. Oh, and he stunk somethin' FIERCE. Would you check up on him, just to make sure he's on the level? He's over there by Jian Ironpaw, making a meal out of the samples.", ["objectivesText"] = "Speak with Barnaby Fletcher in Halfhill Market.", ["rewardGold"] = 11400, ["rewardXP"] = 23600, ["rewardItems"] = { 91806, 91850, 91860, 91861, 91862, 91863, 91864, 91865, 91866 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[32195] = { ["id"] = 32195, ["name"] = "Anger Remains", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5841, ["storyline"] = { 32195 }, ["description"] = "From the looks o' our initial survey, this entire area is humming with residual sha energy. You know what ta do, <name>. Destroy any last traces ye can find o' the stuff!", ["objectivesText"] = "Kill 27 Angerlings .", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5841 } }, ["questType"] = "standard" },
[32197] = { ["id"] = 32197, ["name"] = "Mystery Meatloaf", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 32197 }, ["description"] = "We've been gettin' complaints right and left that the Boss-Lady gets all the good grub and leaves the scraps for the others. Between you and I, they may be onto somethin' here. I don't even get to eat as good as she does! We need somethin' Sezik can make a lot of that at least attempts to disguise how inedible the food is here... I got it! Mystery Meatloaf!", ["objectivesText"] = "Obtain 7 Chunks of Mystery Meat from the local wildlife. Progress: What do ya got for me now?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 91874 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3283 } },
[32198] = { ["id"] = 32198, ["name"] = "One Magical, Flying Kingdom's Trash...", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 32198 }, ["description"] = "Before we enter into a business relationship, I am required by the terms of my rehabilitation program to inform you that I am a recovering potion addict. There, now that THAT's out of the way, let's talk portals! You see, the big portals in the cities - the ones running all day and night - leak tons of magical energy. It crystallizes around the edges and is generally regarded as trash. But I noticed during my, uh... hiatus in the sewers of Dalaran, that these shards still had power. Interested?", ["objectivesText"] = "Speak with Barnaby Fletcher to learn more about Portal Shards.", ["rewardGold"] = 11400, ["rewardXP"] = 23600, ["rewardItems"] = { 91806, 91850, 91860, 91861, 91862, 91863, 91864, 91865, 91866 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[32199] = { ["id"] = 32199, ["name"] = "Krasarang Steampot", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 32199 }, ["description"] = "The Boss-Lady desires crabs! Why are you looking at me like that? It's not uncommon for a classy person, such as her loveliness, to want crab for dinner. What did you think I meant? There are some big crabs wandering around on Bilgewater Beach that should be suitable for her refined palate. Bring Sezik the best crab meat you can find!", ["objectivesText"] = "Obtain 5 chunks of Polluted Viseclaw Meat from the Viseclaw crabs on Bilgewater Beach. Progress: Boss-Lady wants a steampot does she? Well, maybe she should come down here and make it herself!", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 91869 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3283 } },
[32200] = { ["id"] = 32200, ["name"] = "Dangers of Za'Tual", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32200 }, ["series"] = { 32729 }, ["description"] = "<name>, what I ask of you is little short of genocide, but it is a task that must be done. Find trolls within their town or on the beach and slay them, for the good of us all.", ["objectivesText"] = "Slay 12 Trolls in Za'Tual. Progress: Have the Zandalari met their fate, <name>?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3286 } },
[32201] = { ["id"] = 32201, ["name"] = "Grave Circumstances", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32201 }, ["series"] = { 32728 }, ["description"] = "The Court of Bones crawls with mogu forces. Endlessly do they perform their rituals of lightning and thunder. If our mission to take this island is to succeed, then we cannot allow them to hold such a strategic position. They must be eliminated.", ["objectivesText"] = "Kill 10 Shan'ze Gravekeepers, Shan'ze Soulrippers , or Shan'ze Thundercallers. Progress: The mogu are powerful, but with cunning and tenacity, we can defeat them.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3286 } },
[32204] = { ["id"] = 32204, ["name"] = "The Skumblade Threat", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32204 }, ["series"] = { 32730 }, ["description"] = "Ihgaluk Crag has no end of saurok. Those beasts attack my men and spread their disease into nearby water and wildlife, interfering with our operations. Thin their numbers, <name>. Once the Horde takes full control of this island, we can look for more permanent solutions.", ["objectivesText"] = "Slay 10 Skumblade saurok .", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3286 } },
[32205] = { ["id"] = 32205, ["name"] = "Gather Scout Reports", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["storyline"] = { 32205 }, ["rewardGold"] = 114000, ["rewardXP"] = 200, ["rewardItems"] = { 93805 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2LabelIDs"] = { 3286 } },
[32206] = { ["id"] = 32206, ["name"] = "This Just Won't Do", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32206 }, ["description"] = "The Zandalari here are very powerful, <class>. They should not be underestimated. We cannot afford to ignore them as a threat simply because they do not wield swords. More arrive every day, and with them centuries of magic knowledge. This threat must be dealt with, and quickly. Aid us in clearing this area, <class>. Perhaps we can even learn something from them in the process.", ["objectivesText"] = "Kill any 8 Zandalari trolls within Conqueror's Terrace.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3286 } },
[32207] = { ["id"] = 32207, ["name"] = "Saur Loser", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32207 }, ["description"] = "Inside the Beast Pens you will encounter some of the most skilled beast tamers in the Zandalari military. They are trained to kill with axe, beast, and claw. This is where they build their cavalry. We need you to kill any Zandalari you find in there before they can get their mounted monstrosities out into the open battlefield.", ["objectivesText"] = "Defeat 10 Zandalari trolls in the Beast Pens.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3286 } },
[32208] = { ["id"] = 32208, ["name"] = "Maximum Capacitor", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32208 }, ["series"] = { 32209, 32292 }, ["description"] = "The mines north of here are being used to extract Ghost Iron ore and energize it with lightning energy. We need to destroy the drills they use to extract the ore. They are impervious to normal attack, but can be overloaded using the proper methods. Oh - and while you're there, take out whoever is running the operation.", ["objectivesText"] = "Interact with the three lightning drills in the Ghost Iron Mines to destroy them, and kill Metal Lord Mono-Han .", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3286 } },
[32210] = { ["id"] = 32210, ["name"] = "Kill mogu boss for key, use object behind jumping puzzle", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["storyline"] = { 32210 }, ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 94220 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[32213] = { ["id"] = 32213, ["name"] = "Old Enemies", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32213 }, ["description"] = "So Jaina and the Kirin Tor think they can push us out again? I will not stand by and allow them to repeat the events of Dalaran! This time we fight back! This time we do the pushing... Go to Violet Rise and slay any Kirin Tor agent you find.", ["objectivesText"] = "Kill 10 Kirin Tor units or players on the Isle of Thunder .", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "pvp", ["db2LabelIDs"] = { 3286 } },
[32214] = { ["id"] = 32214, ["name"] = "Bilgewater Infiltrators", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 32214 }, ["description"] = "There is nothing more unnerving than walking along, minding your own business, and hearing someone following you. I swear I hear it all over the place down here! We're being watched! I have a feeling the entire beach is just crawling with spies! I made some improvements to our infrared goggle tech to put an end to the sabotogery. That's right sabotogery! Now I just need you to try 'em out! Feel free to dispose of any spies you happen to catch.", ["objectivesText"] = "Kill 10 SI: 7 Saboteurs around Domination Point and Bilgewater Beach.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 92475 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3283 } },
[32215] = { ["id"] = 32215, ["name"] = "Heinous Sacrifice", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32215 }, ["description"] = "The Zandalari perform heinous rites against our people! They must be stopped! Delve into the heart of the Za'Tual and destroy their altars.", ["objectivesText"] = "Destroy the Zandalari sacrificial altars.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3286 } },
[32217] = { ["id"] = 32217, ["name"] = "Dark Offerings", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32217 }, ["description"] = "The spirtibinders of the Zandalari perform sacrificial rites to appease the loa and their vile gods. These dark rituals involve the sacrifice of our people. Destroy any offerings you can find among their tents in Za'Tual and perhaps we can stall the sacrifices.", ["objectivesText"] = "Destroy 6 Zandalari Offerings.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3286 } },
[32218] = { ["id"] = 32218, ["name"] = "Ashes of the Enemy", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32218 }, ["description"] = "The mogu here at the Court of Bones are bolstering their army by resurrecting the spirits of their dead. We cannot allow them to revive their fallen warriors. Take this torch and burn any mummified corpses that you can find. We will destroy our enemies before they have a chance to rise.", ["objectivesText"] = "Burn 8 Mummified Remains .", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 93751 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3286 } },
[32219] = { ["id"] = 32219, ["name"] = "Stone Cold", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32219 }, ["description"] = "Our assault on the Court of Bones continues. Our progress remains slow, but measurable. Unfortunately, we've received several reports of stone quilen statues coming to life without warning. I can't have these quilen threatening my research expedition. Venture into the Court of Bones and destroy any quilen statues that you can find.", ["objectivesText"] = "Destroy 8 Grave Guardians . Progress: Although the stone quilen are dangerous, I may still be able to glean knowledge from their shattered pieces.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3286 } },
[32220] = { ["id"] = 32220, ["name"] = "Soul Surrender", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32220 }, ["description"] = "We assault the mogu at the Court of Bones, but I fear we merely send them fodder for their abominable rituals. The mogu do not merely kill their prisoners - they steal their souls and imbue them in machinations of stone, or reforge the fallen into ghostly tools of war. Horde or Alliance, it matters not. We cannot allow the mogu to bolster their numbers. Go into the crypts. Free any prisoners that are still living.", ["objectivesText"] = "Save 6 Sunreaver Scouts or Silver Covenant Scouts.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3286 } },
[32221] = { ["id"] = 32221, ["name"] = "Storming the Beach", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 32221 }, ["description"] = "Our lumber supply is being jeopardized by constant attacks from Lion's Landing. We've been able to keep the attackers at bay, but it's time to really show 'em some muscle! Head down to the coast and start splitting some skulls!", ["objectivesText"] = "Kill any 10 Shieldwall Forces including SI: 7 Saboteurs in and around Bilgewater Beach.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3283 } },
[32222] = { ["id"] = 32222, ["name"] = "Wanted: Chief Engineer Cogwrench", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 32222 }, ["description"] = "Wanted for crimes against the Bilgewater Operation! Chief Engineer Cogwrench was last seen building what appeared to be a giant spider tank on the edge of Bilgewater Beach. Extreme caution should be used when approaching. A large reward has been posted for Cogwrench's destruction.", ["objectivesText"] = "Destroy Chief Engineer Cogwrench at the edge of Bilgewater Beach.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3283 } },
[32223] = { ["id"] = 32223, ["name"] = "Wanted: Lieutenant Ethan Jacobson", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 32223 }, ["description"] = "Wanted for crimes against the Domination Point forces! Lieutenant Ethan Jacobson is responsible for leading several ground assaults against the Bilgewater lumber operation. Last spotted occupying an island south of Quickchop's Lumber Farm.", ["objectivesText"] = "Destroy Lieutenant Ethan Jacobson in the Southern Isles south of Quickchop's Lumber Farm. Progress: Do not return without his blood on your hands!", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3283 } },
[32224] = { ["id"] = 32224, ["name"] = "Rise No More!", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32224 }, ["description"] = "Have you seen the ghosts wandering the graveyard? They are risen ancestors , the spirits of slain mogu who have been called back to this world. When angered, they attack swiftly and silently, and their numbers increase by the day. They do not belong here. Destroy them, and send them back beyond the grave.", ["objectivesText"] = "Kill 15 Risen Ancestors . Progress: How is the situation at the graveyard?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3286 } },
[32225] = { ["id"] = 32225, ["name"] = "The Call of Thunder", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32225 }, ["description"] = "Within the graveyard, in the deepest ruins of their western crypt, the Thunder King's most powerful sorcerers are charging a lightning rod with crackling electricity. We suspect that this weapon is meant to rain destruction on our stronghold at Dawnseeker Promontory. There is no time to delay. You must stop their ritual at once.", ["objectivesText"] = "Stop the Shan'ze Thundercallers' ritual.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 52596, 52622 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3286 } },
[32226] = { ["id"] = 32226, ["name"] = "Into the Crypts", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32226 }, ["description"] = "The Reliquary is having a field day out here, literally! Every day, the researchers find more relics to study and catalog. Recently, one of our adventurers found this scroll at the Court of Bones. I believe that this incantation can be used to call beyond the grave. And if my Mogu is up to date, I'd say you should use it in the last room in the Hall of the Exalted. Would you be willing to test out my theory?", ["objectivesText"] = "Use the Incantation of Gura in the Hall of the Exalted, then defeat Gura the Reclaimed .", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 93803 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3286 } },
[32227] = { ["id"] = 32227, ["name"] = "Preventing a Future Threat", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32227 }, ["description"] = "The creatures the Zandalari ride don't start out so big, nor do they start out the vicious and loyal creatures they become. If you can frighten some of the hatchling skyscreamers away from the beach, perhaps they will have a chance at a real life.", ["objectivesText"] = "Frighten 12 Hatchling Skyscreamers by running near them. Progress: Were you able to frighten off the hatchlings?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3286 } },
[32228] = { ["id"] = 32228, ["name"] = "The Shuddering Moor", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32228 }, ["description"] = "There is an immense beast in the swamp. It has not yet marched upon us, but I place no stock that we will continue to be so fortunate. Strike it down before it grows hungry enough to brave our defenses.", ["objectivesText"] = "Kill the Mighty Devilsaur .", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 94222 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3286 } },
[32229] = { ["id"] = 32229, ["name"] = "Kill Roaming Troll War Party", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["storyline"] = { 32229 }, ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[32230] = { ["id"] = 32230, ["name"] = "The Zandalari Colossus", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32230 }, ["description"] = "The trolls have dispatched one of their immense constructs on the southern road, blocking our passage around the island. See to it that the road is cleared, <class>.", ["objectivesText"] = "Destroy the Zandalari Colossus .", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3286 } },
[32233] = { ["id"] = 32233, ["name"] = "Very Disarming", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["storyline"] = { 32233 }, ["description"] = "Look around you, <class>. What do you see? I see an opportunity. The casters here work to imbue the Zandalari weapons with powerful magic. As if a sharp blade isn't enough to cut even the strongest foe down to size. In my scouting I've noticed the weapons are not very well guarded. This is where you come in... If we can steal a few of these weapons we may be able to use them. At the very least they are out of enemy hands.", ["objectivesText"] = "Steal 7 Loa-Infused Blades from Conqueror's Terrace.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 93736 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2LabelIDs"] = { 3286 } },
[32234] = { ["id"] = 32234, ["name"] = "Knowledge Is Power", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32234 }, ["description"] = "The Zandalari here practice a different kind of magic. We must understand it before we can defeat it, <class>. Their control over the arcane and shadow is impressive. I wish to learn how they have achieved what so many others have not. I believe their ritual artifacts may hold the answers I seek. Bring me a sampling of the artifacts you find, and I will ensure you are rewarded properly.", ["objectivesText"] = "Retrieve 6 Ritual Artifacts from around Conqueror's Terrace. Progress: Did you find the artifacts?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 93735 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3286 } },
[32235] = { ["id"] = 32235, ["name"] = "Flash! Aaaaaahhhh!", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 32235 }, ["series"] = { 32128 }, ["description"] = "The gnomes have brought their flying contraptions. I want my skies CLEAR! Get up there on whatever mount you have with you and destroy those paltry devices. You may use this grog I \"acquired\" from our goblin allies. It would be better served blasting down gyrocopters than in the gullet of those little green fiends.", ["objectivesText"] = "Use the Bilgewater Molotovs to destroy 6 Skyfire Gyrocopter X2s . Progress: Hellscream's eyes are upon you.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 92019 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3283 } },
[32236] = { ["id"] = 32236, ["name"] = "Bug Off!", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 32236 }, ["description"] = "This cave is crawlin' with nasty shale spiders! How's a girl supposed to get any work done with them gobbling up the miners AND the ore?! This seemed like a good opportunity to use my newest invention, Bug Off. See, all you have to do is spray this stuff all over the shale spiders. They hate it and it doesn't seem to have many long term side-effects for the miners! What could possibly go wrong? Take this handy sprayer and get to work!", ["objectivesText"] = "Spray 5 Agitated Shale Spiders with the Bug Off Sprayer and eradicate 12 Shale Shards . Progress: Shale spiders. Why did it have to be shale spiders?!", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 93026 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3283 } },
[32238] = { ["id"] = 32238, ["name"] = "Universal Remote-Explode", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 32238 }, ["description"] = "The Mecha-Pounders are really making things difficult down here, but I think I may have the solution! I made this universal remote for myself, but it looks like I hit a specific frequency that has an useful result! Apparently this frequency weakens their armor! Use the remote to take them down a few notches then punch 'em in the face!", ["objectivesText"] = "Destroy 9 Shieldwall Mecha-Pounders in and around Quickchop's Lumber Farm.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 91902 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3283 } },
[32252] = { ["id"] = 32252, ["name"] = "Harbingers of the Loa", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32252 }, ["description"] = "Have you heard of the loa? We do not understand all of what it is, but it seems to be a dark magic with some degree of sentience. We do not know what power the loa might possess, but I must ask you to put a stop to their rituals, <class>.", ["objectivesText"] = "Slay 2 Harbingers of the Loa. Progress: These stygian rites must end if we are to gain the upper hand, <race>.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3286 } },
[32254] = { ["id"] = 32254, ["name"] = "Manipulating the Saurok", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32254 }, ["description"] = "I have three magisters entrenched in Ihgaluk Crag, monitoring the saurok and - where they can - turning them against the mogu. I need you to find them and see if they need any supplies or assistance. They will be concealed from view. Look for shimmering columns of light within the saurok village.", ["objectivesText"] = "Check in with Magister Arlan , Magister Sarien , and Magistrix Vesara . Progress: Good luck, <name>.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3286 } },
[32255] = { ["id"] = 32255, ["name"] = "De-Constructed", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32255 }, ["description"] = "Saurok consistently test our borders, and our constructs usually fend them off. Some constructs, however, have been defeated and dragged back to Ihgaluk Crag. I want those constructs back. No slithering lizard will steal Sunreaver property under my watch.", ["objectivesText"] = "Recover the four stolen Sunreaver Constructs.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3286 } },
[32258] = { ["id"] = 32258, ["name"] = "Horde Quest Choice: PvP", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 4, ["storyline"] = { 32258 }, ["rewardGold"] = 456000, ["rewardXP"] = 400, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "pvp", ["db2LabelIDs"] = { 3286 } },
[32259] = { ["id"] = 32259, ["name"] = "Horde Quest Choice: PvE", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 4, ["storyline"] = { 32259 }, ["rewardGold"] = 456000, ["rewardXP"] = 400, ["rewardItems"] = { 94220 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "pvp", ["db2LabelIDs"] = { 3286 } },
[32260] = { ["id"] = 32260, ["name"] = "Alliance Quest Choice: PvE", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 4, ["storyline"] = { 32260 }, ["rewardGold"] = 456000, ["rewardXP"] = 400, ["rewardItems"] = { 94219 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "pvp", ["db2LabelIDs"] = { 3285 } },
[32261] = { ["id"] = 32261, ["name"] = "Alliance Quest Choice: PvP", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 4, ["storyline"] = { 32261 }, ["rewardGold"] = 456000, ["rewardXP"] = 400, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "pvp", ["db2LabelIDs"] = { 3285 } },
[32262] = { ["id"] = 32262, ["name"] = "Captive Audience", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32262 }, ["description"] = "The Kirin Tor have gone too far! Now they hold our fellow Sunreavers as war prisoners! There will be no discussion of prisoner exchange. We will handle this ourselves. Go to Violet Rise and free as many prisoners as you can. Do not get captured yourself. We cannot afford to lose you too.", ["objectivesText"] = "Free 5 Sunreaver Captives around Violet Rise.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "pvp", ["db2LabelIDs"] = { 3286 } },
[32264] = { ["id"] = 32264, ["name"] = "Spellbound", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32264 }, ["description"] = "Jaina possesses several very powerful magic artifacts. These items travel with her at all times, and are never far from her grasp. I have an interest in one of these items. A tome, filled with knowledge, passed from one archmage to another. I have only ever seen glimpses of it. Now that we fight on opposite sides I see no issue in removing the tome from her possession.", ["objectivesText"] = "Retrieve Jaina's Weathered Spellbook from Violet Rise. Progress: Do you have it? Do you have the book?!", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 95340 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "pvp", ["db2LabelIDs"] = { 3286 } },
[32265] = { ["id"] = 32265, ["name"] = "Charged Moganite", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32265 }, ["description"] = "We have been dispatching spies into the Kirin Tor base of operations on a daily basis. Some had orders to recover charged moganite from the enemy and bring it here. They have not returned, and I can confirm they have left the Kirin Tor base. Search the jungle between here and there and find any of the charged moganite that might have been lost in transit. Bring it to me and we will put it to good use.", ["objectivesText"] = "Recover a Charged Moganite and bring it to High Arcanist Savor .", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 95567, 95568 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "pvp", ["db2LabelIDs"] = { 3286 } },
[32266] = { ["id"] = 32266, ["name"] = "Mana Manifestations", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32266 }, ["description"] = "Manafiends are nasty creatures. Small and easy to underestimate, but deadly to our magic casters. The Kirin Tor have these pests crawling all over Violet Rise. We will need to handle them carefully. Alone they are easily managed, but in groups they become a different challenge altogether. Go to Violet Rise and cut down their numbers.", ["objectivesText"] = "Kill 9 Kirin Tor Manafiends .", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "pvp", ["db2LabelIDs"] = { 3286 } },
[32268] = { ["id"] = 32268, ["name"] = "Tactical Mana Bombs", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32268 }, ["description"] = "Ah, $p, just the <race> I was looking for. I have received another batch of tactical mana bombs that I need planted in key positions across Violet Rise to the southeast. Here, take these. I do not trust our standard soldiers with such firepower. Oh... and don't shake them, whatever you do. Plant one of the Kirin Tor ships, another one near their supplies, and the last on the construct they are building.", ["objectivesText"] = "Plant a Tactical Mana Bomb on an Alliance Ship, Alliance Supply Shipment, and on the Construct Ritual.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 94905 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "pvp", ["db2LabelIDs"] = { 3286 } },
[32269] = { ["id"] = 32269, ["name"] = "Breaking Down the Defenses", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["storyline"] = { 32269 }, ["description"] = "We need to keep a close watch on the Kirin Tor and their day-to-day activities. Normally this would be easy. We would sneak in a spy and have them report back to us. However, we've run into a slight problem I believe you can help us with. The Kirin Tor perimeter wards have increased in power. It's next to impossible to get someone past their lines. If they were disabled we might be able to sneak in before they can be repaired.", ["objectivesText"] = "Destroy 6 Kirin Tor Perimeter Wards .", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "pvp", ["db2LabelIDs"] = { 3286 } },
[32275] = { ["id"] = 32275, ["name"] = "Surgical Death", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32275 }, ["description"] = "The Zandalari train skyscreamers to become ferocious beasts in the skies. The spiritbinders require endless sacrifices - of our people - to be brought to them. And, the jaguar warriors venture ever closer toward the heart of our camp. Find them in Za'Tual and remove the threat.", ["objectivesText"] = "Slay 3 Zandalari Spiritbinders , 3 Zandalari Beastcallers , and 3 Zandalari Jaguar Warriors . Progress: Do we have less to fear from the Zandalari?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3286 } },
[32282] = { ["id"] = 32282, ["name"] = "Compy Stomp", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32282 }, ["description"] = "The raptors and compies of the Zandalari represent a substantial threat to our forces here. They are superb hunting beasts that can track prey over great distances and are often lethal to encounter when caught unawares. I need you to head into the Beast Pens and cull their numbers. We need to make sure to slay them before they are fully trained.", ["objectivesText"] = "Kill 5 Raptors and 10 Trained Compies in the Beast Pens.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3286 } },
[32283] = { ["id"] = 32283, ["name"] = "Loa-saur", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32283 }, ["description"] = "The Zandalari have found a way to bind loa to their beasts giving them impressive and lethal powers. We need to put a stop to this. Search the Beast Pens for a loa speaker and slay him. You should be able to find them by keeping a look out for their glowing beasts. We must not allow these atrocities to continue.", ["objectivesText"] = "Defeat a Loa Speaker .", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3286 } },
[32285] = { ["id"] = 32285, ["name"] = "The Sleepless Legion", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32285 }, ["description"] = "The Shan'ze are animating an army from the statues in the center of the isle, an army that batters our defenses day and night. Destroy any of the walking statues you see. Our defenders will greatly appreciate it.", ["objectivesText"] = "Kill 6 Animated Warriors .", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3286 } },
[32286] = { ["id"] = 32286, ["name"] = "Kill Mogu Blood-seekers (Roaming pairs, actively fighting scouts, and performing rituals on corpses)", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["storyline"] = { 32286 }, ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[32287] = { ["id"] = 32287, ["name"] = "Enemies Beneath the Tower", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32287 }, ["description"] = "There are mogu in the Diremoor animating the army of statues near the tower. Lor'themar wants them dead. I think you're the one to do it.", ["objectivesText"] = "Kill 7 Shan'ze mogu in the Diremoor.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3286 } },
[32288] = { ["id"] = 32288, ["name"] = "Bolstering the Defenses", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32288 }, ["description"] = "This island holds many dangers for us. Threats loom from every side. We must defend our hold on these shores at all costs. Perimeter wards have been placed around Dawnseeker Promontory. By default they will inflict damage, but are not fatal in their attack. Now is not the time to be merciful, <race>. The perimeter wards need to be deadly! Go and empower the perimeter wards surrounding our camp.", ["objectivesText"] = "Empower 6 Sunreaver Perimeter Wards .", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "pvp", ["db2LabelIDs"] = { 3286 } },
[32292] = { ["id"] = 32292, ["name"] = "Forge Ahead!", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32292 }, ["series"] = { 32208, 32209 }, ["description"] = "The forge lies ahead of you, and with it the heart of the mogu's weaponsmithing ability. And beyond that, the mogu gatekeeper, who holds the key to unlocking the gate to the next part of the city. It's time to move out!", ["objectivesText"] = "Kill the Master of the Forge and collect a Codex Fragment from Fleshcrafter Hoku in the Isle of Thunder . Progress: Well?", ["rewardGold"] = 228000, ["rewardXP"] = 294000, ["rewardItems"] = { 93731, 94219, 94220 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3286 } },
[32293] = { ["id"] = 32293, ["name"] = "Among the Bones", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32293 }, ["description"] = "My scouts have spotted a dangerous Zandalari among the bones west of Ihgaluk Crag. I need someone capable to see him dispatched. Are you up to the task?", ["objectivesText"] = "Kill Zur'chaka the Bonecrafter .", ["rewardGold"] = 228000, ["rewardXP"] = 294000, ["rewardItems"] = { 94219, 94220 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3286 } },
[32294] = { ["id"] = 32294, ["name"] = "Raining Bones", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32294 }, ["description"] = "We've spotted a Zandalari leader up the central stairs. We need to eliminate him before returning to camp. Would you be willing to do the deed?", ["objectivesText"] = "Kill Zur'chaka the Bonecrafter .", ["rewardGold"] = 228000, ["rewardXP"] = 294000, ["rewardItems"] = { 94219, 94220 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3286 } },
[32295] = { ["id"] = 32295, ["name"] = "An Unusual Tome", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["requiredClasses"] = { 9 }, ["categories"] = {}, ["flags"] = { "class" }, ["sharable"] = false, ["expansion"] = 4, ["storyline"] = { 32295 }, ["series"] = { 32307 }, ["description"] = "The tome appears to be written in an ornate, sprawling script that seems to rise off the pages. It vaguely resembles Demonic, but the symbols are far more elaborate than any you've ever seen. Perhaps one of your demonic companions can tell you more.", ["objectivesText"] = "Speak with your demonic minion to determine the origins of the tome.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 5512, 92426, 92441 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["startItems"] = { 92441 } },
[32296] = { ["id"] = 32296, ["name"] = "Treasures of the Thunder King", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6716, ["storyline"] = { 32296 }, ["description"] = "My scouts have returned with word that more of the treasures from Lei Shen's tomb are being brought up into the citadel. We have access to a secret sewer entrance, but a door bars us from intercepting the shipment. If we're going to succeed in this raid, we will need a key that only the most trusted of Lei Shen's forces carry. If you get your hands on such a key, bring it to me. You can keep whatever spoils you steal from our raid. I simply want to see that this shipment never makes it to Lei Shen.", ["objectivesText"] = "Speak to Taoshi to enter the Thunder King's Citadel. Inside, provide her with a Key to the Palace of Lei Shen to begin the timed raid on his treasure convoy. Progress: We must disrupt Lei Shen in any way we can. Anything to hinder the rise of his power. Anything to hinder his armies from being bolstered. If that means highway robbery, I can live with that.", ["rewardGold"] = 228000, ["rewardXP"] = 294000, ["rewardItems"] = { 74717, 74718, 94222, 95497 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6716 } }, ["questType"] = "standard" },
[32297] = { ["id"] = 32297, ["name"] = "Direhorn or Devilsaur", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32297 }, ["description"] = "We have an opportunity to disrupt the Zandalari war machine as well as have a little fun in the process. Within these beast pens, a devilsaur and a direhorn are being outfitted with armor, their minds being enslaved to the Zandalari charms. Go into the camp and disrupt one of these binding rituals. It doesn't matter which one. Just kill those who are trying to bind the creature. This should let the fully armored beast run mad through the Zandalari camp. Then sit back and watch the hilarity ensue.", ["objectivesText"] = "Disrupt a binding ritual by killing all ritual NPCs around either a Defiant Direhorn or a Defiant Devilsaur.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3286 } },
[32299] = { ["id"] = 32299, ["name"] = "Just Some Light Clean-Up Work", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32299 }, ["description"] = "This is not a glamorous job. Let me put it to you bluntly. The Skumblade saurok pile all of their filth into a pool in the middle of their village. This filth is so concentrated and so rancid that it has congealed into moving, animate matter. The saurok can keep their filth-pool, but once it starts spreading outside of the village, I'd say it's time to intervene.", ["objectivesText"] = "Disperse 75 pieces of filth by killing Quivering Filth in Ihgaluk Crag. Progress: Sorry in advance about the smell.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3286 } },
[32300] = { ["id"] = 32300, ["name"] = "Disarming Irony", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32300 }, ["description"] = "Well, it would seem the Lady Proudmoore has decided to use our own weaponry against us. Our perimeter wards reported several spies slipping through our defenses carrying tactical mana bombs . I would enjoy the irony if these bombs were less dangerous. Search for these bombs and disarm them. Our wards reported one near the horde ships to the north, one on a bridge to the main isle, and one near our scrying crystals on the eastern side of the Promontory.", ["objectivesText"] = "Disarm the Tactical Mana Bombs at the Horde Ships, the Scrying Crystals, and the Bridge within Dawnseeker Promontory.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "pvp", ["db2LabelIDs"] = { 3286 } },
[32302] = { ["id"] = 32302, ["name"] = "Desconstruction", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32302 }, ["description"] = "The Kirin Tor constructs are primitive at best. Nevertheless, they pose a threat. Go to Violet Rise and dismantle Jaina's pitiful war machines. Show the Kirin Tor how easily they can be defeated! This will be a message the Kirin Tor cannot easily ignore.", ["objectivesText"] = "Destroy 3 Kirin Tor Constructs around Violet Rise.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "pvp", ["db2LabelIDs"] = { 3286 } },
[32303] = { ["id"] = 32303, ["name"] = "Made for War", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32303 }, ["description"] = "Jaina thinks this battle will be easily won. I intend to show her how wrong she is! The Kirin Tor brought a weapon with them that must be destroyed. The Arcane Destroyer is a large construct capable of turning the tides of war in their favor. Destroying this monstrosity would send a very clear message to Proudmoore.", ["objectivesText"] = "Kill the Arcane Destroyer .", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "pvp", ["db2LabelIDs"] = { 3286 } },
