[32305] = { ["id"] = 32305, ["name"] = "Overpowered", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32305 }, ["description"] = "The Kirin Tor are using mana foci to empower their forces. We cannot allow this to continue. You'll find these foci scattered around the outskirts of Violet Rise. Use this mana crystal to destroy as many as you can. Each mana focus we destroy is another small victory for our cause.", ["objectivesText"] = "Destroy 7 Mana Foci around Violet Rise.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 95352 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "pvp", ["db2LabelIDs"] = { 3286 } },
[32307] = { ["id"] = 32307, ["name"] = "Reader for the Dead Tongue", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = {}, ["flags"] = { "class" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 1519, ["storyline"] = { 32307 }, ["series"] = { 32295 }, ["description"] = "Return to your capital city and seek out a warlock trainer who may know more about the codex.", ["objectivesText"] = "Bring the codex to a Warlock trainer in your capital city.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 92441 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1519 } }, ["questType"] = "standard" },
[32309] = { ["id"] = 32309, ["name"] = "A Tale of Six Masters", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["requiredClasses"] = { 9 }, ["categories"] = {}, ["flags"] = { "class" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 1637, ["storyline"] = { 32309 }, ["series"] = { 32310, 32317, 32324, 32325 }, ["description"] = "This book may be just the leverage we've been seeking... How familiar are you with the Council of the Black Harvest, <name>? After Deathwing was defeated, six of the greatest Warlocks gathered together to teach all Warlocks advanced forms of magic stolen from our defeated foes. Take a look at the tome beside me...", ["objectivesText"] = "Read the first chapter of the Legacy of the Masters. Progress: Well, what did you think?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 83078, 92426 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1637 } }, ["questType"] = "standard" },
