[32317] = { ["id"] = 32317, ["name"] = "Seeking the Soulstones", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = {}, ["flags"] = { "class" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 1519, ["storyline"] = { 32317 }, ["series"] = { 32309, 32310, 32324, 32325 }, ["description"] = "<name>, take this - the journal of Jubeka Shadowbreaker. Read the journal and use the information contained within to track down where she went. Find her soulstones and use them to locate her.", ["objectivesText"] = "Read Jubeka's Journal and use the clues within to locate the four soulstone fragments.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 92471, 92494, 92495, 92496, 92497 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1519 } }, ["questType"] = "standard" },
[32324] = { ["id"] = 32324, ["name"] = "Seek the Signal", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["requiredClasses"] = { 9 }, ["categories"] = {}, ["flags"] = { "class" }, ["sharable"] = false, ["expansion"] = 4, ["storyline"] = { 32324 }, ["series"] = { 32309, 32310, 32317, 32325 }, ["description"] = "The soulstone shards fuse together easily in your hands. Strangely, no soul is stored within the stone. Instead, the stone seems to be drawing power from somewhere in Shadowmoon Valley. Looking east, you feel the power linked beyond the mountains, to the very gates of the Black Temple.", ["objectivesText"] = "Follow the soulstone to the gates of the Black Temple.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[32325] = { ["id"] = 32325, ["name"] = "Infiltrating the Black Temple", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = {}, ["flags"] = { "class" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6613, ["storyline"] = { 32325 }, ["series"] = { 32309, 32310, 32317, 32324 }, ["description"] = "It's clear that Jubeka's soulstone has lead you here to the Black Temple. The question remains... why? The only remaining option is to head inside and figure out why they were here.", ["objectivesText"] = "Look for Jubeka's mark on the main entrance of the Black Temple. Once inside, speak to Jubeka at the Temple Summit.", ["rewardGold"] = 342000, ["rewardXP"] = 353000, ["rewardItems"] = { 13462 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6613 } }, ["questType"] = "standard" },
[32339] = { ["id"] = 32339, ["name"] = "Rebuilding the Mallet (Tracker)", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["storyline"] = { 32339 }, ["description"] = "Time for the fixing and then time for the mixing!", ["objectivesText"] = "Obtain the Harmonic Mallet.", ["rewardGold"] = 114000, ["rewardXP"] = 200, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[32340] = { ["id"] = 32340, ["name"] = "Plunder the Black Temple", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = {}, ["flags"] = { "class" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6613, ["storyline"] = { 32340 }, ["description"] = "While Akama and his men are dealing with the demons, there is nobody to stop you from stealing a relic or two...", ["objectivesText"] = "Loot everything you can grab and reach the end of the Den of Mortal Delights.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6613 } }, ["questType"] = "standard" },
[32341] = { ["id"] = 32341, ["name"] = "Demonstrate Your Power", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["requiredClasses"] = { 9 }, ["categories"] = {}, ["flags"] = { "class" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6613, ["storyline"] = { 32341 }, ["description"] = "Akama and his men are under siege by the forces you unleashed in the Reliquary of Souls. Demonstrate your power to Akama by saving his men from the demonic forces!", ["objectivesText"] = "Slay the demons who are attacking Akama's men in the Halls of Anguish.", ["rewardItems"] = { 92441, 93387 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6613 } }, ["questType"] = "standard" },
[32342] = { ["id"] = 32342, ["name"] = "The Spirit Trap", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 32342 }, ["description"] = "Within the ruins we have identified several powerful mogu artifacts. They trapped spirits within, probably to use them in some ritual or conjuration. They are a type of device that we haven't identified and desperately need to study - they may reveal more of the secrets of the mogu's spirit binding techniques. Go, find us a few samples so that we may continue a proper study.", ["objectivesText"] = "Collect 3 Spirit Traps . Progress: Have you brought the traps?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 92708 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3283 } },
[32343] = { ["id"] = 32343, ["name"] = "Ogudei's Lieutenants", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 32343 }, ["description"] = "There are two extremely powerful mogu spirits that the Alliance unearthed in their ineptitude. These are choice targets for us, <class>. If you kill them and collect each of their essences, we could make great progress on decoding the history of this strange ruin.", ["objectivesText"] = "Collect Meng-do's Essence and Gen-li's Essence in the Ruins of Ogudei. Progress: The essence isn't going to make itself, <race>.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 92735, 92736 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3283 } },
[32344] = { ["id"] = 32344, ["name"] = "It Is A Mystery", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 32344 }, ["description"] = "We have detected several... anomalies in these mines, of an arcane or spiritual nature. They are disrupting our attempts to discern the nature of the magic used in the spirit binding rituals here. They are quite elusive, but we've managed to isolate the arcane signature of one of these anomalies, and one of our mages has enchanted this bauble with its signature. Take the bauble. It will begin to glow more brightly as you approach the anomaly. Once you reach it, you can use the bauble to draw it out.", ["objectivesText"] = "Use the Arcane Bauble to find an anomaly within the Ruins of Ogudei.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 1217, 38133, 38173, 38174, 38202, 38763, 38764, 38765, 53404, 53435, 55896, 55897, 55898, 199210 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3283 } },
[32345] = { ["id"] = 32345, ["name"] = "We're Not Monsters!", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 32345 }, ["description"] = "The Reliquary may have had a bad name in the past, but we're not monsters. We simply hold different views about archaeology than the Explorer's League. We do focus on performing acts of heroism from time to time. So go, liberate some of the pandaren slave spirits in the ruins.", ["objectivesText"] = "Liberate 14 Troubled Slave Spirits .", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3283 } },
[32346] = { ["id"] = 32346, ["name"] = "Oi Ain't Afraid o' No Ghosts!", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 32346 }, ["description"] = "Look. We got a nasty problem here, and ol' Troteman back at Lion's Landing's gonna throw us out of here if we don't get things under control. Give us a hand, please!", ["objectivesText"] = "Kill 12 Spiritbound Mogu.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3282 } },
[32347] = { ["id"] = 32347, ["name"] = "Eviction Notice", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 32347 }, ["description"] = "The bloody Reliquary's snuck into the ruins. They've taken the lower section and are conducting all kinds of magical shenanigans down there. It's time we gave 'em an eviction notice, in the form of your boot in their rear!", ["objectivesText"] = "Kill any 10 members of the Reliquary in the Ruins of Ogudei.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3282 } },
[32356] = { ["id"] = 32356, ["name"] = "Tracking Event: Ambassadors Summoned", ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["storyline"] = { 32356 }, ["series"] = { 29885, 32357, 32361 }, ["description"] = "It's time for Sully and I to leave. We'll keep our eyes out for any sign of the White Pawn and report back shortly. I'm afraid I must leave you in charge while Admiral Taylor is recovering. Learn as much as you can from these jinyu while we are away. I expect a full report when we return.", ["objectivesText"] = "See the scouts off, then speak to Big Lu.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
