[32359] = { ["id"] = 32359, ["name"] = "The Eye of the Naaru", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["requiredClasses"] = { 9 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["storyline"] = { 32359 }, ["description"] = "The soulcore has transformed into a crystal. This is clearly the artifact that Kanrethad and Jubeka were attempting to create, but you still have no idea where they went. Seek out the Black Prince in the Tavern of the Mists and see if you can acquire some information on where they went.", ["objectivesText"] = "Bring the Eye of the Storm to Wrathion in the Tavern in the Mists.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 92563 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[32361] = { ["id"] = 32361, ["name"] = "Tracking Event: Event Complete", ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["storyline"] = { 32361 }, ["series"] = { 29885, 32356, 32357 }, ["description"] = "It's time for Sully and I to leave. We'll keep our eyes out for any sign of the White Pawn and report back shortly. I'm afraid I must leave you in charge while Admiral Taylor is recovering. Learn as much as you can from these jinyu while we are away. I expect a full report when we return.", ["objectivesText"] = "See the scouts off, then speak to Big Lu.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[32364] = { ["id"] = 32364, ["name"] = "Pandaren Medicine", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["storyline"] = { 32364 }, ["description"] = "While I was in the Vale, I came across an ancient pandaren recipe for Memory Wine. I believe this brew can coax some helpful information out of Shan Kien. I am needed here, so I have no choice but to ask you to find the ingredients for me. The recipe can be found in a book near my other things, just behind me.", ["objectivesText"] = "Find the recipe for Memory Wine.", ["rewardGold"] = 57000, ["rewardXP"] = 118000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[32369] = { ["id"] = 32369, ["name"] = "Secrets of the Past", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["storyline"] = { 32369 }, ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[32373] = { ["id"] = 32373, ["name"] = "The Measure of a Leader", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6006, ["storyline"] = { 32373 }, ["series"] = { 32374 }, ["description"] = "We've progressed to a new part of the Pandaren campaign. The Alliance has landed on the shores with the full might of its navy. Your King aims to check Horde aggression in this new land. Garrosh Hellscream is propelling the Horde headfirst into battle, but King Varian Wrynn is a little more of a mystery to me. Do you have a moment? I'd like to talk to you about this leader of yours.", ["objectivesText"] = "Speak with Wrathion at the Tavern in the Mists. Progress: I love a good chat.", ["rewardGold"] = 57000, ["rewardXP"] = 118000, ["rewardItems"] = { 93403 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6006 } }, ["questType"] = "standard" },
[32374] = { ["id"] = 32374, ["name"] = "The Prince's Pursuit", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6006, ["storyline"] = { 32374 }, ["series"] = { 32373 }, ["description"] = "My goal is an expedient end to this costly war. Prove to me that the Alliance deserves to win. Show me your prowess on the battlefield. You are not fighting some abstract force like the sha: You are facing your enemy head-on, eye-to-eye. Will you triumph?", ["objectivesText"] = "Kill Horde forces along the southern shores of Krasarang Wilds until you are Revered with the Black Prince .", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 64399, 64402, 76091 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6006 } }, ["questType"] = "standard" },
[32375] = { ["id"] = 32375, ["name"] = "A Dash of That", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["storyline"] = { 32375 }, ["description"] = "100 Buttonbelly Mushrooms . Must be freshly harvested from a wet, dark place. <Scrawled along the edge of the page is a hand-written note.> Fungus is very good for the health! (Or it might kill you, cause serious illness, rash, hallucination, or loosen bowels. Note to self - MUST be careful when selecting wild mushrooms!)", ["objectivesText"] = "Collect 100 Buttonbelly Mushrooms .", ["rewardGold"] = 57000, ["rewardXP"] = 118000, ["rewardItems"] = { 92752 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[32388] = { ["id"] = 32388, ["name"] = "A Change of Command", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6006, ["storyline"] = { 32388 }, ["description"] = "There's an orc general I've been keeping a close eye on. Warlord Bloodhilt curried a lot of favor with Garrosh Hellscream by beating back an Alliance advance in Southern Barrens. He's now entrenched within the fortress at Domination Point. I doubt the Alliance can take him out. But... you've proven me wrong before. If you wish to finish him off, bring friends. Lots of friends.", ["objectivesText"] = "Kill Warlord Bloodhilt at Domination Point in Krasarang Wilds. You will need a group.", ["rewardGold"] = 228000, ["rewardXP"] = 294000, ["rewardItems"] = { 74648, 86569 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6006 } }, ["questType"] = "standard" },
[32389] = { ["id"] = 32389, ["name"] = "The Lion Roars", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6006, ["storyline"] = { 32389 }, ["description"] = "This is a global war, <name>. It has spilled onto Pandaria, and it has set hot spots across Kalimdor and the Eastern Kingdoms ablaze. How will you fare on an organized battlefront? I would like to see for myself. I look forward to hearing your report from the front lines.", ["objectivesText"] = "Assist in battles at the Temple of Kotmogu and the Silvershard Mines.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 72986, 76637, 76647, 76685, 89674, 89680, 94361, 94386, 94388 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6006 } }, ["questType"] = "standard" },
[32390] = { ["id"] = 32390, ["name"] = "Call of the Packmaster", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6006, ["storyline"] = { 32390 }, ["description"] = "<class>, through your eyes I've been able to witness the fighting along the coast, and the epic course of battles around the world. You've been very patient... and most informative. I've also been keeping a close eye on your King. Would you be interested to hear what I've learned?", ["objectivesText"] = "Speak with Wrathion . Progress: <Three darkly shimmering gems rest in an ornate silk-lined chest. One of them is yours.>", ["rewardGold"] = 57000, ["rewardXP"] = 118000, ["rewardItems"] = { 93403 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6006 } }, ["questType"] = "standard" },
[32413] = { ["id"] = 32413, ["name"] = "A Return to Krasarang", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6611, ["storyline"] = { 32413 }, ["description"] = "Wherever your loyalties might lie - with Rommath and I, with Garrosh, or elsewhere - one thing is true: your acts today were truly heroic. I can arrange for your transport back to Krasarang Wilds. Speak with me if you would like passage back to Pandaria, <name>.", ["objectivesText"] = "Report to General Nazgrim at Domination Point in Krasarang Wilds.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6611 } }, ["questType"] = "standard" },
[32427] = { ["id"] = 32427, ["name"] = "The Measure of a Leader", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6006, ["storyline"] = { 32427 }, ["description"] = "We've progressed to a new part of the Pandaren campaign. Your Warchief aims to impress the Pandaren with the full might of the Horde's military. He will lay claim to the resources of this land, with or without Pandaren aid. I understand your leader's aims, but I really want to understand the Warchief himself. What drives him? And where is the Horde ultimately going? I'd like to talk to you about this leader of yours.", ["objectivesText"] = "Speak with Wrathion at the Tavern in the Mists. Progress: I love a good chat.", ["rewardGold"] = 57000, ["rewardXP"] = 118000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6006 } }, ["questType"] = "standard" },
[32429] = { ["id"] = 32429, ["name"] = "The Prince's Pursuit", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6006, ["storyline"] = { 32429 }, ["description"] = "My goal is an expedient end to this costly war. Prove to me that the Horde deserves to win. Show me your prowess on the battlefield. You are not fighting some abstract force like the sha: You are facing your enemy head-on, eye-to-eye. Will you triumph?", ["objectivesText"] = "Kill Alliance forces along the southern shores of Krasarang Wilds until you are Revered with the Black Prince .", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 64402, 72988, 74841, 74844, 76091 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6006 } }, ["questType"] = "standard" },
[32431] = { ["id"] = 32431, ["name"] = "Glory to the Horde", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6006, ["storyline"] = { 32431 }, ["description"] = "This is a global war, <name>. It has spilled onto Pandaria, and it has set hot spots across Kalimdor and the Eastern Kingdoms ablaze. How will you fare on an organized battlefront? I would like to see for myself. I look forward to hearing your report from the front lines.", ["objectivesText"] = "Assist in battles at the Temple of Kotmogu and the Silvershard Mines. Progress: What of the war, <class>?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6006 } }, ["questType"] = "standard" },
[32433] = { ["id"] = 32433, ["name"] = "Undermining the Under Miner", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 32433 }, ["description"] = "Grezik Oregrind has become a nuisance that must be eliminated. This land responds to all of our actions as I am sure you are aware, <class>. Because of this, we cannot allow the goblins to haphazardly destroy it. Our scouts have reported Sha emerging from Oregrind's Dig. The brains behind the operation is a goblin named Grezik Oregrind . Destroy him and perhaps we will stall the operation just long enough to contain the Sha.", ["objectivesText"] = "Destroy Grezik Oregrind at Oregrind's Dig.", ["rewardGold"] = 114000, ["rewardXP"] = 200, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3282 } },
[32434] = { ["id"] = 32434, ["name"] = "Burning Pandaren Spirit", ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5842, ["storyline"] = { 32434 }, ["description"] = "You're back! Up for another battle with me?", ["objectivesText"] = "Defeat Burning Pandaren Spirit in a pet battle. Progress: Think you can take me?", ["rewardGold"] = 700, ["rewardXP"] = 80, ["rewardItems"] = { 68618, 90173, 92798, 92799, 92800, 93146, 93147, 93148, 93149, 98715 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5842 } }, ["questType"] = "standard" },
