[32446] = { ["id"] = 32446, ["name"] = "Dis-Assembly Required", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 32446 }, ["description"] = "Those shredders are becoming a problem down there, <class>. We've sent in the Mecha-Pounders, but it just isn't enough. They're getting damaged faster than we can repair 'em! I happened upon this strange remote while scouting. With a little bit of re-configurin' I think we can use it. Try usin' it on the Jungle Shredders. Hopefully it will destroy them and then you can bring me the scrap metal .", ["objectivesText"] = "Destroy the Jungle Shredders using the Re-Configured Remote and then collect 6 pieces of Scrap Metal . Progress: So what did that remote do?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 77467, 77468, 89739, 89740, 93179, 93180 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3282 } },
[32449] = { ["id"] = 32449, ["name"] = "The Ruins of Ogudei", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 32449 }, ["series"] = { 32118 }, ["description"] = "Our scouts at Sparkrocket Outpost have reported some new activity near an area called the Ruins of Ogudei. We need to gather intelligence on what it is the Alliance are doing, and more importantly what it is they found. We cannot afford to have any unknowns. Meet up with Belloc Brightblade in Sparkrocket Outpost and find out what he knows.", ["objectivesText"] = "Report to Belloc Brightblade in Sparkrocket Outpost.", ["rewardGold"] = 11400, ["rewardXP"] = 23600, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3283 } },
[32450] = { ["id"] = 32450, ["name"] = "The Time Is Now!", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6134, ["storyline"] = { 32450 }, ["series"] = { 32135 }, ["description"] = "Now we take the fight to them, <class>! Report to Shademaster Kiryn in Sparkrocket Outpost. She will have your orders. Now we'll see how they handle the full might of the Horde rushing at their precious keep!", ["objectivesText"] = "Report to Shademaster Kiryn in Sparkrocket Outpost.", ["rewardGold"] = 11400, ["rewardXP"] = 23600, ["rewardItems"] = { 91838, 92056 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6134 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3283 } },
[32457] = { ["id"] = 32457, ["name"] = "The Thunder King", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6006, ["storyline"] = { 32457 }, ["series"] = { 32590, 32591 }, ["description"] = "Are you aware of recent events in Kun-Lai Summit? The Zandalari have landed on the northern shores in great numbers and have set about renewing old alliances. To that end, they have resurrected The Thunder King. Even among the mogu, the name of the first emperor commands awe and fear. The Thunder King founded a vast empire of slavery and suffering... but also of power, riches, and splendor. We will take the fight to him soon. Find me when your faction makes its move.", ["objectivesText"] = "Contact Wrathion in the Tavern in the Mists in the Veiled Stair.", ["rewardGold"] = 11400, ["rewardXP"] = 23600, ["rewardItems"] = { 72095, 76132, 79869, 87208, 87209, 87262, 87399, 90597, 90598, 90599, 90600, 90601, 90602, 90603, 90607, 90609, 94593, 94594, 95497, 97153 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6006 } }, ["questType"] = "standard" },
[32459] = { ["id"] = 32459, ["name"] = "With the Wind's Blessing...", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["storyline"] = { 32459 }, ["description"] = "<An urgent plea reaches your ears.> <name>! The Horde fleet is making its way to Pandaria. With favorable winds, they could arrive any moment. The Pandaren have a blessing that will give us good luck with the weather and speed our brothers and sisters to these shores. We simply need to collect charms of good fortune to gain fortune's favor. As our ships draw closer to the island, less charms will be required. But if you have enough, we can speed them here right away...", ["objectivesText"] = "Collect Charms of Good Fortune.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[32461] = { ["id"] = 32461, ["name"] = "The Order of the Cloud Serpent", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5785, ["storyline"] = { 32461 }, ["description"] = "Ahhh, it seems you have found yourself the proud owner of a majestic cloud serpent. Before you may fly the skies on this powerful creature, you must first earn the skill to ride it. The Order of the Cloud Serpent can teach you the knowledge that you seek. If you wish to follow our way, you should speak to Instructor Skythorn at The Arboretum in the Jade Forest . I wish you luck, <race>.", ["objectivesText"] = "Speak to Instructor Skythorn at The Arboretum in The Jade Forest .", ["rewardGold"] = 11400, ["rewardXP"] = 23600, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5785 } }, ["questType"] = "standard" },
[32468] = { ["id"] = 32468, ["name"] = "Crystal Clarity", ["level"] = 13, ["requiredLevel"] = 13, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 32468 }, ["series"] = { 32471 }, ["description"] = "You know, there is a way we can improve your S.E.L.F.I.E. cam, if you're interested. With the right focusing lens, I could add all kinds of features to that thing. I've heard that way out on old Yojamba Isle in Stranglethorn Vale, the mother of all basilisks has been seen. Her hide is dotted with gems that'd make the perfect lens, if I could get my hands on them. She's not going to go down easy, though. You might want to bring some friends along.", ["objectivesText"] = "Collect 1 Pristine Crystal Shard from the Crystal Spine Matriarch on Yojamba Isle in Stranglethorn Vale. Progress: That crystal spine matriarch has the gems we need to upgrade your lens, any luck with that?", ["rewardGold"] = 1239200, ["rewardXP"] = 3640, ["rewardItems"] = { 122661, 155832 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 16926, ["x"] = 0.345, ["y"] = 0.7055 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 16926, ["x"] = 0.345, ["y"] = 0.7055 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.345, ["y"] = 0.7055 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "group" },
[32469] = { ["id"] = 32469, ["name"] = "Crystal Clarity", ["level"] = 13, ["requiredLevel"] = 13, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 32469 }, ["series"] = { 32470 }, ["description"] = "Hi again! Oh, I forgot to tell you! I've devised a foolproof way to improve your S.E.L.F.I.E. cam! In fact, with just the right gemstones, I can make a lens that would allow us to do all sorts of things! Some fellow explorers have told me about a large basilisk out on Yojamba Isle in Stranglethorn Vale. Her hide is dotted with tons of high-quality crystals! What a perfect coincidence! She sounds pretty tough, though! You should bring some friends!", ["objectivesText"] = "Collect 1 Pristine Crystal Shard from the Crystal Spine Matriarch on Yojamba Isle in Stranglethorn Vale. Progress: Hey, stay out of my shot! Oh, it's you! Did you take down that basilisk yet?", ["rewardGold"] = 1239200, ["rewardXP"] = 3640, ["rewardItems"] = { 122661, 155832 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 16908, ["x"] = 0.612, ["y"] = 0.226 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 16908, ["x"] = 0.612, ["y"] = 0.226 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.612, ["y"] = 0.226 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "group" },
[32470] = { ["id"] = 32470, ["name"] = "Light Camera Action", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 1637, ["mapID"] = 84, ["storyline"] = { 32470 }, ["series"] = { 32469 }, ["description"] = "Oh, hi! Isn't this a great shot? I love my S.E.L.F.I.E. camera ! Do you want me to make you one, too? I only need a few parts! For the strap, I'll need a Russet Belt from one of the armor merchants in Stormwind. I've already ordered more housings, you're welcome to take one, you just have to find where my shipment ended up! Oh, and a Standard Scope , most any engineer can make you one of those. Ok, are you ready for a little photography action?!", ["objectivesText"] = "Collect an Iron Box and a Russet Belt from locations within the capital, and a Standard Scope from an engineer. Progress: Look at this shot? I could shoot here all day! Did you get those parts yet?", ["rewardGold"] = 341600, ["rewardXP"] = 200, ["rewardItems"] = { 3593, 4406, 122637, 122674, 155856 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 16908, ["x"] = 0.612, ["y"] = 0.226 }, { ["mapID"] = 85, ["npcID"] = 16926, ["x"] = 0.345, ["y"] = 0.7055 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 16908, ["x"] = 0.612, ["y"] = 0.226 }, { ["mapID"] = 85, ["npcID"] = 16926, ["x"] = 0.345, ["y"] = 0.7055 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.612, ["y"] = 0.226 }, ["mapCandidates"] = { ["npc"] = { 84, 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard" },
[32471] = { ["id"] = 32471, ["name"] = "Light Camera Action", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 32471 }, ["series"] = { 32468 }, ["description"] = "You look like you've got a discerning eye for the visual arts, want to try your hand at photography? I can make you one of these S.E.L.F.I.E. cameras , I just need a few parts. For the strap, grab me a Russet Belt from one of the armor merchants around here. I've got a shipment of extra housings waiting by the back entrance to the city, grab me one when you're over there. Oh, and a Standard Scope , most any engineer can make you one of those. Now get out there, kid. Fame awaits!", ["objectivesText"] = "Collect an Iron Box and a Russet Belt from locations within the capital, and a Standard Scope from an engineer. Progress: You got those parts for me, or what? I'm busy here!", ["rewardGold"] = 341600, ["rewardXP"] = 200, ["rewardItems"] = { 3593, 4406, 122637, 155856 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 16926, ["x"] = 0.345, ["y"] = 0.7055 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 16926, ["x"] = 0.345, ["y"] = 0.7055 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.345, ["y"] = 0.7055 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard" },
[32474] = { ["id"] = 32474, ["name"] = "A Test of Valor", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6006, ["storyline"] = { 32474 }, ["description"] = "<Without warning Wrathion slices his thumb and presses it against your forehead. His blood burns to the touch, but rapidly disappears into your skin.> There! My eye is upon you, <class>. I am watching. The Pandaren, like the Alliance, value the concept of \"Valor.\" There are many ways to prove yourself valorous on this continent, from daily tasks to the defeat of heroic enemies within their lair. I will let you choose your own course. Prove your bravery to me, <name>!", ["objectivesText"] = "Gain the \"A Test of Valor\" Achievement by earning a total of 1600 Valor Points.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6006 } }, ["questType"] = "standard" },
[32475] = { ["id"] = 32475, ["name"] = "A Spark of Life", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["storyline"] = { 32475 }, ["description"] = "The Thunder-Laced Egg burns your hand as you hold it. You recall that Yalia Sagewhisper of the Shado-Pan discussing the history of the Thundering Cloud Serpents, perhaps she will know what to do with it.", ["objectivesText"] = "Deliver the Thunder-Laced Egg to Yalia Sagewhisper on the Isle of Thunder.", ["rewardGold"] = 456000, ["rewardItems"] = { 89317, 93660 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[32476] = { ["id"] = 32476, ["name"] = "A Test of Valor", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6006, ["storyline"] = { 32476 }, ["description"] = "<Without warning Wrathion slices his thumb and presses it against your forehead. His blood burns to the touch, but rapidly disappears into your skin.> There! My eye is upon you, <class>. I am watching. The Pandaren, like the Horde, value the concept of \"Valor.\" There are many ways to prove yourself valorous on this continent, from daily tasks to the defeat of heroic enemies within their lair. I will let you choose your own course. Prove your bravery to me, <name>!", ["objectivesText"] = "Gain the \"A Test of Valor\" Achievement by earning a total of 1600 Valor Points. Progress: Brave, brave <class>. How goes the fight?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6006 } }, ["questType"] = "standard" },
[32485] = { ["id"] = 32485, ["name"] = "Bolstering the Defenses", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["storyline"] = { 32485 }, ["description"] = "This island is a dangerous place, <name>. We have to worry about attacks from the Zandalari, mogu, saurok, and worst of all the Sunreavers. I had perimeter wards placed on the outskirts of our camp for additional protection. In their current state they will only injure an attacker, but I'm done with warnings! With your help we can super-charge the wards into a more deadly defense system.", ["objectivesText"] = "Empower 6 Kirin Tor Perimeter Wards around Violet Rise.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "pvp", ["db2LabelIDs"] = { 3285 } },
[32489] = { ["id"] = 32489, ["name"] = "The Creeping Carpet of Ihgaluk", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32489 }, ["description"] = "Ah, roaches! I once bought a pet roach in the Undercity. Roaches will soak up disease like a sponge, and then spread it as far as they can run. Which is pretty far. Ihgaluk Crag is crawling with the things, and they carry Skumblade filth all over of this island. Crush as many of them as you can while you're there.", ["objectivesText"] = "Crush 75 Ihgaluk Roaches.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 10393 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3286 } },
[32491] = { ["id"] = 32491, ["name"] = "Left To Rot", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32491 }, ["description"] = "The Skumblade saurok do not eat all of the meat they hunt. They reserve large portions of it to rot in piles near their homes, attracting pests and spreading disease. We can't have the saurok spreading their disease beyond the borders of Ihgaluk Crag. Dispose of any excess meat that you find.", ["objectivesText"] = "Destroy 3 Fetid Meat Piles .", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3286 } },
[32492] = { ["id"] = 32492, ["name"] = "Destroy Cauldrons", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["storyline"] = { 32492 }, ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[32493] = { ["id"] = 32493, ["name"] = "They All Fall Down", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["storyline"] = { 32493 }, ["description"] = "The Zandalari do not tolerate weakness in their ranks, <class>. Those that are deemed weak are often sacrificed in barbaric ceremonies. The victims' spirits are captured and entombed within the sentries you see guarding the grounds. I wish to study their essence. For this I will need your help. Take this resonance crystal and siphon the spirits from the sentry corpses. Do not allow them to escape!", ["objectivesText"] = "Kill 5 Spirit-Bound Sentries and then use the Resonance Crystal to capture the Zandalari Spirits trapped within.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 93806 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2LabelIDs"] = { 3286 } },
[32494] = { ["id"] = 32494, ["name"] = "Power Play", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32494 }, ["description"] = "The Zandalari have found a way to infuse items of great power with the essence of their loa. These items are often passed from one generation to another, each recipient adding to the item's power. Two such items exist here. To be specific, two masks, worn by two brothers. Spiritbinder Tu'chek and Arcanital Ra'kul must be stopped and their masks destroyed. Kill them and return their masks to me. I will make sure the masks are disposed of.", ["objectivesText"] = "Retrieve the Mask of the Dark Mystic and the Mask of the Spirit-Caller from Spiritbinder Tu'chek and Arcanital Ra'kul within Conqueror's Terrace. Progress: Do you have the masks?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 93733, 93734 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3286 } },
[32495] = { ["id"] = 32495, ["name"] = "The Bloodletter", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32495 }, ["description"] = "I have heard a disturbing report, <class>. Just beyond our position, in the Court of Bone, the mogu bring captives to a general named Kaida the Bloodletter . I will spare you the details, but he thrives on torturing his victims. This monster must be stopped. If you fall to his blade, I wish you a swift death.", ["objectivesText"] = "Kill Kaida the Bloodletter .", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3286 } },
[32497] = { ["id"] = 32497, ["name"] = "Honor the Flame", ["requiredLevel"] = 1, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["mapID"] = 422, ["storyline"] = { 32497 }, ["description"] = "The Midsummer Fire Festival is a time to honor the elements. The element of fire stirs passion within us all. Many times, that passion pours out into aggressive actions. But here, in this land, we focus our passion on reverence. We will honor the flame as tradition dictates. Will you honor the flame with us, <name>?", ["objectivesText"] = "Honor the Midsummer Bonfire in Dread Wastes.", ["rewardGold"] = 57000, ["rewardXP"] = 40, ["rewardItems"] = { 23247 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422 },
[32498] = { ["id"] = 32498, ["name"] = "Honor the Flame", ["requiredLevel"] = 1, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["mapID"] = 371, ["storyline"] = { 32498 }, ["description"] = "The Midsummer Fire Festival is a time to honor the elements. The element of fire stirs passion within us all. Many times, that passion pours out into aggressive actions. But here, in this land, we focus our passion on reverence. We will honor the flame as tradition dictates. Will you honor the flame with us, <name>?", ["objectivesText"] = "Honor the Midsummer Bonfire in Jade Forest.", ["rewardGold"] = 57000, ["rewardXP"] = 40, ["rewardItems"] = { 23247 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 371 },
