[32501] = { ["id"] = 32501, ["name"] = "Honor the Flame", ["requiredLevel"] = 1, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["mapID"] = 388, ["storyline"] = { 32501 }, ["description"] = "The Midsummer Fire Festival is a time to honor the elements. The element of fire stirs passion within us all. Many times, that passion pours out into aggressive actions. But here, in this land, we focus our passion on reverence. We will honor the flame as tradition dictates. Will you honor the flame with us, <name>?", ["objectivesText"] = "Honor the Midsummer Bonfire in Townlong Steppes.", ["rewardGold"] = 57000, ["rewardXP"] = 40, ["rewardItems"] = { 23247 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 388 },
[32502] = { ["id"] = 32502, ["name"] = "Honor the Flame", ["requiredLevel"] = 1, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["mapID"] = 376, ["storyline"] = { 32502 }, ["description"] = "The Midsummer Fire Festival is a time to honor the elements. The element of fire stirs passion within us all. Many times, that passion pours out into aggressive actions. But here, in this land, we focus our passion on reverence. We will honor the flame as tradition dictates. Will you honor the flame with us, <name>?", ["objectivesText"] = "Honor the Midsummer Bonfire in Valley of the Four Winds.", ["rewardGold"] = 57000, ["rewardXP"] = 40, ["rewardItems"] = { 23247 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 376 },
[32504] = { ["id"] = 32504, ["name"] = "Mission: The Secrets of Stormwind", ["level"] = 20, ["requiredLevel"] = 15, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["storyline"] = { 32504 }, ["description"] = "Send undercover forces into the heart of enemy territory in an effort to learn of their plans.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[32505] = { ["id"] = 32505, ["name"] = "The Crumbled Chamberlain", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32505 }, ["description"] = "You there! Assist me. In life I was the Royal Chamberlain for his majesty, the Thunder King. For my dedication, I was condemned to this stone form, forever forced to watch over a portion of his wealth. Someone has desecrated my glorious body and sent pieces of it across the island. The thought of spending an eternity as nothing more than a head depresses me. Search the island, recover these pieces and I shall grant you one of his majesty's treasures.", ["objectivesText"] = "Check out Wowhead's Isle of Thunder Guide . Full of information on all of the new quests, rare spawns, achievements, and items! Recover the Shoulder, Head, Staff, Hair and Torso of the Chamberlain . Progress: I require ALL of my pieces. If so much as a pebble is missing, I shall consider forfeiting our agreement.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 8827, 40482, 60854, 85500, 93792, 93793, 93794, 93795, 93796, 93803, 94221, 94222, 94233, 95350, 104287, 104293, 109076 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard" },
[32506] = { ["id"] = 32506, ["name"] = "A Wing to Fly On", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32506 }, ["description"] = "I've just received a report that another young pterrorwing has been spotted in the Diremoor. We need to recover as many of these as we can find. They may be the key to flying on this island.", ["objectivesText"] = "Recover a Wild Ptrerrorwing Hatchling. Progress: A great gloom looms over this island...", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 94605 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3286 } },
[32507] = { ["id"] = 32507, ["name"] = "Skin of the Saurok", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32507 }, ["description"] = "Ihgaluk Crag is a dangerous place. Luckily, you have the magic of the Sunreavers behind you. I can transform you into a saurok. I will perform the first half of the illusion on you now. Afterwards, you should go directly to Ihgaluk Crag and slay one of the Skumblade saurok . Once you have done this, I will contact you and complete the second half of the illusion.", ["objectivesText"] = "Go to Ihgaluk Crag and slay a Skumblade saurok .", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard" },
[32518] = { ["id"] = 32518, ["name"] = "Short-Supply Reward", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = { "worldboss" }, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 4, ["storyline"] = { 32518 }, ["rewardItems"] = { 69903, 90818, 103533, 120334, 128803, 140591, 141701, 160054, 184522, 201326, 224573, 259086 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["worldSystems"] = { ["worldBosses"] = { { ["id"] = 3, ["name"] = "Nalak" } } } },
