[32520] = { ["id"] = 32520, ["name"] = "Competing Magic", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32520 }, ["description"] = "My scouts have spotted a dangerous Zandalari just this side of Za'Tual. I need someone capable to see him dispatched. Are you up to the task?", ["objectivesText"] = "Kill Arcweaver Jor'guva .", ["rewardGold"] = 228000, ["rewardXP"] = 294000, ["rewardItems"] = { 94219, 94220 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3286 } },
[32521] = { ["id"] = 32521, ["name"] = "Encroaching Force", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32521 }, ["description"] = "My scouts have spotted a Zandalari war party on the northern beach. I need someone capable to see him dispatched. Are you up to the task?", ["objectivesText"] = "Kill Nurkala , the Zandalari War Leader.", ["rewardGold"] = 228000, ["rewardXP"] = 294000, ["rewardItems"] = { 94220 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3286 } },
[32522] = { ["id"] = 32522, ["name"] = "Imposing Threat", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32522 }, ["description"] = "My scouts have spotted a mogu leader under the central tower. He needs to be killed before he can mount an offensive on our position. Can you take care of this for me?", ["objectivesText"] = "Kill Horgak the Enslaver .", ["rewardGold"] = 228000, ["rewardXP"] = 294000, ["rewardItems"] = { 94219, 94220 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3286 } },
[32524] = { ["id"] = 32524, ["name"] = "The Beating of Troll Drums", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32524 }, ["description"] = "Do you hear that, <class>? The beating of war drums in the distance. The Zandalari are preparing for us. Let's not give them the luxury of time to organize their defenses. We need to push the attack now! Report to Scout Captain Elsia within Conqueror's Terrace. She will have further orders for you.", ["objectivesText"] = "Locate Scout Captain Elsia within Conqueror's Terrace.", ["rewardGold"] = 28500, ["rewardXP"] = 59000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3286 } },
[32525] = { ["id"] = 32525, ["name"] = "Ashes of the Enemy", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32525 }, ["description"] = "The mogu at the Court of Bones are bolstering their army by resurrecting the spirits of their dead. We cannot allow them to revive their fallen warriors. Take this torch and burn any mummified corpses that you can find. We will destroy our enemies before they have a chance to rise.", ["objectivesText"] = "Burn 8 Mummified Remains . Progress: The dead should be allowed to rest.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 93751 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3285 } },
[32527] = { ["id"] = 32527, ["name"] = "Grave Circumstances", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32527 }, ["series"] = { 32731 }, ["description"] = "The Court of Bones crawls with mogu forces. Endlessly do they perform their rituals of lightning and thunder. If our mission to take this island is to succeed, then we cannot allow them to hold such a strategic position. They must be eliminated.", ["objectivesText"] = "Kill 10 Shan'ze Gravekeepers, Shan'ze Soulrippers , or Shan'ze Thundercallers. Progress: The mogu are powerful, but with cunning and tenacity, we can defeat them.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3285 } },
[32528] = { ["id"] = 32528, ["name"] = "Into the Crypts", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32528 }, ["description"] = "Every day, we uncover additional relics from the Court of Bones. Recently, we discovered this scroll amongst the gravestones in one of the deepest crypts. I believe that this incantation can be used to call beyond the grave. And if my Mogu is up to date, I'd say you should use it in the last room in the Hall of the Exalted. Would you be willing to test out my theory?", ["objectivesText"] = "Use the Incantation of Gura in the Hall of the Exalted, then defeat Gura the Reclaimed .", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 93803 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3285 } },
[32529] = { ["id"] = 32529, ["name"] = "The Call of Thunder", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32529 }, ["description"] = "Within the graveyard, in the deepest ruins of their western crypt, the Thunder King's most powerful sorcerers are charging a lightning rod with crackling electricity. We suspect that this weapon is meant to rain destruction on our stronghold at Violet Rise. There is no time to delay. You must stop their ritual at once.", ["objectivesText"] = "Stop the Shan'ze Thundercallers' ritual. Progress: Do not allow them to unleash the force of their weapon.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 52596, 52622 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3285 } },
[32530] = { ["id"] = 32530, ["name"] = "The Bloodletter", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32530 }, ["description"] = "I have heard a disturbing report, <class>. Just beyond our position, in the Court of Bones, the mogu bring captives to a general named Kaida the Bloodletter . He thrives on torturing his victims. This monster must be stopped. If you fall to his blade, I wish you a swift death.", ["objectivesText"] = "Kill Kaida the Bloodletter .", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3285 } },
[32531] = { ["id"] = 32531, ["name"] = "The Conquest of Stone", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32531 }, ["description"] = "In the Court of Bones, the Thunder King's sorcerers perform dark rituals. To bolster their numbers, the Shan'ze soulrippers are imbuing ancient stone statues with stolen spirits from the living. After these stone conquerors are brought to life, they will be formidable opponents on the battlefield. We must stop their ritual before these statues can be revived.", ["objectivesText"] = "Disrupt the Ancient Stone Conqueror ritual in the main temple at the Court of Bones.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3285 } },
[32532] = { ["id"] = 32532, ["name"] = "Rise No More!", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32532 }, ["description"] = "Have you seen the ghosts wandering the graveyard? They are risen ancestors , the spirits of slain mogu who have been called back to this world. When angered, they attack swiftly and silently, and their numbers increase by the day. They do not belong here. Destroy them, and send them back beyond the grave.", ["objectivesText"] = "Kill 15 Risen Ancestors . Progress: How is the situation at the graveyard?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3285 } },
[32533] = { ["id"] = 32533, ["name"] = "Stone Cold", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32533 }, ["description"] = "Our assault on the Court of Bones continues. Our progress remains slow, but measurable. Unfortunately, we've received several reports of stone quilen statues coming to life without warning. These quilen are too dangerous to ignore. Venture into the Court of Bones and destroy any quilen statues that you can find.", ["objectivesText"] = "Destroy 8 Grave Guardians .", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3285 } },
[32535] = { ["id"] = 32535, ["name"] = "The Skumblade Threat", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32535 }, ["series"] = { 32732 }, ["description"] = "Ihgaluk Crag has no end of saurok. Those beasts attack my men and spread their disease into nearby water and wildlife, interfering with our operations. Thin their numbers, <name>. Once the Alliance takes full control of this island, we can look for more permanent solutions.", ["objectivesText"] = "Slay 10 Skumblade saurok . Progress: Our tacticians seem to think there is some value in the saurok's presence. I am starting to strongly question these views.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3285 } },
[32536] = { ["id"] = 32536, ["name"] = "Manipulating the Saurok", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32536 }, ["description"] = "I have three magisters entrenched in Ihgaluk Crag, monitoring the saurok and - where they can - turning them against the mogu. I need you to find them and see if they need any supplies or assistance. They will be concealed from view. Look for shimmering columns of light within the saurok village.", ["objectivesText"] = "Check in with Magister Yalis , Magister Lyanis , and Magistrix Sanal .", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3285 } },
[32537] = { ["id"] = 32537, ["name"] = "De-Constructed", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32537 }, ["description"] = "Saurok consistently test our borders, and our constructs usually fend them off. Some constructs, however, have been defeated and dragged back to Ihgaluk Crag. I want those constructs back. No slithering lizard will steal Silver Covenant property under my watch.", ["objectivesText"] = "Recover the four stolen Silver Covenant Constructs. Progress: Hmph... saurok. <Modera spits.>", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3285 } },
[32538] = { ["id"] = 32538, ["name"] = "Heinous Sacrifice", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32538 }, ["description"] = "Some of the strongest of the spiritbinders perform heinous rites to their wretched gods. We've devised a method to destroy their altars, so the difficult task will be getting to each altar alive. Venture into the depths of Za'Tual and destroy their altars.", ["objectivesText"] = "Destroy the Zandalari's sacrificial altars.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3285 } },
[32539] = { ["id"] = 32539, ["name"] = "Dark Offerings", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32539 }, ["description"] = "The Zandalari's spiritbinders perform dark sacrifices to appease their gods, killing our people in the process. Destroy any Zandalari offerings you can find in Za'Tual to help slow the pace of their dark sacrifices.", ["objectivesText"] = "Destroy 6 Zandalari Offerings.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3285 } },
[32540] = { ["id"] = 32540, ["name"] = "Harbingers of the Loa", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32540 }, ["description"] = "If you spend some time in Za'Tual, you will likely see one of their large tents emanating a pure form of evil. Please, venture into the troll camp and put a stop to these unspeakable rituals.", ["objectivesText"] = "Slay 2 Harbingers of the Loa.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3285 } },
[32541] = { ["id"] = 32541, ["name"] = "Preventing a Future Threat", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32541 }, ["description"] = "It pains me to think of the torture the poor skyscreamers must endure as the trolls train them to become implements of war. The hatchlings are quite fearful, and will fly away if you even get close them. Please, frighten some away before the Zandalari corrupt them.", ["objectivesText"] = "Frighten 12 Hatchling Skyscreamers by running near them.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3285 } },
[32542] = { ["id"] = 32542, ["name"] = "Surgical Strike", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32542 }, ["description"] = "Zandalari spiritbinders perform sacrifices to their gods, the beastcallers bend innocent skyscreamers to their will, and the jaguar warriors venture closer to us by the day. Dispose of these threats in Za'Tual, <race>, and watch the might of the trolls weaken.", ["objectivesText"] = "Slay 3 Zandalari Spiritbinders , 3 Zandalari Beastcallers , and 3 Zandalari Jaguar Warriors .", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3285 } },
[32543] = { ["id"] = 32543, ["name"] = "Dangers of Za'Tual", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32543 }, ["series"] = { 32733 }, ["description"] = "The Zandalari are a formidable foe - more so than many foes we've encountered in the past. But you are a formidable foe as well, <name>. Enter Za'Tual to and show them the risks associated with opposing the likes of you.", ["objectivesText"] = "Slay 12 Trolls in Za'Tual. Progress: Have the trolls discovered the dangers wrought by <name>?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3285 } },
[32544] = { ["id"] = 32544, ["name"] = "Pterrible Ptorment", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32544 }, ["description"] = "One of the trolls' skyscreamers in Za'Tual is undergoing a ritual of torture, its will being bent forever to serve its masters. Kill those that inflict such torment on the creature and we can only hope that it will return to the skies.", ["objectivesText"] = "Free the Tormented Skyscreamer . Progress: Have you freed the creature?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3285 } },
[32545] = { ["id"] = 32545, ["name"] = "The Residents of Ihgaluk", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32545 }, ["description"] = "The Skumblade threaten our people, but responding with all-out slaughter would be an overreaction. A more reasonable response to their threat would be to slay some of their tribal leaders. There will be less bloodshed, and they will still respect our perimeter.", ["objectivesText"] = "Slay a Skumblade Brute , a Skumblade Saur-Priest , and a Skumblade Seadragon .", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3285 } },
[32546] = { ["id"] = 32546, ["name"] = "Just Some Light Clean-Up Work", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32546 }, ["description"] = "This is not a glamorous job. Let me put it to you bluntly. The Skumblade saurok pile all of their filth into a pool in the middle of their village. This filth is so concentrated and so rancid that it has congealed into moving, animate matter. The saurok can keep their filth-pool, but once it starts spreading outside of the village, I'd say it's time to intervene.", ["objectivesText"] = "Disperse 75 pieces of filth by killing Quivering Filth in Ihgaluk Crag. Progress: Sorry in advance about the smell.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3285 } },
[32547] = { ["id"] = 32547, ["name"] = "The Creeping Carpet of Ihgaluk", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32547 }, ["description"] = "Ah, roaches! I once bought a pet roach in Booty Bay. Roaches will soak up disease like a sponge, and then spread it as far as they can run. Which is pretty far. Ihgaluk Crag is crawling with the things, and they carry Skumblade filth all over of this island. Crush as many of them as you can while you're there.", ["objectivesText"] = "Crush 75 Ihgaluk Roaches. Progress: This should be fairly simple. Just smush them.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3285 } },
[32548] = { ["id"] = 32548, ["name"] = "Left To Rot", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32548 }, ["description"] = "The Skumblade saurok do not eat all of the meat they hunt. They reserve large portions of it to rot in piles near their homes, attracting pests and spreading disease. We can't have the saurok spreading their disease beyond the borders of Ihgaluk Crag. Dispose of any excess meat that you find.", ["objectivesText"] = "Destroy 3 Fetid Meat Piles . Progress: I know of many ways to spread disease, but this one is novel.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3285 } },
[32549] = { ["id"] = 32549, ["name"] = "Skin of the Saurok", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32549 }, ["description"] = "Ihgaluk Crag is a dangerous place. Luckily, you have the magic of the Kirin Tor behind you. I can transform you into a saurok. I will perform the first half of the illusion on you now. Afterwards, you should go directly to Ihgaluk Crag and slay one of the Skumblade saurok . Once you have done this, I will contact you and complete the second half of the illusion.", ["objectivesText"] = "Go to Ihgaluk Crag and slay a Skumblade saurok .", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard" },
[32550] = { ["id"] = 32550, ["name"] = "Saur Loser", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32550 }, ["description"] = "Inside the Beast Pens you will encounter some of the most skilled beast tamers in the Zandalari military. They are trained to kill with axe, beast, and claw. This is where they build their cavalry. We need you to kill any Zandalari you find in the Beast Pens before they can get their mounted monstrosities out into the open battlefield.", ["objectivesText"] = "Defeat 10 Zandalari trolls in the Beast Pens.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 69777 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3285 } },
[32551] = { ["id"] = 32551, ["name"] = "Compy Stomp", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32551 }, ["description"] = "The raptors and compies of the Zandalari represent a substantial threat to our forces here. They are superb hunting beasts that can track prey over great distances and are often lethal to encounter when caught unawares. I need you to head into the Beast Pens and cull their numbers. We need to make sure to slay them before they are fully trained.", ["objectivesText"] = "Kill 5 Raptors and 10 Trained Compies in the Beast Pens.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3285 } },
[32552] = { ["id"] = 32552, ["name"] = "Loa-saur", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32552 }, ["description"] = "The Zandalari have found a way to bind loa to their beasts giving them impressive and lethal powers. We need to put a stop to this. Search the Beast Pens for a loa speaker and slay him. You should be able to find them by keeping a look out for their glowing beasts. We must not allow these atrocities to continue.", ["objectivesText"] = "Defeat a Loa Speaker .", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3285 } },
[32553] = { ["id"] = 32553, ["name"] = "Direhorn vs Devilsaur", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["storyline"] = { 32553 }, ["description"] = "We have an opportunity to disrupt the Zandalari war machine as well as have a little fun in the process. Within these beast pens, a devilsaur and a direhorn are being outfitted with armor, their minds being enslaved to the Zandalari charms. Go into the camp and disrupt one of these binding rituals. It doesn't matter which one. Just kill those who are trying to bind the creature. This should let the fully armored beast run mad through the Zandalari camp. Then sit back and watch the hilarity ensue.", ["objectivesText"] = "Disrupt a binding ritual by killing all ritual NPCs around either a Defiant Direhorn or a Defiant Devilsaur.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2LabelIDs"] = { 3285 } },
[32554] = { ["id"] = 32554, ["name"] = "Dino Might", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32554 }, ["description"] = "The Zandalari use a series of fetishes and charms to maintain their control over their menagerie of beasts. Two can play at that game. I want you to find some of these fetishes and try them out on the various beasts in the Beast Pens. Take careful note of how each beast responds to each fetish. Then report your results to me. Maybe this will give us the edge we need against the Zandalari.", ["objectivesText"] = "Find and use Saur Fetishes on 5 raptors, compies, skyscreamers or direhorns in the Beast Pens.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 93668 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3285 } },
[32555] = { ["id"] = 32555, ["name"] = "Centuries in Sentries", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32555 }, ["description"] = "Sacrifices are common place in Zandalari society. There is however one oddity among these barbaric rituals; volunteers. They treat it as a great honor! The weak still seek to contribute, even if that means giving their lives to be bound to the sentries you see walking around. Locked away in service to their people. Take this resonating crystal. Once destroyed, drain the sentry of its Zandalari inhabitant. Return the crystal to me when your task is complete.", ["objectivesText"] = "Kill 5 Spirit-Bound Sentries and then use the Resonance Crystal to capture the Zandalari spirits trapped within.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 93806 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3285 } },
[32556] = { ["id"] = 32556, ["name"] = "The More You Know", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["storyline"] = { 32556 }, ["description"] = "This whole area is littered with Zandalari artifacts. I would be lying if I said studying them didn't interest me. I am fascinated by the significance of these objects to their rituals. The more we understand our enemies, the better prepared we are to defeat them. If I am to study them, I will need to see them up close. Bring me as many artifacts as you can find.", ["objectivesText"] = "Retrieve 6 Ritual Artifacts from around Conqueror's Terrace.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 93735 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2LabelIDs"] = { 3285 } },
[32557] = { ["id"] = 32557, ["name"] = "Out of Enemy Hands", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32557 }, ["description"] = "Magic is a frightening opponent when wielded by an experienced caster. A blade however, is terrifying in even the most inexperienced hands. The Zandalari have some impressive weapons, made even more deadly by the magic they are enhanced with. We should relieve them of this advantage. Steal as many of the weapons as you can find.", ["objectivesText"] = "Steal 7 Loa-Infused Blades from Conqueror's Terrace. Progress: What did you find out there? Anything that can be of use?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 93736 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3285 } },
[32558] = { ["id"] = 32558, ["name"] = "All In the Family", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32558 }, ["description"] = "Conqueror's Terrace is watched over by two brothers; Spiritbinder Tu'chek and Arcanital Rak'ul. They are powerful magic users and should not be underestimated. Their power seems to stem from the ornate masks they wear; relics passed down from one generation to the next. Each owner imbuing it with their own magic before passing it on. We must deal with the brothers and destroy their masks before they fall into the wrong hands.", ["objectivesText"] = "Retrieve the Mask of the Dark Mystic and the Mask of the Spirit-Caller from Spiritbinder Tu'chek and Arcanital Ra'kul within Conqueror's Terrace. Progress: Where are the masks?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 3440, 3446, 57161, 57162, 57163, 81449, 81450, 81451, 81452, 81453, 81454, 81455, 81456, 81457, 87310, 87311, 87312, 87313, 87314, 93733, 93734 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3285 } },
[32559] = { ["id"] = 32559, ["name"] = "Even Giants Fall", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32559 }, ["description"] = "The Zandalari worship the loa; animal spirits they often call to their aid. They may be trying to bind these spirits into a huge golem. The outcome would be disastrous. I've sent ahead a scout to gather more information, but I think this task may require your expertise. Stop that ritual at all costs!", ["objectivesText"] = "Destroy Guardian Tak'u within Conqueror's Terrace.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3285 } },
[32560] = { ["id"] = 32560, ["name"] = "Keep It Secret", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32560 }, ["series"] = { 32568 }, ["description"] = "The Zandalari here are a threat to our campaign, <class>. Their use of magic is an abomination. They mix the power of arcane with the darkness of shadow with little care to consequence. We cannot afford for them to find their full strength here or for the Horde to learn of their twisted magic. Their numbers must be thinned. I will leave this task to you.", ["objectivesText"] = "Kill any 8 Zandalari trolls within Conqueror's Terrace.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 37383, 37434, 37512, 37559, 199210 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3285 } },
[32561] = { ["id"] = 32561, ["name"] = "Competing Magic", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32561 }, ["description"] = "One of my scryers has identified a Zandalari leader near the central tower. He needs to be removed. Would you be willing to do this for me, <class>?", ["objectivesText"] = "Kill Arcweaver Jor'guva . Progress: Is it done?", ["rewardGold"] = 228000, ["rewardXP"] = 294000, ["rewardItems"] = { 94219, 94220 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3286 } },
