[32568] = { ["id"] = 32568, ["name"] = "No Time To Rest", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32568 }, ["series"] = { 32560 }, ["description"] = "We have accomplished much since arriving here, but now is not the time to rest. Your efforts have helped us breach the upper level of the Thunder King's stronghold. Now, I call on you to continue our campaign. Report to Scout Captain Daelin within Conqueror's Terrace. He will have further orders for you.", ["objectivesText"] = "Locate Scout Captain Daelin within Conqueror's Terrace.", ["rewardGold"] = 28500, ["rewardXP"] = 59000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3285 } },
