[32573] = { ["id"] = 32573, ["name"] = "Enemies Beneath the Tower", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32573 }, ["description"] = "There are mogu in the Diremoor animating the army of statues near the tower. Vereesa wants them dead. I think you're the one to do it.", ["objectivesText"] = "Kill 7 Shan'ze mogu in the Diremoor.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3285 } },
[32574] = { ["id"] = 32574, ["name"] = "The Shuddering Moor", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32574 }, ["description"] = "There is an immense beast in the swamp. It has not yet marched upon us, but I place no stock that we will continue to be so fortunate. Strike it down before it grows hungry enough to brave our defenses.", ["objectivesText"] = "Kill the Mighty Devilsaur .", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3285 } },
