[32585] = { ["id"] = 32585, ["name"] = "Encroaching Force", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32585 }, ["description"] = "We've spotted a Zandalari war party up the beach. We need to eliminate him before returning to camp. Would you be willing to handle this one?", ["objectivesText"] = "Kill Nurkala , the Zandalari War Leader.", ["rewardGold"] = 228000, ["rewardXP"] = 294000, ["rewardItems"] = { 94219, 94220 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3285 } },
[32586] = { ["id"] = 32586, ["name"] = "Maximum Capacitor", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32586 }, ["series"] = { 32587, 32588 }, ["description"] = "The mines north of here are critical to the mogu supply line. They are using giant lightning enchanted drills to extract the ore. If you can disrupt the drills, they'll be destroyed, greatly slowing their ability to make weapons. Oh, also, kill whoever is in charge, will you?", ["objectivesText"] = "Destroy the 3 lightning drills in the Ghost Iron Mines, and kill Metal Lord Mono-Han .", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3285 } },
[32587] = { ["id"] = 32587, ["name"] = "Forge Ahead!", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32587 }, ["series"] = { 32586, 32588 }, ["description"] = "The forge lies ahead of you, and with it the heart of the mogu's weaponsmithing ability. And beyond that, the mogu gatekeeper, who holds the key to unlocking the gate to the next part of the city. It's time to move out!", ["objectivesText"] = "Kill the Master of the Forge and collect a Codex Fragment from Fleshcrafter Hoku in the Isle of Thunder . Progress: Well?", ["rewardGold"] = 228000, ["rewardXP"] = 294000, ["rewardItems"] = { 93731, 94219, 94220 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3285 } },
[32588] = { ["id"] = 32588, ["name"] = "On Her Magic-ey Secret Service", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32588 }, ["series"] = { 32586, 32587 }, ["description"] = "Under orders from Jaina herself, some of our agents attempted to sneak past mogu lines to find out what was going on in the mines. They were captured, and are being subjected to who-knows-what kind of awful tortures. You must free them and kill whoever captured them. We don't leave anyone behind!", ["objectivesText"] = "Rescue the three captured Kirin Tor agents within the Ghost Iron Mines, and kill Metal Lord Mono-Han .", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 93761 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3285 } },
[32589] = { ["id"] = 32589, ["name"] = "Life Blood", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32589 }, ["description"] = "Scouts unearthed this strange construct hidden within the Lightning Vein Mine. A secret weapon of the Thunder King no doubt. Perhaps, there is a chance we can use this discovery to our benefit. If we can re-animate it, we can study it. More importantly, we can discover its weakness. Go to the Throne of Thunder and use this crystal to capture whatever essence animates these constructs. Return to me when the task is complete.", ["objectivesText"] = "Use the Attuned Crystal to retrieve the Remnants of the Animus from the Dark Animus within the Throne of Thunder . Progress: Were you successful in our endeavor?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 94116, 94123, 95487, 95488, 95548, 95590 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "raid" },
[32590] = { ["id"] = 32590, ["name"] = "Meet Me Upstairs", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6006, ["storyline"] = { 32590 }, ["series"] = { 32457, 32591 }, ["description"] = "There's someone I'd like you to meet. Stormwind's own crown prince recently paid a visit to this humble inn. I've instructed my guards to defend him from any Horde aggression - I don't want to draw any undue attention to myself. He and I have been discussing world events, such as the battle along the southern shores, his encounter with Garrosh, and the upcoming assault on the Thunder King. Come! Let's talk upstairs...", ["objectivesText"] = "Meet Wrathion upstairs on the second floor of the Tavern in the Mists in the Veiled Stair.", ["rewardGold"] = 11400, ["rewardXP"] = 23600, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6006 } }, ["questType"] = "standard" },
[32591] = { ["id"] = 32591, ["name"] = "Secrets of the First Empire", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6006, ["storyline"] = { 32591 }, ["series"] = { 32457, 32590 }, ["description"] = "For two thousand years the mogu ruled this entire land. So brutal was their regime that its name is never uttered aloud: Pandaren call it either the \"Old Kingdom\" or \"First Dynasty.\" The Thunder King was its founder and first emperor. He amassed enormous power on what is now the Isle of Thunder. His time has passed, <name>. We should claim some of his power for ourselves. Gather mogu relics for me from the Throne of Thunder, and amass some trillium - I have a plan!", ["objectivesText"] = "Collect 20 Secrets of the Empire and 40 Trillium Bars . Progress: What have you uncovered from the Throne of Thunder? Is the Thunder King's ferocious reputation warranted?", ["rewardGold"] = 228000, ["rewardXP"] = 294000, ["rewardItems"] = { 45038, 46017, 72094, 72095, 72103, 76061, 87208, 87209, 89233, 94593, 94594, 94867 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6006 } }, ["questType"] = "standard" },
[32592] = { ["id"] = 32592, ["name"] = "I Need a Champion", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6006, ["storyline"] = { 32592 }, ["description"] = "You are a superb representative of your people, <race>. But I need someone special. I have big plans. And to enact them I will need a champion to carry my flame to the four corners of the world. Are you the one? Prove it to me on the Isle of Thunder! Lay waste to any mogu, Zandalari, or saurok that you find. Impress me!", ["objectivesText"] = "Earn Exalted Reputation with the Black Prince by defeating mogu, Zandalari, and saurok enemies on the Isle of Thunder.", ["rewardGold"] = 228000, ["rewardXP"] = 294000, ["rewardItems"] = { 64399, 64402, 72094, 72096, 72103, 76091, 94221, 94222, 94593, 95344, 95345, 95346, 95347 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6006 } }, ["questType"] = "standard" },
[32593] = { ["id"] = 32593, ["name"] = "The Thunder Forge", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6006, ["storyline"] = { 32593 }, ["series"] = { 32594, 32595, 32596, 32597 }, ["description"] = "Everything is prepared, <name>, and I have selected you to be my champion. Next, we must infiltrate the legendary Thunder Forge of Lei Shen himself! You and your faction will need to advance forward until the Thunder Forge is exposed, if it isn't already. Once you have infiltrated the forge, meet me there. Be ready for a fight!", ["objectivesText"] = "Progress through the Isle of Thunder until you unlock the Thunder Forge. Meet Wrathion outside the Thunder Forge and complete his task. Progress: The Mogu will not appreciate my tinkering with their ancient forge. But we won't let that stop us, hmm?", ["rewardGold"] = 228000, ["rewardXP"] = 294000, ["rewardItems"] = { 2459, 41107, 43867, 45746, 76096, 86572 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6006 } }, ["questType"] = "standard" },
[32595] = { ["id"] = 32595, ["name"] = "The Crown of Heaven", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6006, ["storyline"] = { 32595 }, ["series"] = { 32593, 32594, 32596, 32597 }, ["description"] = "Do you recall Mason's Folly, the hilltop east of here where you and I met before? I'm going to use the Lightning Lance to create something special, and I certainly can't do it in here. Meet me atop Mason's Folly so that we may celebrate our victories together!", ["objectivesText"] = "Meet Wrathion atop Mason's Folly in the Veiled Stair and collect your reward.", ["rewardGold"] = 11400, ["rewardXP"] = 23600, ["rewardItems"] = { 72095, 76132, 94593, 94594, 95344, 95345, 95346, 95347 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6006 } }, ["questType"] = "standard" },
[32596] = { ["id"] = 32596, ["name"] = "Echoes of the Titans", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6006, ["storyline"] = { 32596 }, ["series"] = { 32593, 32594, 32595, 32597 }, ["description"] = "I'm beginning to see the bigger picture, now, and how the mogu relate to the Titans. But every answer brings with it more questions! The only way to put this puzzle together is to find every scrap of Titan information we can scavenge from the Thunder King's palace. Destroy the Thunder King and his minions and collect as many Titan runestones as you can find!", ["objectivesText"] = "Collect 12 Titan Runestones from raid bosses in the Halls of Flesh-Shaping and the Pinnacle of Storms. Progress: What have you discovered so far? We need to gather all the information we can!", ["rewardGold"] = 228000, ["rewardXP"] = 294000, ["rewardItems"] = { 94593, 94594 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6006 } }, ["questType"] = "standard" },
[32599] = { ["id"] = 32599, ["name"] = "Securing A Future", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32599 }, ["description"] = "It is rumored that the Thunder King's power comes directly from a hidden source within his palace. Even when he is defeated a new tyrant, Garrosh perhaps, could still use this magic to a terrible end. That is unless we make the first move! Take my staff into the Pinnacle of Storms. Once Lei Shen has been defeated place my staff in the center of his dais. We will drain the rest of his power and make sure it stays in our hands.", ["objectivesText"] = "Defeat the Thunder King within the Pinnacle of Storms and use the Staff of Antonidas to drain the remaining power from his dais. Progress: We will be unstoppable once Lei Shen's power has been fused with my staff.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 94153, 94155, 95589 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "raid" },
[32600] = { ["id"] = 32600, ["name"] = "The Zandalari Prophecy", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 32600 }, ["description"] = "Dear $p, I have read your reports on the Zandalari and believe I have some clues as to their most recent aggression. If you visit us at the Seat of Knowledge in Vale of Eternal Blossoms we can add this contribution to your personal collection. Thank you for your diligence! Sincerely, Lorewalker Cho", ["objectivesText"] = "Bring The Zandalari Prophecy to Lorewalker Cho . Provided item:", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 94197 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard", ["startItems"] = { 94197 } },
[32601] = { ["id"] = 32601, ["name"] = "Rumbles of Thunder", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 32601 }, ["description"] = "Dear $p, The foreboding sound of thunder has haunted my people for generations. And as you have discovered in your own research, Lei Shen is at the heart of that fear. If you visit us at the Seat of Knowledge in Vale of Eternal Blossoms we can add this contribution to your personal collection. Thank you for your diligence! Sincerely, Lorewalker Cho", ["objectivesText"] = "Bring the Rumbles of Thunder to Lorewalker Cho . Provided item:", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 94198 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard", ["startItems"] = { 94198 } },
[32602] = { ["id"] = 32602, ["name"] = "Gods and Monsters", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 32602 }, ["description"] = "Dear $p, Is it true that the mogu are really connected to the titans? I find this very hard to believe. But looking over your research, some of the truth about the mogu begins to take shape. If you visit us at the Seat of Knowledge in Vale of Eternal Blossoms we can add this contribution to your personal collection. Thank you for your diligence! Sincerely, Lorewalker Cho", ["objectivesText"] = "Bring the Gods and Monsters to Lorewalker Cho . Provided item:", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 94199 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard", ["startItems"] = { 94199 } },
[32603] = { ["id"] = 32603, ["name"] = "Beasts of Fable", ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5840, ["mapID"] = 390, ["storyline"] = { 32603 }, ["description"] = "Have you ever read the great Pandaren book of fables? Pandaren pass these stories on to their cubs - stories of the cricket and the hawk, or the slow-moving turtle - to teach them lessons that they will find useful in life. What few cubs know is that these creatures exist, here, in Pandaria! Though the stories of their travels are made up, they are powerful denizens of this world. Should you happen upon them in your travels, you may test the might of your pets against their storied statures.", ["objectivesText"] = "Defeat the Elite Battle Pets of the Pandaren fables.", ["rewardGold"] = 8000, ["rewardXP"] = 80, ["rewardItems"] = { 78916, 85220, 94025, 94207 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 390, ["questLines"] = { { ["id"] = 289, ["name"] = "Battle Pet Tamers", ["orderIndex"] = 16, ["flags"] = 0 }, { ["id"] = 290, ["name"] = "Battle Pet Tamers", ["orderIndex"] = 16, ["flags"] = 0 } } },
[32604] = { ["id"] = 32604, ["name"] = "Beasts of Fable Book I", ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 32604 }, ["description"] = "The stories of Ka'wi the Gorger , Nitun , Kafi , and Dos-Ryga will exist in this land, always. Do you wish to meet them in battle once more?", ["objectivesText"] = "Defeat Ka'wi the Gorger , Nitun , Kafi , and Dos-Ryga .", ["rewardGold"] = 8000, ["rewardXP"] = 80, ["rewardItems"] = { 31760, 78916, 85220, 94025, 94207, 98715 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[32605] = { ["id"] = 32605, ["name"] = "Subtle Encouragement", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32605 }, ["description"] = "The saurok are vile, but we share an enemy: the mogu. And I'd rather send saurok to kill mogu than send my own men. We've been collecting mogu weaponry. Bury these polearms into the skulls of the saurok. Feed our enemies' rivalry, and you may save Horde lives.", ["objectivesText"] = "Plant Mogu Weapons into the corpses of 9 Skumblade saurok. Progress: As much as it pains me to say it: try not to kill them all. We need some alive if we want to turn them against the mogu.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3286 } },
[32606] = { ["id"] = 32606, ["name"] = "Subtle Encouragement", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32606 }, ["description"] = "The saurok are vile, but we share an enemy: the mogu. And I'd rather send saurok to kill mogu than send my own men. We've been collecting mogu weaponry. Bury these polearms into the skulls of the saurok. Feed our enemies' rivalry, and you may save Alliance lives.", ["objectivesText"] = "Plant Mogu Weapons into the corpses of 9 Skumblade saurok. Progress: As much as it pains me to say it: try not to kill them all. We need some alive if we want to turn them against the mogu.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3285 } },
[32607] = { ["id"] = 32607, ["name"] = "Extended Shore Leave", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32607 }, ["description"] = "The Zandalari have already begun repairing that warship, but we can keep it crippled with minimal effort. Simply relieve the new captain of his post, and steal the ship's damage report from that workshop just outside the vault. No captain. No repairs. No warship.", ["objectivesText"] = "Steal the Workshop Orders and slay the new captain of the Zandalari warship.", ["rewardGold"] = 456000, ["rewardXP"] = 471000, ["rewardItems"] = { 95371 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3285 } },
[32608] = { ["id"] = 32608, ["name"] = "Raiding the Vault", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32608 }, ["description"] = "The Swollen Vault is a repository for some of Lei Shen's nastiest weaponry and most prized trinkets - not surprisingly, these are often one and the same. One artifact in particular, an amulet known as the Choker of Storms , could help us to understand is apparent mastery over lightning. Break into the vault and slay the hoard-keeper. Take his key and use it to recover the amulet from a cache at the back of the vault.", ["objectivesText"] = "Steal the Choker of Storms from The Swollen Vault. Progress: The Thunder King's strength is legendary. We need every advantage we can get if we want to defeat him.", ["rewardGold"] = 456000, ["rewardXP"] = 471000, ["rewardItems"] = { 95372, 95374 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3285 } },
