[32621] = { ["id"] = 32621, ["name"] = "Lightning Steel", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32621 }, ["description"] = "Your trained eyes can see that this metal ingot has some very strange properties. Perhaps there are clues to its nature somewhere around here?", ["objectivesText"] = "Investigate the Thunder Forge to find the Secrets of Lightning Steel . Provided item:", ["rewardGold"] = 11400, ["rewardXP"] = 23600, ["rewardItems"] = { 72096, 94111, 94552, 94553, 94567, 94568, 94569, 94570, 94571, 94572, 94721 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["startItems"] = { 94721 } },
