[32627] = { ["id"] = 32627, ["name"] = "Charged Moganite", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6677, ["storyline"] = { 32627 }, ["description"] = "We have been dispatching spies into the Sunreaver base of operations on a daily basis. Some had orders to recover charged moganite from the enemy and bring it here. They have not returned, and I can confirm they have left the Sunreaver base. Search the jungle between here and there and find any of the charged moganite that might have been lost in transit. Bring it to me and we will put it to good use.", ["objectivesText"] = "Recover a Charged Moganite and bring it to Warmage Yurias .", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 95567 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6677 } }, ["questType"] = "pvp", ["db2LabelIDs"] = { 3285 } },
[32628] = { ["id"] = 32628, ["name"] = "Tactical Mana Bombs", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["storyline"] = { 32628 }, ["description"] = "Ah, $p, just the <race> I was looking for. I have received another batch of tactical mana bombs that I need planted in key positions across Dawnseeker Promontory to the northwest. Here, take these. It is time to give the Sunreavers a taste of their own medicine. Plant one on the Sunreaver ships, another one on their scrying crystals, and the last on the bridge that connects to their forward base.", ["objectivesText"] = "Plant a Tactical Mana Bomb on a Sunreaver ship, the Scrying Crystals, and on the most inland bridge of Dawnseeker Promontory.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 94905 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "pvp", ["db2LabelIDs"] = { 3285 } },
[32631] = { ["id"] = 32631, ["name"] = "High Recognition", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32631 }, ["rewardGold"] = 228000, ["rewardXP"] = 294000, ["rewardItems"] = { 94219, 94220 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "pvp", ["db2LabelIDs"] = { 3285 } },
[32632] = { ["id"] = 32632, ["name"] = "Made for War", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32632 }, ["description"] = "Some things are built with multiple purposes in mind. Some things are built with the sole purpose of destruction. A massive construct called the Pyrestar Demolisher sits guarding Dawnseeker Promontory. Its purpose is solely to destroy. It must be dismantled.", ["objectivesText"] = "Kill the Pyrestar Demolisher .", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "pvp", ["db2LabelIDs"] = { 3285 } },
[32633] = { ["id"] = 32633, ["name"] = "Spellbound", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6677, ["storyline"] = { 32633 }, ["description"] = "Grand Magister Rommath has something in his possession that I want. He brought a very powerful tome with him. It would be better for our cause if it were no longer in Sunreaver hands. Locate Rommath's book of incantations and bring it to me.", ["objectivesText"] = "Retrieve Rommath's Book of Incantations from Dawnseeker Promontory. Progress: Did you find the tome?", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 95094 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6677 } }, ["questType"] = "pvp", ["db2LabelIDs"] = { 3285 } },
[32634] = { ["id"] = 32634, ["name"] = "Breaking Down the Defenses", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32634 }, ["description"] = "Even the strongest defense can still have a weakness, <class>. We just need to find the weakness in the Sunreaver's defense and then exploit it as much as possible. Scouts have reported the use of perimeter wards around Dawnseeker Promontory. They're powerful, but not deadly. Disabling them would allow us to keep closer watch on their activities.", ["objectivesText"] = "Destroy 6 Sunreaver Perimeter Wards around Dawnseeker Promontory.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "pvp", ["db2LabelIDs"] = { 3285 } },
[32635] = { ["id"] = 32635, ["name"] = "Enough with the Bombs!", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32635 }, ["description"] = "The Sunreavers have planted tactical mana bombs around our camp. These must be dismantled before they are detonated. Look for them in areas of high importance such as our supplies. Make sure you find and disable them all. We cannot afford to lose any ground here.", ["objectivesText"] = "Disarm the Tactical Mana Bombs at the Alliance Ships, the Construct Ritual, and the Supplies within Violet Rise.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "pvp", ["db2LabelIDs"] = { 3285 } },
[32636] = { ["id"] = 32636, ["name"] = "Captive Audience", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32636 }, ["description"] = "The Sunreavers will stoop to even the lowest levels to get what they want, <name>. I received reports earlier that several Kirin Tor have gone missing. I suspect the Sunreavers may have something to do with this. Hopefully they have not been harmed, or my wrath will be swift and terrible. I trust you to bring them back in one piece, but please hurry.", ["objectivesText"] = "Free 5 Kirin Tor Captives near Dawnseeker Promontory.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "pvp", ["db2LabelIDs"] = { 3285 } },
[32637] = { ["id"] = 32637, ["name"] = "Overpowered", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32637 }, ["description"] = "The Sunreaver forces have grown more powerful recently. I suspect magic to be at play here, but I can't be certain. I think it would be wise to investigate their camp to see if you can find the source of this extra power. Once you find it, use this crystal to overload and destroy it.", ["objectivesText"] = "Destroy 7 Sunreaver Mana Collectors around Dawnseeker Promontory.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 95360 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "pvp", ["db2LabelIDs"] = { 3285 } },
[32638] = { ["id"] = 32638, ["name"] = "Mana Scavengers", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32638 }, ["description"] = "Sometimes, even the smallest creatures can be the biggest threat. The Sunreavers brought mana wyrms with them. Though small in size they have the ability to cripple our casters in combat. Many have learned the hard way not to underestimate them. They must be dealt with and quickly.", ["objectivesText"] = "Kill 9 Sunreaver Mana Wyrms .", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "pvp", ["db2LabelIDs"] = { 3285 } },
[32639] = { ["id"] = 32639, ["name"] = "Deconstruction", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32639 }, ["description"] = "Scouts are reporting a large number of constructs patrolling outside of Dawnseeker Promontory. If left unchecked they will pose a considerable threat should the Sunreavers mount an attack. The only answer is a preemptive strike. We'll destroy them before they can attack us!", ["objectivesText"] = "Destroy 3 Sunreaver Constructs outside of Dawnseeker Promontory.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "pvp", ["db2LabelIDs"] = { 3285 } },
[32642] = { ["id"] = 32642, ["name"] = "Work Order: Dominance Offensive I", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 32642 }, ["series"] = { 32643 }, ["description"] = "<Yoon's writing decorates the page though his feelings seem conflicted.> I normally try to stay out of conflict, but an order is an order. Since you are of the Horde I decided to pass this order your way. The Dominance Offensive has requested an order of red blossom leeks. The troops down there just can't seem to get enough of them!", ["objectivesText"] = "Plant 8 Red Blossom Leek Seeds on Sunsong Ranch.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[32643] = { ["id"] = 32643, ["name"] = "Work Order: Dominance Offensive II", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 32643 }, ["series"] = { 32642 }, ["description"] = "Once your red blossom leeks are ready to be picked, you'll need only to package them for pick-up. Just think; your red blossom leeks will be a part of your faction's efforts in Pandaria!", ["objectivesText"] = "Harvest 8 Ripe Red Blossom Leek plants and provide 40 Red Blossom Leeks for the Dominance Offensive. Progress: The crate sits empty awaiting your crops.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 74844 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
