[32647] = { ["id"] = 32647, ["name"] = "Work Order: Golden Lotus I", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 32647 }, ["series"] = { 32648 }, ["description"] = "<Yoon kept this order request short.> The Golden Lotus have requested a large number of white turnips. Their request mentioned something about trouble-making sprites wreaking havoc on Mistfall Village. Apparently the sprites don't like turnips!", ["objectivesText"] = "Plant 8 White Turnip Seeds on Sunsong Ranch.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
