[32676] = { ["id"] = 32676, ["name"] = "Extended Shore Leave", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32676 }, ["description"] = "The Zandalari have already begun repairing that warship, but we can keep it crippled with minimal effort. Simply relieve the new captain of his post, and steal the ship's damage report from that workshop just outside the vault. No captain. No repairs. No warship.", ["objectivesText"] = "Steal the Workshop Orders and slay the new captain of the Zandalari warship.", ["rewardGold"] = 456000, ["rewardXP"] = 471000, ["rewardItems"] = { 95371 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3286 } },
[32677] = { ["id"] = 32677, ["name"] = "Raiding the Vault", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32677 }, ["description"] = "The Swollen Vault is a repository for some of Lei Shen's nastiest weaponry and most prized trinkets - not surprisingly, these are often one and the same. One artifact in particular, an amulet known as the Choker of Storms , could help us to understand his apparent mastery over lightning. Break into the vault and slay the hoard-keeper. Take his key and use it to recover the amulet from a cache at the back of the vault.", ["objectivesText"] = "Steal the Choker of Storms from The Swollen Vault. Progress: You have good news, I hope.", ["rewardGold"] = 456000, ["rewardXP"] = 471000, ["rewardItems"] = { 95372, 95374 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3286 } },
[32682] = { ["id"] = 32682, ["name"] = "Inherit the Earth", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 32682 }, ["description"] = "As you know, <name>, I'm getting along in my years. One can't stay a spry young pandaren forever, you know. I'm looking for someone to take over my duties here at the Tillers Union, and I can't think of a better person than Farmer Yoon. He's got a good deal to learn, but he's got a good head on his shoulders and most importantly, a generous heart. Do you think he'd be interested?", ["objectivesText"] = "Speak to Farmer Yoon. Progress: Julep and juice, now that's a nice combination!", ["rewardGold"] = 57000, ["rewardXP"] = 118000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[32683] = { ["id"] = 32683, ["name"] = "So You Want to Be a Blacksmith...", ["level"] = 85, ["requiredLevel"] = 85, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6142, ["storyline"] = { 32683 }, ["description"] = "While it is best to learn the properties of simpler metals and work your way up, it is possible to learn how to become a good blacksmith through mastering the various applications of ghost iron for common household objects. If you wish to take this path towards becoming a zen master blacksmith, I can teach you. Whichever way you choose, you will have my respect if you can show me that you can make a ghostly skeleton key .", ["objectivesText"] = "Create a Ghostly Skeleton Key by attaining at least 500 skill in blacksmithing. If you wish to train through pandaren materials, a training project appropriate to your skill level can be learned from Cullen Hammerbrow . Progress: How are your studies coming along?", ["rewardGold"] = 9400, ["rewardXP"] = 6940, ["rewardItems"] = { 82960 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6142 } }, ["questType"] = "standard" },
[32684] = { ["id"] = 32684, ["name"] = "You Want Fish?", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 32684 }, ["description"] = "Are you looking for golden carp ? or some other Pandaren fish? I'm no fisherman myself, but there is a fellow by the river who has been teaching the folks traveling through here. If you go speak with him, he will likely give you some fish, as well as teach you how to fish.", ["objectivesText"] = "Speak with Ben of the Booming Voice .", ["rewardGold"] = 11400, ["rewardXP"] = 23600, ["rewardItems"] = { 74866 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[32685] = { ["id"] = 32685, ["name"] = "No Fishing Pole Necessary!", ["level"] = 90, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 32685 }, ["description"] = "You don't even need to equip a fishing pole in Pandaria! The waters are TEEMING with fish. You'll catch one pretty much every time, as long as you are paying attention. Give it a go!", ["objectivesText"] = "Catch 5 Golden Carp . Try it without a fishing pole! To fish, simply click the Fishing icon on the Profession pane. Pay attention to the bobber, click on it when it bobs and you will have your fish! Progress: Catch 5 Golden Carp . Try it without a fishing pole!", ["rewardGold"] = 11400, ["rewardXP"] = 23600, ["rewardItems"] = { 74866 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[32686] = { ["id"] = 32686, ["name"] = "Pristine Banner of the Mantid Empire", ["level"] = 90, ["requiredLevel"] = 85, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 32686 }, ["description"] = "This artifact has been restored to a remarkably excellent condition. Perhaps you will put it on display at the Seat of Knowledge, so that lorewalkers and archaeologists can study it.", ["objectivesText"] = "Put the artifact on display. Progress: Remove the clutter and put the artifact on display.", ["rewardItems"] = { 87399, 95373, 95383 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard", ["startItems"] = { 95383 } },
