[32710] = { ["id"] = 32710, ["name"] = "Something Foul is Afoot", ["level"] = 93, ["requiredLevel"] = 90, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6622, ["storyline"] = { 32710 }, ["description"] = "You notice a stronger-than-usual smell permeating from ahead. Your stomach lurches as the thick smell fills your nostrils. You recognize this smell, it's saurok. Rotting, discarded saurok flesh infused with the foul waste of the sewer.", ["objectivesText"] = "Seek and destroy Flesh'rok the Diseased .", ["rewardItems"] = { 97153 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6622 } }, ["questType"] = "raid" },
[32711] = { ["id"] = 32711, ["name"] = "Agony and Anima", ["level"] = 93, ["requiredLevel"] = 90, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 4, ["storyline"] = { 32711 }, ["description"] = "You notice the initials A.K. skillfully and with calligraphic precision engraved onto the side of the Animus. Before you stands Archritualist Kelada , the shaper of the Animus. By command of the Thunder King, Kelada worked tirelessly to craft the perfect vessel to harness the great power of the anima. Something functional, magnificent, sentient, but most importantly... something deadly. He must be stopped before his next imagination is brought to life by the Thunder King.", ["objectivesText"] = "Slay Archritualist Kelada .", ["rewardItems"] = { 97153 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "raid" },
[32712] = { ["id"] = 32712, ["name"] = "Zao'cho the Wicked", ["level"] = 93, ["requiredLevel"] = 90, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6622, ["storyline"] = { 32712 }, ["description"] = "Electricity hums in the distance, tickling your ears and sending impulses down your spine. Your fingers go numb, and your heart races as you approach the door ahead. Zao'cho stands arrogantly atop the steps ahead, weaving lightning between his fingers and smirking at you with demented glee.", ["objectivesText"] = "Slay Zao'cho .", ["rewardItems"] = { 97153 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6622 } }, ["questType"] = "raid" },
[32713] = { ["id"] = 32713, ["name"] = "Rocks Fall, People Die", ["level"] = 93, ["requiredLevel"] = 90, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6622, ["storyline"] = { 32713 }, ["description"] = "Words fail to describe the massive horror of rock, bone, and blood that rumbles mindlessly and aimlessly ahead of you. Massive earthquakes crack the seemingly hollow shell of ground beneath the figure, leaving destruction in its wake. It appears that the creature is unaware of your presence.", ["objectivesText"] = "Slay the Rocky Horror .", ["rewardItems"] = { 97153 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6622 } }, ["questType"] = "raid" },
[32714] = { ["id"] = 32714, ["name"] = "Taming the Tempest", ["level"] = 93, ["requiredLevel"] = 90, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 4, ["storyline"] = { 32714 }, ["description"] = "You hear a fierce and militant voice roaring in the distance. A crackling storm swells and swirls around a clouded, shadowy figure. Lightning flashes and No'ku Stormsayer appears, his scornful gaze aimed directly at you.", ["objectivesText"] = "Slay No'ku Stormsayer .", ["rewardItems"] = { 97153 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "raid" },
[32715] = { ["id"] = 32715, ["name"] = "Requiem for a Queen", ["level"] = 93, ["requiredLevel"] = 90, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6622, ["storyline"] = { 32715 }, ["description"] = "A chilling breeze sweeps across your body, bringing with it a haunting drape of sadness. Your soul sinks as you hear the faint, melodic cries of Monara , the last Queen of the Mogu. Her sweet requiem creeps through the air, bending and shaping itself into a spectral hand, reaching for your heart. As it grabs hold, you see a brief flash of Monara 's last moments... her brutal murder by the hand of Lei Shen. Song turns to sadness and Monara weeps, wailing louder and louder into the darkness.", ["objectivesText"] = "Put Monara to rest.", ["rewardItems"] = { 97153 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6622 } }, ["questType"] = "raid" },
[32716] = { ["id"] = 32716, ["name"] = "Eyes of the Thunder King", ["level"] = 93, ["requiredLevel"] = 90, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 4, ["storyline"] = { 32716 }, ["description"] = "As the fog dissipates from the fallen sentries, you feel a sudden rumbling. The rocks blocking the sewer tunnels tumble forward and crash into the outflow tanks below, as four putrid eyes lunge from the darkness.", ["objectivesText"] = "Defeat the ambush!", ["rewardItems"] = { 97153 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "raid" },
[32718] = { ["id"] = 32718, ["name"] = "Mogu Runes of Fate", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 32718 }, ["description"] = "Greetings, <name>. I am privileged to offer you an excellent opportunity. Through the centuries, we've honed a method by which the very laws of chance themselves can be bent. With a Mogu Rune of Fate , valuable artifacts will find their way into your hands more frequently inside the palace of the Thunder King.", ["objectivesText"] = "Collect 50 Lesser Charms of Good Fortune . Progress: May these charms bring you great luck, <name>.", ["rewardGold"] = 456000, ["rewardXP"] = 471000, ["rewardItems"] = { 90458 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
