[32722] = { ["id"] = 32722, ["name"] = "Forge Ahead!", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32722 }, ["description"] = "There's more you must do. Kill Itoka , master of the forge, and find a codex fragment from Fleshcrafter Hoku, gatekeeper of the Thunder King.", ["objectivesText"] = "Kill the Master of the Forge and collect a Codex Fragment from Fleshcrafter Hoku in the Isle of Thunder . Progress: Well?", ["rewardGold"] = 228000, ["rewardXP"] = 294000, ["rewardItems"] = { 93731, 94219, 94220 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3286 } },
