[32726] = { ["id"] = 32726, ["name"] = "So You Want to Be a Blacksmith...", ["level"] = 85, ["requiredLevel"] = 85, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["storyline"] = { 32726 }, ["description"] = "While it is best to learn the properties of simpler metals and work your way up, it is possible to learn how to become a good blacksmith through mastering the various applications of ghost iron for common household objects. If you wish to take this path towards becoming a zen master blacksmith, I can teach you. Whichever way you choose, you will have my respect if you can show me that you can make a ghostly skeleton key .", ["objectivesText"] = "Create a Ghostly Skeleton Key by attaining at least 500 skill in blacksmithing. If you wish to train through pandaren materials, a training project appropriate to your skill level can be learned from Jorunga Stonehoof.", ["rewardGold"] = 9400, ["rewardXP"] = 6940, ["rewardItems"] = { 82960 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[32728] = { ["id"] = 32728, ["name"] = "The Court of Bones", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32728 }, ["series"] = { 32201 }, ["description"] = "The mogu within the nearby Court of Bones pose a constant threat to our foothold on this island. Grand Magister Rommath has been entrusted with halting their efforts, but I am certain he could use a capable <class> to see this task through. Go to him. Aid in whatever ways that you are able.", ["objectivesText"] = "Find Grand Magister Rommath outside the Court of Bones.", ["rewardGold"] = 28500, ["rewardXP"] = 59000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3286 } },
[32729] = { ["id"] = 32729, ["name"] = "Za'Tual", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32729 }, ["series"] = { 32200 }, ["description"] = "The Zandalari have been a constant nuisance since we arrived on this island. I've assigned Halduron Brightwing to take charge of dismantling their presence at Za'Tual, in the south. Report to Halduron when you are best able. He will have work for you.", ["objectivesText"] = "Find Halduron Brightwing outside of Za'Tual.", ["rewardGold"] = 28500, ["rewardXP"] = 59000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3286 } },
[32730] = { ["id"] = 32730, ["name"] = "Ihgaluk Crag", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32730 }, ["series"] = { 32204 }, ["description"] = "Aethas has taken over at Ihgaluk Crag, to the southeast, continuing his effort to turn the Saurok against the Zandalari and mogu. Go to him, and help in any way that you can.", ["objectivesText"] = "Find Archmage Aethas Sunreaver outside of Ihgaluk Crag.", ["rewardGold"] = 28500, ["rewardXP"] = 59000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3286 } },
[32731] = { ["id"] = 32731, ["name"] = "The Court of Bones", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6507, ["storyline"] = { 32731 }, ["series"] = { 32527 }, ["description"] = "The mogu within the nearby Court of Bones comprise one of the greatest threats to our presence on this island. Narasi Snowdawn has been entrusted with halting their efforts, but I am certain she could use a capable <class> to see this task through. Go to her. Aid in whatever ways that you are able.", ["objectivesText"] = "Find Narasi Snowdawn outside the Court of Bones.", ["rewardGold"] = 28500, ["rewardXP"] = 59000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6507 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3285 } },
