[32758] = { ["id"] = 32758, ["name"] = "Reader for the Dead Tongue", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["requiredClasses"] = { 9 }, ["categories"] = {}, ["flags"] = { "class" }, ["sharable"] = false, ["expansion"] = 4, ["storyline"] = { 32758 }, ["description"] = "Return to your capital city and seek out a warlock trainer who may know more about the codex.", ["objectivesText"] = "Bring the codex to a Warlock trainer in your capital city.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 92441 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
