[32826] = { ["id"] = 32826, ["name"] = "Re-Use Me", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["storyline"] = { 32826 }, ["description"] = "Ah, $p, just the <race> I was looking for. I have received another batch of tactical mana bombs that I need planted in key positions across Dawnseeker Promontory to the northwest. Here, take these. It is time to give the Sunreavers a taste of their own medicine. Plant one on the Sunreaver ships, another one on their scrying crystals, and the last on the bridge that connects to their forward base.", ["objectivesText"] = "Plant a Tactical Mana Bomb on a Sunreaver ship, the Scrying Crystals, and on the most inland bridge of Dawnseeker Promontory.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 22131, 22132, 22133, 22134, 22135, 22136, 71083, 94219, 94905 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "pvp" },
[32827] = { ["id"] = 32827, ["name"] = "Re-Use Me", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 4, ["storyline"] = { 32827 }, ["description"] = "Even the strongest defense can still have a weakness, <class>. We just need to find the weakness in the Sunreaver's defense and then exploit it as much as possible. Scouts have reported the use of perimeter wards around Dawnseeker Promontory. They're powerful, but not deadly. Disabling them would allow us to keep closer watch on their activities.", ["objectivesText"] = "Destroy 6 Sunreaver Perimeter Wards around Dawnseeker Promontory.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 22131, 22132, 22133, 22134, 22135, 22136, 71083, 94219 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "pvp" },
[32836] = { ["id"] = 32836, ["name"] = "A Knockoff Grumplefloot", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["storyline"] = { 32836 }, ["description"] = "The \"grumplefloot\" has been hastily carved out of a tree root, with holes unevenly spaced along its length. A close inspection of its backside, however, reveals words carved into the wood: RETURN TO BRAWLER'S GUILD", ["objectivesText"] = "Return the Knockoff Grumplefloot to someone within your faction's Brawler's Guild.", ["rewardGold"] = 57000, ["rewardItems"] = { 97978 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["startItems"] = { 97978 } },
[32838] = { ["id"] = 32838, ["name"] = "A Tale of Romance and Chivalry", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["storyline"] = { 32838 }, ["description"] = "A small book, written for children. It's well-bound and in fairly good condition. On the back cover of the book, near the spine, you find a few words written in flowing script: RETURN TO BRAWLER'S GUILD", ["objectivesText"] = "Return The Bear and the Lady Fair to someone within your faction's Brawler's Guild.", ["rewardGold"] = 57000, ["rewardItems"] = { 92813, 97979 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["startItems"] = { 97979 } },
[32840] = { ["id"] = 32840, ["name"] = "Boom Boom's Fuse", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["storyline"] = { 32840 }, ["description"] = "Amidst the gibbets of hozen meat and fur flying aimlessly around Kota Kon's sphere of destruction, you seem to have grabbed hold of a small fuse. The fuse is created entirely from woven, matted hozen tail hair. It has a strong smell. Near one of the ends of the fuse, however, is a small paper tag, embossed with the words: RETURN TO BRAWLER'S GUILD", ["objectivesText"] = "Return Boom Boom's Fuse to someone within your faction's Brawler's Guild.", ["rewardGold"] = 57000, ["rewardItems"] = { 97980 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["startItems"] = { 97980 } },
[32842] = { ["id"] = 32842, ["name"] = "Teeth Like Swords", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["storyline"] = { 32842 }, ["description"] = "The tooth comes to a singular edge, almost as if it were sharpened by stone. It clearly belonged to a ferocious beast. Handling it gingerly, you notice a few tiny words, expertly carved into the enamel: RETURN TO BRAWLER'S GUILD", ["objectivesText"] = "Return the Impeccably Sharp Tooth to someone within your faction's Brawler's Guild.", ["rewardGold"] = 57000, ["rewardItems"] = { 97981 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["startItems"] = { 97981 } },
[32844] = { ["id"] = 32844, ["name"] = "Secret of the Ooze", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["storyline"] = { 32844 }, ["description"] = "The contents of the vial swirl and froth violently, causing the vessel to tremble in your hand. As you look into the container, you think you catch a fleeting image of a living, angry face. The vial's stopper fits snugly. Around its edge, some small words have been carved with an expert hand: RETURN TO BRAWLER'S GUILD", ["objectivesText"] = "Return the Vial of Reddish Ooze to someone within your faction's Brawler's Guild.", ["rewardGold"] = 57000, ["rewardItems"] = { 97982 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["startItems"] = { 97982 } },
[32846] = { ["id"] = 32846, ["name"] = "Modified Chomping Apparatus", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["storyline"] = { 32846 }, ["description"] = "You might not have recognized this as a modified chomping apparatus if it didn't have the words \" modified chomping apparatus \" messily painted onto it. Right beneath the sloppy label, you see a smaller message, written much more neatly in bright red ink: RETURN TO BRAWLER'S GUILD", ["objectivesText"] = "Return the Modified Chomping Apparatus to someone within your faction's Brawler's Guild.", ["rewardGold"] = 57000, ["rewardItems"] = { 97983 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["startItems"] = { 97983 } },
[32848] = { ["id"] = 32848, ["name"] = "Frost-Tipped Eggshell", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["storyline"] = { 32848 }, ["description"] = "A piece of an eggshell, presumably penguin. Its edges are covered with rime, and based on its curvature, this egg was quite large when it was intact. Strangely, the inside of the eggshell has a message written on it, in jade-green ink: RETURN TO BRAWLER'S GUILD", ["objectivesText"] = "Return the Frost-Tipped Eggshell to someone within your faction's Brawler's Guild.", ["rewardGold"] = 57000, ["rewardItems"] = { 97984 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["startItems"] = { 97984 } },
[32850] = { ["id"] = 32850, ["name"] = "Last Year's Model", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["storyline"] = { 32850 }, ["series"] = { 32851 }, ["description"] = "The robot is in bad shape. It was built with several sockets which, like the Blingtron 4000, presumably once carried gems, but are now empty. The robot's otherwise dust-covered posterior region contains a small, shiny metal plaque, embossed with the words: RETURN TO BRAWLER'S GUILD", ["objectivesText"] = "Return the Dusty Old Robot to someone within your faction's Brawler's Guild.", ["rewardGold"] = 57000, ["rewardItems"] = { 97985, 98091, 98101 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["startItems"] = { 97985 } },
[32851] = { ["id"] = 32851, ["name"] = "Blingtron 3000", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["storyline"] = { 32851 }, ["series"] = { 32850 }, ["description"] = "The Blingtron line didn't really pick up until the 4000 series hit the vendor shelves. Few remember the Blingtron 3000, but it was a real engineering marvel in its own right! The challenge card you've unlocked gives you the ability to fight Blingtron 3000 right here, in the Brawler's Guild. Lucky you!", ["objectivesText"] = "Defeat Blingtron 3000 by purchasing his challenge card and challenging him in the Brawler's Guild.", ["rewardItems"] = { 52019, 86623, 87214, 97445, 97985, 98091, 98101 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[32852] = { ["id"] = 32852, ["name"] = "The Digmaster's Earthblade", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["storyline"] = { 32852 }, ["series"] = { 32853 }, ["description"] = "An entirely ordinary-looking shovel. The handle is carved with an ornate script: \"The Digmaster's Earthblade \". On the flipside of the handle, however, is a smaller label, written in simpler text: RETURN TO BRAWLER'S GUILD", ["objectivesText"] = "Return the Digmaster's Earthblade to someone within your faction's Brawler's Guild.", ["rewardGold"] = 57000, ["rewardItems"] = { 60847, 87399, 87539, 97279, 97986 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["startItems"] = { 97986 } },
[32853] = { ["id"] = 32853, ["name"] = "Mingus Diggs", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["storyline"] = { 32853 }, ["series"] = { 32852 }, ["description"] = "You've earned the right to challenge Mingus Diggs, the archaeologist! Mingus isn't that tough, from what I hear... but the people in charge let him bring some of his excavated treasures with him into the brawling ring. Those are what you want to watch out for. Come buy his card when you're ready!", ["objectivesText"] = "Defeat Mingus Diggs by purchasing his challenge card and challenging him in the Brawler's Guild.", ["rewardItems"] = { 52019, 86569, 87539, 90078, 97279, 97986, 98063, 98092, 98103, 104320 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[32854] = { ["id"] = 32854, ["name"] = "Well-Worn Blindfold", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 2257, ["storyline"] = { 32854 }, ["series"] = { 32855 }, ["description"] = "A piece of cloth, shaped for a human-sized head. The cloth is unadorned and simple, except for a small tag on the end, which reads: RETURN TO BRAWLER'S GUILD", ["objectivesText"] = "Return the Well-Worn Blindfold to someone within your faction's Brawler's Guild. Progress: You carry something of mine, I believe.", ["rewardGold"] = 57000, ["rewardItems"] = { 93724, 97987 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 2257 } }, ["questType"] = "standard", ["startItems"] = { 97987 } },
[32855] = { ["id"] = 32855, ["name"] = "The Blind Hero", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 2257, ["storyline"] = { 32855 }, ["series"] = { 32854 }, ["description"] = "The challenge card you've earned allows you to fight the Blind Hero, a mysterious warrior from a bygone age. Nobody surpasses his skill with a blade. Nobody. Luckily, he can't see anything. Have fun!", ["objectivesText"] = "Defeat the Blind Hero by purchasing his challenge card and challenging him in the Brawler's Guild.", ["rewardItems"] = { 52019, 93724, 98093, 98103 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 2257 } }, ["questType"] = "standard" },
[32856] = { ["id"] = 32856, ["name"] = "Paper-Covered Rock", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["storyline"] = { 32856 }, ["series"] = { 32857 }, ["description"] = "It's a strange combination of items. The paper envelops the rock completely, dwarfing it like a smothering blanket of wood pulp. Compared to the paper, the rock is barely a pebble. When held up to the light, the paper reveals a distinct watermark, along with the text: RETURN TO BRAWLER'S GUILD", ["objectivesText"] = "Return the Paper-Covered Rock to someone within your faction's Brawler's Guild.", ["rewardGold"] = 57000, ["rewardItems"] = { 74847, 97560, 97988, 98087, 98102 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[32857] = { ["id"] = 32857, ["name"] = "Ro-Shambo", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["storyline"] = { 32857 }, ["series"] = { 32856 }, ["description"] = "The challenge card you have unlocked will allow you to fight Ro-Shambo, an esoteric creature from parts unknown. Watch out. I hear it's got a few tricks up its sleeve.", ["objectivesText"] = "Defeat Ro-Shambo by purchasing her challenge card and challenging her in the Brawler's Guild.", ["rewardItems"] = { 52019, 85215, 85219, 97988, 98087, 98102 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[32858] = { ["id"] = 32858, ["name"] = "Raptorhide Boxing Gloves", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["storyline"] = { 32858 }, ["description"] = "The gloves are stitched together roughly, and by the smell of it, they've been treated with crawler mucus. Nevertheless, they appear sturdy and functional. Somewhat unsurprisingly, the inner seam bears the following words: RETURN TO BRAWLER'S GUILD", ["objectivesText"] = "Return the Raptorhide Boxing Gloves to someone within your faction's Brawler's Guild.", ["rewardGold"] = 57000, ["rewardItems"] = { 97849, 97990 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["startItems"] = { 97990 } },
[32863] = { ["id"] = 32863, ["name"] = "What We've Been Training For", ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 32863 }, ["description"] = "Are you ready to put your pets to the test? The battle pet arena is no place for low-level rabbits, you'd better have a rocketbot in your pocket and be ready for action. If you've got three fully-experienced pets, find battles against trainers of similar skill and show the world what you've got. You can find the instructions in your Pet Journal.", ["objectivesText"] = "Defeat 10 players through Find Battle with a team of level 25 pets.", ["rewardGold"] = 106000, ["rewardXP"] = 80, ["rewardItems"] = { 71076, 98095, 102145, 103670 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
