[32942] = { ["id"] = 32942, ["name"] = "Work Order: Sunreaver Onslaught I", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 32942 }, ["series"] = { 32943 }, ["description"] = "<Yoon keeps the details of this order short, but detailed.> Another request has come through for the Horde. The Sunreaver Onslaught, located out on the Isle of Thunder, has requested a bushel of scallions. Though this Horde and Alliance conflict still gets my fur in a bristle, I won't turn away a hungry stomach.", ["objectivesText"] = "Plant 8 Scallion Seeds on Sunsong Ranch.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[32943] = { ["id"] = 32943, ["name"] = "Work Order: Sunreaver Onslaught II", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 32943 }, ["series"] = { 32942 }, ["description"] = "Once your scallions are ready to be picked, you'll need only to package them for pick-up. Just think; your scallions will feed so many hungry soldiers on the front lines!", ["objectivesText"] = "Harvest 8 Ripe Scallion plants and provide 40 Scallions for the Sunreaver Onslaught. Progress: The crate sits empty awaiting your crops.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 74843 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[32944] = { ["id"] = 32944, ["name"] = "Work Order: Kirin Tor Offensive I", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["storyline"] = { 32944 }, ["series"] = { 32945 }, ["description"] = "<Yoon keeps the details of this order short, but detailed.> Another request has come through for the Alliance. The Kirin Tor Offensive, located out on the Isle of Thunder, has requested a bushel of juicycrunch carrots. Though this Horde and Alliance conflict still gets my fur in a bristle, I won't turn away a hungry stomach.", ["objectivesText"] = "Plant 8 Juicycrunch Carrot Seeds on Sunsong Ranch.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5805 } }, ["questType"] = "standard" },
