[32974] = { ["id"] = 32974, ["name"] = "Rolo's Riddle", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6757, ["storyline"] = { 32974 }, ["series"] = { 32975, 32976, 38552 }, ["description"] = "<The leather vellum is very old. Stained by age, it bears the following letters:> On the isle of time are tall men four Round and strong and nothing more Of these brothers the shortest be Where the trail leads to me.", ["objectivesText"] = "Solve the riddle.", ["rewardGold"] = 68700, ["rewardXP"] = 2060, ["rewardItems"] = { 102225, 104009, 104010, 104012, 104013, 211279 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6757 } }, ["questType"] = "standard" },
[32975] = { ["id"] = 32975, ["name"] = "Rolo's Riddle", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["storyline"] = { 32975 }, ["series"] = { 32974, 32976, 38552 }, ["description"] = "<Another dirty scrap of parchment is buried beneath the soil.> Somewhere hope stands, wings held forth From its feet turn to the north Pass beyond an ancient gate Behind a stone pair, I await.", ["objectivesText"] = "Solve the riddle.", ["rewardGold"] = 68700, ["rewardXP"] = 2060, ["rewardItems"] = { 104009, 104010, 104012, 104013, 104293, 211279 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[32976] = { ["id"] = 32976, ["name"] = "Rolo's Riddle", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["storyline"] = { 32976 }, ["series"] = { 32974, 32975, 38552 }, ["description"] = "The final step, my treasure calls Above the place where water falls Beneath the shade on vantage high No path to walk but air and sky.", ["objectivesText"] = "Solve the riddle.", ["rewardGold"] = 274800, ["rewardXP"] = 5145, ["rewardItems"] = { 104009, 104010, 104012, 104013, 104346, 109076, 211279 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[33008] = { ["id"] = 33008, ["name"] = "Into the Vale", ["level"] = 87, ["requiredLevel"] = 87, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["storyline"] = { 33008 }, ["description"] = "Ah, I have been waiting for your arrival, traveler. I wish we could meet in better times, but alas, I fear the situation in the Vale is quite dire. But let us not speak of that now. Go visit Madam Vee Luo at the Shrine of Two Moons. She should be able to settle you in.", ["objectivesText"] = "Speak to Madam Vee Luo at the Shrine of Two Moons in the Vale of Eternal Blossoms .", ["rewardGold"] = 51000, ["rewardXP"] = 64000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[33018] = { ["id"] = 33018, ["name"] = "Noodle Secrets Long Forgotten", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["requiredProfessions"] = { "cooking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6757, ["storyline"] = { 33018 }, ["series"] = { 33020, 33021, 33022, 33024, 33026, 33027, 33107, 33139 }, ["description"] = "Searching amidst the rubble, you find the fragment of an old sign. Wiping away the dust, you can make out the well-weathered pandaren characters for \"Noodles\" and \"Lin.\" Looking above, you suspect that the establishment this sign belonged to was situated on the bridge, which now lies in rubble about you. An eatery placed on a bridge sounds very temporary, so its owner would likely live nearby. Perhaps there is a clue to be found in the village here on the island?", ["objectivesText"] = "Search the village, Old Pi'jiu, on the Timeless Isle, for the owner of the old sign fragment .", ["rewardGold"] = 280900, ["rewardXP"] = 4790, ["rewardItems"] = { 74833, 74837, 74839, 74841, 74843, 74845, 74846, 74847, 74848, 74856, 74857, 74859, 74864, 74865 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6757 } }, ["questType"] = "standard" },
[33020] = { ["id"] = 33020, ["name"] = "The Lost Secret of the Secret Ingredient", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["requiredProfessions"] = { "cooking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5956, ["storyline"] = { 33020 }, ["series"] = { 33018, 33021, 33022, 33024, 33026, 33027, 33107, 33139 }, ["description"] = "If you've come here to try my family's famous noodle soup, I'm afraid you're out of luck. My father passed away before he could teach me the secret ingredient. He did mention writing down the recipe for a friend of his that studied at the Temple of the Jade Serpent. Perhaps you can find it there?", ["objectivesText"] = "Defeat the Sha of Doubt .", ["rewardGold"] = 549600, ["rewardXP"] = 9580, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5956 } }, ["questType"] = "dungeon" },
[33021] = { ["id"] = 33021, ["name"] = "Secrets Lost, Forever?", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["requiredProfessions"] = { "cooking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5805, ["mapID"] = 376, ["storyline"] = { 33021 }, ["series"] = { 33018, 33020, 33022, 33024, 33026, 33027, 33107, 33139 }, ["description"] = "<With the ancient Lin family noodle soup recipe in hand, you decide to set out for the Halfhill Market.> <If anyone in Pandaria knows how to decipher this scroll, it's Sungshin Ironpaw .>", ["objectivesText"] = "Speak with Sungshin Ironpaw at the Halfhill Market in the Valley of the Four Winds.", ["rewardGold"] = 28090, ["rewardXP"] = 600, ["ends"] = { { ["mapID"] = 376, ["npcID"] = 64231, ["x"] = 0.535, ["y"] = 0.512 } }, ["coords"] = { ["mapID"] = 376, ["source"] = "quest_giver", ["x"] = 0.535, ["y"] = 0.512 }, ["mapCandidates"] = { ["npc"] = { 376 }, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[33022] = { ["id"] = 33022, ["name"] = "Catch and Carry", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["requiredProfessions"] = { "cooking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["mapID"] = 376, ["storyline"] = { 33022 }, ["series"] = { 33018, 33020, 33021, 33024, 33026, 33027, 33107, 33139 }, ["description"] = "Oh my! Grandpa used to tell me stories of the famous Lin family noodle shop. It is sad that the scroll has been warped, but I think we can work together to solve the riddle! To start, we're going to need lots of grain to make noodles. Head down to the granary and catch some grain with this sack. After you've caught some, drop it off at the wagon I've placed at the granary.", ["objectivesText"] = "Use the Grain Catching Sack to catch 20 Sacks of Grain being thrown down by the Granary Vandals at the Imperial Granary. You will drop all your carried grain if you mount or get hurt.", ["rewardGold"] = 137400, ["rewardXP"] = 4790, ["rewardItems"] = { 102372 }, ["starts"] = { { ["mapID"] = 376, ["npcID"] = 64231, ["x"] = 0.535, ["y"] = 0.512 } }, ["ends"] = { { ["mapID"] = 376, ["npcID"] = 64231, ["x"] = 0.535, ["y"] = 0.512 } }, ["coords"] = { ["mapID"] = 376, ["source"] = "quest_giver", ["x"] = 0.535, ["y"] = 0.512 }, ["mapCandidates"] = { ["npc"] = { 376 }, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[33027] = { ["id"] = 33027, ["name"] = "The Secret Ingredient Is...", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["requiredProfessions"] = { "cooking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["mapID"] = 376, ["storyline"] = { 33027 }, ["series"] = { 33018, 33020, 33021, 33022, 33024, 33026, 33107, 33139 }, ["description"] = "The best way to go about doing this is through hands-on experience. I've arranged for merchants, scholars, and farmers from all over Pandaria to come for a taste test of your soups. We'll get the best results if you can match them to the soups they prefer. It's time to find the secret ingredient!", ["objectivesText"] = "Queue for and complete the Finding the Secret Ingredient scenario. Progress: <name>, we need to find the secret ingredient if we're to ever master the Lin family's noodle soup!", ["rewardGold"] = 619600, ["rewardXP"] = 5990, ["rewardItems"] = { 46349, 86425, 181368, 181377, 181583, 181601, 181610, 181703, 181745, 184294, 184362, 184363, 184765, 184766, 184767, 184768, 184839, 184840, 184841, 184842 }, ["starts"] = { { ["mapID"] = 376, ["npcID"] = 64231, ["x"] = 0.535, ["y"] = 0.512 } }, ["ends"] = { { ["mapID"] = 376, ["npcID"] = 64231, ["x"] = 0.535, ["y"] = 0.512 } }, ["coords"] = { ["mapID"] = 376, ["source"] = "quest_giver", ["x"] = 0.535, ["y"] = 0.512 }, ["mapCandidates"] = { ["npc"] = { 376 }, ["zone"] = { 5805 } }, ["questType"] = "standard" },
