[33107] = { ["id"] = 33107, ["name"] = "Bad Feeling, Worse Result", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["requiredProfessions"] = { "cooking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5956, ["storyline"] = { 33107 }, ["series"] = { 33018, 33020, 33021, 33022, 33024, 33026, 33027, 33139 }, ["description"] = "<As you open the scroll, you realize your worst fears have come true: the sha energies have corrupted the Lin recipe.> <Your only choice is to defeat the released energies in the hope that the scroll can be saved.>", ["objectivesText"] = "Defeat the Ghost of Lin Da-Gu .", ["rewardGold"] = 1239200, ["rewardXP"] = 9580, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5956 } }, ["questType"] = "dungeon" },
