[33133] = { ["id"] = 33133, ["name"] = "Warforged Seals", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5840, ["mapID"] = 390, ["storyline"] = { 33133 }, ["description"] = "Greetings, <name>. I am privileged to offer you an excellent opportunity. Through the centuries, we've honed a method by which the very laws of chance themselves can be bent. With a Warforged Seal , valuable artifacts will find their way into your hands more frequently as you pursue Garrosh.", ["objectivesText"] = "Collect 50 Lesser Charms of Good Fortune . Progress: May these charms bring you great luck, <name>.", ["rewardItems"] = { 87771, 87777, 89783, 93666, 94125, 94152, 94228, 94574, 94835, 95057, 95059, 97959, 97960, 104158, 104162, 104163, 104165, 104253, 105751, 116660, 116771, 123890, 127749 }, ["starts"] = { { ["mapID"] = 390, ["npcID"] = 63996, ["x"] = 0.62, ["y"] = 0.206 } }, ["ends"] = { { ["mapID"] = 390, ["npcID"] = 63996, ["x"] = 0.62, ["y"] = 0.206 } }, ["coords"] = { ["mapID"] = 390, ["source"] = "quest_giver", ["x"] = 0.62, ["y"] = 0.206 }, ["mapCandidates"] = { ["npc"] = { 390 }, ["zone"] = { 5840 } }, ["questType"] = "standard" },
