[33137] = { ["id"] = 33137, ["name"] = "The Celestial Tournament", ["requiredLevel"] = 90, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 4, ["storyline"] = { 33137 }, ["description"] = "The Timeless Isle is home to a special tournament created to test the leadership of its participants. Those who prove their worth are granted an opportunity to befriend an embodiment of virtue - the progeny of the celestials themselves. Each time you win the tournament, I will honor you with a single ceremonial coin. When you have enough coins, speak with me again to further discuss your reward.", ["objectivesText"] = "Speak with Master Li to enter the Celestial Tournament and defeat all the challengers there.", ["rewardGold"] = 114000, ["rewardXP"] = 236000, ["rewardItems"] = { 8498, 10822, 73903, 90173, 93040, 94191, 101529, 101771, 102145, 102146, 102147 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[33139] = { ["id"] = 33139, ["name"] = "Secrets Lost, Forever?", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "none", ["requiredProfessions"] = { "cooking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["storyline"] = { 33139 }, ["series"] = { 33018, 33020, 33021, 33022, 33024, 33026, 33027, 33107 }, ["description"] = "<With the ancient Lin family noodle soup recipe in hand, you decide to set out for the Halfhill Market.> <If anyone in Pandaria knows how to decipher this scroll, it's Sungshin Ironpaw.>", ["objectivesText"] = "Speak with Sungshin Ironpaw at the Halfhill Market in the Valley of the Four Winds.", ["rewardGold"] = 30900, ["rewardXP"] = 600, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[33146] = { ["id"] = 33146, ["name"] = "Noodle Time", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["requiredProfessions"] = { "cooking" }, ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["mapID"] = 376, ["storyline"] = { 33146 }, ["description"] = "Hello, <name>. Care to work the noodle stand again? Just let me know when you're ready to work another shift and I'll get everything set up.", ["objectivesText"] = "Queue for and complete a shift at the Halfhill noodle stand . Progress: Keep up the good work, <name>!", ["rewardGold"] = 619600, ["rewardXP"] = 5990, ["rewardItems"] = { 86425, 211279 }, ["starts"] = { { ["mapID"] = 376, ["npcID"] = 64231, ["x"] = 0.535, ["y"] = 0.512 } }, ["ends"] = { { ["mapID"] = 376, ["npcID"] = 64231, ["x"] = 0.535, ["y"] = 0.512 } }, ["coords"] = { ["mapID"] = 376, ["source"] = "quest_giver", ["x"] = 0.535, ["y"] = 0.512 }, ["mapCandidates"] = { ["npc"] = { 376 }, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[33147] = { ["id"] = 33147, ["name"] = "The Last Gasp of Y'Shaarj", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6738, ["storyline"] = { 33147 }, ["series"] = { 33138 }, ["description"] = "A dark, vaporous substance stains the floor of the room. This is all that remains of the Old God Y'Shaarj.", ["objectivesText"] = "Speak with Lorewalker Cho in the Siege of Orgrimmar .", ["rewardGold"] = 280900, ["rewardXP"] = 4790, ["rewardItems"] = { 88589, 90175 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6738 } }, ["questType"] = "standard" },
[33211] = { ["id"] = 33211, ["name"] = "A Timeless Question", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6757, ["storyline"] = { 33211 }, ["description"] = "Destiny. Fate. Karma. Words like these imply that the timeways are unassailable. Would that were the case. To this day, many of Azeroth's inhabitants yearn to change the past. Yet just as our experiences shape us, they also shape the world around us. Consider how those threads have woven the fabric of today's reality. Cut enough threads, and causation inevitably fails, unraveling that fabric. Indeed, cutting even a single thread short can result in disaster, provided it is the right thread.", ["objectivesText"] = "Correctly answer one of Evelyna's questions about the history of Azeroth. Progress: Let us speak, then, of events that have already come to pass.", ["rewardGold"] = 1123600, ["rewardXP"] = 8230, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6757 } }, ["questType"] = "standard" },
[33222] = { ["id"] = 33222, ["name"] = "Little Tommy Newcomer", ["requiredLevel"] = 1, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 4, ["storyline"] = { 33222 }, ["description"] = "I've got a battle pet, too! Want to battle? It'll be fun, I promise!", ["objectivesText"] = "Defeat Little Tommy Newcomer in a pet battle.", ["rewardGold"] = 94000, ["rewardXP"] = 80, ["rewardItems"] = { 73903, 73905 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
