[33229] = { ["id"] = 33229, ["name"] = "A Flash of Bronze...", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 5840, ["storyline"] = { 33229 }, ["series"] = { 33160, 33231 }, ["description"] = "As you survey the devastation of the vale, a flash of bronze catches your eye. Unless you're mistaken, a tiny gnome is trying to catch your attention from the balcony above Mogu'shan Palace, just outside of the Seat of Knowledge. You should see what she wants.", ["objectivesText"] = "Speak with Chromie outside of the Seat of Knowledge in the Vale of Eternal Blossoms .", ["rewardGold"] = 70225, ["rewardXP"] = 1030, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5840 } }, ["questType"] = "standard" },
