[33248] = { ["id"] = 33248, ["name"] = "Proving Grounds", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["storyline"] = { 33248 }, ["description"] = "You there! It's <name>, right? Greetings. I'm Taijing. <Taijing sizes you up.> You look strong. I've seen you a few times here in the Vale, but I've never seen you fight before. I wonder... are you as strong as you seem? If you're interested in proving yourself, speak with Trial Master Rotun at the Temple of the White Tiger, in Kun-Lai. He will put you to the test.", ["objectivesText"] = "Speak with Trial Master Rotun at the Temple of the White Tiger, then enter the Proving Grounds.", ["rewardGold"] = 11400, ["rewardXP"] = 23600, ["rewardItems"] = { 17690, 17691, 19483, 19484 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[33249] = { ["id"] = 33249, ["name"] = "Proving Grounds", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 4, ["storyline"] = { 33249 }, ["description"] = "You there! It's <name>, right? Greetings. I'm Jinho. <Jinho sizes you up.> You look strong. I've seen you a few times here in the Vale, but I've never seen you fight before. I wonder... are you as strong as you seem? If you're interested in proving yourself, speak with Trial Master Rotun at the Temple of the White Tiger, in Kun-Lai. He will put you to the test.", ["objectivesText"] = "Speak with Trial Master Rotun at the Temple of the White Tiger, then enter the Proving Grounds.", ["rewardGold"] = 11400, ["rewardXP"] = 23600, ["rewardItems"] = { 17690, 17691, 19483, 19484 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[33334] = { ["id"] = 33334, ["name"] = "Strong Enough To Survive", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly", "loremaster" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6757, ["storyline"] = { 33334 }, ["series"] = { 33332, 33333 }, ["description"] = "An island lost in time and yet it returns flourishing with life! Where did this island travel to? Did it simply hop forward in time, or did it languish in the dark reaches of the Twisting Nether? There is one thing for certain: the creatures that inhabit this place are far more than they seem. I sense a hidden power in them, forged by the eons. Seek out the champions of their species, duly marked by their power and prowess, and vanquish five such creatures. In death, we may find the clues we seek.", ["objectivesText"] = "Defeat five Rare or Rare Elite creatures on the Timeless Isle . Progress: This journal really is fascinating, I wonder what happened to our dear explorer friend in the end.", ["rewardGold"] = 561800, ["rewardXP"] = 5145, ["rewardItems"] = { 211279 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6757 } }, ["questType"] = "group" },
[33337] = { ["id"] = 33337, ["name"] = "A Vision in Time", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6757, ["storyline"] = { 33337 }, ["series"] = { 33161, 33336, 33338, 33375, 33376, 33377, 33378, 33379 }, ["description"] = "Look at how the Vision reacts! Astounding! Even now it shows shadows of timeways that flit around us constantly. Though not true sands of the Hourglass of Time, the finely-ground epoch stones certainly have a power all their own. Our first task is to use them to calibrate the Vision of Time . Take the Vision of Time to a location where history is in the making: the Siege of Orgrimmar. Once there, turn the hourglass and see what happens.", ["objectivesText"] = "Use the Vision of Time in the Siege of Orgrimmar. Progress: Did you use the Vision of Time ? What was the result?", ["rewardXP"] = 4115, ["rewardItems"] = { 105930, 105934, 211279 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6757 } }, ["questType"] = "standard" },
[33354] = { ["id"] = 33354, ["name"] = "Den Mother's Demise", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["storyline"] = { 33354 }, ["description"] = "This is the pelt of Darkmoon Island's monstrous den mother. Yebb Neblegear, beastmaster of the Darkmoon Faire, will be happy to know the ghostly wolf and her spawn will no longer be terrorizing his menagerie... at least for a little while. Bring it to him.", ["objectivesText"] = "Bring Moonfang's Pelt to Yebb Neblegear at the Darkmoon Faire on Darkmoon Island.", ["rewardXP"] = 236000, ["rewardItems"] = { 105891 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["startItems"] = { 105891 } },
[33358] = { ["id"] = 33358, ["name"] = "Noodle Time: Bonus", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["requiredProfessions"] = { "cooking" }, ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 5805, ["mapID"] = 376, ["storyline"] = { 33358 }, ["description"] = "Hello, <name>. Think you're a truly extraordinary noodle chef? Let's see what you've got!", ["objectivesText"] = "Queue for a shift at the Halfhill noodle stand, then complete the bonus objective.", ["rewardGold"] = 619600, ["rewardXP"] = 5990, ["rewardItems"] = { 86425, 211279 }, ["starts"] = { { ["mapID"] = 376, ["npcID"] = 64231, ["x"] = 0.535, ["y"] = 0.512 } }, ["ends"] = { { ["mapID"] = 376, ["npcID"] = 64231, ["x"] = 0.535, ["y"] = 0.512 } }, ["coords"] = { ["mapID"] = 376, ["source"] = "quest_giver", ["x"] = 0.535, ["y"] = 0.512 }, ["mapCandidates"] = { ["npc"] = { 376 }, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[33374] = { ["id"] = 33374, ["name"] = "Path of the Mistwalker", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = true, ["expansion"] = 4, ["zoneID"] = 6757, ["storyline"] = { 33374 }, ["series"] = { 33335, 33340, 33341, 33342, 33343 }, ["description"] = "You have heard the words of the celestials, but what did you learn on your path to the shrines? The wisdom of the pilgrimage is in its silence and simplicity. As you listen to the wind rustling in the trees, and note even the smallest butterfly, your mind is open to learning the deepest lessons the trials have to teach us. Perhaps you noticed the many great beasts that roam the island? Therein lies your trial. You have learned much from Pandaria, now let us put your knowledge to the test.", ["objectivesText"] = "Defeat 20 Elite creatures on the Timeless Isle . Progress: Have the lessons of Pandaria aided you in your journey?", ["rewardGold"] = 561800, ["rewardXP"] = 5145, ["rewardItems"] = { 64399, 103641, 103642, 103643, 103684 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6757 } }, ["questType"] = "group" },
[33375] = { ["id"] = 33375, ["name"] = "Refining The Vision", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6757, ["storyline"] = { 33375 }, ["series"] = { 33161, 33336, 33337, 33338, 33376, 33377, 33378, 33379 }, ["description"] = "I have finished grinding the stones, and have attuned the hourglass to a new series of timeways. Will you return to the Siege of Orgrimmar and turn the hourglass once more? Return quickly, I am most curious.", ["objectivesText"] = "Use the Vision of Time in the Siege of Orgrimmar. Progress: Did you use the Vision of Time ? What was the result?", ["rewardXP"] = 4115, ["rewardItems"] = { 105931 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6757 } }, ["questType"] = "standard" },
[33376] = { ["id"] = 33376, ["name"] = "Seeking Fate", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6757, ["storyline"] = { 33376 }, ["series"] = { 33161, 33336, 33337, 33338, 33375, 33377, 33378, 33379 }, ["description"] = "I have not been completely forthright with you, despite all that you have done to aid the Timewalkers. I cannot tell you everything, not yet, but know this - there is a traitor amongst us. Tell no one of your mission today, and take caution around any of my flight while you hold the Vision of Time . Quickly now, return to the Siege of Orgrimmar once more and use the hourglass. And be safe.", ["objectivesText"] = "Use the Vision of Time in the Siege of Orgrimmar. Progress: Did you use the Vision of Time ? What was the result?", ["rewardXP"] = 4115, ["rewardItems"] = { 105932 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6757 } }, ["questType"] = "standard" },
[33377] = { ["id"] = 33377, ["name"] = "Hidden Threads", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6757, ["storyline"] = { 33377 }, ["series"] = { 33161, 33336, 33337, 33338, 33375, 33376, 33378, 33379 }, ["description"] = "You have kept our mission a secret, and for that I thank you. Knowledge of the timeways, when in the wrong hands, can cause catastrophic devastation. My flight has little power to repair it, now. We must be careful. The hourglass grows in power. I believe it can now be used to see much further than before. I wish you to push it to its limits. Return to the Siege of Orgrimmar, and focus the hourglass on the most devastating timeway you can find.", ["objectivesText"] = "Use the Vision of Time in the Siege of Orgrimmar.", ["rewardXP"] = 4115, ["rewardItems"] = { 105933 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6757 } }, ["questType"] = "standard" },
[33378] = { ["id"] = 33378, ["name"] = "Courting Destiny", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6757, ["storyline"] = { 33378 }, ["series"] = { 33161, 33336, 33337, 33338, 33375, 33376, 33377, 33379 }, ["description"] = "The Vision of Time is nearly perfected, we now have much more control over the visions we seek. Your efforts have been instrumental in completing the artifact and restoring the strength of not only my flight, but also our allies in the Timewalkers. All of us are in your debt. Quite fortunately, I have located a sort of crux in time - an intersection of timeways - right here in Pandaria. Take the Vision of Time to the Temple of the White Tiger. There, in the cellars, turn the hourglass.", ["objectivesText"] = "Use the Vision of Time at the Temple of the White Tiger in Kun-Lai Summit. Progress: Did you use the Vision of Time ? What was the result?", ["rewardXP"] = 4115, ["rewardItems"] = { 105934 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6757 } }, ["questType"] = "standard" },
[33379] = { ["id"] = 33379, ["name"] = "One Final Turn", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 4, ["zoneID"] = 6757, ["storyline"] = { 33379 }, ["series"] = { 33161, 33336, 33337, 33338, 33375, 33376, 33377, 33378 }, ["description"] = "I do not wish to ask this of you again, but I do not know who I can trust any longer. I have been using the Vision of Time to gather information, and in my searches, I believe I have found another crux in time. It is in the Caverns of Time itself. I did not want to believe it when the vision first came to me, but I cannot sit idly by and let this information pass. The Caverns of Time - you must go there, now, and use the Vision of Time . Move quickly!", ["objectivesText"] = "Use the Vision of Time in the Caverns of Time in Tanaris.", ["rewardXP"] = 4115, ["rewardItems"] = { 18986, 39563, 105935 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6757 } }, ["questType"] = "standard" },
